import { runModelTests } from './models.test.js';
import { runChatTests } from './chat.test.js';
import { runServerTests } from './server.test.js';
import { runCoreEngineTests } from './core-engine.test.js';
import { runUniversalClientTests } from './universal_client.test.js';
import { runConsiliumTests } from './consilium.test.js';
import { runRolesTests } from './roles.test.js';
import { runAnsiStreamEngineTests } from './ansi_stream_engine.test.js';
import { runPluginManagerTests, runEventBusTests } from './plugin-manager.test.js';
import { runLLMProvidersTests } from './llm-providers.test.js';
import { runKnowledgeBaseTests } from './knowledge-base.test.js';
import { runPluginConsiliumTests } from './consilium-new.test.js';
import { runAccountingAndBuilderTests } from './accounting_and_builder.test.js';
import { runCommandsAndHistoryTests } from './commands_and_history.test.js';
import { runProductsTests } from './products.test.js';
import { runTelegramTests } from './telegram.test.js';
import { runResilienceTests } from './resilience.test.js';
import { runDebugLogTests } from './debug_log.test.js';
import { runTranslateTests } from './translate.test.js';
import { runCloudTtsTests } from './cloudtts.test.js';
import { runCloudSttTests } from './cloudstt.test.js';
import { runDeveloperModeTests } from './developer_mode.test.js';
import { runUiParityTests } from './ui_parity.test.js';
import { runGeminiRoutingTests } from './gemini_routing.test.js';
import { runCliTuiTests } from './cli_tui.test.js';
import { runTelegramDeepTests } from './telegram_deep.test.js';
import { runRouterTests } from './routers.test.js';
import { runSubagentEngineTests } from './subagent_engine.test.js';
import { runAutoModelRouterTests } from './auto_model_router.test.js';
import { runCoveragePushTests } from './coverage_push.test.js';

async function runAllTests(): Promise<void> {
  console.log('================================================================');
  console.log('⚡ EVABOT v0.1.0 — FULL TEST SUITE (29 test suites)');
  console.log('================================================================\n');

  const results = [
    await runModelTests(),
    await runChatTests(),
    await runServerTests(),
    await runCoreEngineTests(),
    await runUniversalClientTests(),
    await runConsiliumTests(),
    await runRolesTests(),
    await runAnsiStreamEngineTests(),
    await runPluginManagerTests(),
    await runEventBusTests(),
    await runLLMProvidersTests(),
    await runKnowledgeBaseTests(),
    await runPluginConsiliumTests(),
    await runAccountingAndBuilderTests(),
    await runCommandsAndHistoryTests(),
    await runProductsTests(),
    await runTelegramTests(),
    await runResilienceTests(),
    await runDebugLogTests(),
    await runTranslateTests(),
    await runCloudTtsTests(),
    await runCloudSttTests(),
    await runDeveloperModeTests(),
    await runUiParityTests(),
    await runGeminiRoutingTests(),
    await runCliTuiTests(),
    await runTelegramDeepTests(),
    await runRouterTests(),
    await runSubagentEngineTests(),
    runAutoModelRouterTests(),
    await runCoveragePushTests(),
  ];

  const testNames = [
    'ModelTests',
    'ChatTests',
    'ServerTests',
    'CoreEngineTests',
    'UniversalClientTests',
    'ConsiliumTests',
    'RolesTests',
    'AnsiStreamEngineTests',
    'PluginManagerTests',
    'EventBusTests',
    'LLMProvidersTests',
    'KnowledgeBaseTests',
    'ConsiliumNewTests',
    'AccountingAndBuilderTests',
    'CommandsAndHistoryTests',
    'ProductsTests',
    'TelegramTests',
    'ResilienceTests',
    'DebugLogTests',
    'TranslateTests',
    'CloudTtsTests',
    'CloudSttTests',
    'DeveloperModeTests',
    'UiParityTests',
    'GeminiRoutingTests',
    'CliTuiTests',
    'TelegramDeepTests',
    'RouterTests',
    'SubagentEngineTests',
    'AutoModelRouterTests',
    'CoveragePushTests',
  ];

  let allPassed = true;
  console.log('\n================================================================');
  results.forEach((res, i) => {
    if (res) {
      console.log(`✓ Suite PASSED: ${testNames[i]}`);
    } else {
      console.error(`❌ Suite FAILED: ${testNames[i]}`);
      allPassed = false;
    }
  });

  console.log('\n================================================================');
  if (allPassed) {
    console.log('✅ ALL 29 TEST SUITES (100% OF TESTS) PASSED SUCCESSFULLY!');
    console.log('================================================================\n');
    process.exit(0);
  } else {
    console.error('❌ SOME TESTS FAILED.');
    console.log('================================================================\n');
    process.exit(1);
  }
}

runAllTests();

import { ModelRegistry, GEMINI_MODELS } from '../src/models/ModelRegistry.js';

export function runModelTests(): boolean {
  console.log('\n--- Running ModelRegistry Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  const all = ModelRegistry.getAllModels();
  assert(all.length >= 4, `At least 4 Gemini models registered (found ${all.length})`);

  const flash25 = ModelRegistry.getModelById('gemini-2.5-flash');
  assert(Boolean(flash25), 'gemini-2.5-flash is registered');
  assert(flash25?.recommended === true, 'gemini-2.5-flash is marked as recommended');

  const pro25 = ModelRegistry.getModelById('gemini-2.5-pro');
  assert(Boolean(pro25), 'gemini-2.5-pro is registered');

  const defaultModel = ModelRegistry.getDefaultModel();
  assert(defaultModel.id === 'gemini-2.5-flash', 'Default model is gemini-2.5-flash');

  assert(ModelRegistry.isValidModel('gemini-2.0-flash'), 'gemini-2.0-flash is valid');
  assert(!ModelRegistry.isValidModel('non-existent-gpt-model'), 'Invalid model returns false');

  // Gemini 3.x Frontier Models Verification
  const flash38 = ModelRegistry.getModelById('gemini-3.8-flash');
  assert(Boolean(flash38), 'gemini-3.8-flash is registered');
  assert(flash38?.contextWindow === 1048576, 'gemini-3.8-flash context window is 1M tokens');
  assert(flash38?.maxOutputTokens === 8192, 'gemini-3.8-flash max output tokens is 8192');
  assert(Boolean(flash38?.pricing.inputPer1MTokensUSD.includes('$')), 'gemini-3.8-flash has USD pricing');
  assert(Boolean(flash38?.pricing.inputPer1MTokensEUR.includes('€')), 'gemini-3.8-flash has EUR pricing');

  const pro31 = ModelRegistry.getModelById('gemini-3.1-pro');
  assert(Boolean(pro31), 'gemini-3.1-pro is registered');
  assert(pro31?.contextWindow === 2097152, 'gemini-3.1-pro context window is 2M tokens');
  assert(pro31?.maxOutputTokens === 8192, 'gemini-3.1-pro max output tokens is 8192');
  assert(Boolean(pro31?.pricing.inputPer1MTokensUSD.includes('$')), 'gemini-3.1-pro has USD pricing');
  assert(Boolean(pro31?.pricing.inputPer1MTokensEUR.includes('€')), 'gemini-3.1-pro has EUR pricing');

  assert(ModelRegistry.isValidModel('omniroute/gemini-3.8-flash'), 'omniroute/gemini-3.8-flash is valid');
  assert(ModelRegistry.isValidModel('omniroute/gemini-3.1-pro'), 'omniroute/gemini-3.1-pro is valid');

  return passed;
}

import { ChatSession } from '../src/core/ChatSession.js';
import { Config } from '../src/core/Config.js';

export function runChatTests(): boolean {
  console.log('\n--- Running ChatSession & Currency Compliance Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  const session = new ChatSession({
    model: 'gemini-2.5-flash',
    maxHistoryTurns: 5,
  });

  assert(session.getModel() === 'gemini-2.5-flash', 'Session initializes with correct model');
  assert(session.getHistory().length === 0, 'Session starts with empty history');

  const switched = session.setModel('gemini-2.5-pro');
  assert(switched && session.getModel() === 'gemini-2.5-pro', 'Model switched to gemini-2.5-pro');

  const invalidSwitch = session.setModel('fake-model');
  assert(!invalidSwitch && session.getModel() === 'gemini-2.5-pro', 'Invalid model switch safely rejected');

  // Currency Compliance Verification
  const systemPrompt = session.getSystemInstruction();
  const containsRub = systemPrompt.includes('RUB') || systemPrompt.includes('₽');
  assert(!containsRub, 'System prompt contains NO rubles (RUB / ₽)');
  assert(systemPrompt.includes('USD') && systemPrompt.includes('EUR'), 'System prompt enforces USD ($) and EUR (€)');

  assert(Config.supportedCurrencies.includes('USD') && Config.supportedCurrencies.includes('EUR'), 'Config enforces USD and EUR only');

  return passed;
}

/**
 * server.test.ts — Server HTTP API tests.
 *
 * Hermetic: the /api/chat LLM call is mocked by stubbing
 * UniversalLlmClient.prototype.generateContent (same pattern as
 * tests/routers.test.ts) so the suite never hits the live Google API.
 */

import { createServer } from '../src/server/server.js';
import { UniversalLlmClient } from '../src/core/UniversalLlmClient.js';

export async function runServerTests(): Promise<boolean> {
  console.log('\n--- Running Server HTTP API Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // Mock the LLM layer (no live network) — mirrors tests/routers.test.ts.
  const proto: any = UniversalLlmClient.prototype;
  const origGenerate = proto.generateContent;
  const origStream = proto.streamContent;
  proto.generateContent = async function (
    _model: string,
    _messages: any[],
    _options: any = {}
  ): Promise<string> {
    return 'MOCK-LLM-REPLY';
  };
  proto.streamContent = async function (
    _model: string,
    _messages: any[],
    onChunk: (c: string) => void,
    _options: any = {}
  ): Promise<string> {
    onChunk('MOCK-LLM-REPLY');
    return 'MOCK-LLM-REPLY';
  };

  const server = createServer();
  await new Promise<void>((resolve) => {
    server.listen(0, '127.0.0.1', () => resolve());
  });
  const address = server.address() as any;
  const testPort = address.port;

  try {
    // Test /api/health
    const healthRes = await fetch(`http://127.0.0.1:${testPort}/api/health`);
    assert(healthRes.status === 200, '/api/health returns 200 OK');
    const healthJson: any = await healthRes.json();
    assert(healthJson.status === 'online', '/api/health status is online');
    assert(healthJson.availableModels >= 4, '/api/health reports models');

    // Test /api/models
    const modelsRes = await fetch(`http://127.0.0.1:${testPort}/api/models`);
    assert(modelsRes.status === 200, '/api/models returns 200 OK');
    const modelsJson: any = await modelsRes.json();
    assert(Array.isArray(modelsJson.models) && modelsJson.models.length >= 4, '/api/models lists array of models');

    // Test /api/chat error without API key
    const chatRes = await fetch(`http://127.0.0.1:${testPort}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message: 'Hello' }),
    });
    // Should be 401 if no server key, 200 with the mocked LLM reply otherwise
    assert(chatRes.status === 401 || chatRes.status === 200, `/api/chat handles key check gracefully (status ${chatRes.status})`);

  } catch (err: any) {
    console.error(`  ✗ Server test error: ${err.message}`);
    passed = false;
  } finally {
    proto.generateContent = origGenerate;
    proto.streamContent = origStream;
    await new Promise<void>((resolve) => {
      server.close(() => resolve());
    });
  }

  return passed;
}

import { UniversalLlmClient } from '../src/core/UniversalLlmClient.js';
import { CORPORATE_ROLES, KnowledgeBaseConnector } from '../src/core/CorporateRoles.js';
import { ModelRegistry } from '../src/models/ModelRegistry.js';
import { createServer } from '../src/server/server.js';

export async function runCoreEngineTests(): Promise<boolean> {
  console.log('\n--- Running Core Engine & Consilium Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // 1. UniversalLlmClient Provider Resolution
  const client = new UniversalLlmClient();
  assert(client.resolveProvider('gemini-2.5-flash') === 'google', 'Resolves gemini-2.5-flash to google');
  assert(client.resolveProvider('omniroute/deepseek-r1') === 'omniroute', 'Resolves omniroute model to omniroute');
  assert(client.resolveProvider('deepseek/deepseek-r1:free') === 'openrouter', 'Resolves openrouter free model to openrouter');
  assert(client.resolveProvider('opencode/go-coder-32b') === 'opencode', 'Resolves opencode model to opencode');
  assert(client.resolveProvider('any-model', 'omniroute') === 'omniroute', 'Explicit provider overrides default');

  // Message normalization
  const normalizedStr = client.normalizeToUniversal('Hello test');
  assert(normalizedStr.length === 1 && normalizedStr[0].content === 'Hello test', 'Normalizes string to UniversalMessage[]');

  const normalizedChat = client.normalizeToUniversal([
    { role: 'user', parts: [{ text: 'User msg' }] },
    { role: 'model', parts: [{ text: 'Assistant msg' }] },
  ]);
  assert(normalizedChat.length === 2 && normalizedChat[1].role === 'assistant', 'Normalizes ChatMessage[] to UniversalMessage[]');

  // 2. Corporate Roles & KnowledgeBaseConnector
  const roles = Object.values(CORPORATE_ROLES);
  assert(roles.length >= 4, `At least 4 corporate roles defined (found ${roles.length})`);
  assert(Boolean(CORPORATE_ROLES.architect), 'Architect role exists');
  assert(Boolean(CORPORATE_ROLES.devops), 'DevOps role exists');
  assert(Boolean(CORPORATE_ROLES.security_auditor), 'Security Auditor role exists');
  assert(Boolean(CORPORATE_ROLES.general_assistant), 'General Assistant role exists');

  // Currency compliance on role prompts
  for (const role of roles) {
    const hasRub = role.systemPrompt.includes('RUB') || role.systemPrompt.includes('₽');
    assert(!hasRub, `Role ${role.id} contains NO rubles`);
  }

  const kb = new KnowledgeBaseConnector();
  const searchResults = await kb.search('Kubernetes deployment microservices');
  assert(searchResults.length > 0, 'KnowledgeBaseConnector returns matching hybrid documents');
  assert(Boolean(searchResults[0].source), 'KnowledgeBase document contains hybrid source attribution');

  // 3. ModelRegistry additions
  const freeModels = ModelRegistry.getFreeModels();
  assert(freeModels.some((m) => m.id === 'deepseek/deepseek-r1:free'), 'deepseek/deepseek-r1:free is registered');
  assert(freeModels.some((m) => m.id === 'meta-llama/llama-3.3-70b:free'), 'meta-llama/llama-3.3-70b:free is registered');
  assert(freeModels.some((m) => m.id === 'google/gemini-2.0-flash-exp:free'), 'google/gemini-2.0-flash-exp:free is registered');
  assert(ModelRegistry.isValidModel('omniroute/gemini-2.5-pro'), 'omniroute/gemini-2.5-pro is valid');
  assert(ModelRegistry.isValidModel('opencode/go-coder-32b'), 'opencode/go-coder-32b is valid');

  // Pricing currency compliance check across all models
  for (const model of ModelRegistry.getAllModels()) {
    const p = model.pricing;
    const str = `${p.inputPer1MTokensUSD} ${p.outputPer1MTokensUSD} ${p.inputPer1MTokensEUR} ${p.outputPer1MTokensEUR} ${p.freeTierDetails}`;
    if (str.includes('RUB') || str.includes('₽')) {
      assert(false, `Model ${model.id} contains forbidden currency`);
    }
  }
  assert(true, `All ${ModelRegistry.getAllModels().length} models strictly enforce USD ($) and EUR (€) without rubles`);

  // 4. Server Endpoints Verification
  const server = createServer();
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', () => resolve()));
  const address = server.address() as any;
  const testPort = address.port;

  try {
    // GET /api/roles
    const rolesRes = await fetch(`http://127.0.0.1:${testPort}/api/roles`);
    assert(rolesRes.status === 200, 'GET /api/roles returns 200');
    const rolesJson: any = await rolesRes.json();
    assert(Array.isArray(rolesJson.roles) && rolesJson.roles.length >= 4, 'GET /api/roles returns list of roles');

    // POST /api/consilium validation
    const consiliumInvalidRes = await fetch(`http://127.0.0.1:${testPort}/api/consilium`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mode: 'invalid-mode', prompt: 'test' }),
    });
    assert(consiliumInvalidRes.status === 400, 'POST /api/consilium rejects invalid mode with 400');

    const consiliumEmptyPromptRes = await fetch(`http://127.0.0.1:${testPort}/api/consilium`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ mode: 'solo' }),
    });
    assert(consiliumEmptyPromptRes.status === 400, 'POST /api/consilium rejects missing prompt with 400');
  } finally {
    await new Promise<void>((resolve) => server.close(() => resolve()));
  }

  return passed;
}

import { UniversalLlmClient } from '../src/core/UniversalLlmClient.js';
import { Config } from '../src/core/Config.js';
import { ChatMessage } from '../src/core/GeminiClient.js';

export async function runUniversalClientTests(): Promise<boolean> {
  console.log('\n--- Running UniversalLlmClient & Multi-Provider Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  const client = new UniversalLlmClient();

  // 1. Provider Resolution Tests
  assert(client.resolveProvider('gemini-2.5-flash') === 'google', 'Resolves standard Gemini model to google provider');
  assert(client.resolveProvider('gemini-2.5-pro') === 'google', 'Resolves Gemini 2.5 Pro to google provider');
  assert(client.resolveProvider('omniroute/gpt-4o') === 'omniroute', 'Resolves omniroute/ prefix to omniroute provider');
  assert(client.resolveProvider('opencode/deepseek-r1') === 'opencode', 'Resolves opencode/ prefix to opencode provider');
  assert(client.resolveProvider('openrouter/meta-llama/llama-3.3-70b') === 'openrouter', 'Resolves openrouter/ prefix to openrouter provider');
  assert(client.resolveProvider('deepseek/deepseek-r1:free') === 'openrouter', 'Resolves deepseek-r1:free to openrouter provider');
  assert(client.resolveProvider('meta-llama/llama-3.3-70b:free') === 'openrouter', 'Resolves llama-3.3-70b:free to openrouter provider');
  assert(client.resolveProvider('google/gemini-2.0-flash-exp:free') === 'openrouter', 'Resolves gemini-2.0-flash-exp:free to openrouter provider');

  // Explicit provider override test
  assert(client.resolveProvider('gemini-2.5-flash', 'omniroute') === 'omniroute', 'Explicit provider overrides model naming convention');

  // 2. Message Normalization Tests
  const fromString = client.normalizeToUniversal('Test user message');
  assert(fromString.length === 1 && fromString[0].role === 'user' && fromString[0].content === 'Test user message', 'Normalizes string to UniversalMessage[]');

  const rawChatMsgs: ChatMessage[] = [
    { role: 'user', parts: [{ text: 'Hello bot' }] },
    { role: 'model', parts: [{ text: 'Hello human' }] },
  ];
  const fromChatMsgs = client.normalizeToUniversal(rawChatMsgs);
  assert(fromChatMsgs.length === 2, 'Normalizes ChatMessage[] length');
  assert(fromChatMsgs[0].role === 'user' && fromChatMsgs[0].content === 'Hello bot', 'Converts user role and extracts content');
  assert(fromChatMsgs[1].role === 'assistant' && fromChatMsgs[1].content === 'Hello human', 'Converts model role to assistant');

  // 3. Gemini Format Conversion Tests
  const geminiConverted = client.toGeminiFormat([
    { role: 'system', content: 'You are EvaBot, strict compliance.' },
    { role: 'user', content: 'Explain quantum computing.' },
    { role: 'assistant', content: 'Quantum computing uses qubits.' },
  ], 'Default instruction');

  assert(geminiConverted.systemInstruction?.includes('strict compliance.'), 'Extracts system role into systemInstruction');
  assert(geminiConverted.contents.length === 2, 'Excludes system message from Gemini contents');
  assert(geminiConverted.contents[0].role === 'user', 'First turn is user');
  assert(geminiConverted.contents[1].role === 'model', 'Second turn converted to model');

  // 4. Currency and Sanctions Compliance
  const sysInst = Config.defaultSystemInstruction;
  const hasRubles = sysInst.includes('RUB') || sysInst.includes('₽');
  assert(!hasRubles, 'System prompt enforces strict NO rubles policy (RUB / ₽)');
  assert(sysInst.includes('USD') && sysInst.includes('EUR'), 'System prompt strictly enforces USD ($) and EUR (€)');

  return passed;
}

import { ConsiliumEngine, ConsiliumRunOptions, ConsiliumProgressEvent, ConsiliumParticipant } from '../src/core/ConsiliumEngine.js';
import { CORPORATE_ROLES } from '../src/core/CorporateRoles.js';

export async function runConsiliumTests(): Promise<boolean> {
  console.log('\n--- Running ConsiliumEngine & Multi-Agent Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  const engine = new ConsiliumEngine();

  // 1. Participant Resolution Tests
  const participants = (engine as any).resolveParticipants({
    mode: 'broadcast',
    prompt: 'Evaluate cloud architecture',
    models: ['gemini-2.5-flash', 'gemini-2.5-pro', 'omniroute/gpt-4o'],
  });

  assert(participants.length === 3, 'Resolves participant list for 3 models');
  assert(participants[0].model === 'gemini-2.5-flash', 'Participant 1 model mapped correctly');
  assert(Boolean(participants[0].roleId), 'Participant 1 has assigned corporate role');
  assert(Boolean(participants[0].systemPrompt), 'Participant 1 has inherited role system prompt');

  // Explicit role assignment
  const customParticipants = (engine as any).resolveParticipants({
    mode: 'dialogue',
    prompt: 'Architecture review',
    participants: [
      { id: 'p1', model: 'gemini-2.5-flash', roleId: 'architect' },
      { id: 'p2', model: 'gemini-2.5-pro', roleId: 'security_auditor' },
    ],
  });

  assert(customParticipants.length === 2, 'Resolves explicit participants');
  assert(customParticipants[0].name === CORPORATE_ROLES.architect.name, 'Enriches participant with architect role name');
  assert(customParticipants[1].name === CORPORATE_ROLES.security_auditor.name, 'Enriches participant with security auditor role name');

  // Participant Bounds: 3 to 10 Validation
  // Case A: 0 participants -> auto-expands to 3
  const bounded0 = engine.validateConsiliumParticipants([]);
  assert(bounded0.length === 3, '0 participants auto-expanded to minimum 3 participants');
  assert(bounded0[0].roleId === 'architect', 'Auto-expanded participant 1 assigned architect role');
  assert(bounded0[1].roleId === 'devops', 'Auto-expanded participant 2 assigned devops role');
  assert(bounded0[2].roleId === 'security_auditor', 'Auto-expanded participant 3 assigned security_auditor role');

  // Case B: 1 participant -> auto-expands to 3
  const bounded1 = engine.validateConsiliumParticipants([
    { id: 'solo', model: 'gemini-2.5-flash', name: 'Lead Dev', roleId: 'architect' },
  ]);
  assert(bounded1.length === 3, '1 participant auto-expanded to 3 participants');
  assert(bounded1[0].id === 'solo', 'Original participant preserved at index 0');

  // Case C: 2 participants -> auto-expands to 3
  const bounded2 = engine.validateConsiliumParticipants([
    { id: 'p1', model: 'gemini-2.5-flash', name: 'P1' },
    { id: 'p2', model: 'gemini-2.5-pro', name: 'P2' },
  ]);
  assert(bounded2.length === 3, '2 participants auto-expanded to 3 participants');

  // Case D: Exactly 3 participants -> preserved
  const bounded3 = engine.validateConsiliumParticipants(participants);
  assert(bounded3.length === 3, 'Exactly 3 participants preserved without modification');

  // Case E: 5 participants -> preserved
  const list5: ConsiliumParticipant[] = Array.from({ length: 5 }, (_, i) => ({
    id: `agent-${i + 1}`,
    model: 'gemini-2.5-flash',
    name: `Agent ${i + 1}`,
  }));
  const bounded5 = engine.validateConsiliumParticipants(list5);
  assert(bounded5.length === 5, '5 participants preserved correctly');

  // Case F: Exactly 10 participants -> preserved
  const list10: ConsiliumParticipant[] = Array.from({ length: 10 }, (_, i) => ({
    id: `agent-${i + 1}`,
    model: 'gemini-2.5-flash',
    name: `Agent ${i + 1}`,
  }));
  const bounded10 = engine.validateConsiliumParticipants(list10);
  assert(bounded10.length === 10, '10 participants preserved at upper boundary');

  // Case G: 12 participants -> clamped to 10
  const list12: ConsiliumParticipant[] = Array.from({ length: 12 }, (_, i) => ({
    id: `agent-${i + 1}`,
