  // Case H: 15 participants -> clamped to 10
  const list15: ConsiliumParticipant[] = Array.from({ length: 15 }, (_, i) => ({
    id: `agent-${i + 1}`,
    model: 'gemini-2.5-flash',
    name: `Agent ${i + 1}`,
  }));
  const bounded15 = engine.validateConsiliumParticipants(list15);
