  // ============================================================================
  // 3. Mode 2: Broadcast Mode Tests (1 prompt -> all selected models in parallel)
  // ============================================================================
  mockCallCount = 0;
  const broadcastEvents: ConsiliumProgressEvent[] = [];
  const broadcastResult = await engine.run({
    mode: 'broadcast',
