  assert(consiliumEvents.some((e) => e.type === 'synthesis_complete'), 'Consilium emits synthesis_complete event');

  // Consilium 3 models, 2 rounds (3 R1 turns + 3 R2 turns = 6 turns + 1 synthesis)
