import { CORPORATE_ROLES, KnowledgeBaseConnector } from '../src/core/CorporateRoles.js';

export async function runRolesTests(): Promise<boolean> {
  console.log('\n--- Running Corporate Roles & Knowledge Base Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // 1. Verify Presets exist
  const roleKeys = Object.keys(CORPORATE_ROLES);
  assert(roleKeys.length >= 4, `At least 4 corporate roles configured (found ${roleKeys.length})`);
  assert('architect' in CORPORATE_ROLES, 'Corporate role "architect" is present');
  assert('devops' in CORPORATE_ROLES, 'Corporate role "devops" is present');
  assert('security_auditor' in CORPORATE_ROLES, 'Corporate role "security_auditor" is present');
  assert('general_assistant' in CORPORATE_ROLES, 'Corporate role "general_assistant" is present');

  // 2. Validate role schemas and currency compliance
  for (const [key, role] of Object.entries(CORPORATE_ROLES)) {
    assert(Boolean(role.id && role.name && role.title && role.department), `Role ${key} has identity metadata`);
    assert(Boolean(role.preferredModel), `Role ${key} specifies a preferred model`);
    assert(role.suggestedTemperature >= 0 && role.suggestedTemperature <= 1, `Role ${key} has valid suggested temperature`);
    assert(['public', 'internal', 'confidential', 'restricted'].includes(role.knowledgeAccessLevel), `Role ${key} has valid access level`);

    // Strict Currency and Geography checks
    const prompt = role.systemPrompt;
    const hasRub = prompt.includes('RUB') || prompt.includes('₽');
    assert(!hasRub, `Role ${key} system prompt contains NO rubles (RUB / ₽)`);
  }

  // 3. KnowledgeBaseConnector Tests
  const kb = new KnowledgeBaseConnector();
  const allDocs = kb.listAllDocuments();
  assert(allDocs.length >= 4, `Knowledge base contains indexed company documents (found ${allDocs.length})`);

  // Search by keyword
  const archDocs = await kb.search('microservices architecture');
  assert(archDocs.length > 0, 'Knowledge base search returns relevant architecture documents');
  assert(archDocs[0].category === 'architecture', 'Top search match matches category architecture');

  // Filter by category
  const secDocs = await kb.search('security', { category: 'security' });
  assert(secDocs.length > 0, 'Knowledge base search filters by category');
  assert(secDocs.every(d => d.category === 'security'), 'All returned docs belong to security category');

  // Document formatting
  const formatted = kb.formatContextForPrompt(archDocs);
  assert(formatted.includes('EVALINE HYBRID DATABASE CONTEXT'), 'Context formatter formats documents with header');
  assert(formatted.includes('doc-arch-001') || formatted.includes('EvaLine Core Microservices'), 'Context formatter contains document title or content');

  // Retrieval by ID
  const docById = await kb.getDocumentById('doc-db-004');
  assert(docById !== null && docById.id === 'doc-db-004', 'KnowledgeBaseConnector retrieves document by exact ID');

  return passed;
}

/**
 * ansi_stream_engine.test.ts
 * Automated Test Suite for AnsiStreamEngine
 */

import {
  AnsiStreamEngine,
  AnsiColors,
  stripAnsi,
  visibleWidth,
  padEndVisible,
  padStartVisible,
  toHtml,
  toPlainText,
  statusBadge,
  trafficLightIcon,
  trafficLightColor,
  TableFormatter,
  AnsiStreamWriter,
} from '../src/core/AnsiStreamEngine.js';

export async function runAnsiStreamEngineTests(): Promise<boolean> {
  console.log('\n--- Running AnsiStreamEngine Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // 1. ANSI stripping and visible width
  const styled = `${AnsiColors.green}${AnsiColors.bold}[OK] ONLINE${AnsiColors.reset}`;
  const clean = stripAnsi(styled);
  assert(clean === '[OK] ONLINE', 'stripAnsi correctly strips ANSI escape codes');
  assert(toPlainText(styled) === '[OK] ONLINE', 'toPlainText strips ANSI codes identically');

  const widthClean = visibleWidth('ONLINE');
  assert(widthClean === 6, 'visibleWidth handles ASCII standard characters');
  const widthWide = visibleWidth('中');
  assert(widthWide === 2, 'visibleWidth recognizes 2-width wide characters');

  const padded = padEndVisible('STATUS', 10);
  assert(visibleWidth(padded) === 10, 'padEndVisible correctly pads visible width');
  const paddedStart = padStartVisible('100', 6);
  assert(visibleWidth(paddedStart) === 6, 'padStartVisible correctly pads start width');

  // 2. Traffic light icons & badges (emoji-free: [OK] / [MED] / [HIGH])
  assert(trafficLightIcon('green') === '[OK]', 'trafficLightIcon returns [OK] for green');
  assert(trafficLightIcon('yellow') === '[MED]', 'trafficLightIcon returns [MED] for yellow');
  assert(trafficLightIcon('red') === '[HIGH]', 'trafficLightIcon returns [HIGH] for red');

  const greenBadge = statusBadge('online');
  assert(greenBadge.includes('[OK]') && greenBadge.includes('[ONLINE]'), 'statusBadge formats online badge with traffic light');

  const freeBadge = statusBadge('free');
  assert(freeBadge.includes('[OK]') && freeBadge.includes('[100% FREE QUOTA]'), 'statusBadge formats 100% free quota badge');

  const paidBadge = statusBadge('paid');
  assert(paidBadge.includes('[MED]') && paidBadge.includes('[PAID / METERED]'), 'statusBadge formats paid/metered badge');

  // 3. Web HTML 1:1 mapping
  const htmlOut = toHtml(`${AnsiColors.green}Active${AnsiColors.reset}`);
  assert(htmlOut.includes('color:#22c55e') && htmlOut.includes('Active'), 'toHtml correctly translates ANSI color to HTML span style');

  // 4. Formatted Monospace Table
  interface TestRow {
    name: string;
    status: string;
    price: string;
  }
  const testRows: TestRow[] = [
    { name: 'Gemini 3.8 Flash', status: '[OK] Free', price: '$0.00 / €0.00' },
    { name: 'Claude 3.7 Sonnet', status: '[MED] Paid', price: '$3.00 / €2.80' },
  ];

  const tableStr = TableFormatter.render<TestRow>(testRows, {
    columns: [
      { key: 'name', header: 'MODEL', minWidth: 18 },
      { key: 'status', header: 'STATUS', minWidth: 10 },
      { key: 'price', header: 'PRICING', minWidth: 15 },
    ],
    borderStyle: 'unicode',
  });

  assert(tableStr.includes('┌') && tableStr.includes('┘'), 'TableFormatter renders valid unicode box borders');
  assert(tableStr.includes('Gemini 3.8 Flash') && tableStr.includes('Claude 3.7 Sonnet'), 'TableFormatter renders data rows');
  assert(!tableStr.includes('RUB') && !tableStr.includes('₽'), 'Table output strictly enforces USD/EUR without rubles');

  // 5. Reactive Stream Writer
  const writer = new AnsiStreamWriter();
  const receivedLines: string[] = [];
  const receivedChunks: string[] = [];

  writer.on('chunk', (c) => receivedChunks.push(c));
  writer.on('line', (l) => receivedLines.push(l));

  writer.write('Hello ');
  writer.write('World!\nSecond line.\n');
  writer.flush();

  assert(receivedChunks.length === 2, 'AnsiStreamWriter emits chunk events');
  assert(receivedLines.length === 2, 'AnsiStreamWriter processes lines upon newline');
  assert(receivedLines[0] === 'Hello World!', 'First line extracted cleanly');
  assert(receivedLines[1] === 'Second line.', 'Second line extracted cleanly');
  assert(writer.getFullText('plain').includes('Hello World!\nSecond line.'), 'AnsiStreamWriter getFullText plain parity');

  return passed;
}

import { PluginManager } from '../src/core/plugin-system/PluginManager.js';
