export function runCommandsAndHistoryTests(): boolean {
  console.log('\n--- Running Command Aliases, ChatHistoryStore & CapitalExpenses Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // 1. Command alias normalization
  const aliasCases: Array<[string, string, string]> = [
    ['/історія', '/history', 'UK /історія → /history'],
    ['/история', '/history', 'RU /история → /history'],
    ['/hist', '/history', '/hist → /history'],
    ['/журнал', '/history', '/журнал → /history'],
    ['/пам\'ять', '/memory', "UK /пам'ять → /memory"],
    ['/пам’ять', '/memory', 'UK /пам’ять (curly) → /memory'],
    ['/пам`ять', '/memory', 'UK /пам`ять (backtick) → /memory'],
    ['/память', '/memory', 'RU /память → /memory'],
    ['/mem', '/memory', '/mem → /memory'],
    ['/памятка', '/memory', '/памятка → /memory'],
    ['/пошук', '/search', 'UK /пошук → /search'],
    ['/поиск', '/search', 'RU /поиск → /search'],
    ['/знайти', '/search', 'UK /знайти → /search'],
    ['/найти', '/search', 'RU /найти → /search'],
    ['/знайди', '/find', 'UK /знайди → /find'],
    ['/найди', '/find', 'RU /найди → /find'],
    ['/сервіси', '/services', 'UK /сервіси → /services'],
    ['/сервисы', '/services', 'RU /сервисы → /services'],
    ['/служби', '/services', 'UK /служби → /services'],
    ['/службы', '/services', 'RU /службы → /services'],
    ['/сервери', '/servers', 'UK /сервери → /servers'],
    ['/серверы', '/servers', 'RU /серверы → /servers'],
    ['/вми', '/servers', '/вми → /servers'],
    ['/vm', '/servers', '/vm → /servers'],
    ['/моделі', '/models', 'UK /моделі → /models'],
    ['/модели', '/models', 'RU /модели → /models'],
    ['/допомога', '/help', 'UK /допомога → /help'],
    ['/помощь', '/help', 'RU /помощь → /help'],
    ['/мова', '/lang', 'UK /мова → /lang'],
    ['/язык', '/lang', 'RU /язык → /lang'],
    ['/вартість', '/cost', 'UK /вартість → /cost'],
    ['/стоимость', '/cost', 'RU /стоимость → /cost'],
    ['/фінанси', '/cost', 'UK /фінанси → /cost'],
    ['/финансы', '/cost', 'RU /финансы → /cost'],
    ['/бюджет', '/cost', '/бюджет → /cost'],
    ['/бухгалтерія', '/cost', 'UK /бухгалтерія → /cost'],
    ['/бухгалтерия', '/cost', 'RU /бухгалтерия → /cost'],
    ['/очистити', '/clear', 'UK /очистити → /clear'],
    ['/очистить', '/clear', 'RU /очистить → /clear'],
    ['/очистка', '/clear', '/очистка → /clear'],
  ];

  for (const [input, expected, label] of aliasCases) {
    assert(normalizeCommand(input) === expected, label);
  }

  // Case-insensitivity, whitespace trimming and argument preservation
  assert(normalizeCommand('  /ПОШУК  gemini flash  ') === '/search gemini flash', 'Uppercase + spaces normalized, args preserved');
  assert(normalizeCommand('/TOP free') === '/top free', 'Existing commands still normalize args');
  assert(Object.keys(COMMAND_ALIASES).length >= 30, `COMMAND_ALIASES map is populated (${Object.keys(COMMAND_ALIASES).length} aliases)`);

  // Alias-backed command execution smoke tests
  const costCmdUk = ModelCommand.execute('/вартість');
  assert(costCmdUk.includes('COST LEDGER'), 'UK /вартість executes /cost (AccountingEngine report)');

  const helpCmdRu = ModelCommand.execute('/помощь');
  assert(typeof helpCmdRu === 'string' && helpCmdRu.includes('COMMANDS'), 'RU /помощь executes /help');
  const ruHelp = I18nEngine.formatHelp('ru');
  assert(ruHelp.includes('СИСТЕМНЫЕ КОМАНДЫ'), 'RU help lists the command set');
  assert(ruHelp.includes('/history'), 'Help lists the new /history command');
  assert(ruHelp.includes('/servers'), 'Help lists the new /servers command');

  // 2. ChatHistoryStore (temp DB path)
  const tmpDb = path.join(os.tmpdir(), `evabot-chat-test-${Date.now()}-${Math.floor(Math.random() * 100000)}.db`);
  const store = ChatHistoryStore.getInstance(tmpDb);
  assert(store.isReady(), `ChatHistoryStore opens a temp DB (${tmpDb})`);

  const id1 = store.appendMessage({ sessionId: 'session-a', role: 'user', content: 'Какая модель лучше для кодинга?', model: 'gemini-3.8-flash', lang: 'ru' });
  const id2 = store.appendMessage({ sessionId: 'session-a', role: 'assistant', content: 'Gemini 3.8 Flash — новейшая frontier модель с 1M контекстом.', model: 'gemini-3.8-flash', lang: 'ru' });
  const id3 = store.appendMessage({ sessionId: 'session-b', role: 'user', content: 'Яка модель найкраща для кодування Qwen або DeepSeek?', model: 'qwen-2.5-coder', lang: 'uk' });
  const id4 = store.appendMessage({ sessionId: 'consilium', role: 'assistant', content: 'Consilium synthesis: рекомендуємо Gemini 3.1 Pro для планування.', model: 'consilium', lang: 'en' });
  assert(id1 !== null && id2 !== null && id3 !== null && id4 !== null, 'appendMessage returns row ids for all messages');

  const historyA = store.getSessionHistory('session-a', 10);
  assert(historyA.length === 2, `getSessionHistory returns session-a messages (found ${historyA.length})`);
  assert(historyA[0].role === 'user' && historyA[1].role === 'assistant', 'Session history is in chronological order');

  const recent = store.getRecentMessages(10);
  assert(recent.length === 4, `getRecentMessages spans all sessions (found ${recent.length})`);
  assert(recent[recent.length - 1].sessionId === 'consilium', 'Newest message across sessions is the consilium one');

  const found = store.searchMessages('модель');
  assert(found.length >= 2, `FTS5 search finds messages by keyword (found ${found.length})`);
  const notFound = store.searchMessages('supercalifragilisticword');
  assert(Array.isArray(notFound) && notFound.length === 0, 'FTS5 search returns empty array for non-matching query');

  const sessions = store.listSessions(10);
  assert(sessions.length === 3, `listSessions lists distinct sessions (found ${sessions.length})`);
  const consiliumSession = sessions.find((s) => s.sessionId === 'consilium');
  assert(Boolean(consiliumSession), 'consilium session is persisted and listed');

  const counts = store.countAll();
  assert(counts.totalMessages === 4, `countAll counts total messages (${counts.totalMessages})`);
  assert(counts.sessions === 3, `countAll counts distinct sessions (${counts.sessions})`);

  // Error resilience: fire-and-forget append must never throw
  let threw = false;
  try {
    (store as any).db = null;
    const fallback = store.appendMessage({ sessionId: 'x', role: 'user', content: 'broken db write' });
    assert(fallback === null, 'appendMessage returns null (not throw) when DB handle is broken');
    assert(store.countAll().totalMessages === 0 || Array.isArray(store.searchMessages('модель')), 'Reads degrade gracefully when DB handle is broken');
  } catch (e) {
    threw = true;
  }
  assert(!threw, 'No exception escapes ChatHistoryStore on DB failure');

  store.close();
  try { fs.unlinkSync(tmpDb); } catch (e) { /* temp cleanup best-effort */ }

  // 3. CapitalExpenses ledger
  const capitalTotal = CapitalExpenses.getTotalCapitalUSD();
  assert(capitalTotal === 1500, `Capital investments total is exactly $1500 (found $${capitalTotal})`);
  const ledger = CapitalExpenses.getCapitalExpenses();
  assert(ledger.length === 4, `Capital ledger has 4 entries (found ${ledger.length})`);
  assert(ledger[0].item.includes('evabot-agent-vm') && ledger[0].usd === 300, 'Ledger entry #1 is the GCP server plan ($300)');
  assert(ledger[3].item.includes('Pixel 10 Pro XL') && ledger[3].usd === 1000, 'Ledger entry #4 is the Pixel 10 Pro XL ($1000)');
  assert(ledger.every((e) => e.date === '2026-09-01'), 'All capital entries are dated 2026-09-01');

  const costReport = AccountingEngine.formatCostReport();
  assert(costReport.includes('CAPITAL INVESTMENTS'), 'Cost report contains the CAPITAL INVESTMENTS section');
  assert(costReport.includes('$1500.00'), 'Cost report shows the $1500 capital total');
  assert(costReport.includes('Pixel 10 Pro XL'), 'Cost report itemizes the Pixel 10 Pro XL');

  // /cost via alias renders the same capital section
  const costViaAlias = ModelCommand.execute('/фінанси');
  assert(costViaAlias.includes('CAPITAL INVESTMENTS'), 'UK /фінанси (alias of /cost) includes capital section');

  return passed;
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { ProductCatalog, Product } from '../src/core/ProductCatalog.js';
import { CompanyKnowledge } from '../src/core/CompanyKnowledge.js';
import { ModelCommand, normalizeCommand, COMMAND_ALIASES } from '../src/models/ModelRatings.js';
import { CORPORATE_ROLES } from '../src/core/CorporateRoles.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const dataPath = path.resolve(here, '../data/products.json');

export function runProductsTests(): boolean {
  console.log('\n--- Running ProductCatalog, CompanyKnowledge & /products // /who Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // 1. Product DB file exists and is valid JSON with products array
  assert(fs.existsSync(dataPath), `data/products.json exists at ${dataPath}`);
  const raw = JSON.parse(fs.readFileSync(dataPath, 'utf8'));
  assert(Array.isArray(raw.products) && raw.products.length > 0, 'products.json has a non-empty products array');
  assert(typeof raw.updatedAt === 'string', 'products.json has updatedAt');

  // 2. Catalog loads
  const products: Product[] = ProductCatalog.getProducts();
  assert(products.length === raw.products.length, `ProductCatalog.getProducts() count (${products.length}) matches JSON (${raw.products.length})`);
  assert(products.every((p) => p.id && p.name?.en && p.name?.uk && p.name?.ru && p.category), 'every product has id, en/uk/ru names and category');

  // 3. Stats counts match JSON
  const st = ProductCatalog.stats();
  assert(st.total === raw.products.length, 'stats().total matches products count');
  const sumByCat = Object.values(st.byCategory).reduce((a, b) => a + b, 0);
  assert(sumByCat === raw.products.length, 'sum of per-category counts equals total product count');
  assert(Object.keys(st.byCategory).length > 0, 'stats has at least one category');

  // 4. byCategory works
  const kids = ProductCatalog.byCategory('kids');
  assert(kids.length === (st.byCategory['kids'] || 0), `byCategory('kids') matches stats (${kids.length})`);
  assert(ProductCatalog.byCategory('KIDS ').length === kids.length, 'byCategory is case/trim-insensitive');

  // 5. Search works (EN + UK + RU + attribute)
  assert(ProductCatalog.search('tatami').some((p) => p.id.includes('tatami')), "search('tatami') finds tatami product");
  assert(ProductCatalog.search('бурьонка').length > 0, "search('бурьонка') finds livestock mats (UK)");
  assert(ProductCatalog.search('бурёнка').length > 0, "search('бурёнка') finds livestock mats (RU)");
  assert(ProductCatalog.search('EN 71 nonexist').length === 0, 'search of a non-existing string returns empty');
  assert(ProductCatalog.search('2000x1250').some((p) => p.id === 'car-mat-sheets'), "search('2000x1250') finds car mat sheets by size");

  // 6. New command aliases resolve
  const aliasCases: Array<[string, string]> = [
    ['/продукти', '/products'],
    ['/продукты', '/products'],
    ['/товари', '/products'],
    ['/товары', '/products'],
    ['/catalog', '/products'],
    ['/каталог', '/products'],
    ['/хто', '/who'],
    ['/кто', '/who'],
    ['/роли', '/who'],
    ['/ролі', '/who'],
  ];
  for (const [alias, canonical] of aliasCases) {
    assert(COMMAND_ALIASES[alias] === canonical, `${alias} → ${canonical}`);
    assert(normalizeCommand(alias).startsWith(canonical), `normalizeCommand(${alias}) → ${canonical}`);
  }

  // 7. /products default output: stats + category list
  const def = ModelCommand.execute('/products');
  assert(def.includes('PRODUCT CATALOG'), '/products output contains catalog title');
  for (const cat of ProductCatalog.getCategories()) {
    assert(def.includes(cat), `/products default output lists category "${cat}"`);
  }
  assert(def.includes(`: ${raw.products.length}`), '/products stats shows total product count');

  // 8. /products filtered by category and by query
  const byCatOut = ModelCommand.execute('/products livestock');
  assert(byCatOut.includes('Burenka'), "/products livestock lists 'Burenka' mats");
  const byQueryOut = ModelCommand.execute('/products puzzle');
  assert(byQueryOut.length > 0 && !byQueryOut.includes('[ERROR]'), "/products puzzle returns filtered results");
  const none = ModelCommand.execute('/products zzz-nonexistent');
  assert(none.includes('No products match') || none.includes('не знайдено'), "/products <unknown> shows no-match message");

  // 9. /who matrix + role detail
  const whoAll = ModelCommand.execute('/who');
  assert(whoAll.includes('KNOWLEDGE MATRIX'), '/who contains knowledge matrix title');
  for (const roleId of Object.keys(CompanyKnowledge.getMatrix())) {
    assert(Object.prototype.hasOwnProperty.call(CORPORATE_ROLES, roleId), `matrix roleId "${roleId}" exists in CORPORATE_ROLES`);
    assert(whoAll.includes(roleId), `/who matrix lists role "${roleId}"`);
  }
  const whoCfo = ModelCommand.execute('/who cfo');
  assert(whoCfo.includes('CFO') && whoCfo.includes('budget planning'), '/who cfo shows CFO domains');
  const whoAlias = ModelCommand.execute('/кто cto');
  assert(whoAlias.includes('CTO'), '/кто cto resolves alias and shows CTO');
  const whoUnknown = ModelCommand.execute('/who nobody-here');
  assert(whoUnknown.includes('Unknown role') || whoUnknown.includes('Невідома') || whoUnknown.includes('Неизвестная'), '/who <unknown> shows unknown-role message');

  // 10. /company enrichment contains knowledge matrix + product stats
  const company = ModelCommand.execute('/company');
  assert(company.includes('KNOWLEDGE MATRIX'), '/company output enriched with knowledge matrix');
  assert(company.includes('data/products.json'), '/company output references product DB source');
  assert(company.includes(`products`), '/company output shows product stats');

  // 11. Localized help includes new commands (en/uk/ru)
  const helpEn = ModelCommand.execute('/help');
  assert(helpEn.includes('/products') && helpEn.includes('/who'), 'EN help lists /products and /who');

  console.log('  (ProductsTests finished)');
  return passed;
}

import { splitTelegramMessage, TelegramBot } from '../src/telegram/TelegramBot.js';
import { normalizeCommand, ModelCommand } from '../src/models/ModelRatings.js';
import { Config } from '../src/core/Config.js';

async function runTelegramTests(): Promise<boolean> {
  console.log('================================================================');
  console.log('🤖 TELEGRAM BOT TESTS');
  console.log('================================================================\n');

  let passed = 0;
  let failed = 0;

  const test = (name: string, condition: boolean, detail: string = '') => {
    if (condition) {
      passed++;
      console.log(`  ✓ ${name}`);
    } else {
      failed++;
      console.error(`  ✗ ${name} ${detail}`);
    }
  };

  // --- 1. Chunking: short message stays intact ---
  const short = 'Hello, EvaBot!';
  const shortChunks = splitTelegramMessage(short);
  test('short message → single chunk', shortChunks.length === 1 && shortChunks[0] === short);

  // --- 2. Chunking: long message is split within the 4096 limit ---
  const longText = Array.from({ length: 400 }, (_, i) => `Line ${i + 1}: ${'x'.repeat(50)}`).join('\n');
  const longChunks = splitTelegramMessage(longText);
  test('long message split into ≤4096 chunks', longChunks.length > 1 && longChunks.every((c) => c.length <= 4096),
    `chunks=${longChunks.length} lens=${longChunks.map((c) => c.length).join(',')}`);

  // --- 3. Chunking: no content lost ---
  const rejoined = longChunks.join(' ');
  const originalWords = longText.replace(/\s+/g, ' ').trim().split(' ').length;
  const rejoinedWords = rejoined.replace(/\s+/g, ' ').trim().split(' ').length;
  test('chunking preserves content volume', originalWords === rejoinedWords,
    `original=${originalWords} rejoined=${rejoinedWords}`);

  // --- 4. Chunking: unbreakable wall of text is hard-cut ---
  const wall = 'a'.repeat(9000);
  const wallChunks = splitTelegramMessage(wall);
  test('unbroken text hard-cut at limit', wallChunks.length === Math.ceil(9000 / 4096) && wallChunks.every((c) => c.length <= 4096),
    `chunks=${wallChunks.length} lens=${wallChunks.map((c) => c.length).join(',')}`);

  // --- 5. Chunking: empty input ---
  test('empty input → no chunks', splitTelegramMessage('').length === 0);

  // --- 6. Command normalization via the shared alias map ---
  test('/моделі → /models', normalizeCommand('/моделі') === '/models');
  test('/история 5 → /history 5', normalizeCommand('/история 5') === '/history 5');
  test('/top args preserved', normalizeCommand('/top free 5') === '/top free 5');

  // --- 7. Mocked execute: command flows through normalizeCommand into the engine ---
  const received: string[] = [];
  const mockExecutor = (command: string): string => {
    received.push(command);
    return `MOCK:${command}`;
  };
  const bot = new TelegramBot({ token: 'test-token', execute: mockExecutor });

  test('bot accepts injected executor', Boolean(bot));

  // Simulate the exact path handleCommand uses: normalize then execute
  const rawUkInput = '/моделі';
  const normalized = normalizeCommand(rawUkInput);
  const out = mockExecutor(normalized);
  test('ukrainian alias reaches engine normalized', received.includes('/models') && out === 'MOCK:/models');

  // --- 8. Per-chat locale map defaults and switching ---
  test('default locale en', bot.getChatLocale(111) === 'en');

  // --- 9. Real (non-mocked) shared engine smoke: /help executes synchronously ---
  const helpOut = ModelCommand.execute('/help');
  test('ModelCommand.execute(/help) returns help banner', helpOut.includes('SYSTEM COMMANDS') || helpOut.includes('КОМАНДИ') || helpOut.includes('КОМАНДЫ'));

  // --- 10. Config exposes telegram token field ---
  test('Config.telegramBotToken field exists', typeof Config.telegramBotToken === 'string');

  console.log('\n----------------------------------------------------------------');
  console.log(`Telegram tests: ${passed} passed, ${failed} failed`);
  console.log('----------------------------------------------------------------\n');
  return failed === 0;
}

export { runTelegramTests };

/**
 * resilience.test.ts — CircuitBreaker, withTimeout, ProviderFallbackChain
 * and NewsEngine (tag sets + formatNews grouping) tests.
 */

import { CircuitBreaker, withTimeout, ProviderFallbackChain, getBreaker, BREAKERS, BREAKER_PROVIDER_NAMES } from '../src/core/Resilience.js';
import { NewsEngine, NEWS_TAGS, NewsItem } from '../src/core/NewsEngine.js';
import { ModelCommand, COMMAND_ALIASES, normalizeCommand } from '../src/models/ModelRatings.js';
import { I18nEngine } from '../src/core/I18nEngine.js';

export async function runResilienceTests(): Promise<boolean> {
  console.log('\n--- Running Resilience (Breakers/Timeout) & NewsEngine Tests ---');
  let passed = true;

  // Reset all breakers to a fresh closed state: earlier suites in the same
  // process may have opened omniroute/openrouter breakers via LLM calls.
  for (const p of BREAKER_PROVIDER_NAMES) {
    getBreaker(p).recordSuccess();
  }

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // 1. CircuitBreaker opens after 3 consecutive failures
  {
    const b = new CircuitBreaker('test-open');
    assert(b.getState() === 'closed', 'fresh breaker starts closed');
    b.recordFailure(new Error('e1'));
    b.recordFailure(new Error('e2'));
    assert(b.getState() === 'closed', 'breaker still closed after 2 failures');
    b.recordFailure(new Error('e3'));
    assert(b.getState() === 'open', 'breaker opens after 3 consecutive failures');
    assert(b.canAttempt() === false, 'canAttempt() false while breaker open');
    const snap = b.snapshot();
    assert(snap.lastError === 'e3' && snap.state === 'open', 'snapshot carries last error + open state');
  }

  // 2. Half-open probe after cooldown (real timers, tiny cooldown)
  {
    const b = new CircuitBreaker('test-cooldown');
    b.cooldownMs = 50;
    b.recordFailure(new Error('boom'));
    b.recordFailure(new Error('boom'));
    b.recordFailure(new Error('boom'));
    assert(b.getState() === 'open', 'open before cooldown');
    await sleep(60);
    assert(b.getState() === 'half-open', 'breaker transitions to half-open after cooldown');
    assert(b.canAttempt() === true, 'half-open admits a probe');
    b.recordSuccess();
    assert(b.getState() === 'closed', 'successful probe closes the breaker');
  }

  // 3. withTimeout rejects on a hanging promise and resolves on fast promise
  {
    const slow = new Promise<string>((resolve) => setTimeout(() => resolve('late'), 500));
    const t0 = Date.now();
    let rejected = false;
    let msg = '';
    try {
      await withTimeout(slow, 50, 'slow-op');
    } catch (err: any) {
      rejected = true;
      msg = err.message;
    }
    assert(rejected, 'withTimeout rejects a hanging promise');
    assert(msg.includes('[TIMEOUT]') && msg.includes('slow-op'), `timeout error is labeled (${msg})`);
    assert(Date.now() - t0 < 400, 'withTimeout rejects at the deadline, not the promise duration');

    const fast = withTimeout(Promise.resolve('ok'), 1000, 'fast-op');
    assert((await fast) === 'ok', 'withTimeout passes through fast resolutions');
  }

  // 4. Fallback chain skips candidates behind an open breaker
  {
    // Open the 'google' breaker via a dedicated breaker in the registry map
    const googleBreaker = getBreaker('google');
    googleBreaker.recordFailure(new Error('f1'));
    googleBreaker.recordFailure(new Error('f2'));
    googleBreaker.recordFailure(new Error('f3'));
    assert(googleBreaker.getState() === 'open', 'google breaker opened for chain test');

    const chain = new ProviderFallbackChain();
    const candidates = [
      'gemini-3.8-flash',              // → google (open — must be skipped)
      'omniroute/gemini-3.8-flash',    // → omniroute (closed — must survive)
      'qwen/qwen-2.5-coder-32b-instruct:free', // → openrouter (closed — must survive)
    ];
    const healthy = chain.filterHealthy(candidates);
    assert(!healthy.includes('gemini-3.8-flash'), 'open-breaker candidate skipped');
    assert(healthy.includes('omniroute/gemini-3.8-flash'), 'omniroute candidate kept');
    assert(healthy.includes('qwen/qwen-2.5-coder-32b-instruct:free'), 'openrouter candidate kept');
    assert(chain.getEvents().some((e) => e.outcome === 'skipped-open-breaker'), 'skip event recorded');

    // restore google to closed so later suites are unaffected
    googleBreaker.recordSuccess();
  }

  // 5. Static BREAKERS registry covers the provider fleet
  {
    for (const p of ['google', 'omniroute', 'openrouter', 'hf', 'zai', 'groq', 'cerebras', 'cloudflare', 'mistral']) {
      assert(BREAKERS[p] instanceof CircuitBreaker, `BREAKERS registry contains "${p}"`);
    }
  }

  // 6. Health report renders a text table
  {
    const report = ProviderFallbackChain.getHealthReport();
    assert(report.includes('google') && report.includes('omniroute'), 'health report lists providers');
    assert(report.includes('ПОСЛЕДНИЕ 5 ОШИБОК'), 'health report has last-5-errors section');
  }

  // 7. NewsEngine tag sets contain required keywords
  {
    const allKeywords = Object.values(NEWS_TAGS).flatMap((c) => c.keywords.map((k) => k.toLowerCase()));
    const allQueries = Object.values(NEWS_TAGS).flatMap((c) => c.queries.map((k) => k.toLowerCase()));
    const has = (needle: string, pool: string[]) => pool.some((k) => k.includes(needle));
    assert(has('одеса', allKeywords) || has('odessa', allKeywords), 'war/regional keywords include Odesa (uk/en)');
    assert(has('eva', allKeywords) && (has('foam', allKeywords) || has('піна', allKeywords) || has('пена', allKeywords)), 'eva-foam keywords present');
    assert(has('повітряна тривога', allKeywords), 'war_security keywords include "Повітряна тривога"');
    assert(has('бпла', allKeywords), 'war_security keywords include БПЛА');
    assert(has('гривня', allKeywords) || has('нбу', allKeywords), 'business_economy keywords include hryvnia/NBU');
    assert(has('en71', allKeywords) || has('en 71', allKeywords), 'trends_product keywords include EN71');
    assert(has('evaline', allKeywords), 'company_visibility keywords include Evaline');
    assert(allQueries.length >= 6, `each category has Google News queries (${allQueries.length} total)`);
    assert(has('black sea', allKeywords) || has('чорне море', allKeywords), 'black sea keyword present');
    for (const tag of Object.values(NEWS_TAGS)) {
      assert(tag.aliases.length > 0 && tag.labels.uk && tag.labels.ru && tag.labels.en, `tag ${tag.id} has aliases + 3 labels`);
    }
  }

  // 8. Tag alias resolution
  {
    assert(NewsEngine.resolveTag('war') === 'war_security', "alias 'war' → war_security");
    assert(NewsEngine.resolveTag('одеса') === 'region_odessa', "alias 'одеса' → region_odessa");
    assert(NewsEngine.resolveTag('eva') === 'market_eva_foam', "alias 'eva' → market_eva_foam");
    assert(NewsEngine.resolveTag('evaline') === 'company_visibility', "alias 'evaline' → company_visibility");
    assert(NewsEngine.resolveTag('nonexistent-tag') === null, 'unknown tag resolves to null');
  }

  // 9. formatNews groups items by category and renders top items
  {
    const mk = (title: string, url: string, category: NewsItem['category']): NewsItem => ({
      title, url, source: 'TestSource', date: new Date('2026-09-01T10:00:00Z').toISOString(), category,
    });
    const items: NewsItem[] = [
      mk('Odesa port struck by drones', 'https://example.com/1', 'war_security'),
      mk('Hryvnia strengthens against USD', 'https://example.com/2', 'business_economy'),
      mk('New EVA foam plant opens', 'https://example.com/3', 'market_eva_foam'),
      mk('Odesa port struck by drones!', 'https://example.com/4', 'war_security'), // near-dup
    ];
    const deduped = NewsEngine.dedupeByTitle(items);
    assert(deduped.length === 3, `dedupeByTitle removes near-duplicates (${deduped.length} kept)`);

    const text = NewsEngine.formatNews('uk', deduped);
    assert(text.includes('НОВИНИ EVALINE'), 'formatNews header present');
    assert(text.includes('Війна та безпека'), 'formatNews groups war_security with UK label');
    assert(text.includes('Ринок EVA-пени'.replace('пени', 'піни')) || text.includes('Ринок EVA-піни'), 'formatNews groups market_eva_foam');
    assert(text.includes('Бізнес та економіка'), 'formatNews groups business_economy');
    assert(text.includes('Odesa port struck by drones'), 'formatNews renders item title');
    assert(text.includes('https://example.com/1'), 'formatNews renders item link');
    assert(text.includes('TestSource'), 'formatNews renders item source');

    const ruText = NewsEngine.formatNews('ru', deduped);
    assert(ruText.includes('Война и безопасность'), 'formatNews supports ru labels');
  }

  // 10. /news and /health registered in the command registry (sync paths)
  {
    assert(normalizeCommand('/новини') === '/news', 'UK /новини → /news');
    assert(normalizeCommand('/новости') === '/news', 'RU /новости → /news');
    assert(normalizeCommand('/новини odessa') === '/news odessa', 'news args preserved');
    assert(normalizeCommand('/здоров\'я') === '/health', "UK /здоров'я → /health");
    assert(normalizeCommand('/здоровье') === '/health', 'RU /здоровье → /health');
    assert(normalizeCommand('/статус-моделей') === '/health', '/статус-моделей → /health');
    assert(COMMAND_ALIASES['/новини'] === '/news' && COMMAND_ALIASES['/новости'] === '/news', 'COMMAND_ALIASES contains /news aliases');

    const healthOut = ModelCommand.execute('/health');
    assert(typeof healthOut === 'string' && healthOut.includes('HEALTH'), '/health executes via registry');
    const healthUk = ModelCommand.execute('/статус-моделей');
    assert(healthUk.includes('HEALTH'), '/статус-моделей executes /health');

    const newsSync = ModelCommand.execute('/news');
    assert(typeof newsSync === 'string' && newsSync.length > 0, '/news sync path returns text (cache or warm-up notice)');

    // help entries registered in all 3 locales
    for (const locale of ['en', 'uk', 'ru'] as const) {
      const help = I18nEngine.formatHelp(locale);
      assert(help.includes('/news'), `help (${locale}) lists /news`);
      assert(help.includes('/health'), `help (${locale}) lists /health`);
    }
  }

  // 11. executeAsync /news path (network may be sandboxed — must not throw)
  {
    try {
      const out = await ModelCommand.executeAsync('/news');
      assert(typeof out === 'string' && out.length > 0, 'executeAsync(/news) returns formatted digest or error text');
    } catch (err: any) {
      assert(false, `executeAsync(/news) threw unexpectedly: ${err.message}`);
    }
  }

  return passed;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * debug_log.test.ts — OpLog (ring buffer, query filters, JSONL persistence +
 * rotation), DebugContext gating, /log / /debug / /monitor command behavior
 * and multilingual alias resolution.
 */

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { OpLog, setDebugOn, isDebugOn, startSpan, renderDebugFooter } from '../src/core/OpLog.js';
import { ModelCommand, normalizeCommand } from '../src/models/ModelRatings.js';

export async function runDebugLogTests(): Promise<boolean> {
  console.log('\n--- Running Debug/OpLog Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // Isolated temp workspace for persistence tests
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'evalog-'));
  const jsonlPath = path.join(tmpDir, 'operations.jsonl');

  // 1. Ring buffer: caps at 1000 entries, drops the oldest
  {
    setDebugOn(true); // ensure all levels recorded for this test
    const log = new OpLog({ filePath: path.join(tmpDir, 'ring.jsonl') });
    for (let i = 0; i < 1010; i++) {
      log.log('info', 'system', `entry-${i}`);
    }
    const all = log.query({ limit: 2000 });
    assert(all.length === 1000, `ring buffer caps at 1000 entries (got ${all.length})`);
    assert(all[0].text === 'entry-1009', 'newest-first ordering (head = entry-1009)');
    assert(all[all.length - 1].text === 'entry-10', 'oldest 10 entries evicted from the ring');
  }

  // 2. Query filters: level, kind, textLike, since, limit
  {
    const log = new OpLog({ filePath: path.join(tmpDir, 'query.jsonl') });
    const base = Date.now() - 10_000;
    log.log('info', 'command', '/top free');
    log.log('error', 'llm', 'provider=google model=x fail: boom');
    log.log('warn', 'breaker', 'google → open');
    log.log('info', 'llm', 'provider=google model=y latencyMs=12 ok');
    const byLevel = log.query({ limit: 10, level: 'error' });
    assert(byLevel.length === 1 && byLevel[0].kind === 'llm', 'query filters by level');
    const byKind = log.query({ limit: 10, kind: 'command' });
    assert(byKind.length === 1 && byKind[0].text === '/top free', 'query filters by kind');
    const byText = log.query({ limit: 10, textLike: 'BOOM' });
    assert(byText.length === 1, 'textLike filter is case-insensitive substring match');
    const limited = log.query({ limit: 2 });
    assert(limited.length === 2, 'query respects limit');
    assert(limited[0].ts >= limited[1].ts, 'query returns newest first');
    const sinceNow = log.query({ limit: 10, since: base + 60_000 });
    assert(sinceNow.length === 0, 'since filter excludes older entries');
    const sincePast = log.query({ limit: 10, since: base - 60_000 });
    assert(sincePast.length === 4, 'since in the past keeps all entries');
  }

  // 3. JSONL persistence + rotation (injectable path + small rotate threshold)
  {
    const rotatePath = path.join(tmpDir, 'rot.jsonl');
    const log = new OpLog({ filePath: rotatePath, rotateBytes: 300 });
    for (let i = 0; i < 20; i++) {
      log.log('info', 'system', `rotation-test-entry-${i}-${'x'.repeat(30)}`);
    }
    assert(fs.existsSync(rotatePath), 'JSONL file created at injected path');
    const rotated = fs.existsSync(rotatePath + '.1');
    assert(rotated, 'rotation produced operations.jsonl.1 when threshold exceeded');
    const lines = fs.readFileSync(rotatePath, 'utf8').trim().split('\n');
    assert(lines.length > 0, 'JSONL file has content after rotation');
    let validJson = true;
    for (const l of lines) {
      try { JSON.parse(l); } catch { validJson = false; }
    }
    assert(validJson, 'every JSONL line parses as a valid entry object');
    const last = JSON.parse(lines[lines.length - 1]);
    assert(last.level === 'info' && last.kind === 'system' && typeof last.ts === 'number', 'entry schema {ts,level,kind,text}');
    assert(fs.statSync(rotatePath).size < 600, 'post-rotation file stays under 2x threshold');
  }

  // 4. log() never throws + debug gating
  {
    const log = new OpLog({ filePath: path.join(tmpDir, 'gate.jsonl') });
    setDebugOn(false);
    log.log('debug', 'llm', 'should be skipped while debug off');
    log.log('error', 'system', 'errors always recorded even when debug off');
    assert(log.query({ limit: 10, level: 'debug' }).length === 0, 'debug entries skipped while debug flag OFF');
    assert(log.query({ limit: 10, level: 'error' }).length === 1, 'error entries recorded regardless of debug flag');
    setDebugOn(true);
    log.log('debug', 'llm', 'now recorded');
    assert(log.query({ limit: 10, level: 'debug' }).length === 1, 'debug entries recorded while debug flag ON');
    // Never-throw contract: log to an impossible path must not throw
    // (/dev/null/... fails fast with ENOTDIR; /proc paths can hang mkdirSync).
    const bad = new OpLog({ filePath: '/dev/null/definitely/not/writable/ops.jsonl' });
    let threw = false;
    try { bad.log('info', 'system', 'must not throw'); } catch { threw = true; }
    assert(!threw, 'log() never throws even when persistence fails');
  }

  // 5. DebugSpan + footer rendering
  {
    setDebugOn(true);
    const span = startSpan('gemini-2.5-flash', 'google');
    span.end('no');
    assert(span.ended && typeof span.latencyMs === 'number' && span.latencyMs! >= 0, 'span.end() records latency');
    const footer = renderDebugFooter(span);
    assert(footer.startsWith('* debug: model=gemini-2.5-flash provider=google latency='), 'footer format matches * debug spec');
    span.end(); // second end() is a no-op
    assert(renderDebugFooter(span) === footer, 'span.end() is idempotent');
    setDebugOn(false);
  }

  // 6. /debug command: status / on / off toggle
  {
    setDebugOn(false);
    const status0 = ModelCommand.execute('/debug status');
    assert(status0.includes('Debug mode: OFF'), '/debug status reports OFF');
    ModelCommand.execute('/debug on');
    assert(isDebugOn() === true, '/debug on sets the flag');
    ModelCommand.execute('/debug off');
    assert(isDebugOn() === false, '/debug off clears the flag');
    const full = ModelCommand.execute('/debug full');
    assert(full.includes('DEBUG FULL'), '/debug full renders diagnostics header');
    assert(full.includes('Node ') && full.includes('OPLOG'), '/debug full includes node + OpLog stats');
    assert(full.includes('chat-history.db') && full.includes('operations.jsonl'), '/debug full lists DB paths');
  }

  // 7. /log output format
  {
    const out = ModelCommand.execute('/log');
    assert(out.includes('ЖУРНАЛ ОПЕРАЦІЙ'), '/log renders the header');
    assert(/^\s{2}\d{2}:\d{2}:\d{2} /m.test(out), 'entries formatted as HH:MM:SS');
    assert(out.includes('Tip: /debug on'), '/log shows the /debug interaction tip');
    const five = ModelCommand.execute('/log 5');
    const dataLines = five.split('\n').filter((l) => /^\s{2}\d{2}:\d{2}:\d{2} /.test(l));
    assert(dataLines.length <= 5, '/log 5 limits output to 5 entries');
    const errOnly = ModelCommand.execute('/log error');
    assert(errOnly.includes('level=error'), '/log error applies the level filter');
  }

  // 8. /monitor command (report exists in repo)
  {
    const out = ModelCommand.execute('/monitor');
    assert(
      out.includes('TOP-10') || out.includes('model-monitor.py'),
      '/monitor returns report sections or a fallback instruction'
    );
  }

  // 9. Aliases resolve (EN / UK / RU)
  {
    assert(normalizeCommand('/дебаг status') === '/debug status', "alias '/дебаг' → '/debug'");
    assert(normalizeCommand('/отладка') === '/debug', "alias '/отладка' → '/debug'");
    assert(normalizeCommand('/наладка') === '/debug', "alias '/наладка' → '/debug'");
    assert(normalizeCommand('/лог 50') === '/log 50', "alias '/лог' → '/log' (args preserved)");
    assert(normalizeCommand('/журнал-лог') === '/log', "alias '/журнал-лог' → '/log'");
    assert(normalizeCommand('/логи') === '/log', "alias '/логи' → '/log'");
    assert(normalizeCommand('/монитор') === '/monitor', "alias '/монитор' → '/monitor'");
    assert(normalizeCommand('/рейтинг') === '/monitor', "alias '/рейтинг' → '/monitor'");
    assert(normalizeCommand('/топ-моделей') === '/monitor', "alias '/топ-моделей' → '/monitor'");
    assert(ModelCommand.execute('/дебаг status').includes('Debug mode:'), '/debug works through the alias path');
  }

  // Cleanup temp workspace
  try {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  } catch {
    /* best effort */
  }

  console.log('--- Debug/OpLog Tests Complete ---');
  return passed;
}

/**
