  // 2. Arg parsing: '/translate uk текст' and error cases (original casing kept)
  {
    const ok = ModelCommand.parseTranslateCommand('/translate uk Привіт світ');
    assert(ok.to === 'uk' && ok.text === 'Привіт світ', 'parseTranslateCommand extracts target + original-case text');
    const en = ModelCommand.parseTranslateCommand('/translate en какой прогноз цен на EVA');
    assert(en.to === 'en' && en.text === 'какой прогноз цен на EVA', 'parseTranslateCommand handles the /translate en example');
    const aliased = ModelCommand.parseTranslateCommand('/переклад en Hello World');
    assert(aliased.to === 'en' && aliased.text === 'Hello World', 'parseTranslateCommand resolves aliases and keeps case');
    assert(!!ModelCommand.parseTranslateCommand('/translate uk').error, 'missing text → usage error');
    assert(!!ModelCommand.parseTranslateCommand('/translate Привіт світ').error, 'missing target lang → usage error');
    assert(ModelCommand.parseTranslateCommand('/news today').error === 'not-a-translate-command', 'non-translate command is rejected by parser');
  }

  // 3. Request-body builder (v3 shape)
  {
    const body = buildTranslateBody(['Привіт', 'Світ'], 'en');
    assert(body.targetLanguageCode === 'en' && Array.isArray(body.contents) && (body.contents as string[]).length === 2, 'body has targetLanguageCode + contents[]');
    assert(body.mimeType === 'text/plain', 'body uses text/plain mimeType');
    const withSrc = buildTranslateBody(['hi'], 'uk', 'en');
    assert(withSrc.sourceLanguageCode === 'en', 'explicit source is included when given');
    assert(!('sourceLanguageCode' in body), 'auto-detect omits sourceLanguageCode');
  }

  // 4. Batch splitting (max 128 fragments/request)
  {
    assert(TRANSLATE_MAX_FRAGMENTS_PER_REQUEST === 128, 'v3 batch limit is 128 fragments');
    const many = Array.from({ length: 257 }, (_, i) => `f${i}`);
    const batches = splitIntoBatches(many);
    assert(batches.length === 3, '257 fragments split into 3 batches');
    assert(batches[0].length === 128 && batches[1].length === 128 && batches[2].length === 1, 'batch sizes are 128/128/1');
    const flat = batches.flat();
    assert(flat.length === 257 && flat[0] === 'f0' && flat[256] === 'f256', 'batches preserve order and content');
  }

  // 5. Usage cap: refusal when the call would cross the 480k soft cap
  {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'translate-test-'));
    const usagePath = path.join(tmpDir, 'translate-usage.json');
    const tr = new Translator({
      usageFilePath: usagePath,
      fetchFn: (async () => { throw new Error('must not be called'); }) as unknown as typeof fetch,
      getCredentials: (async () => ({ token: 'fake', type: 'bearer', source: 'test', account: 'test' })) as any,
    });
    fs.writeFileSync(usagePath, JSON.stringify({ month: tr.getUsage().month, chars: TRANSLATE_MONTHLY_CAP - 5 }), 'utf8');
    const res = await tr.translate('всього п\'ять символів', 'en');
    assert(!res.ok, 'translate() refuses when cap would be crossed');
    assert(res.error!.includes(String(TRANSLATE_MONTHLY_CAP).replace('_', '')) || res.error!.includes('480'), 'refusal message names the cap');
    assert(res.error!.includes('вичерпано') || res.error!.includes('ліміт'), 'refusal message is user-readable (uk)');
    const persisted = JSON.parse(fs.readFileSync(usagePath, 'utf8'));
    assert(persisted.chars === TRANSLATE_MONTHLY_CAP - 5, 'counter unchanged after refusal');
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }

  // 6. Happy path with mocked fetch: batching, usage persistence, header check
  {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'translate-test-'));
    const usagePath = path.join(tmpDir, 'translate-usage.json');
    const frags = Array.from({ length: 129 }, (_, i) => `frag-${i}`);
    let called = 0;
    const seenBodies: any[] = [];
    let seenHeaders: any = null;
    const fetchStub = (async (url: any, init?: any) => {
      called++;
      seenHeaders = init.headers;
      seenBodies.push(JSON.parse(init.body));
      const contents = JSON.parse(init.body).contents as string[];
      return new Response(
        JSON.stringify({
          translations: contents.map((c: string) => ({ translatedText: `EN:${c}`, detectedLanguageCode: 'uk' })),
        }),
        { status: 200, headers: { 'Content-Type': 'application/json' } }
      );
    }) as unknown as typeof fetch;

    const tr = new Translator({
      usageFilePath: usagePath,
      fetchFn: fetchStub,
      getCredentials: (async () => ({ token: 'ya29.fake', type: 'bearer', source: 'test', account: 'test' })) as any,
    });
    const res = await tr.translate(frags, 'en', 'uk');
    assert(res.ok && res.translations.length === 129 && res.translations[0] === 'EN:frag-0', 'all fragments translated in order');
    assert(called === 2, '129 fragments → exactly 2 HTTP requests (128 + 1)');
    assert(seenBodies[0].contents.length === 128 && seenBodies[1].contents.length === 1, 'first batch 128, second batch 1');
    assert(seenBodies[0].targetLanguageCode === 'en' && seenBodies[0].sourceLanguageCode === 'uk', 'body carries target + source');
    assert(seenHeaders['Authorization'] === 'Bearer ya29.fake', 'Authorization: Bearer token header');
    assert(seenHeaders['X-Goog-User-Project'] === 'evabot-agent-server', 'REQUIRED X-Goog-User-Project header');
    assert(res.usage.chars === frags.reduce((s, f) => s + f.length, 0), 'usage counter += requested characters');
    const persisted = JSON.parse(fs.readFileSync(usagePath, 'utf8'));
    assert(persisted.chars === res.usage.chars && !!persisted.month, 'usage persisted to translate-usage.json');
    assert(TRANSLATE_FREE_TIER_CHARS === 500_000, 'documented free tier is 500,000 chars/month');
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }

  // 7. Month roll resets the counter; error path never throws
  {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'translate-test-'));
    const usagePath = path.join(tmpDir, 'translate-usage.json');
    fs.writeFileSync(usagePath, JSON.stringify({ month: '2000-01', chars: 123456 }), 'utf8');
    const tr = new Translator({
      usageFilePath: usagePath,
      fetchFn: (async () => { throw new Error('network down'); }) as unknown as typeof fetch,
      getCredentials: (async () => null) as any,
    });
    assert(tr.getUsage().chars === 0, 'counter resets to 0 when the month key changes');
    const res = await tr.translate('Привіт', 'en');
    assert(!res.ok && !!res.error && res.translations.length === 0, 'credentials=null → ok:false reply, no throw');
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }

  return passed;
}

/**
 * cloudtts.test.ts — CloudTTS unit tests (no live API calls).
 *
 * Covers:
 *  - Usage counter persistence + monthly rollover
 *  - ONLY-FREE cap enforcement (over-cap refusal, counter not charged)
 *  - Cache hit path (identical text+voice → no fetch, no counter increment)
 *  - Persona/alias voice resolution (eva/adam/lang/explicit)
 *  - Request-body builder correctness (languageCode, name, MP3 encoding)
 *  - Error resilience (fetch failure never throws, resolves ok:false)
 */

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { CloudTTS, buildSynthesizeRequest, voiceFamily, languageCodeOf } from '../src/core/CloudTTS.js';
import { COMMAND_ALIASES } from '../src/models/ModelRatings.js';

export async function runCloudTtsTests(): Promise<boolean> {
  console.log('\n--- Running CloudTTS (Google TTS / ONLY-FREE cap) Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  function makeTmp(): string {
    return fs.mkdtempSync(path.join(os.tmpdir(), 'evabot-tts-test-'));
  }

  /** Mock fetch returning a fixed audioContent, recording call count + body. */
  function mockFetch(calls: Array<{ url: string; body: string }>, audio = 'U29tZUF1ZGlvQnl0ZXM=') {
    const fn: any = async (url: string, init: any) => {
      calls.push({ url, body: init.body });
      return {
        ok: true,
        status: 200,
        text: async () => '',
        json: async () => ({ audioContent: audio }),
      } as any;
    };
    return fn;
  }

  const fakeCreds = async () => ({ token: 'test-token' });

  // 1. Voice resolution (persona aliases)
  {
    const tts = new CloudTTS({ dataDir: makeTmp(), getCredentials: fakeCreds });
    assert(tts.resolveVoice({ persona: 'eva' }) === 'uk-UA-Chirp3-HD-Aoede', 'persona eva → uk-UA-Chirp3-HD-Aoede (female, Chirp3-HD 1M chars/mo free)');
    assert(tts.resolveVoice({ persona: 'adam' }) === 'ru-RU-Chirp3-HD-Fenrir', 'persona adam → ru-RU-Chirp3-HD-Fenrir (male, Chirp3-HD 1M chars/mo free)');
    assert(tts.resolveVoice({ lang: 'ru-RU' }) === 'ru-RU-Chirp3-HD-Fenrir', 'lang ru → adam voice');
    assert(tts.resolveVoice({ lang: 'uk-UA' }) === 'uk-UA-Chirp3-HD-Aoede', 'lang uk → eva voice');
    assert(tts.resolveVoice({ voiceName: 'uk-UA-Standard-B' }) === 'uk-UA-Standard-B', 'explicit voiceName wins over persona');
    assert(voiceFamily('uk-UA-Wavenet-B') === 'wavenet', 'family detection: Wavenet');
    assert(voiceFamily('ru-RU-Chirp3-HD-Kore') === 'chirp3-hd', 'family detection: Chirp3-HD');
    assert(languageCodeOf('uk-UA-Wavenet-B') === 'uk-UA', 'languageCode extraction from voice name');
  }

  // 2. Request-body builder correctness
  {
    const body = buildSynthesizeRequest('Привіт', 'uk-UA-Wavenet-B');
    assert(JSON.stringify(body.input) === '{"text":"Привіт"}', 'request body: input.text exact');
    assert(body.voice?.name === 'uk-UA-Wavenet-B', 'request body: voice.name');
    assert(body.voice?.languageCode === 'uk-UA', 'request body: voice.languageCode');
    assert(body.audioConfig?.audioEncoding === 'MP3', 'request body: MP3 encoding');
  }

  // 3. Usage counter persistence + successful synthesis
  {
    const dir = makeTmp();
    const calls: Array<{ url: string; body: string }> = [];
    const tts = new CloudTTS({ dataDir: dir, fetchFn: mockFetch(calls), getCredentials: fakeCreds });
    const r1 = await tts.synthesize('Привіт, я Ева', { persona: 'eva' });
    assert(r1.ok === true && r1.base64Audio === 'U29tZUF1ZGlvQnl0ZXM=', 'synthesize returns base64 audio on success');
    assert(r1.voice === 'uk-UA-Chirp3-HD-Aoede', 'synthesize uses eva voice');
    assert(r1.charCount === 'Привіт, я Ева'.length, 'charCount matches text length');
    assert(tts.getMonthChars() === 'Привіт, я Ева'.length, 'monthly counter charged after successful synthesis');
    assert(calls.length === 1, 'exactly one API call');
    assert(calls[0].url === 'https://texttospeech.googleapis.com/v1/text:synthesize', 'POST /v1/text:synthesize endpoint');
    const persisted = JSON.parse(fs.readFileSync(path.join(dir, 'tts-usage.json'), 'utf8'));
    assert(persisted.chars === 'Привіт, я Ева'.length && persisted.month === CloudTTS.currentMonth(), 'usage counter persisted at data/tts-usage.json {month, chars}');
  }

  // 4. Cache hit path: identical text+voice → no fetch, no counter change
  {
    const dir = makeTmp();
    const calls: Array<{ url: string; body: string }> = [];
    const tts = new CloudTTS({ dataDir: dir, fetchFn: mockFetch(calls), getCredentials: fakeCreds });
    await tts.synthesize('Кешований текст', { persona: 'eva' });
    const after1 = tts.getMonthChars();
    const r2 = await tts.synthesize('Кешований текст', { persona: 'eva' });
    assert(r2.ok === true && r2.cached === true, 'identical (text+voice) resolves from cache');
    assert(r2.base64Audio === 'U29tZUF1ZGlvQnl0ZXM=', 'cache hit returns audio');
    assert(calls.length === 1, 'cache hit does not call the API');
    assert(tts.getMonthChars() === after1, 'cache hit does not increment usage counter');
    assert(fs.existsSync(path.join(dir, 'tts-cache')), 'tts-cache directory exists');
  }

  // 5. ONLY-FREE cap enforcement (counter persisted over 900k → refuse)
  {
    const dir = makeTmp();
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'tts-usage.json'), JSON.stringify({ month: CloudTTS.currentMonth(), chars: 899_990 }));
    const calls: Array<{ url: string; body: string }> = [];
    const tts = new CloudTTS({ dataDir: dir, fetchFn: mockFetch(calls), getCredentials: fakeCreds });
    const r = await tts.synthesize('Це вже понад безкоштовний ліміт', { persona: 'eva' });
    assert(r.ok === false && r.overCap === true, 'over-cap request refused (never silently spends money)');
    assert(r.payPerCharAfterCap === true, 'over-cap result labeled pay-per-char after cap');
    assert(calls.length === 0, 'no API call when over cap');
    assert(tts.getMonthChars() === 899_990, 'counter unchanged after refusal');
    assert(r.error?.includes('900000'), 'refusal error mentions the cap');
  }

  // 6. Cap edge: text that fits exactly within remaining allowance is allowed
  {
    const dir = makeTmp();
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'tts-usage.json'), JSON.stringify({ month: CloudTTS.currentMonth(), chars: 900_000 - 10 }));
    const tts = new CloudTTS({ dataDir: dir, fetchFn: mockFetch([]), getCredentials: fakeCreds });
    const r = await tts.synthesize('0123456789', { persona: 'adam' });
    assert(r.ok === true, 'text fitting exactly within cap is synthesized');
    assert(tts.getMonthChars() === 900_000, 'counter reaches the cap exactly');
    const r2 = await tts.synthesize('one more', { persona: 'adam' });
    assert(r2.ok === false && r2.overCap === true, 'next request after cap is refused');
  }

  // 7. Monthly rollover
  {
    const dir = makeTmp();
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(path.join(dir, 'tts-usage.json'), JSON.stringify({ month: '2020-01', chars: 500_000 }));
    const tts = new CloudTTS({ dataDir: dir, getCredentials: fakeCreds });
    assert(tts.getMonthChars() === 0, 'usage counter resets on month rollover');
  }

  // 8. Errors never throw into chat flow
  {
    const dir = makeTmp();
    const failing: any = async () => { throw new Error('network down'); };
    const tts = new CloudTTS({ dataDir: dir, fetchFn: failing, getCredentials: fakeCreds });
    const r = await tts.synthesize('текст', { persona: 'eva' });
    assert(r.ok === false && r.error?.includes('network down'), 'fetch failure resolves ok:false, never throws');
    const noCreds = new CloudTTS({ dataDir: dir, fetchFn: mockFetch([]), getCredentials: async () => null });
    const r2 = await noCreds.synthesize('текст', { persona: 'eva' });
    assert(r2.ok === false && r2.error?.includes('credentials'), 'missing credentials resolve ok:false');
  }

  // 9. /say aliases registered in COMMAND_ALIASES
  {
    assert(COMMAND_ALIASES['/скажи'] === '/say', 'COMMAND_ALIASES: /скажи → /say');
    assert(COMMAND_ALIASES['/сказать'] === '/say', 'COMMAND_ALIASES: /сказать → /say');
  }

  // 10. /api/tts/status contract fields
  {
    const tts = new CloudTTS({ dataDir: makeTmp(), getCredentials: fakeCreds });
    assert(typeof tts.getCap() === 'number' && tts.getCap() === 900_000, 'default cap = 900,000 chars/month (Chirp3-HD/Wavenet free-tier safety margin)');
    assert(tts.getEvaVoice() === 'uk-UA-Chirp3-HD-Aoede' && tts.getAdamVoice() === 'ru-RU-Chirp3-HD-Fenrir', 'status exposes eva/adam default Chirp3-HD voices');
  }

  console.log('--- CloudTTS tests done ---');
  return passed;
}

import fs from 'node:fs';
import {
  monthKey,
  readUsage,
  writeUsage,
  resetUsageForTest,
  isWithinCap,
  recordUsage,
  estimateAudioSeconds,
  buildFfmpegFlacArgs,
  buildRecognizeRequest,
  transcribeAudio,
  STT_MONTHLY_CAP_SECONDS,
  STT_MODEL,
  STT_ENDPOINT,
  STT_PROJECT_HEADER,
  type SttUsage,
} from '../src/core/CloudSTT.js';
import { extractMultipartFile } from '../src/server/routes/VoiceRouter.js';
import { TelegramBot } from '../src/telegram/TelegramBot.js';
import { normalizeCommand } from '../src/models/ModelRatings.js';

async function runCloudSttTests(): Promise<boolean> {
  console.log('================================================================');
  console.log('CLOUD STT TESTS');
  console.log('================================================================\n');

  let passed = 0;
  let failed = 0;

  const test = (name: string, condition: boolean, detail: string = '') => {
    if (condition) {
      passed++;
      console.log(`  ✓ ${name}`);
    } else {
      failed++;
      console.error(`  ✗ ${name} ${detail}`);
    }
  };

  // --- 1. Constants: ONLY-FREE design invariants ---
  test('endpoint is v1 recognize', STT_ENDPOINT === 'https://speech.googleapis.com/v1/speech:recognize');
  test('model is latest_long (v1 standard → 60 min/mo free tier)', STT_MODEL === 'latest_long');
  test('required billing project header', STT_PROJECT_HEADER === 'evabot-agent-server');
  test('monthly cap is 3000s (50 min free + safety margin)', STT_MONTHLY_CAP_SECONDS === 3000);

  // --- 2. Usage cap logic ---
  resetUsageForTest();
  test('resetUsageForTest → zero counter for current month',
    readUsage().month === monthKey() && readUsage().secondsUsed === 0);

  writeUsage({ month: monthKey(), secondsUsed: 2998 });
  test('within cap: 2998 + 2 = 3000 exactly allowed', isWithinCap(2) === true);
  test('over cap: 2998 + 3 = 3001 refused', isWithinCap(3) === false);

  writeUsage({ month: monthKey(), secondsUsed: STT_MONTHLY_CAP_SECONDS });
  test('cap reached: any further usage refused', isWithinCap(1) === false);

  const stale: SttUsage = { month: '2000-01', secondsUsed: 999999 };
  test('stale month never blocks a new month', isWithinCap(6000, stale) === true);

  writeUsage({ month: '2000-01', secondsUsed: 5000 });
  const rolled = readUsage();
  test('readUsage rolls stale month over to a fresh counter',
    rolled.month === monthKey() && rolled.secondsUsed === 0);

  resetUsageForTest();
  const after = recordUsage(3);
  test('recordUsage accumulates and persists', after.secondsUsed === 3 && readUsage().secondsUsed === 3);
  resetUsageForTest();

  // --- 3. Cap refusal never throws and never calls the network ---
  writeUsage({ month: monthKey(), secondsUsed: STT_MONTHLY_CAP_SECONDS });
  const refused = await transcribeAudio(Buffer.from('RIFF....'), { encoding: 'OGG_OPUS' });
  test('transcribeAudio refuses at cap (MONTHLY_CAP_REACHED)',
    refused.ok === false && (refused.error || '').includes('MONTHLY_CAP_REACHED') && refused.secondsBilled === 0);
  test('transcribeAudio refuses empty audio without network', (await transcribeAudio(Buffer.alloc(0))).error === 'EMPTY_AUDIO');
  resetUsageForTest();

  // --- 4. Request builder (v1 recognize body) ---
  const req = buildRecognizeRequest('QUJD', { lang: 'ru-RU', encoding: 'OGG_OPUS', sampleRate: 48000 });
  test('request uses latest_long model', req.config.model === STT_MODEL);
  test('request carries OGG_OPUS @ 48 kHz and ru-RU',
    req.config.encoding === 'OGG_OPUS' && req.config.sampleRateHertz === 48000 && req.config.languageCode === 'ru-RU');
  test('request carries base64 audio payload', req.audio.content === 'QUJD');

  const flacReq = buildRecognizeRequest('AAAA', { lang: 'uk-UA', encoding: 'FLAC' });
  test('FLAC omits sampleRateHertz (auto-detected from header)', !('sampleRateHertz' in flacReq.config) && flacReq.config.encoding === 'FLAC');

  const linReq = buildRecognizeRequest('AAAA', { encoding: 'LINEAR16', sampleRate: 44100 });
  test('LINEAR16 keeps explicit sample rate', linReq.config.sampleRateHertz === 44100);

  // --- 5. ffmpeg command construction + real conversion roundtrip ---
  const args = buildFfmpegFlacArgs('/tmp/in.ogg', '/tmp/out.flac');
  test('ffmpeg args: 16 kHz mono FLAC', args.includes('-ar') && args.includes('16000') && args.includes('-ac') && args.includes('1') && args[args.length - 1] === '/tmp/out.flac');

  const tmpWav = `/tmp/evabot-stt-test-${Date.now()}.wav`;
  const tmpFlac = tmpWav.replace(/\.wav$/, '.flac');
  try {
    fs.writeFileSync(tmpWav, Buffer.alloc(0));
    const { execFileSync } = await import('node:child_process');
    execFileSync('ffmpeg', ['-y', '-f', 'lavfi', '-i', 'sine=frequency=440:duration=0.5', tmpWav], { encoding: 'utf8', timeout: 15000 });
    test('local ffmpeg generates test wav', fs.statSync(tmpWav).size > 1000);

    const { convertToFlac16k, probeAudioSeconds } = await import('../src/core/CloudSTT.js');
    const wav = fs.readFileSync(tmpWav);
    const flac = convertToFlac16k(wav);
    test('convertToFlac16k produces non-trivial FLAC', Boolean(flac) && (flac as Buffer).length > 500);
    const probed = probeAudioSeconds(wav);
    test('probeAudioSeconds measures ~0.5–1s', probed !== null && probed >= 1 && probed <= 1);
  } catch (err: any) {
    test('ffmpeg local conversion path', false, err.message);
  } finally {
    try { fs.unlinkSync(tmpWav); } catch { /* ignore */ }
    try { fs.unlinkSync(tmpFlac); } catch { /* ignore */ }
  }

  // --- 6. Duration estimation ---
  test('OGG_OPUS estimate: 60000 B @ ~48 kbps → 10s', estimateAudioSeconds(60000, 'OGG_OPUS') === 10);
  test('FLAC estimate: 32000 B @ 16 kHz mono → 1s', estimateAudioSeconds(32000, 'FLAC') === 1);

  // --- 7. /listen alias resolution (COMMAND_ALIASES) ---
  test('/розпізнай → /listen (UK)', normalizeCommand('/розпізнай /tmp/a.ogg') === '/listen /tmp/a.ogg');
  test('/распознать → /listen (RU)', normalizeCommand('/распознать /tmp/a.ogg') === '/listen /tmp/a.ogg');
  test('/прослушать → /listen (RU alt)', normalizeCommand('/прослушать /tmp/a.ogg') === '/listen /tmp/a.ogg');

  // --- 8. Multipart extraction for the /api/stt route ---
  const boundary = '----evabotBoundary42';
  const mpBody = Buffer.from(
    `--${boundary}\r\nContent-Disposition: form-data; name="audio"; filename="voice.ogg"\r\nContent-Type: audio/ogg\r\n\r\nOGGDATAPAYLOAD\r\n--${boundary}--\r\n`,
    'utf8'
  );
  const extracted = extractMultipartFile(mpBody, `multipart/form-data; boundary=${boundary}`);
  test('multipart file part extracted byte-exact', extracted !== null && extracted.toString() === 'OGGDATAPAYLOAD');
  test('multipart without boundary → null', extractMultipartFile(mpBody, 'multipart/form-data') === null);

  // --- 9. Telegram handler wiring with mocked STT (no live calls) ---
  const sent: string[] = [];
  const chatRouted: string[] = [];
  const receivedCommands: string[] = [];
  const transcriberCalls: Array<{ bytes: number; lang: string }> = [];
  const mockExecutor = (command: string): string => {
    receivedCommands.push(command);
    return `MOCK:${command}`;
  };
  const bot = new TelegramBot({
    token: 'test-token',
    execute: mockExecutor,
    transcriber: async (audio, lang) => {
      transcriberCalls.push({ bytes: audio.length, lang });
      return { transcript: '/help', confidence: 0.92, secondsBilled: 2, ok: true };
    },
  });
  (bot as any).sendMessage = async (_chatId: number, text: string) => { sent.push(text); };
  (bot as any).downloadVoiceFile = async () => Buffer.from('fake-ogg-bytes');
  (bot as any).handleChatMessage = async (_chatId: number, text: string) => { chatRouted.push(text); };

  await (bot as any).handleVoiceMessage({
    message_id: 1,
    date: 0,
    chat: { id: 42, type: 'private' },
    from: { id: 7, username: 'tester' },
    voice: { file_id: 'F1', duration: 2, mime_type: 'audio/ogg' },
  });

  test('transcriber called with downloaded audio buffer', transcriberCalls.length === 1 && transcriberCalls[0].bytes === 14);
  test('chat locale maps to STT lang (en → en-US)', transcriberCalls[0].lang === 'en-US');
  test('voice reply sent with Розпізнано: prefix', sent.some((t) => t.includes('Розпізнано:') && t.includes('/help')));
  test('command transcript routed into handleCommand (mock executor received /help)',
    receivedCommands.includes('/help'));

  // Non-command transcript flows into the normal chat engine
  const bot2 = new TelegramBot({
    token: 'test-token',
    execute: mockExecutor,
    transcriber: async () => ({ transcript: 'Привіт, як справи?', confidence: 0.8, secondsBilled: 3, ok: true }),
  });
  (bot2 as any).sendMessage = async (_chatId: number, text: string) => { sent.push(text); };
  (bot2 as any).downloadVoiceFile = async () => Buffer.from('fake-ogg-bytes');
  (bot2 as any).handleChatMessage = async (_chatId: number, text: string) => { chatRouted.push(text); };
  await (bot2 as any).handleVoiceMessage({
    message_id: 2,
    date: 0,
    chat: { id: 42, type: 'private' },
    from: { id: 7, username: 'tester' },
    voice: { file_id: 'F2', duration: 3, mime_type: 'audio/ogg' },
  });
  test('plain transcript routed into handleChatMessage', chatRouted.includes('Привіт, як справи?'));

  // Failed transcription → error notice, no routing
  const bot3 = new TelegramBot({
    token: 'test-token',
    execute: mockExecutor,
    transcriber: async () => ({ transcript: '', confidence: 0, secondsBilled: 0, ok: false, error: 'STT_API_ERROR: boom' }),
  });
  (bot3 as any).sendMessage = async (_chatId: number, text: string) => { sent.push(text); };
  (bot3 as any).downloadVoiceFile = async () => Buffer.from('fake-ogg-bytes');
  await (bot3 as any).handleVoiceMessage({
    message_id: 3,
    date: 0,
    chat: { id: 42, type: 'private' },
    from: { id: 7, username: 'tester' },
    voice: { file_id: 'F3', duration: 2, mime_type: 'audio/ogg' },
  });
  test('failed STT → warning message, nothing routed', sent.some((t) => t.includes('Не вдалося розпізнати') && t.includes('boom')));

  console.log('\n----------------------------------------------------------------');
  console.log(`CloudSTT tests: ${passed} passed, ${failed} failed`);
  console.log('----------------------------------------------------------------\n');
  return failed === 0;
}

export { runCloudSttTests };

/**
 * developer_mode.test.ts — SystemContext (FEATURE 1) + DeveloperMode (FEATURE 2)
 *
 * Covers:
 *  - Wrong password denied / correct password unlocks (constant-time verify)
 *  - TTL expiry via injected fake clock (no real timers)
 *  - /developer lock + status
 *  - Password masking for chat persistence (/developer unlock → ****)
 *  - SystemContext content: default model, VM names, company identity,
 *    product count, ≤1200 chars, 60s cache
 *  - /sys command output via ModelCommand
 */

import { DeveloperMode } from '../src/core/DeveloperMode.js';
import { SystemContext } from '../src/core/SystemContext.js';
import { ModelCommand, COMMAND_ALIASES, normalizeCommand } from '../src/models/ModelRatings.js';
import { Config } from '../src/core/Config.js';

export async function runDeveloperModeTests(): Promise<boolean> {
  console.log('\n--- Running DeveloperMode & SystemContext Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // Isolated fixture state per suite run.
  const realNow = Date.now;
  let fakeNow = realNow();
  DeveloperMode.setClock(() => fakeNow);
  DeveloperMode.resetAll();
  // Test password: set through env (DeveloperMode reads live env over Config).
  // Remember the real value (from .env) so it can be restored afterwards.
  const originalEnvPassword = process.env.EVADEV_PASSWORD;
  process.env.EVADEV_PASSWORD = 'test-dev-pass-9137';

  try {
    // 1. Wrong password denied
    {
      const ok = DeveloperMode.unlock('sess-a', 'wrong-password');
      assert(ok === false, 'unlock with wrong password is denied');
      assert(DeveloperMode.isUnlocked('sess-a') === false, 'session stays locked after wrong password');
      const out = ModelCommand.execute('/developer unlock wrong-password');
      assert(out.includes('Невірний пароль'), 'wrong password reply does not unlock');
      assert(!out.includes('wrong-password'), 'wrong password is never echoed back');
    }

    // 2. Correct password unlocks
    {
      const ok = DeveloperMode.unlock('sess-b', 'test-dev-pass-9137');
      assert(ok === true, 'unlock with correct password succeeds');
      assert(DeveloperMode.isUnlocked('sess-b') === true, 'session becomes unlocked');
      assert(DeveloperMode.ttlRemainingMs('sess-b') > 0, 'TTL is positive after unlock');
      const out = ModelCommand.execute('/developer unlock test-dev-pass-9137');
      assert(out.includes('АКТИВОВАНО') || out.includes('активовано'), 'unlock command replies success');
      assert(!out.includes('test-dev-pass-9137'), 'unlock reply does NOT echo the password');
    }

    // 3. Password-casing preserved through the raw-command path
    {
      DeveloperMode.resetAll();
      process.env.EVADEV_PASSWORD = 'MiXeD-Case-Pw';
      const out = ModelCommand.execute('/developer unlock MiXeD-Case-Pw');
      assert(DeveloperMode.isUnlocked('cli') === true, 'mixed-case password unlocks via ModelCommand (no lowercasing)');
      assert(!out.includes('MiXeD-Case-Pw'), 'mixed-case password never echoed');
      process.env.EVADEV_PASSWORD = 'test-dev-pass-9137';
      DeveloperMode.resetAll();
    }

    // 4. TTL expiry (fake clock)
    {
      DeveloperMode.resetAll();
      DeveloperMode.unlock('sess-ttl', 'test-dev-pass-9137');
      assert(DeveloperMode.isUnlocked('sess-ttl') === true, 'unlocked before TTL elapses');
      fakeNow += DeveloperMode.UNLOCK_TTL_MS - 1000;
      assert(DeveloperMode.isUnlocked('sess-ttl') === true, 'still unlocked 1s before TTL');
      fakeNow += DeveloperMode.UNLOCK_TTL_MS + 1000;
      assert(DeveloperMode.isUnlocked('sess-ttl') === false, 'expired right after TTL (2h)');
    }

    // 5. lock + status
    {
      DeveloperMode.resetAll();
      DeveloperMode.unlock('sess-c', 'test-dev-pass-9137');
      const locked = DeveloperMode.lock('sess-c');
      assert(locked === true, 'lock() reports the session was unlocked');
      assert(DeveloperMode.isUnlocked('sess-c') === false, 'session locked again');
      const status = DeveloperMode.statusLine('sess-c');
      assert(status.includes('ЗАЧИНЕНО'), 'status shows locked state');
      DeveloperMode.unlock('sess-d', 'test-dev-pass-9137');
      fakeNow += 30 * 60 * 1000; // +30 min
      const status2 = DeveloperMode.statusLine('sess-d');
      assert(status2.includes('АКТИВНИЙ') && status2.includes('90 хв'), 'status shows unlocked + remaining TTL');
    }

    // 6. Missing env → mode unavailable
    {
      DeveloperMode.resetAll();
      // Hermetic: getPassword() falls back to Config.developerPassword (loaded
      // from .env at import time), so stub both sources to force the empty
      // state — never touching the real .env file.
      const savedEnvPwd = process.env.EVADEV_PASSWORD;
      const savedConfigPwd = (Config as any).developerPassword;
      delete process.env.EVADEV_PASSWORD;
      (Config as any).developerPassword = '';
      try {
        const out = ModelCommand.execute('/developer unlock whatever');
        assert(out.includes('режим недоступний: встанови EVADEV_PASSWORD'), 'missing EVADEV_PASSWORD → unavailable notice');
      } finally {
        process.env.EVADEV_PASSWORD = savedEnvPwd;
        (Config as any).developerPassword = savedConfigPwd;
      }
    }

    // 7. Password masking in the persistence helper
    {
      const masked = DeveloperMode.maskPasswordIn('/developer unlock supersecret123');
      assert(masked === '/developer unlock ****', 'EN command password masked');
      const maskedUk = DeveloperMode.maskPasswordIn('/розробник unlock парольСекрет');
      assert(maskedUk === '/розробник unlock ****', 'UK alias password masked');
      const maskedTail = DeveloperMode.maskPasswordIn('/developer unlock  p@ss word tail');
      assert(maskedTail.includes('****') && !maskedTail.includes('p@ss'), 'password token masked, tail preserved');
      assert(DeveloperMode.maskPasswordIn('just a normal message') === 'just a normal message', 'normal text untouched');
      assert(
        DeveloperMode.maskPasswordIn('/developer unlock S3cret!') === '/developer unlock ****',
        'symbol-rich password fully masked'
      );
    }

    // 8. Aliases registered + normalizeCommand routing
    {
      assert(COMMAND_ALIASES['/система'] === '/sys', 'alias /система → /sys');
      assert(COMMAND_ALIASES['/системa'] === '/sys', 'alias /системa (latin a) → /sys');
      assert(COMMAND_ALIASES['/whereami'] === '/sys', 'alias /whereami → /sys');
      assert(COMMAND_ALIASES['/девелопер'] === '/developer', 'alias /девелопер → /developer');
      assert(COMMAND_ALIASES['/розробник'] === '/developer', 'alias /розробник → /developer');
      assert(normalizeCommand('/система').startsWith('/sys'), 'normalizeCommand resolves /система');
    }

    // 9. SystemContext content: model + VM + company + products
    {
      SystemContext.invalidate();
      const block = SystemContext.build();
      assert(block.includes(Config.defaultModel), `block includes configured default model (${Config.defaultModel})`);
      assert(block.includes('evabot-agent-vm'), 'block includes evabot-agent-vm');
      assert(block.includes('evabot-micro'), 'block includes evabot-micro');
      assert(block.includes('ЕВА-ЛАЙН'), 'block includes company name');
      assert(block.includes('40484497'), 'block includes ЄДРПОУ');
      assert(/\d+/.test(block), 'block includes numeric stats');
      assert(block.length <= 1200, `block ≤1200 chars (got ${block.length})`);
      assert(block.includes('Breakers:'), 'block includes breaker health summary');
    }

    // 10. /sys output via ModelCommand
    {
      const out = ModelCommand.execute('/sys');
      assert(out.includes(Config.defaultModel), '/sys output includes the default model');
      assert(out.includes('evabot-agent-vm'), '/sys output includes the brain VM');
      const outUk = ModelCommand.execute('/система');
      assert(outUk.includes(Config.defaultModel), 'ukrainian alias /система works');
    }

    // 11. Last-used model surfaces in SystemContext
    {
      SystemContext.invalidate();
      const { recordLastUsedModel } = await import('../src/core/SystemContext.js');
      recordLastUsedModel('test-model-x', 'google');
      const block = SystemContext.build();
      assert(block.includes('test-model-x'), 'block shows last-used model after recordLastUsedModel');
    }

    // 12. Developer prompt block content
    {
      assert(SystemContext.DEVELOPER_BLOCK.includes('режимі розробника'), 'DEVELOPER_BLOCK text present');
      assert(SystemContext.DEVELOPER_BLOCK.includes('Не приховуй'), 'DEVELOPER_BLOCK instructs full disclosure');
    }

    // 13. developer command parse edge cases
    {
      assert(DeveloperMode.parseCommand('/developer')?.sub === 'help', 'bare /developer → help');
      assert(DeveloperMode.parseCommand('/розробник status')?.sub === 'status', 'uk alias status subcommand');
      assert(DeveloperMode.parseCommand('/developer lock')?.sub === 'lock', 'lock subcommand');
      assert(DeveloperMode.parseCommand('/models') === null, 'non-developer command → null');
      assert(
        DeveloperMode.parseCommand('/developer unlock My Secret Pass')?.password === 'My Secret Pass',
        'password with spaces preserved'
      );
      const helpOut = ModelCommand.execute('/developer');
      assert(helpOut.includes('/developer unlock'), '/developer without subcommand prints usage');
    }
  } finally {
    // Restore real clock + env for subsequent suites.
    DeveloperMode.setClock(realNow);
    DeveloperMode.resetAll();
    if (originalEnvPassword !== undefined) {
      process.env.EVADEV_PASSWORD = originalEnvPassword;
    } else {
      delete process.env.EVADEV_PASSWORD;
    }
    SystemContext.invalidate();
  }

  console.log(`--- DeveloperMode & SystemContext Tests ${passed ? 'PASSED' : 'FAILED'} ---`);
  return passed;
}

/**
 * ui_parity.test.ts — Task 1 + Task 2 verification:
 *  - stripEmoji correctness (emoji removed/replaced, box-drawing & ● kept)
 *  - /voices set validation rejects paid-only families (e.g. studio)
 *  - /settings output contains the required settings keys
 *  - /agents lists 18 corporate + 10 Sephirot entries
 *  - banner parity: browser I18N header labels === CLI renderDashboard() labels
 *    (same key substrings: Ping:, Model:, Pool:, Lang:, Databases:)
 */
import fs from 'node:fs';
import path from 'node:path';
import { stripEmoji, I18nEngine } from '../src/core/I18nEngine.js';
import { ModelCommand, COMMAND_ALIASES } from '../src/models/ModelRatings.js';
import { validateVoiceName, voiceFamily } from '../src/core/CloudTTS.js';
import { CORPORATE_ROLES } from '../src/core/CorporateRoles.js';
import { SEPHIROT_ROLES } from '../src/core/SephirotEngine.js';

export function runUiParityTests(): boolean {
  console.log('\n--- Running UI Parity, stripEmoji & Voice/Settings/Agents Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // 1. stripEmoji: emoji removed / ASCII-mapped, box drawing + ●■ kept
  {
    assert(stripEmoji('Hello 🎤 world') === 'Hello [ MIC ] world', 'stripEmoji: surrogate-pair emoji mapped to [ MIC ]');
    assert(stripEmoji('done ✅ and failed ❌') === 'done [OK] and failed [X]', 'stripEmoji: ✅→[OK], ❌→[X]');
    assert(stripEmoji('┌──[TEST] ──┐') === '┌──[TEST] ──┐', 'stripEmoji: box drawing kept');
    assert(stripEmoji('● EvaBot ■■■░░ 42%') === '● EvaBot ■■■░░ 42%', 'stripEmoji: ● and ■ kept');
    assert(stripEmoji('a⚠b⚡c♥d★e') === 'a[WRN]b*c*d*e', 'stripEmoji: BMP symbols replaced via map');
    assert(stripEmoji('модель 🔊🔊 mute 🔇') === 'модель [ TTS:ON ][ TTS:ON ] mute [ TTS:OFF ]', 'stripEmoji: TTS toggles mapped');
    assert(stripEmoji('plain text 🗣️✨Rocket🚀') === 'plain text Rocket', 'stripEmoji: unmapped emoji (incl. variation selectors) removed');
  }

  // 2. /voices set validation: paid-only + unknown families rejected
  {
    const studio = ModelCommand.execute('/voices set eva en-US-Studio-F');
    assert(studio.includes('[ERROR]') && /studio/i.test(studio), '/voices set rejects studio (paid-only) family');
    assert(validateVoiceName('en-US-Studio-F').ok === false, 'validateVoiceName: studio rejected');
    assert(validateVoiceName('uk-UA-Chirp3-HD-Kore').ok === true && validateVoiceName('uk-UA-Chirp3-HD-Kore').family === 'chirp3-hd', 'validateVoiceName: Chirp3-HD allowed');
    assert(validateVoiceName('ru-RU-Wavenet-D').ok === true, 'validateVoiceName: Wavenet allowed');
    assert(validateVoiceName('definitely-not-a-voice').ok === false, 'validateVoiceName: unknown voice rejected');
    assert(voiceFamily('uk-UA-Chirp3-HD-Aoede') === 'chirp3-hd', 'voiceFamily: Chirp3-HD detection');

    const help = ModelCommand.execute('/voices');
    assert(help.includes('uk-UA') && help.includes('ru-RU') && help.includes('en-US'), '/voices lists all three languages');
    assert(help.includes('Chirp3-HD'.toUpperCase()) || help.includes('CHIRP3-HD'), '/voices groups Chirp3-HD family');
    assert(help.includes('Eva =') && help.includes('Adam ='), '/voices shows current Eva/Adam selection');
    assert(help.includes('/voices set eva'), '/voices prints the set hint');

    assert(COMMAND_ALIASES['/голоси'] === '/voices' && COMMAND_ALIASES['/голоса'] === '/voices' && COMMAND_ALIASES['/звуки'] === '/voices', '/voices UK/RU aliases registered');
    assert(COMMAND_ALIASES['/налаштування'] === '/settings' && COMMAND_ALIASES['/настройки'] === '/settings', '/settings UK/RU aliases registered');
    assert(COMMAND_ALIASES['/агенти'] === '/agents' && COMMAND_ALIASES['/рота'] === '/agents' && COMMAND_ALIASES['/роли-агентів'] === '/agents', '/agents UK/RU aliases registered');
  }

  // 3. /settings output contains the required keys
  {
    const out = ModelCommand.execute('/settings');
    for (const key of ['Locale', 'Mode', 'Model (default)', 'Debug', 'TTS usage', 'STT usage', 'Translate usage', 'Autocorrect', 'Emoji mode', 'Developer mode', 'Session id']) {
      assert(out.includes(key), `/settings contains "${key}"`);
    }
  }

  // 4. /agents lists 18 corporate + 10 Sephirot entries
  {
    const out = ModelCommand.execute('/agents');
    const corporateCount = Object.keys(CORPORATE_ROLES).length;
    assert(corporateCount === 18, `corporate roster has 18 roles (got ${corporateCount})`);
    assert(SEPHIROT_ROLES.length === 10, 'Sephirot roster has 10 nodes');
    assert(out.includes('[CORPORATE]') && out.includes('[SEPHIROT]'), '/agents has both sections');
    assert(out.includes(`= ${corporateCount + SEPHIROT_ROLES.length} агентів`), '/agents footer sums 18+10 entries');
    assert(out.includes('[ADAM]') && out.includes('[EVA]'), '/agents marks Adam/Eva personas');
  }

  // 5. Banner parity: browser I18N header labels === CLI renderDashboard labels
  {
    const htmlPath = path.resolve(process.cwd(), 'public', 'index.html');
    const html = fs.existsSync(htmlPath) ? fs.readFileSync(htmlPath, 'utf8') : '';
    assert(html.length > 0, 'browser index.html readable for parity check');
    const pairs: Array<[string, string]> = [
      ['id="lbl-ping">Ping:<', 'ping'],
      ['id="lbl-model">Model:<', 'model'],
      ['id="lbl-pool">Pool:<', null],
      ['id="lbl-lang">Lang:<', 'lang'],
      ['id="lbl-databases">Databases:<', 'databasesLabel'],
      ['id="lbl-mode">Mode:<', 'mode'],
      ['id="lbl-commands">Commands:<', 'commandsLabel'],
      ['id="lbl-load">Load:<', 'loadLabel'],
    ];
    for (const [needle] of pairs) {
      assert(html.includes(needle), `browser banner contains "${needle}" (CLI parity)`);
    }
    const s = I18nEngine.getStrings('en');
    assert(s.ping === 'Ping:' && s.model === 'Model:' && s.databasesLabel === 'Databases:', 'CLI dashboard labels match browser labels (EN)');
    assert(html.includes('>Ping:<') === html.includes(`id="lbl-ping">${s.ping}<`), 'browser Ping label equals CLI dictionary value');
    // Ukrainian parity: static HTML holds EN defaults, UK labels live in the
    // in-page I18N dictionary that setLanguage() applies to the same labels.
    const su = I18nEngine.getStrings('uk');
    assert(html.includes(`ping: '${su.ping}'`) && html.includes(`model: '${su.model}'`) && html.includes(`databases: '${su.databasesLabel}'`), 'browser UK I18N labels equal CLI dictionary values');
    // Emoji-free banner (task 1): no mic/speaker emoji in the header block
    assert(!stripEmoji(html).includes('🎤') && !html.includes('🔊'), 'browser banner contains no emoji (stripped / replaced)');
    assert(html.includes('[ TTS:ON ]') || html.includes('tts-toggle'), 'TTS toggle present with ASCII label');
  }

  console.log('--- UI parity tests done ---');
  return passed;
}

import { GeminiClient, ChatMessage } from '../src/core/GeminiClient.js';
import { GoogleAuthProvider, DEFAULT_GEMINI_API_KEY, resolveGeminiApiKey } from '../src/core/GoogleAuthProvider.js';
import { Config } from '../src/core/Config.js';
import { UniversalLlmClient } from '../src/core/UniversalLlmClient.js';
import { getBreaker } from '../src/core/Resilience.js';

/**
 * Gemini routing matrix tests — ONLY-FREE policy.
 *
 * Verifies that:
 *  - GEMINI_API_KEY env (Config) → generativelanguage?key= (free tier)
 *  - no env → lazily-resolved default key (env → Secret Manager 'evabot-gemini-api-key'; TASK-331 removed the literal)
 *  - Vertex (paid) is OFF by default; only reachable via EVA_VERTEX_ENABLED=1
 *    (bearer from GoogleAuthProvider) or an explicitly set bearer token
 *  - key path never sends Authorization or X-Goog-User-Project
 *  - 429 from generativelanguage → thrown error → breaker recordFailure event
 */

const OK_BODY = { candidates: [{ content: { parts: [{ text: 'ok' }] } }] };

interface CapturedCall {
  url: string;
  headers: Record<string, string>;
}

const originalFetch = globalThis.fetch;
let captured: CapturedCall[] = [];
let responder: (url: string) => { status: number; body?: any; sse?: string } = () => ({ status: 200, body: OK_BODY });

function installFetchMock(): void {
  (globalThis as any).fetch = async (url: any, init: any = {}) => {
    const headers: Record<string, string> = {};
    if (init && init.headers) {
      for (const [k, v] of Object.entries(init.headers)) headers[k.toLowerCase()] = String(v);
    }
    captured.push({ url: String(url), headers });
    const r = responder(String(url));
    if (r.sse !== undefined) {
      const stream = new ReadableStream({
        start(controller) {
          controller.enqueue(new TextEncoder().encode(r.sse!));
          controller.close();
        },
      });
      return new Response(stream, { status: r.status, headers: { 'content-type': 'text/event-stream' } });
    }
    return new Response(JSON.stringify(r.body ?? {}), { status: r.status, headers: { 'content-type': 'application/json' } });
  };
}

function restoreFetch(): void {
  globalThis.fetch = originalFetch;
  captured = [];
}

function withConfig(overrides: { geminiApiKey?: string; vertexEnabled?: boolean }, fn: () => Promise<void>): Promise<void> {
  const savedKey = Config.geminiApiKey;
  const savedVertex = Config.vertexEnabled;
  if (overrides.geminiApiKey !== undefined) (Config as any).geminiApiKey = overrides.geminiApiKey;
  if (overrides.vertexEnabled !== undefined) (Config as any).vertexEnabled = overrides.vertexEnabled;
  return fn().finally(() => {
    (Config as any).geminiApiKey = savedKey;
    (Config as any).vertexEnabled = savedVertex;
  });
}

/** Traps ambient credential resolution — key-path tests must NEVER hit ADC. */
function trapGetCredentials(): () => void {
  const orig = GoogleAuthProvider.getCredentials;
  (GoogleAuthProvider as any).getCredentials = async () => {
    throw new Error('TRAP: getCredentials must not be called on the free-tier key path');
  };
  return () => {
    (GoogleAuthProvider as any).getCredentials = orig;
  };
}

const SAMPLE_MSGS: ChatMessage[] = [{ role: 'user', parts: [{ text: 'ping' }] }];

export async function runGeminiRoutingTests(): Promise<boolean> {
  console.log('\n--- Running Gemini Routing Matrix Tests (ONLY-FREE policy) ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // ── 1. Explicit GEMINI_API_KEY (via Config) → generativelanguage?key= ──
  await withConfig({ geminiApiKey: 'TEST-ENV-KEY-123', vertexEnabled: false }, async () => {
    installFetchMock();
    const untrap = trapGetCredentials();
    try {
      const client = new GeminiClient(); // no explicit token → ambient resolution
      const out = await client.generateContent('gemini-2.5-flash', SAMPLE_MSGS);
      const call = captured[0];
      assert(out === 'ok', 'Env key path returns model text');
      assert(call.url.startsWith('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=TEST-ENV-KEY-123'),
        'Env key routes to generativelanguage with ?key= (free tier)');
      assert(!('authorization' in call.headers), 'Key path sends NO Authorization bearer header');
      assert(!('x-goog-user-project' in call.headers), 'Key path sends NO X-Goog-User-Project header');
      assert(call.headers['x-goog-api-key'] === 'TEST-ENV-KEY-123', 'Key path authenticates via x-goog-api-key header');
    } catch (e: any) {
      assert(false, `Env key path threw: ${e.message}`);
    } finally {
      untrap();
      restoreFetch();
    }
  });

  // ── 2. No env key (Config.geminiApiKey='') → lazily-resolved default key ──
  // (TASK-331: the hard-coded literal is gone; the fallback resolves
  // GEMINI_API_KEY env → Secret Manager 'evabot-gemini-api-key' → ''.
  // Network-free by construction: env is already populated from .env in this
  // process, so the resolver short-circuits before any gcloud/Secret Manager
  // access; assertions only check string-ness and internal consistency.)
  await withConfig({ geminiApiKey: '', vertexEnabled: false }, async () => {
    installFetchMock();
    const untrap = trapGetCredentials();
    try {
      assert(typeof resolveGeminiApiKey() === 'string', 'resolveGeminiApiKey() exists and returns a string (env → Secret Manager fallback)');
      const client = new GeminiClient();
      await client.generateContent('gemini-2.5-flash', SAMPLE_MSGS);
      const call = captured[0];
      const resolvedKey = resolveGeminiApiKey();
      assert(call.url.includes(`?key=${resolvedKey}`), 'Missing env falls back to the lazily-resolved default key (no hard-coded literal in source)');
      assert(call.headers['x-goog-api-key'] === String(DEFAULT_GEMINI_API_KEY), 'Lazy default key coerces consistently in URL and x-goog-api-key header');
      assert(call.url.startsWith('https://generativelanguage.googleapis.com/'), 'Default-key path stays on generativelanguage (free)');
    } catch (e: any) {
      assert(false, `Default-key path threw: ${e.message}`);
    } finally {
      untrap();
      restoreFetch();
    }
  });

  // ── 3. Regression: client seeded with the lazy DEFAULT key must NOT skip it ──
  // (old setApiKey() ignored the embedded fallback and fell through to ADC bearer → paid Vertex)
  await withConfig({ geminiApiKey: DEFAULT_GEMINI_API_KEY as string, vertexEnabled: false }, async () => {
    installFetchMock();
    const untrap = trapGetCredentials();
    try {
      const client = new GeminiClient(DEFAULT_GEMINI_API_KEY as string); // what UniversalLlmClient/ChatRouter seed
      await client.generateContent('gemini-2.5-flash', SAMPLE_MSGS);
      const call = captured[0];
      assert(call.url.includes('generativelanguage.googleapis.com'), 'Lazy default key passed via setApiKey routes to generativelanguage (was silently dropped before)');
    } catch (e: any) {
      assert(false, `Default key via setApiKey threw: ${e.message}`);
    } finally {
      untrap();
      restoreFetch();
    }
  });

  // ── 4. Vertex OFF by default (no EVA_VERTEX_ENABLED) ──
  await withConfig({ geminiApiKey: 'TEST-ENV-KEY-123', vertexEnabled: false }, async () => {
    installFetchMock();
    const untrap = trapGetCredentials();
    try {
      const client = new UniversalLlmClient(); // production construction path
      await client.generateContent('gemini-2.5-flash', 'hello');
      const call = captured[0];
      assert(!call.url.includes('aiplatform.googleapis.com'), 'Default config never targets Vertex AI endpoints');
      assert(!('authorization' in call.headers), 'Default config never sends paid bearer tokens');
      assert(call.url.includes('/models/gemini-2.5-flash:generateContent'), 'Model id resolution unchanged for run-evaline-consilium style ids');
    } catch (e: any) {
      assert(false, `Vertex-off test threw: ${e.message}`);
    } finally {
      untrap();
      restoreFetch();
    }
  });

  // ── 5. EVA_VERTEX_ENABLED=1 → Vertex bearer (explicit paid opt-in) ──
  await withConfig({ geminiApiKey: 'TEST-ENV-KEY-123', vertexEnabled: true }, async () => {
    installFetchMock();
    const orig = GoogleAuthProvider.getCredentials;
    (GoogleAuthProvider as any).getCredentials = async () => ({
      token: 'ya29.MOCKTOKEN', type: 'bearer', source: 'mock ADC', account: 'mock',
    });
    try {
      const client = new GeminiClient(); // NOT seeded with a key → env opt-in honored
      await client.generateContent('gemini-2.5-flash', SAMPLE_MSGS);
      const call = captured[0];
      assert(call.url.startsWith('https://europe-west3-aiplatform.googleapis.com/v1/projects/evabot-agent-server/locations/europe-west3/publishers/google/models/gemini-2.5-flash:generateContent'),
        'EVA_VERTEX_ENABLED=1 routes to Vertex AI (explicit paid opt-in)');
      assert(call.headers['authorization'] === 'Bearer ya29.MOCKTOKEN', 'Vertex path uses bearer token');
      assert(!call.url.includes('key='), 'Vertex path carries no API key');
    } catch (e: any) {
      assert(false, `Vertex opt-in test threw: ${e.message}`);
    } finally {
      (GoogleAuthProvider as any).getCredentials = orig;
      restoreFetch();
    }
  });

  // ── 6. Explicit bearer token = request-level Vertex opt-in ──
  await withConfig({ geminiApiKey: 'TEST-ENV-KEY-123', vertexEnabled: false }, async () => {
    installFetchMock();
    const untrap = trapGetCredentials();
    try {
      const client = new GeminiClient('ya29.EXPLICIT');
      await client.generateContent('gemini-2.5-flash', SAMPLE_MSGS);
      const call = captured[0];
      assert(call.url.includes('-aiplatform.googleapis.com'), 'Explicit ya29 bearer token opts request into Vertex');
      assert(call.headers['authorization'] === 'Bearer ya29.EXPLICIT', 'Explicit bearer used as Authorization');
    } catch (e: any) {
      assert(false, `Explicit bearer test threw: ${e.message}`);
    } finally {
      untrap();
      restoreFetch();
    }
  });

  // ── 7. Streaming key path: SSE URL + no project-billing header ──
  await withConfig({ geminiApiKey: 'TEST-ENV-KEY-123', vertexEnabled: false }, async () => {
    installFetchMock();
    const untrap = trapGetCredentials();
    try {
      responder = () => ({
        status: 200,
        sse: 'data: {"candidates":[{"content":{"parts":[{"text":"hello"}]}}]}\n\n',
      });
      const client = new GeminiClient();
      let chunked = '';
      const out = await client.streamContent('gemini-2.5-flash', SAMPLE_MSGS, (c) => { chunked += c; });
      const call = captured[0];
      assert(out === 'hello' && chunked === 'hello', 'Streaming key path delivers SSE chunks');
      assert(call.url.includes(':streamGenerateContent?alt=sse&key=TEST-ENV-KEY-123'), 'Stream routes to generativelanguage SSE with ?key=');
      assert(!('x-goog-user-project' in call.headers) && !('authorization' in call.headers), 'Stream key path sends no bearer / no X-Goog-User-Project');
    } catch (e: any) {
      assert(false, `Stream test threw: ${e.message}`);
    } finally {
      responder = () => ({ status: 200, body: OK_BODY });
      untrap();
      restoreFetch();
    }
  });

  // ── 8. 429 from generativelanguage → error → breaker event (fallback to free omniroute models) ──
  await withConfig({ geminiApiKey: 'TEST-ENV-KEY-123', vertexEnabled: false }, async () => {
    installFetchMock();
    responder = () => ({ status: 429, body: { error: { message: 'Resource has been exhausted (e.g. check quota)' } } });
    const breaker = getBreaker('google');
    breaker.recordSuccess(); // zero out state from other suites
    const savedThreshold = breaker.openThreshold;
    breaker.openThreshold = 1; // open on first 429 for test speed
    try {
      const client = new UniversalLlmClient(); // seeds free-tier key, vertex off
      let gotErr: any = null;
      try {
        await client.generateContent('gemini-2.5-flash', 'ping', {}, false); // no fallback: isolate attempt
      } catch (e: any) {
        gotErr = e;
      }
      assert(Boolean(gotErr) && gotErr.message.includes('429'), '429 surfaces as thrown error (contains status 429)');
      assert(breaker.snapshot().consecutiveFailures >= 1, '429 recorded as breaker failure (recordFailure)');
      // Now a follow-up call must be blocked by the open breaker — routing to
      // the ranked fallback chain (omniroute free models) instead of retrying.
      let blocked: any = null;
      try {
        await client.generateContent('gemini-2.5-flash', 'ping', {}, false);
      } catch (e: any) {
        blocked = e;
      }
      assert(Boolean(blocked) && blocked.message.includes('CIRCUIT_OPEN'), 'Open breaker blocks further google attempts → fallback chain handles failover');
    } finally {
      breaker.openThreshold = savedThreshold;
      breaker.recordSuccess();
      responder = () => ({ status: 200, body: OK_BODY });
      restoreFetch();
    }
  });

  console.log('--- Gemini Routing Matrix Tests done ---\n');
  return passed;
}

/**
 * cli_tui.test.ts — CLI/TUI layer coverage:
 *  - TuiRenderer: domain resolution, page template loading (frontmatter,
 *    fallbacks), renderText hydration, renderHtml output
 *  - ChatSession: history add/trim (max turns), clear, serialization,
 *    role handling, streaming vs unary, error path (offline via fetch stub)
 *  - terminal-chat pure parts: renderDashboard banner, printHelp commands,
 *    COMMAND_ALIASES routing for the CLI default case, /lang parsing,
 *    de-emoji strip filter on output, renderTerminalMarkdown + streamer
 * No real network/LLM: globalThis.fetch is stubbed for ChatSession paths.
 */
import fs from 'node:fs';
import path from 'node:path';
import { TuiRenderer, DOMAINS_CONFIG } from '../src/core/TuiRenderer.js';
import { ChatSession } from '../src/core/ChatSession.js';
import { ModelRegistry } from '../src/models/ModelRegistry.js';
import { ModelCommand, COMMAND_ALIASES } from '../src/models/ModelRatings.js';
import { I18nEngine, stripEmoji } from '../src/core/I18nEngine.js';

// terminal-chat auto-starts main() on import; disable for the test process
// (see the import-safety guard documented in src/cli/terminal-chat.ts).
process.env.EVABOT_CLI_AUTOSTART = 'off';

const C_RESET = '\x1b[0m';
const C_BOLD = '\x1b[1m';

export async function runCliTuiTests(): Promise<boolean> {
  console.log('\n--- Running CLI/TUI Renderer & ChatSession Tests ---');
  let passed = true;

  function assert(cond: boolean, msg: string) {
    if (cond) {
      console.log(`  ✓ ${msg}`);
    } else {
      console.error(`  ✗ FAIL: ${msg}`);
      passed = false;
    }
  }

  // =====================================================================
  // 1. TuiRenderer — domain resolution
  // =====================================================================
  {
    const meta0 = TuiRenderer.resolveDomain(undefined);
    assert(meta0.domain === DOMAINS_CONFIG[0].domain, 'resolveDomain(undefined) → first DOMAINS_CONFIG entry');

    const meta1 = TuiRenderer.resolveDomain('www.EvaBot.ONLINE:443');
    assert(meta1.domain === 'evabot.online' && meta1.badge === 'NEURAL CORE', 'resolveDomain strips www/port and lowercases host');

    const meta2 = TuiRenderer.resolveDomain('evaline.network');
    assert(meta2.domain === 'evaline.network' && meta2.badge === 'EDGE MESH', 'resolveDomain maps evaline.network to EDGE MESH meta');
  }

  // =====================================================================
  // 2. TuiRenderer — page template loading (frontmatter + fallbacks)
  // =====================================================================
  {
    const fm = TuiRenderer.loadPageTemplate('evabot.online');
    assert(fm.meta.domain === 'evabot.online', 'loadPageTemplate: known host returns its meta');
    assert(typeof fm.body === 'string' && fm.body.length > 0, 'loadPageTemplate: body read from template file');

    const missing = TuiRenderer.loadPageTemplate('no-such-host-xyz-42');
    assert(missing.meta.domain === DOMAINS_CONFIG[0].domain, 'loadPageTemplate: unknown host falls back to default meta');
    assert(missing.body.length > 0, 'loadPageTemplate: unknown host falls back to default template body');

    // Temporary fixture with front-matter override (incl. colon in value)
    const fixture = path.join(process.cwd(), 'pages', 'tui-test-fixture.unui.md');
    try {
      fs.writeFileSync(
        fixture,
        [
          '---',
          'domain: tui-test-fixture.dev',
          'badge: TEST-BADGE',
          'role: Test Role Line',
          'infra: Test Infra: with colon',
          'target: ip: 10.0.0.1',
          '---',
          '# Body Marker XYZ',
          'plain body line',
          '',
        ].join('\n'),
        'utf-8'
      );
      const parsed = TuiRenderer.loadPageTemplate('tui-test-fixture');
      assert(parsed.meta.domain === 'tui-test-fixture.dev', 'frontmatter: domain override parsed');
      assert(parsed.meta.badge === 'TEST-BADGE' && parsed.meta.role === 'Test Role Line', 'frontmatter: badge/role parsed');
      assert(parsed.meta.infra === 'Test Infra: with colon', 'frontmatter: values containing colons survive (join(":"))');
      assert(parsed.meta.target === 'ip: 10.0.0.1', 'frontmatter: target parsed with colon value');
      assert(parsed.body.includes('# Body Marker XYZ'), 'frontmatter: body after closing --- separator');

      const raw = TuiRenderer.getRawTemplate('tui-test-fixture');
      assert(raw.includes('TEST-BADGE') && raw.includes('# Body Marker XYZ'), 'getRawTemplate returns full raw markdown');

      const rawText = TuiRenderer.getRawTextTemplate('tui-test-fixture');
      assert(typeof rawText === 'string' && rawText.length > 0, 'getRawTextTemplate reads .unui.txt variant or fallback');
    } finally {
      if (fs.existsSync(fixture)) fs.unlinkSync(fixture);
    }

    const rawDefault = TuiRenderer.getRawTemplate('www.UNKNOWN-HOST.invalid:8080');
    const rawDefaultDisk = fs.readFileSync(path.join(process.cwd(), 'pages', 'default.unui.md'), 'utf-8');
    assert(rawDefault === rawDefaultDisk, 'getRawTemplate: unknown host (www/port stripped) → default.unui.md');

    const rawTextFallback = TuiRenderer.getRawTextTemplate('tui-test-no-file');
    const rawTextDisk = fs.readFileSync(path.join(process.cwd(), 'pages', 'default.unui.txt'), 'utf-8');
    assert(rawTextFallback === rawTextDisk && rawTextFallback.length > 0, 'getRawTextTemplate: unknown host → default.unui.txt');

    const resolveMeta = TuiRenderer.resolveDomain('tui-test-fixture');
    assert(resolveMeta.domain === DOMAINS_CONFIG[0].domain, 'resolveDomain with host without template → default meta');
  }

  // =====================================================================
  // 3. TuiRenderer — renderText / renderHtml (offline: local metrics only)
  // =====================================================================
  {
    const text = TuiRenderer.renderText('evabot.online');
    assert(text.length > 100, 'renderText: produces substantial output');
    assert(text.includes('● EvaBot v0.0.1') && text.includes('Ping:'), 'renderText: banner body rendered from template');
    assert(text.endsWith('\n') && !text.endsWith('\n\n'), 'renderText: output trimmed to single trailing newline');
    assert(!/<!--\s*\/?SLOT:[A-Z_]+\s*-->/.test(text), 'renderText: slot comment tags stripped from terminal stream');

    const textHost = TuiRenderer.renderText('www.EVALINE.NETWORK:8080');
    assert(textHost.length > 100, 'renderText: www/port normalization works for evaline.network');

    const html = TuiRenderer.renderHtml('evabot.online');
    assert(html.startsWith('<!DOCTYPE html>'), 'renderHtml: valid HTML document start');
    assert(html.includes('EVALINE CONSOLE // evabot.online [NEURAL CORE]'), 'renderHtml: topbar shows domain + badge');
    assert(html.includes('proc-table') && html.includes('LIVE PROCESS WATCHER'), 'renderHtml: process watcher section present');
    assert(html.includes('EVABRAIN') && html.includes('WIREGUARD MESH BACKBONE'), 'renderHtml: telemetry section present');
    assert(html.includes('makeBar') && html.includes('formatSecs'), 'renderHtml: embedded JS helpers present');

    const htmlOther = TuiRenderer.renderHtml('evaline.website');
    assert(htmlOther.includes('evaline.website [CHRONICLE]'), 'renderHtml: alternate domain maps to its badge');
  }

  // =====================================================================
  // 4. ChatSession — history add/trim/clear/serialization (fetch stubbed)
  // =====================================================================
  const realFetch = globalThis.fetch;
  {
    const geminiOk = () => Promise.resolve({
      ok: true,
      status: 200,
      text: async () => '',
      json: async () => ({
        candidates: [{ content: { parts: [{ text: 'MOCK-REPLY' }] } }],
      }),
    } as unknown as Response);

    globalThis.fetch = (async (url: unknown) => {
      const u = String(url);
      if (u.includes('generativelanguage.googleapis.com')) return geminiOk();
      throw new Error(`Unexpected fetch in test: ${u}`);
    }) as typeof fetch;

    try {
      const session = new ChatSession({ model: 'gemini-2.5-flash', apiKey: 'test-key-123456', maxHistoryTurns: 2 });

      const empty = session.getHistory();
      assert(empty.length === 0, 'ChatSession: starts with empty history');

      const reply = await session.sendMessage('  Привет, как дела?  ');
      assert(reply === 'MOCK-REPLY', 'ChatSession.sendMessage: returns model reply from API response');
      let hist = session.getHistory();
      assert(hist.length === 2, 'ChatSession: one exchange records user+model messages');
      assert(hist[0].role === 'user' && hist[0].parts[0].text === 'Привет, как дела?', 'ChatSession: user prompt is trimmed and role=user');
      assert(hist[1].role === 'model' && hist[1].parts[0].text === 'MOCK-REPLY', 'ChatSession: model reply recorded with role=model');

      const serialized = JSON.stringify(hist);
      const revived = JSON.parse(serialized);
      assert(revived.length === 2 && revived[0].role === 'user' && revived[1].role === 'model', 'ChatSession: history JSON-serializable (round-trip)');

      hist[0].parts[0].text = 'TAMPERED';
      assert(session.getHistory()[0].parts[0].text === 'TAMPERED', 'getHistory: shallow copy shares message objects (documented finding)');
      const beforePush = session.getHistory().length;
      session.getHistory().push({ role: 'user', parts: [{ text: 'extra' }] });
      assert(session.getHistory().length === beforePush, 'ChatSession: getHistory returns a copy (array-level isolation)');

      await session.sendMessage('msg-2');
      await session.sendMessage('msg-3');
      hist = session.getHistory();
      // maxHistoryTurns=2 → at most 4 messages kept (2 turns * user+model)
      assert(hist.length === 4, `ChatSession.trimHistory: keeps maxHistoryTurns*2 messages (got ${hist.length})`);
      assert(hist[0].parts[0].text === 'msg-2' && hist[1].parts[0].text === 'MOCK-REPLY', 'trimHistory: oldest exchange dropped, newest kept');
      assert(hist[3].parts[0].text === 'MOCK-REPLY' && hist[2].parts[0].text === 'msg-3', 'trimHistory: newest exchange intact');

      session.clearHistory();
      assert(session.getHistory().length === 0, 'ChatSession.clearHistory: empties history');

      // trimHistory is a no-op when under the limit
      await session.sendMessage('short');
      session.trimHistory();
      assert(session.getHistory().length === 2, 'trimHistory: no-op when under the limit');

      // Error path: fetch failure → throws, history not mutated
      const before = session.getHistory().length;
      globalThis.fetch = (async () => Promise.resolve({
        ok: false,
        status: 429,
        text: async () => JSON.stringify({ error: { message: 'rate limited (stub)' } }),
        json: async () => ({}),
      } as unknown as Response)) as typeof fetch;
      let threw = false;
      try {
        await session.sendMessage('boom');
      } catch (err: any) {
        threw = true;
        assert(String(err.message).includes('429'), 'ChatSession.sendMessage: propagates API error');
      }
      assert(threw, 'ChatSession.sendMessage: throws on API error');
      assert(session.getHistory().length === before, 'ChatSession: failed exchange is not recorded in history');

      // Streaming path (SSE body) with onChunk callback
      globalThis.fetch = (async (url: unknown) => {
        const u = String(url);
        if (!u.includes('streamGenerateContent')) throw new Error(`Expected stream URL, got ${u}`);
        const encoder = new TextEncoder();
        const events = [
          'data: {"candidates":[{"content":{"parts":[{"text":"PAR"}]}}]}\n\n',
          'data: {"candidates":[{"content":{"parts":[{"text":"T2"}]}}]}\n\n',
          'data: [DONE]\n\n',
        ];
        const body = new ReadableStream({
          start(controller) {
            for (const e of events) controller.enqueue(encoder.encode(e));
            controller.close();
          },
        });
        return { ok: true, status: 200, body, text: async () => '', json: async () => ({}) } as unknown as Response;
      }) as typeof fetch;

      const chunks: string[] = [];
      const streamed = await session.sendMessage('stream me', (c) => chunks.push(c));
      assert(streamed === 'PART2', 'ChatSession.streamContent: SSE chunks concatenated into full text');
      assert(chunks.join('') === 'PART2', 'ChatSession: onChunk receives each streamed chunk');
      const streamHist = session.getHistory();
      const last = streamHist[streamHist.length - 1];
      assert(last.role === 'model' && last.parts[0].text === 'PART2', 'ChatSession: streamed reply recorded in history');
    } finally {
      globalThis.fetch = realFetch;
    }

    // Model fallback on invalid constructor model
    const defaultId = ModelRegistry.getDefaultModel().id;
    const fallbackSession = new ChatSession({ model: 'definitely-not-a-model', apiKey: 'test-key-123456' });
    assert(fallbackSession.getModel() === defaultId, 'ChatSession: invalid constructor model falls back to registry default');

    const sysSession = new ChatSession({ apiKey: 'test-key-123456' });
    sysSession.setSystemInstruction('Always answer in Ukrainian.');
    assert(sysSession.getSystemInstruction() === 'Always answer in Ukrainian.', 'ChatSession: setSystemInstruction/getSystemInstruction');

    assert(sysSession.hasApiKey() === true, 'ChatSession: hasApiKey true after explicit key');
    sysSession.setApiKey('another-key-654321');
    assert(sysSession.hasApiKey() === true, 'ChatSession: setApiKey replaces credential');

    // trimHistory keeps newest half of the window when over the limit
    assert(ModelRegistry.isValidModel('gemini-2.5-flash'), 'ModelRegistry: valid model accepted');
    assert(!ModelRegistry.isValidModel('nope-nope'), 'ModelRegistry: invalid model rejected');
  }

  // =====================================================================
  // 5. terminal-chat — banner (renderDashboard), help, aliases, /lang
  // =====================================================================
  const cli = await import('../src/cli/terminal-chat.js');
  {
    const realLog = console.log;
    let captured = '';
    console.log = (...args: unknown[]) => {
      captured += args.map((a) => (typeof a === 'string' ? a : '')).join('') + '\n';
    };
    try {
      I18nEngine.setLocale('en');
      const session = new ChatSession({ apiKey: 'test-key-123456', model: ModelRegistry.getDefaultModel().id });
      cli.renderDashboard(session);

      const lines = captured.split('\n');
      assert(lines[0].includes('●') && lines[0].includes('EvaBot v0.0.1'), 'renderDashboard line 1: project name + status dot');
      assert(captured.includes('Ping:'), 'renderDashboard: Ping line present');
      assert(captured.includes('Model:') && captured.includes(session.getModel()), 'renderDashboard: Model line shows active model');
      assert(captured.includes('[FREE]') || captured.includes('[PAID]'), 'renderDashboard: pricing tier badge present');
      assert(captured.includes('Pool:'), 'renderDashboard: model pool count line present');
      assert(captured.includes('Lang:'), 'renderDashboard: Lang line present');
      assert(captured.includes('Databases:'), 'renderDashboard: Databases line present');
      assert(captured.includes('Load:') && captured.includes('Brain(Frankfurt)') && captured.includes('Face(Iowa)'), 'renderDashboard: cluster load telemetry line present');
      assert(captured.includes('■') && captured.includes('░'), 'renderDashboard: ASCII load bars rendered');
      assert(captured.includes('system :'), 'renderDashboard: system greeting printed');

      const strip = captured.split('\n').find((l) => l.includes('/help') && l.includes('/clear')) || '';
      const dashCommands = ['/help', '/?', '/top', '/models', '/cost', '/company', '/evaline', '/products', '/who', '/lang', '/mode', '/consilium', '/sephirot', '/mcp', '/lsp', '/history', '/memory', '/search', '/services', '/servers', '/clear'];
      const missingCmds = dashCommands.filter((c) => !strip.includes(c));
      assert(missingCmds.length === 0, `renderDashboard: 21-command strip complete (missing: ${missingCmds.join(',')})`);
      const slashCount = (strip.match(/\//g) || []).length;
      assert(slashCount >= 21, `renderDashboard: strip advertises ≥21 commands (got ${slashCount})`);

      captured = '';
      cli.printHelp();
      const help = captured;
      const requiredHelp = ['/voices', '/settings', '/agents', '/developer', '/sys', '/say', '/listen', '/translate', '/monitor', '/emoji', '/exit'];
      const missingHelp = requiredHelp.filter((c) => !help.includes(c));
      assert(missingHelp.length === 0, `printHelp: documents new commands (missing: ${missingHelp.join(',')})`);
      assert(help.includes('/help') && help.includes('/?'), 'printHelp: basics documented');
    } finally {
      console.log = realLog;
    }

    // /lang parsing (I18nEngine.setLocale) as used by the /lang CLI case
    assert(I18nEngine.setLocale('uk').locale === 'uk', '/lang uk → uk locale');
    assert(I18nEngine.setLocale('UA').locale === 'uk', '/lang UA (uppercase alias) → uk locale');
    assert(I18nEngine.setLocale('ukr').locale === 'uk', '/lang ukr → uk locale');
    assert(I18nEngine.setLocale('ru').locale === 'ru', '/lang ru → ru locale');
    assert(I18nEngine.setLocale('RUS').locale === 'ru', '/lang RUS → ru locale');
    assert(I18nEngine.setLocale('de').locale === 'en', '/lang with unsupported code → en fallback');
    assert(I18nEngine.setLocale('').locale === 'en', '/lang with empty arg → en fallback');
    const ukStrings = I18nEngine.getStrings('uk');
    assert(typeof ukStrings.helpCommands.length === 'number' && ukStrings.helpCommands.length > 0, 'I18n: every locale has help commands');
    const ruHelp = I18nEngine.formatHelp('ru');
    assert(ruHelp.includes('═'.repeat(78)) && ruHelp.split('\n').length > 5, 'I18n: formatHelp ru renders framed help');
    const enLocale = I18nEngine.setLocale('en');
    assert(enLocale.locale === 'en' && typeof enLocale.message === 'string', '/lang en resets locale');

    // CLI default case: alias routing table covers every canonical target
    const canonicalTargets = ['/history', '/memory', '/search', '/find', '/services', '/servers', '/health', '/news', '/translate', '/products', '/who', '/debug', '/log', '/monitor', '/say', '/listen', '/sys', '/developer', '/voices', '/settings', '/agents'];
    const unroutable = canonicalTargets.filter((t) => !Object.values(COMMAND_ALIASES).includes(t));
    assert(unroutable.length === 0, `COMMAND_ALIASES: every CLI default-case target has ≥1 alias (unroutable: ${unroutable.join(',')})`);
    assert(COMMAND_ALIASES['/скажи'] === '/say' && COMMAND_ALIASES['/сказать'] === '/say', 'alias routing: /say UK/RU aliases');
    assert(COMMAND_ALIASES['/історія'] === '/history' && COMMAND_ALIASES['/история'] === '/history', 'alias routing: /history UK/RU aliases');
    assert(COMMAND_ALIASES['/stt'] === '/listen' && COMMAND_ALIASES['/переклад'] === '/translate', 'alias routing: /listen + /translate aliases');
    const badAliasValues = Object.values(COMMAND_ALIASES).filter((v) => !/^\/[a-z]+$/.test(v));
    assert(badAliasValues.length === 0, `COMMAND_ALIASES: all values are canonical /commands (bad: ${badAliasValues.slice(0, 3).join(',')})`);
  }

  // =====================================================================
  // 6. terminal-chat — de-emoji strip filter (installEmojiStripFilter)
  // =====================================================================
  {
    const written: string[] = [];
    const fakeStream = { write: (...args: unknown[]) => { written.push(String(args[0])); return true; } };
    cli.installEmojiStripFilter(fakeStream as any);
    fakeStream.write('Broadcast 🎤 on 🔊 off 🔇 done ✅\n');
    assert(written[0] === 'Broadcast [ MIC ] on [ TTS:ON ] off [ TTS:OFF ] done [OK]\n', 'emoji strip filter: emoji replaced with ASCII on output');

    const rawOut: string[] = [];
    const rawStream = { write: (...args: unknown[]) => { rawOut.push(args.map(String).join('|')); return true; } };
    cli.installEmojiStripFilter(rawStream as any, () => false);
    rawStream.write('🎤 stays\n');
    assert(rawOut[0] === '🎤 stays\n', 'emoji strip filter: disabled mode passes emoji through');
    rawStream.write('non-string fallback: ', 42, '\n');
    assert(rawOut[1] === 'non-string fallback: |42|\n', 'emoji strip filter: non-string args forwarded untouched');

    // stripEmoji composition (same function the CLI writer delegates to)
    assert(stripEmoji('Готово 🚀 ✅ мир') === 'Готово  [OK] мир', 'stripEmoji: unmapped emoji removed, ✅ → [OK]');
    const rendered = cli.renderTerminalMarkdown('**Готово** 🚀 ✅');
    assert(!stripEmoji(rendered).includes('🚀') && stripEmoji(rendered).includes('[OK]'), 'strip path: markdown output de-emojified with ASCII badge');
  }

  // =====================================================================
  // 7. terminal-chat — renderTerminalMarkdown (batch) & streamer
  // =====================================================================
  {
    assert(cli.renderTerminalMarkdown('') === '', 'renderTerminalMarkdown: empty input → empty output');

    const md = cli.renderTerminalMarkdown('# Заголовок\n**bold** *ital* `code`\n- item\n1. step\n> quote\n---\n[text](https://example.com)');
    assert(md.includes('# Заголовок') && md.includes('\x1b[32m'), 'markdown: heading highlighted (bold+green)');
    assert(md.includes(C_BOLD), 'markdown: bold ANSI applied');
    assert(md.includes('bold') && md.includes('ital') && md.includes('code'), 'markdown: inline styles rendered');
    assert(md.includes('•'), 'markdown: unordered list bullet');
    assert(md.includes('│'), 'markdown: blockquote bar');
    assert(md.includes('─'.repeat(50)), 'markdown: horizontal rule');
    assert(md.includes('https://example.com'), 'markdown: link URL preserved');

    const code = cli.renderTerminalMarkdown('```ts\nconst a = 1;\n```');
    assert(code.includes('[TS]') && code.includes('┌──') && code.includes('└──'), 'markdown: fenced code block boxed with language tag');
    const codeNoLang = cli.renderTerminalMarkdown('```\nplain\n```');
    const stripped = codeNoLang.replace(/\x1b\[[0-9;]*m/g, '');
    assert(stripped.includes('┌──') && !stripped.includes('['), 'markdown: fence without language omits tag');

    const writes: string[] = [];
    const streamer = new cli.TerminalMarkdownStreamer((t) => writes.push(t));
    streamer.push('```py\n');
    streamer.push('print(1)\n');
    streamer.push('```\n');
    streamer.push('done **x**');
    streamer.finish();
    const out = writes.join('');
    assert(out.includes('[PY]') && out.includes('print(1)'), 'streamer: code block rendered across pushed chunks');
    assert(out.includes('└──'), 'streamer: closing fence after code block');
    assert(out.includes('done') && out.includes('x'), 'streamer: trailing partial line flushed by finish()');
    assert(out.includes('─'.repeat(46)), 'streamer: code block rule lines');
  }

  // =====================================================================
  // 8. ModelCommand.execute — offline sanity for commands routed by the CLI
  // =====================================================================
  {
    const models = ModelCommand.execute('/models');
    assert(models.length > 50 && (models.includes('модел') || models.toLowerCase().includes('model')), 'ModelCommand /models: catalog rendered offline');
    const unknownCmd = I18nEngine.getStrings('en');
    assert(unknownCmd.unknownCommand.includes('{cmd}'), 'I18n: unknownCommand template has {cmd} placeholder');
  }

  console.log('--- CLI/TUI Renderer & ChatSession tests done ---');
  return passed;
}

