function buildRouter(): Router {
  const router = new Router();

  router.get('/api/health', async (ctx) => {
    const creds = await GoogleAuthProvider.getCredentials();
    const pluginList = pluginManager.list();
    const pluginStatuses = await pluginManager.healthCheckAll();

    const micro = ClusterMonitor.getMicroMetrics();
    const meshLatency = ClusterMonitor.getMeshLatency();
    const bLoad = os.loadavg()[0].toFixed(2);
    const bCpuPct = Math.min(100, Math.round((parseFloat(bLoad) / os.cpus().length) * 100));
    const bTotMem = Math.round(os.totalmem() / (1024 * 1024 * 1024));
    const bUsedMem = ((os.totalmem() - os.freemem()) / (1024 * 1024 * 1024)).toFixed(1);

    ctx.sendJson(200, {
      status: 'online',
      version: 'v0.1.0',
      server: 'evabot-online-edge',
      uptimeSeconds: Math.floor(process.uptime()),
      memoryUsageMb: Math.round(process.memoryUsage().rss / (1024 * 1024)),
      systemLoad: bLoad,
      cpuCores: os.cpus().length,
      totalMemoryMb: Math.round(os.totalmem() / (1024 * 1024)),
      freeMemoryMb: Math.round(os.freemem() / (1024 * 1024)),
      availableModels: 78,
      hasServerApiKey: Boolean(creds),
      authSource: creds ? creds.source : 'None',
      databases: {
        chroma: { name: 'ChromaDB Vector', count: 1075, status: 'OK' },
        fts: { name: 'SQLite FTS5', count: 1086, status: 'OK' },
        memoryKb: { name: 'Memory KnowledgeBase', count: 178, status: 'OK' },
        mcp: { name: 'MCP SQLite', status: 'OK' },
      },
      telemetry: {
        frankfurt: {
          load: bLoad,
          cpuPct: bCpuPct,
          memUsedGb: bUsedMem,
          memTotalGb: bTotMem,
        },
        iowa: {
          load: micro.loadAvg.split(',')[0],
          cpuPct: micro.cpuPct,
          memUsedMb: micro.memUsedMb,
          memTotalMb: micro.memTotalMb,
        },
        meshLatencyMs: meshLatency,
      },
      plugins: {
        loaded: pluginList.length,
        active: pluginList.filter(p => p.enabled).length,
        list: pluginList,
        health: pluginStatuses,
      },
    });
  });

  const subRouters = [
    createModelsRouter(),
    createLogsRouter(),
    createSecurityRouter(),
    createAlertsRouter(),
    createPluginsRouter(),
    createVoiceRouter(),
  ];

  for (const sub of subRouters) {
    for (const route of (sub as any).routes) {
      router.add(route.method, route.pattern as string, route.handler);
    }
  }

  const pluginRoutes = pluginManager.getAllPluginRoutes();
  for (const pr of pluginRoutes) {
    router.add(pr.method, pr.path, async (ctx) => {
      const body = ctx.method === 'GET' ? null : await ctx.parseJsonBody().catch(() => ({}));
      const queryObj: any = {};
      ctx.query.forEach((v, k) => { queryObj[k] = v; });
      try {
        const result = await pr.handler(body || {}, queryObj);
        ctx.sendJson(200, result);
      } catch (err: any) {
        ctx.sendJson(err.statusCode || 500, { error: err.message });
      }
    });
  }

  const chatRouter = new ChatRouter();
  for (const route of (chatRouter as any).routes) {
    router.add(route.method, route.pattern as string, route.handler);
  }

  return router;
}

export function createServer(): http.Server {
  ClusterMonitor.init();

  const router = buildRouter();

  return http.createServer(async (req, res) => {
    const parsedUrl = new URL(req.url || '/', `http://${req.headers.host || 'localhost'}`);
    const pathname = parsedUrl.pathname;
    const startTime = Date.now();
    const clientIp = (req.headers['x-forwarded-for'] as string)?.split(',')[0] || req.socket.remoteAddress || 'unknown';
    const userAgent = (req.headers['user-agent'] as string) || 'unknown';
    const method = req.method || 'GET';

    if (method === 'OPTIONS') {
      res.writeHead(204, {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Gemini-Key, X-OmniRoute-Key, X-OpenRouter-Key',
      });
      res.end();
      return;
    }

    if (securityConfig.blockedIPs.has(clientIp)) {
      logger.warn(LogCategory.SYSTEM, 'SECURITY', `Blocked IP: ${clientIp} -> ${method} ${pathname}`);
      res.writeHead(403, { 'Content-Type': 'text/plain' });
      res.end('403 Forbidden');
      return;
    }

    const rateCheck = Security.checkRateLimit(clientIp);
    res.setHeader('X-RateLimit-Limit', securityConfig.rateLimit.maxRequests.toString());
    res.setHeader('X-RateLimit-Remaining', rateCheck.remaining.toString());
    res.setHeader('X-RateLimit-Reset', Math.ceil(rateCheck.resetIn / 1000).toString());

    if (!rateCheck.allowed) {
      res.writeHead(429, { 'Retry-After': Math.ceil(rateCheck.resetIn / 1000).toString() });
      res.end('429 Too Many Requests');
      return;
    }

    const suspCheck = Security.isSuspicious(pathname, method);
    if (suspCheck.suspicious) Security.recordSuspicious(clientIp, suspCheck.reason || 'unknown');

    res.on('finish', () => {
      const duration = Date.now() - startTime;
      logger.logHttpRequest(method, pathname, res.statusCode, duration, clientIp, userAgent);
    });

    const match = router.match(method, pathname);
    if (match) {
      const ctx = createRouteContext(req, res, pathname, parsedUrl, {
        sendJson: (status, data) => sendJson(res, status, data),
        sendText: (status, text) => sendText(res, status, text),
        parseJsonBody: () => parseJsonBody(req),
      });
      try {
        await match.route.handler(ctx);
      } catch (err: any) {
        logger.error(LogCategory.HTTP, 'ROUTE', `${method} ${pathname}: ${err.message}`);
        if (!res.headersSent) {
          sendJson(res, 500, { error: err.message || 'Internal server error' });
        }
      }
      return;
    }

    const staticRoutes = [
      '/', '/index.html',
      '/manifesto', '/manifesto.html',
      '/hub', '/hub.html',
      '/network', '/network.html',
      '/visualize', '/visualize.html',
      '/terminal', '/terminal.txt', '/plain',
    ];

    if (pathname.startsWith('/dist/') || pathname.startsWith('/fonts/') || staticRoutes.includes(pathname)) {
      let filePath = '';
      const host = (req.headers.host || 'localhost').toLowerCase().replace(/^www\./, '');

      if (pathname.startsWith('/fonts/')) {
        // Self-hosted static fonts (public/fonts) — path-sanitized, no traversal
        const rel = pathname.slice('/fonts/'.length).replace(/\\/g, '/').replace(/\.\./g, '');
        filePath = path.resolve(process.cwd(), 'public', 'fonts', rel);
      } else if (pathname.startsWith('/dist/')) {
        filePath = path.resolve(process.cwd(), pathname.slice(1));
      } else if (pathname === '/manifesto' || pathname === '/manifesto.html') {
        filePath = path.resolve(process.cwd(), 'public', 'manifesto.html');
      } else if (pathname === '/hub' || pathname === '/hub.html') {
        filePath = path.resolve(process.cwd(), 'public', 'hub.html');
      } else if (pathname === '/network' || pathname === '/network.html' || pathname === '/visualize' || pathname === '/visualize.html') {
        filePath = path.resolve(process.cwd(), 'public', 'network.html');
      } else if (pathname === '/' || pathname === '/index.html') {
        const ua = (req.headers['user-agent'] || '').toLowerCase();
        const isCliBrowser = ua.includes('curl') || ua.includes('wget') || ua.includes('lynx') || ua.includes('w3m') || ua.includes('elinks') || ua.includes('httpie');
        if (isCliBrowser) {
          const text = TuiRenderer.renderText(host);
          sendText(res, 200, text, 'text/plain; charset=utf-8');
          return;
        }

        // Domain-specific home page routing:
        if (host.includes('evaline.online')) {
          filePath = path.resolve(process.cwd(), 'public', 'manifesto.html');
        } else if (host.includes('evaline.website')) {
          filePath = path.resolve(process.cwd(), 'public', 'hub.html');
        } else if (host.includes('evaline.network')) {
          const text = TuiRenderer.renderHtml(host);
          sendText(res, 200, text, 'text/html; charset=utf-8');
          return;
        } else {
          filePath = path.resolve(process.cwd(), 'public', 'index.html');
        }
      } else if (pathname === '/terminal' || pathname === '/terminal.txt' || pathname === '/plain') {
        const isCurl = (req.headers['user-agent'] || '').toLowerCase().includes('curl');
        const text = isCurl ? TuiRenderer.renderText(host) : TuiRenderer.renderHtml(host);
        const contentType = isCurl ? 'text/plain; charset=utf-8' : 'text/html; charset=utf-8';
        sendText(res, 200, text, contentType);
        return;
      }

      if (filePath && fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
        const ext = path.extname(filePath).toLowerCase();
        const contentType = MIME_TYPES[ext] || 'application/octet-stream';
        res.writeHead(200, { 'Content-Type': contentType });
        fs.createReadStream(filePath).pipe(res);
        return;
      }
    }

    sendText(res, 404, 'Not Found');
  });
}

export async function startServerAsync(port: number = Config.serverPort, host: string = Config.serverHost): Promise<void> {
  await initializePlugins();
  const server = createServer();

  server.listen(port, host, () => {
    logger.info(LogCategory.SYSTEM, 'Server', `[+] EvaBot HTTP Server listening on http://${host}:${port}`);
  });

  try {
    startTelegramBot();
  } catch (err: any) {
    logger.warn(LogCategory.SYSTEM, 'Server', `Telegram bot init failed: ${err.message}`);
  }

  process.on('SIGTERM', async () => {
    logger.info(LogCategory.SYSTEM, 'Server', 'Shutting down...');
    await pluginManager.shutdownAll();
    server.close();
  });
}

export function startServer(port: number = Config.serverPort, host: string = Config.serverHost): void {
  startServerAsync(port, host).catch(err => {
    logger.error(LogCategory.SYSTEM, 'Server', `Failed to start: ${err.message}`);
  });
}

if (process.argv[1] && (process.argv[1].endsWith('server.js') || process.argv[1].endsWith('server.ts'))) {
  startServer();
}

import { GeminiClient, ChatMessage, GenerationOptions } from './GeminiClient.js';
import { Config } from './Config.js';
import { logger } from './Logger.js';
import { ModelRegistry } from '../models/ModelRegistry.js';
import { ModelRatings } from '../models/ModelRatings.js';
import { withTimeout, getBreaker, LLM_CALL_TIMEOUT_MS, ProviderFallbackChain } from './Resilience.js';
import { OpLog } from './OpLog.js';

export type LlmProvider = 'google' | 'omniroute' | 'openrouter' | 'opencode';

export interface UniversalMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface UniversalGenerationOptions {
  temperature?: number;
  maxOutputTokens?: number;
  systemInstruction?: string;
  provider?: LlmProvider;
  apiKey?: string;
  signal?: AbortSignal;
}

export class UniversalLlmClient {
  private geminiClient: GeminiClient;

  constructor(apiKeyOrToken?: string) {
    // When paid Vertex traffic is explicitly enabled (EVA_VERTEX_ENABLED=1),
    // do NOT seed the free-tier key as an explicit credential — leave the
    // GeminiClient free to resolve the Vertex bearer per its ONLY-FREE policy.
    const seedKey = apiKeyOrToken || (Config.vertexEnabled ? undefined : Config.geminiApiKey) || undefined;
    this.geminiClient = new GeminiClient(seedKey);
  }

  /**
   * Automatically resolves provider based on model name or explicit option
   */
  public resolveProvider(model: string, explicitProvider?: LlmProvider): LlmProvider {
    if (explicitProvider) {
      return explicitProvider;
    }

    const m = model.toLowerCase();
    if (m.startsWith('omniroute/') || m.startsWith('omni/')) {
      return 'omniroute';
    }
    if (m.startsWith('opencode/')) {
      return 'opencode';
    }
    if (
      m.startsWith('openrouter/') ||
      m.endsWith(':free')
    ) {
      return 'openrouter';
    }

    const modelInfo = ModelRegistry.getModelById(model);
    if (modelInfo) {
      if (
        modelInfo.category.startsWith('OpenRouter') ||
        modelInfo.tier === '100% Free Community' ||
        modelInfo.provider === 'OpenRouter'
      ) {
        return 'openrouter';
      }
      if (modelInfo.category.startsWith('OmniRoute') || modelInfo.tier === 'OmniRoute Daemon' || modelInfo.provider === 'OmniRoute') {
        return 'omniroute';
      }
      if (modelInfo.category.startsWith('OpenCode') || modelInfo.tier === 'OpenCode Platform' || modelInfo.provider === 'OpenCode AI') {
        return 'opencode';
      }
      if (modelInfo.provider === 'Google DeepMind') {
        return 'google';
      }
    }

    if (
      m.startsWith('anthropic/') ||
      m.startsWith('openai/') ||
      m.startsWith('deepseek/') ||
      m.startsWith('qwen/') ||
      m.startsWith('mistralai/') ||
      m.startsWith('microsoft/') ||
      m.startsWith('x-ai/') ||
      m.startsWith('cohere/') ||
      m.startsWith('meta-llama/')
    ) {
      return 'openrouter';
    }

    return 'google';
  }

  /**
   * Normalizes input messages from either ChatMessage[] or UniversalMessage[] or string
   */
  public normalizeToUniversal(
    input: string | UniversalMessage[] | ChatMessage[]
  ): UniversalMessage[] {
    if (typeof input === 'string') {
      return [{ role: 'user', content: input }];
    }

    if (!Array.isArray(input) || input.length === 0) {
      return [];
    }

    // Check if it's ChatMessage[]
    if ('parts' in input[0]) {
      const chatMsgs = input as ChatMessage[];
      return chatMsgs.map((m) => ({
        role: m.role === 'model' ? 'assistant' : 'user',
        content: m.parts.map((p) => p.text || '').join('\n'),
      }));
    }

    return input as UniversalMessage[];
  }

  /**
   * Converts UniversalMessage[] to Gemini ChatMessage[] and extracts system prompt
   */
  public toGeminiFormat(
    messages: UniversalMessage[],
    defaultSystem?: string
  ): { contents: ChatMessage[]; systemInstruction?: string } {
    let systemInstruction = defaultSystem;
    const contents: ChatMessage[] = [];

    for (const msg of messages) {
      if (msg.role === 'system') {
        systemInstruction = systemInstruction ? `${systemInstruction}\n${msg.content}` : msg.content;
      } else {
        contents.push({
          role: msg.role === 'assistant' ? 'model' : 'user',
          parts: [{ text: msg.content }],
        });
      }
    }

    return { contents, systemInstruction };
  }

  /**
   * Strips provider prefixes like 'omniroute/' or 'opencode/' or 'openrouter/' for upstream payload if needed
   */
  private cleanModelId(model: string, provider: LlmProvider): string {
    // NOTE: the LiteLLM daemon serves ids WITH the omni/ prefix (verified
    // live 2026-09-08: /v1/models → 'omni/cf-gpt-oss-120b', …) — never strip
    // 'omni/'. Only the legacy 'omniroute/' alias prefix is stripped.
    if (provider === 'omniroute' && model.startsWith('omniroute/')) {
      return model.replace('omniroute/', '');
    }
    if (provider === 'opencode' && model.startsWith('opencode/')) {
      return model.replace('opencode/', '');
    }
    // Exception: 'openrouter/free' is the REAL upstream model id of the
    // OpenRouter free-models meta-router — the prefix must NOT be stripped.
    if (provider === 'openrouter' && model.startsWith('openrouter/') && model !== 'openrouter/free') {
      return model.replace('openrouter/', '');
    }
    return model;
  }

  /**
   * Internal execution of generateContent for a specific model without fallback
   */
  private async executeGenerate(
    model: string,
    universalMsgs: UniversalMessage[],
    options: UniversalGenerationOptions
  ): Promise<string> {
    const provider = this.resolveProvider(model, options.provider);
    logger.debug('UniversalLlmClient', `Generating unary response via provider: ${provider} [model: ${model}]`);

    if (provider === 'google') {
      const { contents, systemInstruction } = this.toGeminiFormat(
        universalMsgs,
        options.systemInstruction || Config.defaultSystemInstruction
      );
      if (options.apiKey) {
        this.geminiClient.setApiKey(options.apiKey);
      }
      return this.geminiClient.generateContent(model, contents, {
        temperature: options.temperature,
        maxOutputTokens: options.maxOutputTokens,
        systemInstruction,
        signal: options.signal,
      });
    }

    return this.generateOpenAiCompatible(provider, model, universalMsgs, options);
  }

  /**
   * Resilience-wrapped single attempt: hard 45s deadline (hang protection),
   * CircuitBreaker admission check + success/failure recording for the
   * provider resolved from the model id.
   */
  private async attempt(
    model: string,
    universalMsgs: UniversalMessage[],
    options: UniversalGenerationOptions,
    onChunk?: (chunk: string) => void
  ): Promise<string> {
    const provider = this.resolveProvider(model);
    const breaker = getBreaker(provider);
    if (!breaker.canAttempt()) {
      throw new Error(`[CIRCUIT_OPEN] provider "${provider}" breaker is open — skipping attempt for ${model}`);
    }
    const p = onChunk
      ? this.executeStream(model, universalMsgs, onChunk, options)
      : this.executeGenerate(model, universalMsgs, options);
    const t0 = Date.now();
    try {
      const result = await withTimeout(p, LLM_CALL_TIMEOUT_MS, `llm:${provider}:${model}`);
      breaker.recordSuccess();
      OpLog.getInstance().log('debug', 'llm', `provider=${provider} model=${model} latencyMs=${Date.now() - t0} ok`);
      return result;
    } catch (err: any) {
      breaker.recordFailure(err);
      OpLog.getInstance().log('error', 'llm', `provider=${provider} model=${model} latencyMs=${Date.now() - t0} fail: ${err.message}`);
      throw err;
    }
  }

  /**
   * Generates content with automatic ranked fallback on failure
   */
  public async generateContent(
    model: string,
    messages: string | UniversalMessage[] | ChatMessage[],
    options: UniversalGenerationOptions = {},
    enableFallback: boolean = true
  ): Promise<string> {
    const universalMsgs = this.normalizeToUniversal(messages);
    try {
      return await this.attempt(model, universalMsgs, options);
    } catch (err: any) {
      if (!enableFallback) throw err;

      const resilience = new ProviderFallbackChain();
      const fallbackChain = resilience.filterHealthy(ModelRatings.getFallbackChain(model));
      logger.warn('UniversalLlmClient', `Model "${model}" failed: ${err.message}. Initiating ranked fallback chain (${fallbackChain.length} healthy candidates)...`);

      for (const fallbackModel of fallbackChain) {
        try {
          logger.info('UniversalLlmClient', `[FALLBACK] Attempting ranked candidate: ${fallbackModel}`);
          return await this.attempt(fallbackModel, universalMsgs, options);
        } catch (fallbackErr: any) {
          logger.warn('UniversalLlmClient', `[FALLBACK] Candidate "${fallbackModel}" failed: ${fallbackErr.message}`);
        }
      }

      throw new Error(`All models in ranked fallback chain failed. Last error: ${err.message}`);
    }
  }

  /**
   * Internal execution of streamContent for a specific model without fallback
   */
  private async executeStream(
    model: string,
    universalMsgs: UniversalMessage[],
    onChunk: (chunk: string) => void,
    options: UniversalGenerationOptions
  ): Promise<string> {
    const provider = this.resolveProvider(model, options.provider);
    logger.debug('UniversalLlmClient', `Streaming response via provider: ${provider} [model: ${model}]`);

    if (provider === 'google') {
      const { contents, systemInstruction } = this.toGeminiFormat(
        universalMsgs,
        options.systemInstruction || Config.defaultSystemInstruction
      );
      if (options.apiKey) {
        this.geminiClient.setApiKey(options.apiKey);
      }
      return this.geminiClient.streamContent(model, contents, onChunk, {
        temperature: options.temperature,
        maxOutputTokens: options.maxOutputTokens,
        systemInstruction,
        signal: options.signal,
      });
    }

    return this.streamOpenAiCompatible(provider, model, universalMsgs, onChunk, options);
  }

  /**
   * Streams content chunk-by-chunk via SSE with automatic ranked fallback on failure
   */
  public async streamContent(
    model: string,
    messages: string | UniversalMessage[] | ChatMessage[],
    onChunk: (chunk: string) => void,
    options: UniversalGenerationOptions = {},
    enableFallback: boolean = true
  ): Promise<string> {
    const universalMsgs = this.normalizeToUniversal(messages);
    let chunksEmitted = 0;
    const trackedOnChunk = (chunk: string) => {
      chunksEmitted++;
      onChunk(chunk);
    };

    try {
      const result = await this.attempt(model, universalMsgs, options, trackedOnChunk);
      // Reasoning models (e.g. nemotron-super) sometimes stream NOTHING into
      // `content` — all output lands in the reasoning field. Treat an empty
      // stream as failure: rethrow so the ranked fallback chain engages
      // instead of silently returning ''.
      if (!result.trim() && chunksEmitted === 0) {
        getBreaker(this.resolveProvider(model)).recordFailure(new Error('[EMPTY_STREAM] no content'));
        throw new Error(`[EMPTY_STREAM] ${model} returned no content (reasoning-only response)`);
      }
      return result;
    } catch (err: any) {
      if (!enableFallback || chunksEmitted > 0) {
        throw err;
      }

      const resilience = new ProviderFallbackChain();
      const fallbackChain = resilience.filterHealthy(ModelRatings.getFallbackChain(model));
      logger.warn('UniversalLlmClient', `Stream for model "${model}" failed before output: ${err.message}. Initiating ranked fallback...`);

      for (const fallbackModel of fallbackChain) {
        try {
          logger.info('UniversalLlmClient', `[STREAM FALLBACK] Trying candidate: ${fallbackModel}`);
          return await this.attempt(fallbackModel, universalMsgs, options, onChunk);
        } catch (fallbackErr: any) {
          logger.warn('UniversalLlmClient', `[STREAM FALLBACK] Candidate "${fallbackModel}" failed: ${fallbackErr.message}`);
        }
      }

      throw new Error(`Stream fallback chain exhausted. Last error: ${err.message}`);
    }
  }

  /**
   * Handles OpenAI-compatible providers: OmniRoute, OpenRouter, OpenCode Go
   */
  private getProviderEndpointConfig(
    provider: 'omniroute' | 'openrouter' | 'opencode',
    optionsApiKey?: string
  ): { url: string; headers: Record<string, string> } {
    if (provider === 'omniroute') {
      const url = `${Config.omnirouteBaseUrl}/chat/completions`;
      const apiKey = optionsApiKey || Config.omnirouteApiKey || 'omniroute-token';
      return {
        url,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`,
        },
      };
    }

    if (provider === 'openrouter') {
      const url = `${Config.openrouterBaseUrl}/chat/completions`;
      const apiKey = optionsApiKey || Config.openrouterApiKey || process.env.OPENROUTER_API_KEY || '';
      return {
        url,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${apiKey}`,
          'HTTP-Referer': 'https://evabot.online',
          'X-Title': 'EvaBot Autonomous Agent',
        },
      };
    }

    // opencode (OpenCode Go)
    const url = `${Config.opencodeBaseUrl}/chat/completions`;
    const apiKey = optionsApiKey || Config.opencodeApiKey || process.env.OPENCODE_API_KEY || 'opencode-token';
    return {
      url,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${apiKey}`,
        'X-Client': 'EvaBot-OpenCode-Go-Adapter',
      },
    };
  }

  private buildOpenAiMessages(
    messages: UniversalMessage[],
    systemInstruction?: string
  ): { role: string; content: string }[] {
    const formatted: { role: string; content: string }[] = [];
    const effectiveSystem = systemInstruction || Config.defaultSystemInstruction;

    if (effectiveSystem) {
      formatted.push({ role: 'system', content: effectiveSystem });
    }

    for (const msg of messages) {
      formatted.push({
        role: msg.role === 'assistant' ? 'assistant' : msg.role === 'system' ? 'system' : 'user',
        content: msg.content,
      });
    }

    return formatted;
  }

  private async generateOpenAiCompatible(
    provider: 'omniroute' | 'openrouter' | 'opencode',
    model: string,
    messages: UniversalMessage[],
    options: UniversalGenerationOptions
  ): Promise<string> {
    const { url, headers } = this.getProviderEndpointConfig(provider, options.apiKey);
    const targetModel = this.cleanModelId(model, provider);
    const payload = {
      model: targetModel,
      messages: this.buildOpenAiMessages(messages, options.systemInstruction),
      temperature: options.temperature ?? 0.7,
      max_tokens: options.maxOutputTokens ?? 4096,
      stream: false,
    };

    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
      signal: options.signal,
    });

    if (!response.ok) {
      const errText = await response.text();
      let errorDetail = errText;
      try {
        const json = JSON.parse(errText);
        errorDetail = json.error?.message || json.message || errText;
      } catch {
        // use raw
      }
      logger.error('UniversalLlmClient', `${provider} API Error ${response.status}: ${errorDetail}`);
      throw new Error(`${provider.toUpperCase()} API Error (${response.status}): ${errorDetail}`);
    }

    const data: any = await response.json();
    const output = data.choices?.[0]?.message?.content;
    if (typeof output !== 'string') {
      return '[No content returned by model]';
    }
    return output;
  }

  private async streamOpenAiCompatible(
    provider: 'omniroute' | 'openrouter' | 'opencode',
    model: string,
    messages: UniversalMessage[],
    onChunk: (chunk: string) => void,
    options: UniversalGenerationOptions
  ): Promise<string> {
    const { url, headers } = this.getProviderEndpointConfig(provider, options.apiKey);
    const targetModel = this.cleanModelId(model, provider);
    const payload = {
      model: targetModel,
      messages: this.buildOpenAiMessages(messages, options.systemInstruction),
      temperature: options.temperature ?? 0.7,
      max_tokens: options.maxOutputTokens ?? 4096,
      stream: true,
    };

    const response = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
      signal: options.signal,
    });

    if (!response.ok) {
      const errText = await response.text();
      let errorDetail = errText;
      try {
        const json = JSON.parse(errText);
        errorDetail = json.error?.message || json.message || errText;
      } catch {
        // use raw
      }
      logger.error('UniversalLlmClient', `${provider} Stream Error ${response.status}: ${errorDetail}`);
      throw new Error(`${provider.toUpperCase()} Stream Error (${response.status}): ${errorDetail}`);
    }

    if (!response.body) {
      throw new Error(`Empty response body from ${provider}`);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder('utf-8');
    let buffer = '';
    let fullText = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed.startsWith('data: ')) {
          const dataStr = trimmed.slice(6).trim();
          if (dataStr === '[DONE]') continue;

          try {
            const parsed = JSON.parse(dataStr);
            const delta = parsed.choices?.[0]?.delta?.content;
            if (delta) {
              fullText += delta;
              onChunk(delta);
            }
          } catch {
            // Buffer fragment
          }
        }
      }
    }

    // Process leftover buffer
    if (buffer.trim().startsWith('data: ')) {
      const dataStr = buffer.trim().slice(6).trim();
      if (dataStr !== '[DONE]') {
        try {
          const parsed = JSON.parse(dataStr);
          const delta = parsed.choices?.[0]?.delta?.content;
          if (delta) {
            fullText += delta;
            onChunk(delta);
          }
        } catch {
          // ignore
        }
      }
    }

    return fullText;
  }
}

import { UniversalLlmClient, UniversalMessage, LlmProvider } from './UniversalLlmClient.js';
import { ModelRegistry, GeminiModelInfo, TokenCostEstimate } from '../models/ModelRegistry.js';
import { CORPORATE_ROLES, CorporateRole, KnowledgeBaseConnector } from './CorporateRoles.js';
import { applyLocalePolicy } from './LocalePolicy.js';
import { Config } from './Config.js';
import { logger } from './Logger.js';

export type ConsiliumMode = 'chat' | 'dialog' | 'interview' | 'consilium' | 'solo' | 'broadcast' | 'dialogue';
export type PersonaId = 'eva' | 'adam' | 'dual';

export interface ConsiliumParticipant {
  id: string;
  model: string;
  roleId?: string;
  name?: string;
  title?: string;
  systemPrompt?: string;
  temperature?: number;
  provider?: LlmProvider;
}

export interface ConsiliumTurn {
  round: number;
  participantId: string;
  name: string;
  model: string;
  role?: string;
  content: string;
  timestamp: string;
  durationMs: number;
  promptTokens?: number;
  completionTokens?: number;
  totalTokens?: number;
  cost?: TokenCostEstimate;
}

export interface ConsiliumProgressEvent {
  type: 'turn_start' | 'turn_complete' | 'round_complete' | 'synthesis_start' | 'synthesis_complete' | 'error';
  round?: number;
  participantId?: string;
  turn?: ConsiliumTurn;
  message?: string;
}

export interface ConsiliumRunOptions {
  mode: ConsiliumMode;
  persona?: PersonaId;
  prompt: string;
  models?: string[];
  participants?: ConsiliumParticipant[];
  rounds?: number;
  preset?: 'top10_paid' | 'top10_free';
  synthesizerModel?: string;
  systemInstruction?: string;
  apiKey?: string;
  useKnowledgeBase?: boolean;
  onProgress?: (event: ConsiliumProgressEvent) => void;
  signal?: AbortSignal;
}

export interface ConsiliumResult {
  mode: ConsiliumMode;
  prompt: string;
  participants: ConsiliumParticipant[];
  turns: ConsiliumTurn[];
  synthesis?: string;
  totalRounds: number;
  durationMs: number;
  knowledgeBaseContextIncluded: boolean;
  totalPromptTokens?: number;
  totalCompletionTokens?: number;
  totalTokens?: number;
  totalCostUSD?: number;
  totalCostEUR?: number;
  costSummary?: {
    totalPromptTokens: number;
    totalCompletionTokens: number;
    totalTokens: number;
    totalCostUSD: number;
    totalCostEUR: number;
    formattedUSD: string;
    formattedEUR: string;
    models: Array<{
      model: string;
      tokens: number;
      costUSD: number;
      costEUR: number;
      formattedUSD: string;
      formattedEUR: string;
    }>;
  };
}

export class ConsiliumEngine {
  private client: UniversalLlmClient;
  private kbConnector: KnowledgeBaseConnector;

  constructor(apiKey?: string) {
    this.client = new UniversalLlmClient(apiKey);
    this.kbConnector = new KnowledgeBaseConnector();
  }

  /**
   * Main entrypoint for running any Consilium engine mode
   */
  public async run(options: ConsiliumRunOptions): Promise<ConsiliumResult> {
    const startTime = Date.now();
    logger.info('ConsiliumEngine', `Starting execution: mode=${options.mode}, rounds=${options.rounds || 1}`);

    // Fetch hybrid DB context if enabled or if prompt concerns EvaLine
    let kbContext = '';
    let kbIncluded = false;
    const shouldQueryKB = Boolean(options.useKnowledgeBase) || /(evaline|євалайн|евалайн|eva-line)/i.test(options.prompt);
    if (shouldQueryKB) {
      try {
        const docs = await this.kbConnector.search(options.prompt, { limit: 5 });
        if (docs.length > 0) {
          kbContext = this.kbConnector.formatContextForPrompt(docs);
          kbIncluded = true;
          logger.info('ConsiliumEngine', `Injected ${docs.length} hybrid DB knowledge documents into context`);
        }
      } catch (err: any) {
        logger.warn('ConsiliumEngine', `Failed retrieving knowledge base: ${err.message}`);
      }
    }

    const participants = this.resolveParticipants(options);

    let result: ConsiliumResult;

    switch (options.mode) {
      case 'chat':
      case 'solo':
        result = await this.runSolo(options, participants, kbContext, startTime, kbIncluded);
        break;
      case 'broadcast':
        result = await this.runBroadcast(options, participants, kbContext, startTime, kbIncluded);
        break;
      case 'dialog':
      case 'dialogue':
        result = await this.runDialogue(options, participants, kbContext, startTime, kbIncluded);
        break;
      case 'interview':
        result = await this.runInterview(options, participants, kbContext, startTime, kbIncluded);
        break;
      case 'consilium':
        result = await this.runConsilium(options, participants, kbContext, startTime, kbIncluded);
        break;
      default:
        throw new Error(`Unsupported Consilium mode: ${(options as any).mode}`);
    }

    return result;
  }

  /**
   * Resolves and enriches participants list with corporate roles and defaults
   */
  public resolveParticipants(options: ConsiliumRunOptions): ConsiliumParticipant[] {
    if (options.participants && options.participants.length > 0) {
      return options.participants.map((p, idx) => {
        const role = p.roleId && CORPORATE_ROLES[p.roleId] ? CORPORATE_ROLES[p.roleId] : undefined;
        return {
          id: p.id || `participant-${idx + 1}`,
          model: p.model || Config.defaultModel,
          roleId: p.roleId,
          name: p.name || role?.name || `Agent ${idx + 1}`,
          title: p.title || role?.title || 'Specialist',
          systemPrompt: applyLocalePolicy(p.systemPrompt || role?.systemPrompt || Config.defaultSystemInstruction),
          temperature: p.temperature ?? role?.suggestedTemperature ?? 0.5,
          provider: p.provider,
        };
      });
    }

    let modelList: string[] = [];
    if (options.preset === 'top10_paid') {
      modelList = ModelRegistry.getTop10PaidSmartestModels().map((m) => m.id);
    } else if (options.preset === 'top10_free') {
      modelList = ModelRegistry.getTop10FreeModels().map((m) => m.id);
    } else if (options.models && options.models.length > 0) {
      modelList = options.models;
    } else {
      modelList = [Config.defaultModel];
    }

    const defaultRoleKeys = Object.keys(CORPORATE_ROLES);

    return modelList.map((model, idx) => {
      const roleKey = defaultRoleKeys[idx % defaultRoleKeys.length];
      const role = CORPORATE_ROLES[roleKey];
      return {
        id: `agent-${idx + 1}-${role.id}`,
        model,
        roleId: role.id,
        name: role.name,
        title: role.title,
        systemPrompt: applyLocalePolicy(role.systemPrompt),
        temperature: role.suggestedTemperature,
      };
    });
  }

  /**
   * Validates and bounds participants for Consilium mode (strictly between 3 and 10 participants)
   */
  public validateConsiliumParticipants(participants: ConsiliumParticipant[]): ConsiliumParticipant[] {
    let activeParticipants = [...participants];
    if (activeParticipants.length < 3) {
      // Expand up to 3 minimum with corporate roles
      const extraRoles = ['architect', 'devops', 'security_auditor'];
      while (activeParticipants.length < 3) {
        const role = CORPORATE_ROLES[extraRoles[activeParticipants.length % extraRoles.length]];
        activeParticipants.push({
          id: `consilium-agent-${activeParticipants.length + 1}`,
          model: role.preferredModel,
          roleId: role.id,
          name: role.name,
          title: role.title,
        systemPrompt: applyLocalePolicy(role.systemPrompt),
          temperature: role.suggestedTemperature,
        });
      }
    } else if (activeParticipants.length > 10) {
      // Bound to maximum 10 participants
      activeParticipants = activeParticipants.slice(0, 10);
    }
    return activeParticipants;
  }

  /**
   * Mode 1: Solo Mode (Standard 1-on-1 execution)
   */
  private async runSolo(
    options: ConsiliumRunOptions,
    participants: ConsiliumParticipant[],
    kbContext: string,
    startTime: number,
    kbIncluded: boolean
  ): Promise<ConsiliumResult> {
    const participant = participants[0] || {
      id: 'solo-agent',
      model: Config.defaultModel,
      name: 'EvaBot Solo Agent',
      title: 'AI Specialist',
      systemPrompt: applyLocalePolicy(Config.defaultSystemInstruction),
      temperature: 0.7,
    };

    options.onProgress?.({
      type: 'turn_start',
      round: 1,
      participantId: participant.id,
      message: `${participant.name} is formulating response...`,
    });

    const turnStart = Date.now();
    const effectivePrompt = kbContext ? `${kbContext}\n\nUser Request: ${options.prompt}` : options.prompt;

    let response: string;
    try {
      response = await this.client.generateContent(
        participant.model,
        [{ role: 'user', content: effectivePrompt }],
        {
          temperature: participant.temperature,
          systemInstruction: participant.systemPrompt,
          apiKey: options.apiKey,
          signal: options.signal,
        }
      );
    } catch (err: any) {
      logger.error('ConsiliumEngine', `Solo execution error on ${participant.model}: ${err.message}`);
      response = `[Error querying model ${participant.model}: ${err.message}]`;
    }

    const turn = this.createTurn(1, participant, effectivePrompt, response, Date.now() - turnStart);

    options.onProgress?.({
      type: 'turn_complete',
      round: 1,
      participantId: participant.id,
      turn,
    });

    const costSummary = this.calculateCostSummary([turn]);

    return {
      mode: options.mode === 'chat' ? 'chat' : 'solo',
      prompt: options.prompt,
      participants: [participant],
      turns: [turn],
      totalRounds: 1,
      durationMs: Date.now() - startTime,
      knowledgeBaseContextIncluded: kbIncluded,
      ...costSummary,
    };
  }

  /**
   * Mode: Interview Mode (Structured technical or executive interview)
   */
  private async runInterview(
    options: ConsiliumRunOptions,
    participants: ConsiliumParticipant[],
    kbContext: string,
    startTime: number,
    kbIncluded: boolean
  ): Promise<ConsiliumResult> {
    const persona = options.persona || 'eva';
    let interviewer = participants[0];

    if (persona === 'eva') {
      interviewer = {
        id: 'eva-interviewer',
        model: interviewer?.model || 'gemini-2.5-flash',
        name: 'Eva (Frontend & Strategic Interviewer)',
        title: 'Lead Frontend Architect & UX Director',
        systemPrompt: applyLocalePolicy(
          'You are Eva, conducting a professional Frontend, UX, and Strategic Architecture interview for EvaLine (Headquarters and manufacturing in Chernomorsk, Ukraine, EU Hub in Bratislava, Slovakia). ' +
          'Evaluate the candidate response with constructive depth. ' +
          'Format your reply in three clean sections:\n' +
          '1. * Feedback & Assessment: Strengths and gaps observed in candidate answer.\n' +
          '2. [SCORE] Score: Candidate competence rating (e.g. 85/100 or Seniority Level).\n' +
          '3. ? Next Question / Scenario: Present the next targeted question or architectural trade-off challenge.'
        ),
        temperature: 0.4,
      };
    } else if (persona === 'adam') {
      interviewer = {
        id: 'adam-interviewer',
        model: interviewer?.model || 'gemini-2.5-pro',
        name: 'Adam (Backend & Systems Interviewer)',
        title: 'Chief Backend Architect & Core Systems Lead',
        systemPrompt: applyLocalePolicy(
          'You are Adam, conducting an advanced Backend, Cloud Infrastructure, and Distributed Systems interview for EvaLine (Headquarters and manufacturing in Chernomorsk, Ukraine, EU Hub in Bratislava, Slovakia). ' +
          'Evaluate the candidate with technical rigor and zero tolerance for sloppy architecture. ' +
          'Format your reply in three clean sections:\n' +
          '1. * Technical Critique: Algorithmic efficiency, scalability, and security posture.\n' +
          '2. [SCORE] Score: Technical rigor score (e.g. 90/100 or Staff Engineer Level).\n' +
          '3. ? Next System Challenge: Present the next low-latency or high-throughput distributed system scenario.'
        ),
        temperature: 0.3,
      };
    } else if (persona === 'dual') {
      interviewer = {
        id: 'dual-interviewers',
        model: interviewer?.model || 'gemini-2.5-pro',
        name: 'Eva & Adam (Dual Co-Pilot Interview Board)',
        title: 'Full-Stack Technical Interview Board',
        systemPrompt: applyLocalePolicy(
          'You are Eva (Lead Frontend Architect) and Adam (Chief Backend Architect), conducting a dual co-pilot technical interview for EvaLine (Headquarters and manufacturing in Chernomorsk, Ukraine, EU Hub in Bratislava, Slovakia). ' +
          'Both evaluate the candidate from your respective specialties:\n' +
          '[Eva ]: Assess frontend ergonomics, API consumption, usability, and strategic clarity.\n' +
          '[Adam ]: Assess backend architecture, database latency, security, and algorithmic performance.\n' +
          'Conclude with the next joint full-stack architectural challenge.'
        ),
        temperature: 0.4,
      };
    }

    const turnStart = Date.now();
    const effectivePrompt = kbContext
      ? `${kbContext}\n\nCandidate Input / Topic: ${options.prompt}`
      : `Candidate Input / Topic: ${options.prompt}`;

    options.onProgress?.({
      type: 'turn_start',
      round: 1,
      participantId: interviewer.id,
      message: `${interviewer.name} is evaluating response and drafting next question...`,
    });

    let response: string;
    try {
      response = await this.client.generateContent(
        interviewer.model,
        [{ role: 'user', content: effectivePrompt }],
        {
          temperature: interviewer.temperature,
          systemInstruction: interviewer.systemPrompt,
          apiKey: options.apiKey,
          signal: options.signal,
        }
      );
    } catch (err: any) {
      logger.error('ConsiliumEngine', `Interview execution error on ${interviewer.model}: ${err.message}`);
      response = `[Interview error querying model ${interviewer.model}: ${err.message}]`;
    }

    const turn = this.createTurn(1, interviewer, effectivePrompt, response, Date.now() - turnStart);

    options.onProgress?.({
      type: 'turn_complete',
      round: 1,
      participantId: interviewer.id,
      turn,
    });

    const costSummary = this.calculateCostSummary([turn]);

    return {
      mode: 'interview',
      prompt: options.prompt,
      participants: [interviewer],
