  /**
   * Mode 2: Broadcast Mode (Query N models concurrently)
   */
  private async runBroadcast(
    options: ConsiliumRunOptions,
    participants: ConsiliumParticipant[],
    kbContext: string,
    startTime: number,
    kbIncluded: boolean
  ): Promise<ConsiliumResult> {
    const effectivePrompt = kbContext ? `${kbContext}\n\nUser Request: ${options.prompt}` : options.prompt;

    options.onProgress?.({
      type: 'round_complete',
      round: 1,
      message: `Broadcasting prompt concurrently to ${participants.length} models...`,
    });

    const promises = participants.map(async (p) => {
      const turnStart = Date.now();
      options.onProgress?.({
        type: 'turn_start',
        round: 1,
        participantId: p.id,
        message: `${p.name} (${p.model}) is processing broadcast request...`,
      });

      try {
        const content = await this.client.generateContent(
          p.model,
          [{ role: 'user', content: effectivePrompt }],
          {
            temperature: p.temperature,
            systemInstruction: p.systemPrompt,
            apiKey: options.apiKey,
            signal: options.signal,
          }
        );

        const turn = this.createTurn(1, p, effectivePrompt, content, Date.now() - turnStart);

        options.onProgress?.({
          type: 'turn_complete',
          round: 1,
          participantId: p.id,
          turn,
        });

        return turn;
      } catch (err: any) {
        logger.error('ConsiliumEngine', `Broadcast error on participant ${p.id} (${p.model}): ${err.message}`);
        const failedTurn = this.createTurn(
          1,
          p,
          effectivePrompt,
          `[Error querying model ${p.model}: ${err.message}]`,
          Date.now() - turnStart
        );
        return failedTurn;
      }
    });

    const turns = await Promise.all(promises);
    const costSummary = this.calculateCostSummary(turns);

    return {
      mode: 'broadcast',
      prompt: options.prompt,
      participants,
      turns,
      totalRounds: 1,
      durationMs: Date.now() - startTime,
      knowledgeBaseContextIncluded: kbIncluded,
      ...costSummary,
    };
  }

  /**
   * Mode 3: Dual-model Dialogue Mode (2 models exchange arguments over K rounds)
   */
  private async runDialogue(
    options: ConsiliumRunOptions,
    participants: ConsiliumParticipant[],
    kbContext: string,
    startTime: number,
    kbIncluded: boolean
  ): Promise<ConsiliumResult> {
    const p1 = participants[0] || {
      id: 'agent-1',
      model: 'gemini-2.5-pro',
      name: 'Lead Proponent',
      title: 'Lead Architect',
      systemPrompt: CORPORATE_ROLES.architect.systemPrompt,
      temperature: 0.4,
    };

    const p2 = participants[1] || {
      id: 'agent-2',
      model: 'gemini-2.5-flash',
      name: 'Lead Challenger',
      title: 'Principal Security & Risk Auditor',
      systemPrompt: CORPORATE_ROLES.security_auditor.systemPrompt,
      temperature: 0.4,
    };

    const totalRounds = Math.max(1, Math.min(options.rounds || 2, 5));
    const turns: ConsiliumTurn[] = [];
    const dialogueHistory: UniversalMessage[] = [];

    const effectivePrompt = kbContext ? `${kbContext}\n\nTopic for Technical Deliberation: ${options.prompt}` : options.prompt;
    dialogueHistory.push({ role: 'user', content: effectivePrompt });

    for (let round = 1; round <= totalRounds; round++) {
      // Participant 1's turn
      const t1Start = Date.now();
      options.onProgress?.({
        type: 'turn_start',
        round,
        participantId: p1.id,
        message: `Round ${round}/${totalRounds}: ${p1.name} is presenting arguments...`,
      });

      const p1Prompt = round === 1
        ? effectivePrompt
        : `Round ${round} Counter-Argument: Review the previous reply and defend or refine your architectural stance:\n\n${dialogueHistory[dialogueHistory.length - 1].content}`;

      let p1Response = '';
      try {
        p1Response = await this.client.generateContent(
          p1.model,
          [...dialogueHistory, { role: 'user', content: p1Prompt }],
          {
            temperature: p1.temperature,
            systemInstruction: `${p1.systemPrompt}\nYou are participating in a bilateral technical dialogue with ${p2.name} (${p2.title}). Maintain intellectual rigor, focus on concrete trade-offs, and defend your positions with evidence.`,
            apiKey: options.apiKey,
            signal: options.signal,
          }
        );
      } catch (err: any) {
        logger.error('ConsiliumEngine', `Dialogue turn error for ${p1.name}: ${err.message}`);
        p1Response = `[Error generating argument from ${p1.name}: ${err.message}]`;
      }

      const turn1 = this.createTurn(round, p1, p1Prompt, p1Response, Date.now() - t1Start);
      turns.push(turn1);
      dialogueHistory.push({ role: 'assistant', content: `[${p1.name}]: ${p1Response}` });

      options.onProgress?.({
        type: 'turn_complete',
        round,
        participantId: p1.id,
        turn: turn1,
      });

      // Participant 2's turn
      const t2Start = Date.now();
      options.onProgress?.({
        type: 'turn_start',
        round,
        participantId: p2.id,
        message: `Round ${round}/${totalRounds}: ${p2.name} is responding and critiquing...`,
      });

      const p2Prompt = `Round ${round} Critique: Directly address the arguments posed by ${p1.name} above. Point out vulnerabilities, edge cases, cost implications in USD/EUR, and suggest counter-proposals:\n\n${p1Response}`;

      let p2Response = '';
      try {
        p2Response = await this.client.generateContent(
          p2.model,
          [...dialogueHistory, { role: 'user', content: p2Prompt }],
          {
            temperature: p2.temperature,
            systemInstruction: `${p2.systemPrompt}\nYou are participating in a bilateral technical dialogue with ${p1.name} (${p1.title}). Critically analyze their statements, probe for weak spots, and propose resilient solutions.`,
            apiKey: options.apiKey,
            signal: options.signal,
          }
        );
      } catch (err: any) {
        logger.error('ConsiliumEngine', `Dialogue turn error for ${p2.name}: ${err.message}`);
        p2Response = `[Error generating argument from ${p2.name}: ${err.message}]`;
      }

      const turn2 = this.createTurn(round, p2, p2Prompt, p2Response, Date.now() - t2Start);
      turns.push(turn2);
      dialogueHistory.push({ role: 'assistant', content: `[${p2.name}]: ${p2Response}` });

      options.onProgress?.({
        type: 'turn_complete',
        round,
        participantId: p2.id,
        turn: turn2,
      });
    }

    // Synthesize final dialogue outcome
    const synthModel = options.synthesizerModel || 'gemini-2.5-pro';
    options.onProgress?.({
      type: 'synthesis_start',
      message: `Synthesizing final dialogue conclusion with ${synthModel}...`,
    });

    const synthPrompt =
      `You are the Senior Technical Arbiter. Synthesize the debate between ${p1.name} and ${p2.name} on the topic:\n"${options.prompt}"\n\n` +
      (kbContext ? `Grounded Knowledge Base Context:\n${kbContext}\n\n` : '') +
      `Deliberation Transcript:\n` +
      turns.map((t) => `### Round ${t.round} - ${t.name} (${t.role}):\n${t.content}`).join('\n\n') +
      `\n\nProduce an authoritative Executive Synthesis with:\n` +
      `1. Core Points of Consensus\n` +
      `2. Unresolved Trade-Offs & Edge Cases\n` +
      `3. Definitive Actionable Recommendation (with cost impact in USD ($) or EUR (€)).`;

    let synthesis = '';
    try {
      synthesis = await this.client.generateContent(
        synthModel,
        [{ role: 'user', content: synthPrompt }],
        {
          temperature: 0.2,
          systemInstruction: Config.defaultSystemInstruction,
          apiKey: options.apiKey,
          signal: options.signal,
        }
      );
    } catch (err: any) {
      logger.error('ConsiliumEngine', `Dialogue synthesis error: ${err.message}`);
      synthesis = `[Dialogue synthesis generation error: ${err.message}]`;
    }

    options.onProgress?.({
      type: 'synthesis_complete',
      message: 'Dialogue synthesis completed.',
    });

    const costSummary = this.calculateCostSummary(turns, synthesis, synthModel, synthPrompt);

    return {
      mode: 'dialogue',
      prompt: options.prompt,
      participants: [p1, p2],
      turns,
      synthesis,
      totalRounds,
      durationMs: Date.now() - startTime,
      knowledgeBaseContextIncluded: kbIncluded,
      ...costSummary,
    };
  }

  /**
   * Mode 4: Consilium Mode (3 to 10 models discuss in rounds, then synthesizer produces consensus)
   */
  private async runConsilium(
    options: ConsiliumRunOptions,
    participants: ConsiliumParticipant[],
    kbContext: string,
    startTime: number,
    kbIncluded: boolean
  ): Promise<ConsiliumResult> {
    // Validate bounds: 3 to 10 participants
    const activeParticipants = this.validateConsiliumParticipants(participants);

    const totalRounds = Math.max(1, Math.min(options.rounds || 2, 4));
    const turns: ConsiliumTurn[] = [];
    const effectivePrompt = kbContext ? `${kbContext}\n\nConsilium Mandate / Technical Challenge: ${options.prompt}` : options.prompt;

    // Round 1: Independent vantage evaluations (concurrent)
    logger.info('ConsiliumEngine', `Consilium Round 1: ${activeParticipants.length} agents evaluating concurrently`);
    options.onProgress?.({
      type: 'round_complete',
      round: 1,
      message: `Consilium Round 1: ${activeParticipants.length} agents providing independent expert perspectives...`,
    });

    const round1Promises = activeParticipants.map(async (p) => {
      const turnStart = Date.now();
      options.onProgress?.({
        type: 'turn_start',
        round: 1,
        participantId: p.id,
        message: `${p.name} (${p.title}) is drafting Round 1 stance...`,
      });

      const userMsg = `Please analyze the following challenge from your specific professional perspective as ${p.title}:\n\n"${effectivePrompt}"\n\nState your primary recommendations, essential prerequisites, and critical risks.`;

      try {
        const content = await this.client.generateContent(
          p.model,
          [{ role: 'user', content: userMsg }],
          {
            temperature: p.temperature,
            systemInstruction: p.systemPrompt,
            apiKey: options.apiKey,
            signal: options.signal,
          }
        );

        const turn = this.createTurn(1, p, options.prompt, content, Date.now() - turnStart);

        options.onProgress?.({
          type: 'turn_complete',
          round: 1,
          participantId: p.id,
          turn,
        });

        return turn;
      } catch (err: any) {
        logger.error('ConsiliumEngine', `Consilium Round 1 error for ${p.name}: ${err.message}`);
        return this.createTurn(
          1,
          p,
          options.prompt,
          `[Perspective unavailable due to query error: ${err.message}]`,
          Date.now() - turnStart
        );
      }
    });

    const round1Turns = await Promise.all(round1Promises);
    turns.push(...round1Turns);

    // Round 2 to K: Cross-deliberation & debate
    for (let r = 2; r <= totalRounds; r++) {
      logger.info('ConsiliumEngine', `Consilium Round ${r}: Cross-evaluation across ${activeParticipants.length} agents`);
      options.onProgress?.({
        type: 'round_complete',
        round: r,
        message: `Consilium Round ${r}: Deliberating on peers' statements and refining alignment...`,
      });

      const peerSummary = turns
        .filter((t) => t.round === r - 1)
        .map((t) => `[${t.name} - ${t.role}]:\n${t.content}`)
        .join('\n\n---\n\n');

      const roundPromises = activeParticipants.map(async (p) => {
        const turnStart = Date.now();
        options.onProgress?.({
          type: 'turn_start',
          round: r,
          participantId: p.id,
          message: `${p.name} is evaluating peers' input in Round ${r}...`,
        });

        const prompt =
          `You are participating in Round ${r} of the EvaLine Technical Consilium.\n` +
          `Original Mandate: "${options.prompt}"\n\n` +
          (kbContext ? `${kbContext}\n\n` : '') +
          `Below are the stances delivered by your colleagues in the previous round:\n\n${peerSummary}\n\n` +
          `Critique, support, or refine these viewpoints from your vantage as ${p.title}. Highlight consensus or irreconcilable trade-offs.`;

        try {
          const content = await this.client.generateContent(
            p.model,
            [{ role: 'user', content: prompt }],
            {
              temperature: p.temperature,
              systemInstruction: p.systemPrompt,
              apiKey: options.apiKey,
              signal: options.signal,
            }
          );

          const turn = this.createTurn(r, p, prompt, content, Date.now() - turnStart);

          options.onProgress?.({
            type: 'turn_complete',
            round: r,
            participantId: p.id,
            turn,
          });

          return turn;
        } catch (err: any) {
          logger.error('ConsiliumEngine', `Consilium Round ${r} error for ${p.name}: ${err.message}`);
          return this.createTurn(
            r,
            p,
            prompt,
            `[Deliberation note unavailable: ${err.message}]`,
            Date.now() - turnStart
          );
        }
      });

      const currentRoundTurns = await Promise.all(roundPromises);
      turns.push(...currentRoundTurns);
    }

    // Final Stage: Synthesizer produces authoritative corporate consensus
    const synthModel = options.synthesizerModel || 'gemini-2.5-pro';
    logger.info('ConsiliumEngine', `Synthesizing final consensus with ${synthModel}`);
    options.onProgress?.({
      type: 'synthesis_start',
      message: `Consilium deliberation concluded. Synthesizing consensus document with ${synthModel}...`,
    });

    const fullTranscript = turns
      .map((t) => `### Round ${t.round} — ${t.name} (${t.role} / ${t.model}):\n${t.content}`)
      .join('\n\n');

    const synthesisPrompt =
      `You are the EvaLine Supreme Technical Council Synthesizer.\n` +
      `Your role is to formulate the definitive, binding consensus from a ${activeParticipants.length}-agent expert consilium.\n\n` +
      `Original Mandate:\n"${options.prompt}"\n\n` +
      (kbContext ? `Grounded Knowledge Base Context (Verified Corporate Facts & Hubs):\n${kbContext}\n\n` : '') +
      `Consilium Transcript:\n${fullTranscript}\n\n` +
      `Formulate a comprehensive, structured Consilium Consensus Report strictly in Markdown:\n` +
      `## 1. Executive Summary & Final Verdict\n` +
      `## 2. Unanimous Consensus & Strategic Alignment\n` +
      `## 3. Disputed Decisions, Risk Analysis & Trade-Offs\n` +
      `## 4. Implementation Roadmap & Technical Milestones\n` +
      `## 5. Budgetary & Infrastructure Impact (strictly in USD ($) and EUR (€))\n\n` +
      `MANDATORY GROUNDED VERIFICATION:\n` +
      `- Confirm official manufacturing plant and office: м. Чорноморськ, вул. Промислова, 1 (Одеська обл., Україна).\n` +
      `- Confirm official European logistics hub and office: м. Братислава, Obchodna 37 (Словаччина).\n` +
      `- Detail the complete product portfolio (automotive sheets/mats Diamond & Honeycomb, sports tatami & puzzle mats with dovetail locks, livestock mats 'Бурьонка', footwear/orthopedic materials, marine teak, Private Label OEM/ODM).\n` +
      `- Detail physical EVA advantages over rubber (5x lighter) and PVC (4x lighter), closed-cell hygiene, non-absorption (<0.1%), temperature resistance (-50°C to +75°C), 20-75 Shore A.\n` +
      `- Confirm UNIC integrity membership, MOH/СЕС sanitary conclusions, CE European declaration, and autonomous industrial diesel generators ensuring uninterrupted manufacturing during wartime blackouts.\n`;

    let synthesis = '';
    try {
      synthesis = await this.client.generateContent(
        synthModel,
        [{ role: 'user', content: synthesisPrompt }],
        {
          temperature: 0.2,
          systemInstruction: Config.defaultSystemInstruction,
          apiKey: options.apiKey,
          signal: options.signal,
        }
      );
    } catch (err: any) {
      logger.error('ConsiliumEngine', `Consilium synthesis error: ${err.message}`);
      synthesis = `[Consilium consensus synthesis generation error: ${err.message}]`;
    }

    options.onProgress?.({
      type: 'synthesis_complete',
      message: 'Consilium Consensus Report successfully generated.',
    });

    const costSummary = this.calculateCostSummary(turns, synthesis, synthModel, synthesisPrompt);

    return {
      mode: 'consilium',
      prompt: options.prompt,
      participants: activeParticipants,
      turns,
      synthesis,
      totalRounds,
      durationMs: Date.now() - startTime,
      knowledgeBaseContextIncluded: kbIncluded,
      ...costSummary,
    };
  }

  private createTurn(
    round: number,
    participant: ConsiliumParticipant,
    prompt: string,
    content: string,
    durationMs: number
  ): ConsiliumTurn {
    const promptTokens = ModelRegistry.estimateTokens(prompt);
    const completionTokens = ModelRegistry.estimateTokens(content);
    const cost = ModelRegistry.calculateCost(participant.model, promptTokens, completionTokens);

    return {
      round,
      participantId: participant.id,
      name: participant.name || participant.id,
      model: participant.model,
      role: participant.title,
      content,
      timestamp: new Date().toISOString(),
      durationMs,
      promptTokens,
      completionTokens,
      totalTokens: promptTokens + completionTokens,
      cost,
    };
  }

  private calculateCostSummary(
    turns: ConsiliumTurn[],
    synthesis?: string,
    synthModel?: string,
    synthesisPrompt?: string
  ): {
    totalPromptTokens: number;
    totalCompletionTokens: number;
    totalTokens: number;
    totalCostUSD: number;
    totalCostEUR: number;
    costSummary: {
      totalPromptTokens: number;
      totalCompletionTokens: number;
      totalTokens: number;
      totalCostUSD: number;
      totalCostEUR: number;
      formattedUSD: string;
      formattedEUR: string;
      models: Array<{
        model: string;
        tokens: number;
        costUSD: number;
        costEUR: number;
        formattedUSD: string;
        formattedEUR: string;
      }>;
    };
  } {
    let totalPromptTokens = 0;
    let totalCompletionTokens = 0;
    let totalCostUSD = 0;
    let totalCostEUR = 0;
    const modelStats = new Map<string, { tokens: number; costUSD: number; costEUR: number }>();

    for (const t of turns) {
      const p = t.promptTokens || 0;
      const c = t.completionTokens || 0;
      totalPromptTokens += p;
      totalCompletionTokens += c;
      if (t.cost) {
        totalCostUSD += t.cost.costUSD;
        totalCostEUR += t.cost.costEUR;
      }
      const st = modelStats.get(t.model) || { tokens: 0, costUSD: 0, costEUR: 0 };
      st.tokens += (p + c);
      st.costUSD += (t.cost?.costUSD || 0);
      st.costEUR += (t.cost?.costEUR || 0);
      modelStats.set(t.model, st);
    }

    if (synthesis && synthModel && synthesisPrompt) {
      const sp = ModelRegistry.estimateTokens(synthesisPrompt);
      const sc = ModelRegistry.estimateTokens(synthesis);
      const sCost = ModelRegistry.calculateCost(synthModel, sp, sc);
      totalPromptTokens += sp;
      totalCompletionTokens += sc;
      totalCostUSD += sCost.costUSD;
      totalCostEUR += sCost.costEUR;

      const st = modelStats.get(synthModel) || { tokens: 0, costUSD: 0, costEUR: 0 };
      st.tokens += (sp + sc);
      st.costUSD += sCost.costUSD;
      st.costEUR += sCost.costEUR;
      modelStats.set(synthModel, st);
    }

    const totalTokens = totalPromptTokens + totalCompletionTokens;
    const models = Array.from(modelStats.entries()).map(([model, stat]) => ({
      model,
      tokens: stat.tokens,
      costUSD: stat.costUSD,
      costEUR: stat.costEUR,
      formattedUSD: stat.costUSD === 0 ? '$0.00 (100% Free Quota)' : `$${stat.costUSD.toFixed(4)}`,
      formattedEUR: stat.costEUR === 0 ? '€0.00 (100% Free Quota)' : `€${stat.costEUR.toFixed(4)}`,
    }));

    return {
      totalPromptTokens,
      totalCompletionTokens,
      totalTokens,
      totalCostUSD,
      totalCostEUR,
      costSummary: {
        totalPromptTokens,
        totalCompletionTokens,
        totalTokens,
        totalCostUSD,
        totalCostEUR,
        formattedUSD: totalCostUSD === 0 ? '$0.00 (100% Free Quota)' : `$${totalCostUSD.toFixed(4)}`,
        formattedEUR: totalCostEUR === 0 ? '€0.00 (100% Free Quota)' : `€${totalCostEUR.toFixed(4)}`,
        models,
      },
    };
  }
}

/**
 * AnsiStreamEngine.ts
 * EvaBot Online v0.0.1 MVP — Reactive ANSI Terminal Stream Engine
 * 
 * Features:
 * - Line-by-line reactive streaming and chunk buffering
 * - Traffic light badges ([OK] [MED] [HIGH]) and status indicators
 * - Clean headers, banners, dividers, and prompt symbols
 * - Robust monospace table formatter with auto-column width and border styles
 * - 1:1 parity across ANSI Terminal, Plain Text files, and Web HTML
 * - Strict financial standard: USD ($) & EUR (€) only
 */

import { EventEmitter } from 'node:events';

// ============================================================================
// ANSI Color and Style Codes
// ============================================================================

export const AnsiColors = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  italic: '\x1b[3m',
  underline: '\x1b[4m',
  inverse: '\x1b[7m',

  // Standard Foreground
  black: '\x1b[30m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
  white: '\x1b[37m',

  // Bright / Zinc Foreground
  gray: '\x1b[90m',
  brightRed: '\x1b[91m',
  brightGreen: '\x1b[92m',
  brightYellow: '\x1b[93m',
  brightBlue: '\x1b[94m',
  brightMagenta: '\x1b[95m',
  brightCyan: '\x1b[96m',
  brightWhite: '\x1b[97m',

  // Standard Background
  bgBlack: '\x1b[40m',
  bgRed: '\x1b[41m',
  bgGreen: '\x1b[42m',
  bgYellow: '\x1b[43m',
  bgBlue: '\x1b[44m',
  bgMagenta: '\x1b[45m',
  bgCyan: '\x1b[46m',
  bgWhite: '\x1b[47m',
} as const;

export type ColorName = keyof typeof AnsiColors;

// ============================================================================
// ANSI & String Width Utilities (1:1 Parity Terminal / Plain / Web)
// ============================================================================

const ANSI_REGEX = new RegExp(
  '[\\u001B\\u009B][[\\]()#;?]*(?:(?:(?:(?:;[-a-zA-Z\\d\\/#&.:=?%@~_]+)*|[a-zA-Z\\d]+(?:;[-a-zA-Z\\d\\/#&.:=?%@~_]*)*)?\\u0007)|(?:(?:\\d{1,4}(?:;\\d{0,4})*)?[\\dA-PR-TZcf-nq-uy=><~]))',
  'g'
);

/**
 * Strips all ANSI escape sequences from a string to produce clean plain text
 */
export function stripAnsi(text: string): string {
  return text.replace(ANSI_REGEX, '');
}

/**
 * Calculates visible terminal character width.
 * Accounts for 2-column emojis ([OK], [MED], [HIGH], etc.) and wide characters.
 */
export function visibleWidth(text: string): number {
  const clean = stripAnsi(text);
  let width = 0;
  for (const char of clean) {
    const code = char.codePointAt(0) || 0;
    // Common 2-width emojis (traffic lights, checkmarks, sparkles, etc.)
    if (
      (code >= 0x1f300 && code <= 0x1f9ff) || // Misc Symbols & Pictographs, Supplemental Symbols
      (code >= 0x2600 && code <= 0x27bf) ||   // Misc symbols, Dingbats
      (code >= 0x1fa00 && code <= 0x1faff) || // Chess, Symbols & Pictographs Extended-A
      (code >= 0x2e80 && code <= 0x9fff)     // CJK
    ) {
      width += 2;
    } else {
      width += 1;
    }
  }
  return width;
}

/**
 * Pads a string to a target visible width, taking ANSI escapes into account
 */
export function padEndVisible(text: string, targetWidth: number, padChar = ' '): string {
  const current = visibleWidth(text);
  if (current >= targetWidth) return text;
  return text + padChar.repeat(targetWidth - current);
}

/**
 * Pads start of a string to a target visible width
 */
export function padStartVisible(text: string, targetWidth: number, padChar = ' '): string {
  const current = visibleWidth(text);
  if (current >= targetWidth) return text;
  return padChar.repeat(targetWidth - current) + text;
}

/**
 * Converts ANSI colored text into sanitized HTML with inline CSS or classes
 * for 1:1 rendering in browser cyber-terminals.
 */
export function toHtml(ansiText: string): string {
  const colorMap: Record<string, string> = {
    '30': 'color:#000000',
    '31': 'color:#ef4444',
    '32': 'color:#22c55e',
    '33': 'color:#eab308',
    '34': 'color:#3b82f6',
    '35': 'color:#a855f7',
    '36': 'color:#06b6d4',
    '37': 'color:#e4e4e7',
    '90': 'color:#71717a',
    '91': 'color:#f87171',
    '92': 'color:#4ade80',
    '93': 'color:#fde047',
    '94': 'color:#60a5fa',
    '95': 'color:#c084fc',
    '96': 'color:#22d3ee',
    '97': 'color:#ffffff',
    '1': 'font-weight:bold',
    '2': 'opacity:0.6',
    '3': 'font-style:italic',
    '4': 'text-decoration:underline',
  };

  // Escape basic HTML characters
  let escaped = ansiText
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // Replace ANSI SGR codes with spans
  escaped = escaped.replace(/\x1b\[([0-9;]+)m/g, (_match, p1: string) => {
    if (p1 === '0') {
      return '</span>';
    }
    const codes = p1.split(';');
    const styles: string[] = [];
    for (const code of codes) {
      if (colorMap[code]) {
        styles.push(colorMap[code]);
      }
    }
    if (styles.length > 0) {
      return `<span style="${styles.join(';')}">`;
    }
    return '';
  });

  return escaped;
}

/**
 * Converts ANSI text directly to plain text (strips ANSI codes)
 */
export function toPlainText(ansiText: string): string {
  return stripAnsi(ansiText);
}

// ============================================================================
// Traffic Light Badges & Status Indicators
// ============================================================================

export type TrafficLightStatus =
  | 'green'
  | 'yellow'
  | 'red'
  | 'ok'
  | 'warn'
  | 'error'
  | 'online'
  | 'standby'
  | 'offline'
  | 'free'
  | 'paid';

export function trafficLightIcon(status: TrafficLightStatus): string {
  switch (status) {
    case 'green':
    case 'ok':
    case 'online':
    case 'free':
      return '[OK]';
    case 'yellow':
    case 'warn':
    case 'standby':
    case 'paid':
      return '[MED]';
    case 'red':
    case 'error':
    case 'offline':
      return '[HIGH]';
    default:
      return '[--]';
  }
}

export function trafficLightColor(status: TrafficLightStatus): string {
  switch (status) {
    case 'green':
    case 'ok':
    case 'online':
    case 'free':
      return AnsiColors.green;
    case 'yellow':
    case 'warn':
    case 'standby':
    case 'paid':
      return AnsiColors.yellow;
    case 'red':
    case 'error':
    case 'offline':
      return AnsiColors.red;
    default:
      return AnsiColors.white;
  }
}

/**
 * Generates standard cyber-terminal traffic light badge:
 * e.g. "[OK] ONLINE", "[MED] STANDBY", "[HIGH] OFFLINE", "[OK] FREE QUOTA"
 */
export function statusBadge(status: TrafficLightStatus, customLabel?: string): string {
  const icon = trafficLightIcon(status);
  const color = trafficLightColor(status);
  let label = customLabel;

  if (!label) {
    switch (status) {
      case 'green':
      case 'ok':
      case 'online':
        label = 'ONLINE';
        break;
      case 'yellow':
      case 'warn':
      case 'standby':
        label = 'STANDBY';
        break;
      case 'red':
      case 'error':
      case 'offline':
        label = 'OFFLINE';
        break;
      case 'free':
        label = '100% FREE QUOTA';
        break;
      case 'paid':
        label = 'PAID / METERED';
        break;
      default:
        label = String(status).toUpperCase();
    }
  }

  return `${icon} ${color}${AnsiColors.bold}[${label}]${AnsiColors.reset}`;
}

/**
 * Minimal inline badge
 */
export function badge(text: string, color: string = AnsiColors.cyan): string {
  return `${AnsiColors.gray}[${AnsiColors.reset}${color}${text}${AnsiColors.reset}${AnsiColors.gray}]${AnsiColors.reset}`;
}

// ============================================================================
// Clean Headers, Dividers, and Prompt Symbols
// ============================================================================

export function divider(char = '─', width = 78, color = AnsiColors.gray): string {
  return `${color}${char.repeat(width)}${AnsiColors.reset}`;
}

export function sectionHeader(title: string, tag = '', width = 78): string {
  const cleanTitle = ` ${title.toUpperCase()} `;
  const cleanTag = tag ? ` [ ${tag} ] ` : '';
  const remaining = Math.max(4, width - visibleWidth(cleanTitle) - visibleWidth(cleanTag) - 2);
  const left = '──';
  const right = '─'.repeat(remaining);

  return `${AnsiColors.gray}┌${left}${AnsiColors.reset}${AnsiColors.bold}${AnsiColors.white}${cleanTitle}${AnsiColors.reset}${cleanTag ? `${AnsiColors.cyan}${cleanTag}${AnsiColors.reset}` : ''}${AnsiColors.gray}${right}┐${AnsiColors.reset}`;
}

export function sectionFooter(width = 78): string {
  return `${AnsiColors.gray}└${'─'.repeat(width - 2)}┘${AnsiColors.reset}`;
}

export function formatBanner(lines: string[], title = 'EVABOT ONLINE v0.0.1 MVP', width = 78): string {
  const contentWidth = width - 4;
  const top = `${AnsiColors.gray}┌${'─'.repeat(width - 2)}┐${AnsiColors.reset}`;
  const bottom = `${AnsiColors.gray}└${'─'.repeat(width - 2)}┘${AnsiColors.reset}`;

  const renderedLines: string[] = [top];
  renderedLines.push(
    `${AnsiColors.gray}│${AnsiColors.reset} ${AnsiColors.bold}${AnsiColors.brightWhite}${padEndVisible(title, contentWidth - 1)}${AnsiColors.reset} ${AnsiColors.gray}│${AnsiColors.reset}`
  );
  renderedLines.push(`${AnsiColors.gray}├${'─'.repeat(width - 2)}┤${AnsiColors.reset}`);

  for (const line of lines) {
    const padded = padEndVisible(line, contentWidth - 1);
    renderedLines.push(`${AnsiColors.gray}│${AnsiColors.reset} ${padded} ${AnsiColors.gray}│${AnsiColors.reset}`);
  }

  renderedLines.push(bottom);
  return renderedLines.join('\n');
}

export function promptSymbol(mode: string = 'solo'): string {
  switch (mode.toLowerCase()) {
    case 'consilium':
      return `${AnsiColors.green}[TEAM] ❯${AnsiColors.reset}`;
    case 'dialogue':
      return `${AnsiColors.cyan}❯${AnsiColors.reset}`;
    case 'broadcast':
      return `${AnsiColors.yellow}[NET] ❯${AnsiColors.reset}`;
    default:
      return `${AnsiColors.brightGreen}❯${AnsiColors.reset}`;
  }
}

export function formatPrompt(options: {
  model?: string;
  mode?: string;
  role?: string;
}): string {
  const mode = (options.mode || 'solo').toUpperCase();
  const model = options.model ? ` (${options.model})` : '';
  const role = options.role && options.role !== 'general_assistant' ? ` [${options.role}]` : '';
  const symbol = promptSymbol(options.mode);

  return `${AnsiColors.bold}${AnsiColors.white}eva${AnsiColors.reset}${AnsiColors.gray}${model}${role} ${AnsiColors.cyan}[${mode}]${AnsiColors.reset} ${symbol} `;
}

// ============================================================================
// Formatted Monospace Table Engine
// ============================================================================

export interface TableColumn<T = any> {
  key: keyof T | string;
  header: string;
  align?: 'left' | 'center' | 'right';
  minWidth?: number;
  maxWidth?: number;
  format?: (value: any, row: T) => string;
}

export interface TableOptions<T = any> {
  columns: TableColumn<T>[];
  borderStyle?: 'unicode' | 'ascii' | 'minimal' | 'none';
  headerColor?: string;
  borderColor?: string;
  padding?: number;
  maxWidth?: number;
}

export class TableFormatter {
  /**
   * Formats rows into a clean, perfectly aligned monospace table
   */
  public static render<T extends Record<string, any>>(
    rows: T[],
    options: TableOptions<T>
  ): string {
    const {
      columns,
      borderStyle = 'unicode',
      headerColor = `${AnsiColors.bold}${AnsiColors.white}`,
      borderColor = AnsiColors.gray,
      padding = 1,
    } = options;

    const pad = ' '.repeat(padding);

    // 1. Calculate column widths
    const colWidths: number[] = columns.map((col) => {
      let max = visibleWidth(col.header);
      if (col.minWidth) max = Math.max(max, col.minWidth);

      for (const row of rows) {
        const val = col.format
          ? col.format(row[col.key], row)
          : String(row[col.key] ?? '');
        max = Math.max(max, visibleWidth(val));
      }

      if (col.maxWidth) max = Math.min(max, col.maxWidth);
      return max;
    });

    // 2. Borders definition
    const chars = {
      unicode: {
        tl: '┌',
        tm: '┬',
        tr: '┐',
        ml: '├',
        mm: '┼',
        mr: '┤',
        bl: '└',
        bm: '┴',
        br: '┘',
        h: '─',
        v: '│',
      },
      ascii: {
        tl: '+',
        tm: '+',
        tr: '+',
        ml: '+',
        mm: '+',
        mr: '+',
        bl: '+',
        bm: '+',
        br: '+',
        h: '-',
        v: '|',
      },
      minimal: {
        tl: '',
        tm: '',
        tr: '',
        ml: '',
        mm: '',
        mr: '',
        bl: '',
        bm: '',
        br: '',
        h: '─',
        v: ' ',
      },
      none: {
        tl: '',
        tm: '',
        tr: '',
        ml: '',
        mm: '',
        mr: '',
        bl: '',
        bm: '',
        br: '',
        h: '',
        v: ' ',
      },
    }[borderStyle];

    const formatCell = (content: string, width: number, align: 'left' | 'center' | 'right' = 'left'): string => {
      const vWidth = visibleWidth(content);
      if (vWidth >= width) return content;
      const diff = width - vWidth;

      if (align === 'right') {
        return ' '.repeat(diff) + content;
      }
      if (align === 'center') {
        const leftPad = Math.floor(diff / 2);
        const rightPad = diff - leftPad;
        return ' '.repeat(leftPad) + content + ' '.repeat(rightPad);
      }
      return content + ' '.repeat(diff);
    };

    const out: string[] = [];

    // Top border
    if (borderStyle === 'unicode' || borderStyle === 'ascii') {
      const topParts = colWidths.map((w) => chars.h.repeat(w + padding * 2));
      out.push(
        `${borderColor}${chars.tl}${topParts.join(chars.tm)}${chars.tr}${AnsiColors.reset}`
      );
    }

    // Header row
    const headerCells = columns.map((col, idx) => {
      const aligned = formatCell(col.header, colWidths[idx], col.align || 'left');
      return `${pad}${headerColor}${aligned}${AnsiColors.reset}${pad}`;
    });
    out.push(
      `${borderColor}${chars.v}${AnsiColors.reset}${headerCells.join(`${borderColor}${chars.v}${AnsiColors.reset}`)}${borderColor}${chars.v}${AnsiColors.reset}`
    );

    // Separator border
    if (borderStyle !== 'none') {
      const midParts = colWidths.map((w) => chars.h.repeat(w + padding * 2));
      const midLeft = borderStyle === 'minimal' ? '' : chars.ml;
      const midRight = borderStyle === 'minimal' ? '' : chars.mr;
      const midJoint = borderStyle === 'minimal' ? ' ' : chars.mm;
      out.push(
        `${borderColor}${midLeft}${midParts.join(midJoint)}${midRight}${AnsiColors.reset}`
      );
    }

    // Data rows
    for (const row of rows) {
      const dataCells = columns.map((col, idx) => {
        const raw = col.format
          ? col.format(row[col.key], row)
          : String(row[col.key] ?? '');
        const aligned = formatCell(raw, colWidths[idx], col.align || 'left');
        return `${pad}${aligned}${pad}`;
      });
      out.push(
        `${borderColor}${chars.v}${AnsiColors.reset}${dataCells.join(`${borderColor}${chars.v}${AnsiColors.reset}`)}${borderColor}${chars.v}${AnsiColors.reset}`
      );
    }

    // Bottom border
    if (borderStyle === 'unicode' || borderStyle === 'ascii') {
      const botParts = colWidths.map((w) => chars.h.repeat(w + padding * 2));
      out.push(
        `${borderColor}${chars.bl}${botParts.join(chars.bm)}${chars.br}${AnsiColors.reset}`
      );
    }

    return out.join('\n');
  }
}

// ============================================================================
// SGR Mouse Tracking (Mode 1006)
// ============================================================================

export interface SgrMouseEvent {
  button: number;       // 0=left, 1=middle, 2=right, 64=scroll-up, 65=scroll-down, 3=release
  pressed: boolean;     // true = press, false = release
  col: number;          // 1-based column
  row: number;          // 1-based row
  isRelease: boolean;
}

export interface ClickableArea {
  id: string;
  row: number;          // 1-based row (viewport)
  startCol: number;     // 1-based inclusive
  endCol: number;       // 1-based inclusive
  label: string;
  action: () => void | Promise<void>;
}

export class MouseTracker {
  private clickables: ClickableArea[] = [];
  private enabled = false;
  private onData?: (event: SgrMouseEvent) => void;

  constructor(onData?: (event: SgrMouseEvent) => void) {
    this.onData = onData;
  }

  /**
   * Enable SGR mouse mode 1003 (all events) + mode 1006 (SGR coordinates)
   */
  public enable(): void {
    if (this.enabled) return;
    this.enabled = true;
    process.stdout.write('\x1b[?1003h\x1b[?1006h');
  }

  /**
   * Disable SGR mouse tracking and restore terminal
   */
  public disable(): void {
    if (!this.enabled) return;
    this.enabled = false;
    process.stdout.write('\x1b[?1003l\x1b[?1006l');
  }

  public isEnabled(): boolean {
    return this.enabled;
  }

  /**
   * Parse raw input bytes for SGR mouse events.
   * SGR format: ESC [ < Cb ; Cc ; Cd M / m
   *   Cb = button (0-3 normal, 64=scroll up, 65=scroll down)
   *   Cc = column (1-based)
   *   Cd = row (1-based)
   *   M = press, m = release
   */
  public parseBuffer(data: Buffer): SgrMouseEvent[] {
    const events: SgrMouseEvent[] = [];
    const str = data.toString('utf-8');

    let i = 0;
    while (i < str.length) {
      // Look for ESC [ <
      if (str[i] === '\x1b' && i + 2 < str.length && str[i + 1] === '[' && str[i + 2] === '<') {
        i += 3;
        let cbStr = '';
        let ccStr = '';
        let cdStr = '';
        let phase = 0;

        while (i < str.length) {
          const ch = str[i];
          if (ch === ';') {
            phase++;
            i++;
            continue;
          }
          if (ch === 'M' || ch === 'm') {
            const isRelease = ch === 'm';
            const cb = parseInt(cbStr, 10) || 0;
            const cc = parseInt(ccStr, 10) || 0;
            const cd = parseInt(cdStr, 10) || 0;

            const event: SgrMouseEvent = {
              button: cb,
              pressed: !isRelease,
              col: cc,
              row: cd,
              isRelease,
            };

            events.push(event);
            this.onData?.(event);
            this.checkClickable(event);
            i++;
            break;
          }
          if (ch >= '0' && ch <= '9') {
            if (phase === 0) cbStr += ch;
            else if (phase === 1) ccStr += ch;
            else if (phase === 2) cdStr += ch;
          }
          i++;
        }
      } else {
        i++;
      }
    }

    return events;
  }

  /**
   * Register a clickable area
   */
  public registerClickable(area: ClickableArea): void {
    this.clickables.push(area);
  }

  /**
   * Clear all registered clickables (call on each render cycle)
   */
  public clearClickables(): void {
    this.clickables = [];
  }

  /**
   * Check if a mouse event hits a registered clickable
   */
  private checkClickable(event: SgrMouseEvent): void {
    if (event.isRelease) return;

    const hit = this.clickables.find(
      (c) => event.row === c.row && event.col >= c.startCol && event.col <= c.endCol
    );

    if (hit) {
      hit.action();
    }
  }

  /**
   * Setup raw mode stdin listener for mouse events
   */
  public attachStdin(stdin: NodeJS.ReadStream): void {
    if (stdin.isTTY) {
      stdin.setRawMode(true);
    }
    stdin.resume();
    stdin.on('data', (data: Buffer) => {
      this.parseBuffer(data);
    });
  }

  /**
   * Detach stdin listener
   */
  public detachStdin(stdin: NodeJS.ReadStream): void {
    stdin.removeAllListeners('data');
    if (stdin.isTTY) {
      stdin.setRawMode(false);
    }
  }
}

/**
 * Helper: render a clickable text span that registers coordinates for mouse hit-testing.
 * Returns the plain text (for screen output) and registers the clickable area.
 */
export function clickableText(
  tracker: MouseTracker,
  text: string,
  row: number,
  startCol: number,
  id: string,
  action: () => void | Promise<void>
): string {
  tracker.registerClickable({
    id,
    row,
    startCol,
    endCol: startCol + visibleWidth(text) - 1,
    label: text,
    action,
  });
  return text;
}

// ============================================================================
// Reactive Stream Engine (Line-by-line & progressive streaming)
// ============================================================================

export interface AnsiStreamWriterOptions {
  prefix?: string;
  writeToStdout?: boolean;
  onChunk?: (chunk: string) => void;
  onLine?: (line: string) => void;
}

export class AnsiStreamWriter extends EventEmitter {
  private lineBuffer: string = '';
  private fullAnsiBuffer: string = '';
  private lines: string[] = [];
  private prefix: string;
  private writeToStdout: boolean;
  private onChunkCallback?: (chunk: string) => void;
  private onLineCallback?: (line: string) => void;
  private isStartOfLine: boolean = true;

  constructor(options: AnsiStreamWriterOptions = {}) {
    super();
    this.prefix = options.prefix ?? '';
    this.writeToStdout = options.writeToStdout ?? false;
    this.onChunkCallback = options.onChunk;
    this.onLineCallback = options.onLine;
  }

  /**
   * Set dynamic prefix for streamed lines (e.g. `│ ` or ` `)
   */
  public setPrefix(prefix: string): void {
    this.prefix = prefix;
  }

  /**
   * Appends a chunk to the stream, processing complete lines reactively
   */
  public write(chunk: string): void {
    this.fullAnsiBuffer += chunk;
    this.lineBuffer += chunk;

    if (this.onChunkCallback) {
      this.onChunkCallback(chunk);
    }
    this.emit('chunk', chunk);

    // Process newlines
    let nlIdx = this.lineBuffer.indexOf('\n');
    while (nlIdx !== -1) {
      const line = this.lineBuffer.slice(0, nlIdx);
      this.lineBuffer = this.lineBuffer.slice(nlIdx + 1);
      this.lines.push(line);

      if (this.writeToStdout) {
        if (this.isStartOfLine && this.prefix) {
          process.stdout.write(this.prefix);
        }
        process.stdout.write(line + '\n');
        this.isStartOfLine = true;
      }

      if (this.onLineCallback) {
        this.onLineCallback(line);
      }
      this.emit('line', line);

      nlIdx = this.lineBuffer.indexOf('\n');
    }

    // Output partial line to stdout if enabled
    if (this.writeToStdout && this.lineBuffer.length > 0) {
      if (this.isStartOfLine && this.prefix) {
        process.stdout.write(this.prefix);
        this.isStartOfLine = false;
      }
    }
  }

  /**
   * Writes a complete line
   */
  public writeLine(line: string = ''): void {
    this.write(line + '\n');
  }

  /**
   * Flushes any remaining content in the buffer
   */
  public flush(): void {
    if (this.lineBuffer.length > 0) {
      const line = this.lineBuffer;
      this.lineBuffer = '';
      this.lines.push(line);

      if (this.writeToStdout) {
        if (this.isStartOfLine && this.prefix) {
          process.stdout.write(this.prefix);
        }
        process.stdout.write(line + '\n');
        this.isStartOfLine = true;
      }

      if (this.onLineCallback) {
        this.onLineCallback(line);
      }
      this.emit('line', line);
    }
  }

  /**
   * Signals the end of the stream and flushes remaining content
   */
  public end(): void {
    this.flush();
    this.emit('end', this.fullAnsiBuffer);
  }

  /**
   * Returns complete accumulated text formatted for ANSI, Plain Text, or HTML
   */
  public getFullText(format: 'ansi' | 'plain' | 'html' = 'ansi'): string {
    switch (format) {
      case 'plain':
        return toPlainText(this.fullAnsiBuffer);
      case 'html':
        return toHtml(this.fullAnsiBuffer);
      default:
        return this.fullAnsiBuffer;
    }
  }

  /**
   * Returns all processed lines
   */
  public getLines(format: 'ansi' | 'plain' = 'ansi'): string[] {
    if (format === 'plain') {
      return this.lines.map(toPlainText);
    }
    return [...this.lines];
  }

  /**
   * Clears all internal buffers
   */
  public clear(): void {
    this.lineBuffer = '';
    this.fullAnsiBuffer = '';
    this.lines = [];
    this.isStartOfLine = true;
  }
}

