import { Plugin, PluginContext, PluginManifest, PluginError, PluginEventBus } from './types.js';
import { logger, LogCategory } from '../Logger.js';

interface LoadedPlugin {
  plugin: Plugin;
  status: 'loaded' | 'initializing' | 'active' | 'shutdown' | 'failed' | 'disabled';
  error?: string;
  loadedAt: Date;
  manifest: PluginManifest;
}

export class PluginManager {
  private static instance: PluginManager;
  private plugins: Map<string, LoadedPlugin> = new Map();
  private eventBus: PluginEventBus = new PluginEventBus();
  private routes: Array<{ method: string; path: string; handler: Function; pluginId: string }> = [];
  private commands: Map<string, { handler: Function; help?: string; pluginId: string }> = new Map();

  private constructor() {}

  public static getInstance(): PluginManager {
    if (!PluginManager.instance) {
      PluginManager.instance = new PluginManager();
    }
    return PluginManager.instance;
  }

  public static resetInstance(): void {
    PluginManager.instance = null as any;
  }

  public async register(plugin: Plugin): Promise<void> {
    const id = plugin.manifest.id;

    if (this.plugins.has(id)) {
      throw new PluginError(id, 'Plugin already registered');
    }

    if (plugin.manifest.dependencies) {
      for (const dep of plugin.manifest.dependencies) {
        if (!this.plugins.has(dep)) {
          throw new PluginError(id, `Missing dependency: ${dep}`);
        }
      }
    }

    this.plugins.set(id, {
      plugin,
      status: 'initializing',
      loadedAt: new Date(),
      manifest: plugin.manifest,
    });

    try {
      const context: PluginContext = {
        config: this.getPluginConfig(id),
        logger: this.createPluginLogger(id),
        eventBus: this.eventBus,
        registerRoute: (method, path, handler) => {
          this.routes.push({ method, path, handler, pluginId: id });
        },
        registerCommand: (command, handler, help) => {
          this.commands.set(command, { handler, help, pluginId: id });
        },
        getStorage: (name) => null,
      };

      await plugin.initialize(context);

      const loaded = this.plugins.get(id)!;
      loaded.status = plugin.manifest.enabled ? 'active' : 'disabled';

      logger.info(LogCategory.SYSTEM, 'PluginManager', `Plugin registered: ${id} v${plugin.manifest.version}`);
    } catch (err: any) {
      const loaded = this.plugins.get(id)!;
      loaded.status = 'failed';
      loaded.error = err.message;
      throw new PluginError(id, `Failed to initialize: ${err.message}`, err);
    }
  }

  public async enable(pluginId: string): Promise<void> {
    const loaded = this.plugins.get(pluginId);
    if (!loaded) throw new PluginError(pluginId, 'Plugin not found');
    if (loaded.status === 'active') return;

    loaded.manifest.enabled = true;
    loaded.status = 'active';
    logger.info(LogCategory.SYSTEM, 'PluginManager', `Plugin enabled: ${pluginId}`);
  }

  public async disable(pluginId: string): Promise<void> {
    const loaded = this.plugins.get(pluginId);
    if (!loaded) throw new PluginError(pluginId, 'Plugin not found');
    if (loaded.status === 'disabled') return;

    loaded.manifest.enabled = false;
    loaded.status = 'disabled';
    logger.info(LogCategory.SYSTEM, 'PluginManager', `Plugin disabled: ${pluginId}`);
  }

  public async shutdown(pluginId: string): Promise<void> {
    const loaded = this.plugins.get(pluginId);
    if (!loaded) return;

    try {
      await loaded.plugin.shutdown();
      loaded.status = 'shutdown';
      logger.info(LogCategory.SYSTEM, 'PluginManager', `Plugin shut down: ${pluginId}`);
    } catch (err: any) {
      logger.error(LogCategory.SYSTEM, 'PluginManager', `Shutdown error for ${pluginId}: ${err.message}`);
    }
  }

  public async shutdownAll(): Promise<void> {
    for (const id of this.plugins.keys()) {
      await this.shutdown(id);
    }
  }

  public get(pluginId: string): Plugin | undefined {
    return this.plugins.get(pluginId)?.plugin;
  }

  public list(): PluginManifest[] {
    return Array.from(this.plugins.values()).map(p => ({
      ...p.manifest,
      enabled: p.status === 'active',
    }));
  }

  public getStatus(pluginId: string): string | undefined {
    return this.plugins.get(pluginId)?.status;
  }

  public getRoutes(): Array<{ method: string; path: string; handler: Function; pluginId: string }> {
    return this.routes.filter(r => {
      const loaded = this.plugins.get(r.pluginId);
      return loaded && loaded.status === 'active';
    });
  }

  public getAllPluginRoutes(): Array<{ method: string; path: string; handler: (body: any, query: any) => Promise<any> | any; pluginId: string }> {
    const result: Array<{ method: string; path: string; handler: (body: any, query: any) => Promise<any> | any; pluginId: string }> = [];
    for (const [id, loaded] of this.plugins) {
      if (loaded.status === 'active') {
        const plugin = loaded.plugin as any;
        if (plugin.routes && Array.isArray(plugin.routes)) {
          for (const r of plugin.routes) {
            result.push({ method: r.method, path: r.path, handler: r.handler, pluginId: id });
          }
        }
      }
    }
    return result;
  }

  public getCommands(): Map<string, { handler: Function; help?: string; pluginId: string }> {
    return this.commands;
  }

  public getEventBus(): PluginEventBus {
    return this.eventBus;
  }

  public async healthCheckAll(): Promise<Record<string, { status: string; message?: string }>> {
    const results: Record<string, { status: string; message?: string }> = {};

    for (const [id, loaded] of this.plugins) {
      if (loaded.status === 'active' && loaded.plugin.healthCheck) {
        try {
          results[id] = await loaded.plugin.healthCheck();
        } catch (err: any) {
          results[id] = { status: 'down', message: err.message };
        }
      } else {
        results[id] = { status: loaded.status };
      }
    }

    return results;
  }

  private getPluginConfig(pluginId: string): Record<string, any> {
    return {};
  }

  private createPluginLogger(pluginId: string) {
    return {
      info: (msg: string, meta?: any) => logger.info(LogCategory.SYSTEM, pluginId, msg, meta),
      warn: (msg: string, meta?: any) => logger.warn(LogCategory.SYSTEM, pluginId, msg, meta),
      error: (msg: string, meta?: any) => logger.error(LogCategory.SYSTEM, pluginId, msg, meta),
      debug: (msg: string, meta?: any) => logger.debug(LogCategory.SYSTEM, pluginId, msg, meta),
    };
  }
}

export const pluginManager = PluginManager.getInstance();

/**
 * EvaBot Plugin System
 * Автономные плагины которые можно подключать/отключать
 */

export interface PluginContext {
  config: Record<string, any>;
  logger: any;
  eventBus: PluginEventBus;
  registerRoute: (method: string, path: string, handler: Function) => void;
  registerCommand: (command: string, handler: Function, help?: string) => void;
  getStorage: (name: string) => any;
}

export interface PluginManifest {
  id: string;
  name: string;
  version: string;
  description: string;
  author?: string;
  dependencies?: string[];
  enabled: boolean;
  category: 'core' | 'ai' | 'data' | 'security' | 'integration';
}

export interface Plugin {
  manifest: PluginManifest;
  initialize(context: PluginContext): Promise<void>;
  shutdown(): Promise<void>;
  healthCheck?(): Promise<{ status: 'healthy' | 'degraded' | 'down'; message?: string }>;
}

export class PluginError extends Error {
  constructor(public pluginId: string, message: string, public cause?: Error) {
    super(`[${pluginId}] ${message}`);
    this.name = 'PluginError';
  }
}

export type PluginEventHandler = (data: any) => void | Promise<void>;

export class PluginEventBus {
  private handlers: Map<string, Set<PluginEventHandler>> = new Map();

  public on(event: string, handler: PluginEventHandler): void {
    if (!this.handlers.has(event)) {
      this.handlers.set(event, new Set());
    }
    this.handlers.get(event)!.add(handler);
  }

  public off(event: string, handler: PluginEventHandler): void {
    this.handlers.get(event)?.delete(handler);
  }

  public async emit(event: string, data: any): Promise<void> {
    const handlers = this.handlers.get(event);
    if (!handlers) return;

    await Promise.all(
      Array.from(handlers).map(h => Promise.resolve(h(data)))
    );
  }

  public clear(): void {
    this.handlers.clear();
  }
}

import { Plugin, PluginContext, PluginManifest } from '../../core/plugin-system/types.js';
import { logger, LogCategory } from '../../core/Logger.js';

export interface LLMProvider {
  id: string;
  name: string;
  baseUrl: string;
  apiKey: string;
  enabled: boolean;
  modelPrefix?: string;
  freeOnly: boolean;
}

export interface LLMRequest {
  model: string;
  messages: Array<{ role: string; content: string }>;
  temperature?: number;
  maxTokens?: number;
  stream?: boolean;
}

export interface LLMResponse {
  content: string;
  model: string;
  provider: string;
  tokens?: number;
  durationMs: number;
}

export interface PluginRoute {
  method: string;
  path: string;
  handler: (body: any, query: any) => Promise<any> | any;
}

const MANIFEST: PluginManifest = {
  id: 'llm-providers',
  name: 'LLM Multi-Provider Gateway',
  version: '1.0.0',
  description: 'Unified gateway to 4 LLM providers: Google, OmniRoute, OpenRouter, OpenCode',
  author: 'EvaBot Engineering',
  enabled: true,
  category: 'ai',
};

export class LLMProvidersPlugin implements Plugin {
  public readonly manifest = MANIFEST;
  public readonly routes: PluginRoute[] = [];
  public readonly commands: Array<{ cmd: string; handler: (args: string) => Promise<string>; help?: string }> = [];

  private providers: Map<string, LLMProvider> = new Map();

  public async initialize(context: PluginContext): Promise<void> {
    this.setupProviders();

    this.routes.push({
      method: 'GET',
      path: '/api/llm/providers',
      handler: async () => ({
        providers: this.getProviderStatus(),
        total: this.providers.size,
        active: Array.from(this.providers.values()).filter(p => p.enabled).length,
      }),
    });

    this.routes.push({
      method: 'POST',
      path: '/api/llm/chat',
      handler: async (body) => await this.chat(body),
    });

    this.routes.push({
      method: 'POST',
      path: '/api/llm/test',
      handler: async (body) => await this.testProvider(body.provider),
    });

    this.commands.push({
      cmd: '/providers',
      handler: async () => this.formatProviderList(),
      help: 'List all LLM providers',
    });

    logger.info(LogCategory.LLM, 'LLMProviders', `Initialized with ${this.providers.size} providers`);
  }

  public async shutdown(): Promise<void> {
    this.providers.clear();
  }

  public async healthCheck() {
    const enabled = Array.from(this.providers.values()).filter(p => p.enabled).length;
    return {
      status: enabled > 0 ? 'healthy' as const : 'down' as const,
      message: `${enabled}/${this.providers.size} providers enabled`
    };
  }

  public registerProvider(provider: LLMProvider): void {
    this.providers.set(provider.id, provider);
  }

  public getProvider(id: string): LLMProvider | undefined {
    return this.providers.get(id);
  }

  public resolveProvider(model: string): LLMProvider {
    const m = model.toLowerCase();

    if (m.startsWith('omniroute/')) return this.providers.get('omniroute')!;
    if (m.startsWith('opencode/')) return this.providers.get('opencode')!;
    if (m.startsWith('openrouter/') || m.includes(':free') || m.includes('/free')) {
      return this.providers.get('openrouter')!;
    }
    if (m.startsWith('kilo/') || m.startsWith('kilocode/')) return this.providers.get('kilocode')!;

    if (m.includes('claude') || m.includes('gpt-') || m.includes('openai')) {
      return this.providers.get('openrouter')!;
    }

    return this.providers.get('google')!;
  }

  public async chat(request: LLMRequest): Promise<LLMResponse> {
    const provider = this.resolveProvider(request.model);
    if (!provider) {
      throw new Error(`No provider available for model: ${request.model}`);
    }
    if (!provider.enabled) {
      const err: any = new Error(`Provider ${provider.id} is disabled`);
      err.statusCode = 503;
      err.provider = provider.id;
      throw err;
    }

    return await this.callProvider(provider, request);
  }

  private async callProvider(provider: LLMProvider, request: LLMRequest): Promise<LLMResponse> {
    const start = Date.now();

    const targetModel = this.cleanModelId(request.model, provider);
    const url = `${provider.baseUrl}/chat/completions`;
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };

    if (provider.apiKey) {
      headers['Authorization'] = `Bearer ${provider.apiKey}`;
    }
    if (provider.id === 'openrouter') {
      headers['HTTP-Referer'] = 'https://evabot.online';
      headers['X-Title'] = 'EvaBot Autonomous Agent';
    }

    const payload = {
      model: targetModel,
      messages: request.messages,
      temperature: request.temperature ?? 0.7,
      max_tokens: request.maxTokens ?? 2048,
    };

    const res = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(30000),
    });

    if (!res.ok) {
      const error = await res.text();
      const err: any = new Error(`Provider ${provider.id} error ${res.status}: ${error.substring(0, 200)}`);
      err.statusCode = res.status;
      err.provider = provider.id;
      throw err;
    }

    const data = await res.json() as any;
    const content = data.choices?.[0]?.message?.content || '';
    const tokens = data.usage?.total_tokens;

    return {
      content,
      model: request.model,
      provider: provider.id,
      tokens,
      durationMs: Date.now() - start,
    };
  }

  public async testProvider(providerId: string): Promise<{ provider: string; status: 'ok' | 'error'; latencyMs?: number; error?: string }> {
    const provider = this.providers.get(providerId);
    if (!provider) {
      throw new Error(`Unknown provider: ${providerId}`);
    }

    const start = Date.now();
    try {
      await this.callProvider(provider, {
        model: this.getTestModel(provider),
        messages: [{ role: 'user', content: 'test' }],
        maxTokens: 10,
      });
      return {
        provider: providerId,
        status: 'ok',
        latencyMs: Date.now() - start,
      };
    } catch (err: any) {
      return {
        provider: providerId,
        status: 'error',
        error: err.message,
      };
    }
  }

  private getTestModel(provider: LLMProvider): string {
    const tests: Record<string, string> = {
      google: 'gemini-2.5-flash',
      omniroute: 'gemini-2.5-flash',
      openrouter: 'google/gemini-2.0-flash-exp:free',
      opencode: 'zen-fast',
      kilocode: 'minimax/minimax-m3:free',
    };
    return tests[provider.id] || 'test';
  }

  private cleanModelId(model: string, provider: LLMProvider): string {
    const prefixes = ['omniroute/', 'opencode/', 'openrouter/', 'kilo/', 'kilocode/'];
    for (const prefix of prefixes) {
      if (model.startsWith(prefix)) {
        return model.substring(prefix.length);
      }
    }
    return model;
  }

  public getProviderStatus() {
    return Array.from(this.providers.values()).map(p => ({
      id: p.id,
      name: p.name,
      enabled: p.enabled,
      freeOnly: p.freeOnly,
    }));
  }

  public formatProviderList(): string {
    let output = '\n╔══ LLM PROVIDERS ══╗\n';
    for (const p of this.providers.values()) {
      const status = p.enabled ? '[OK]' : '[HIGH]';
      output += `  ${status} ${p.id}: ${p.name}${p.freeOnly ? ' (free)' : ''}\n`;
    }
    output += '╚═════════════════════╝\n';
    return output;
  }

  private setupProviders(): void {
    this.providers.set('google', {
      id: 'google',
      name: 'Google AI (Gemini)',
      baseUrl: 'https://generativelanguage.googleapis.com/v1beta',
      apiKey: process.env.GEMINI_API_KEY || '',
      enabled: true,
      freeOnly: false,
    });

    this.providers.set('omniroute', {
      id: 'omniroute',
      name: 'OmniRoute (Internal LiteLLM Proxy)',
      baseUrl: process.env.OMNIROUTE_BASE_URL || 'http://localhost:20128/v1',
      apiKey: process.env.OMNIROUTE_API_KEY || 'sk-1234',
      enabled: true,
      freeOnly: false,
    });

    this.providers.set('openrouter', {
      id: 'openrouter',
      name: 'OpenRouter',
      baseUrl: 'https://openrouter.ai/api/v1',
      apiKey: process.env.OPENROUTER_API_KEY || '',
      enabled: Boolean(process.env.OPENROUTER_API_KEY),
      freeOnly: false,
    });

    this.providers.set('opencode', {
      id: 'opencode',
      name: 'OpenCode Go',
      baseUrl: process.env.OPENCODE_BASE_URL || 'http://localhost:20128/v1',
      apiKey: process.env.OPENCODE_API_KEY || 'sk-1234',
      enabled: true,
      freeOnly: false,
    });

    this.providers.set('kilocode', {
      id: 'kilocode',
      name: 'KiloCode (Free Models Aggregator)',
      baseUrl: 'https://api.kilocode.ai/v1',
      apiKey: process.env.KILOCODE_API_KEY || '',
      enabled: Boolean(process.env.KILOCODE_API_KEY),
      freeOnly: true,
    });
  }
}

export const llmProvidersPlugin = new LLMProvidersPlugin();

import { Plugin, PluginContext, PluginManifest } from '../../core/plugin-system/types.js';
import fs from 'node:fs';
import path from 'node:path';
import { logger, LogCategory } from '../../core/Logger.js';

export interface KnowledgeDocument {
  id: string;
  title: string;
  content: string;
  category: string;
  language: 'en' | 'uk' | 'ru' | 'pl' | 'ro' | 'de';
  tags: string[];
  source: string;
}

const MANIFEST: PluginManifest = {
  id: 'knowledge-base',
  name: 'EvaLine Knowledge Base',
  version: '1.0.0',
  description: 'EvaLine corporate knowledge base (182 documents, 6 languages)',
  author: 'EvaBot Engineering',
  enabled: true,
  category: 'data',
};

export class KnowledgeBasePlugin implements Plugin {
  public readonly manifest = MANIFEST;
  public readonly routes: Array<{ method: string; path: string; handler: (body: any, query: any) => Promise<any> }> = [];
  public readonly commands: Array<{ cmd: string; handler: (args: string) => Promise<string>; help?: string }> = [];

  private documents: Map<string, KnowledgeDocument> = new Map();
  private knowledgeBasePath: string = '';
  private context?: PluginContext;

  public async initialize(context: PluginContext): Promise<void> {
    this.context = context;
    this.knowledgeBasePath = path.resolve(process.cwd(), 'knowledge-base');

    this.loadFromEvaLine();

    this.routes.push({
      method: 'GET',
      path: '/api/kb/status',
      handler: async () => ({
        totalDocuments: this.documents.size,
        languages: this.getLanguages(),
        categories: this.getCategories(),
      }),
    });

    this.routes.push({
      method: 'GET',
      path: '/api/kb/search',
      handler: async (body: any, query: any) => {
        const q = query.q || '';
        const limit = parseInt(query.limit || '5', 10);
        const results = this.search(q, { limit });
        return {
          query: q,
          count: results.length,
          results: results.map(d => ({
            id: d.id,
            title: d.title,
            category: d.category,
            language: d.language,
            preview: d.content.substring(0, 300),
          })),
        };
      },
    });

    this.routes.push({
      method: 'GET',
      path: '/api/kb/list',
      handler: async (body: any, query: any) => {
        const docs = this.listDocuments({
          language: query.language,
          category: query.category,
        });
        return {
          count: docs.length,
          documents: docs.map(d => ({
            id: d.id,
            title: d.title,
            category: d.category,
            language: d.language,
          })),
        };
      },
    });

    this.commands.push({
      cmd: '/kb',
      handler: async (args: string) => this.handleCommand(args),
      help: 'Knowledge base. Usage: /kb status|search <q>|list [lang]',
    });

    logger.info(LogCategory.KB, 'KnowledgeBase', `Plugin initialized with ${this.documents.size} documents`);
  }

  public async shutdown(): Promise<void> {
    this.documents.clear();
  }

  public async healthCheck() {
    return { 
      status: this.documents.size > 0 ? 'healthy' as const : 'degraded' as const,
      message: `${this.documents.size} documents loaded`
    };
  }

  public search(query: string, options: { limit?: number; language?: string; category?: string; minScore?: number } = {}): KnowledgeDocument[] {
    const limit = options.limit || 5;
    const minScore = options.minScore || 0.1;
    const queryLower = query.toLowerCase();
    const queryWords = queryLower.split(/\s+/).filter(w => w.length > 2);

    if (queryWords.length === 0) return [];

    const results: Array<{ doc: KnowledgeDocument; score: number }> = [];

    for (const doc of this.documents.values()) {
      if (options.language && doc.language !== options.language) continue;
      if (options.category && doc.category !== options.category) continue;

      const contentLower = (doc.title + ' ' + doc.content + ' ' + doc.tags.join(' ')).toLowerCase();
      let score = 0;
      let matches = 0;

      for (const word of queryWords) {
        const safeWord = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const count = (contentLower.match(new RegExp(safeWord, 'g')) || []).length;
        if (count > 0) {
          score += count * 0.1;
          matches++;
        }
      }

      if (queryLower.includes(doc.title.toLowerCase())) score += 0.5;
      for (const tag of doc.tags) {
        if (queryLower.includes(tag)) score += 0.2;
      }

      if (matches > 0) {
        score = Math.min(0.99, score);
        if (score >= minScore) {
          results.push({ doc, score });
        }
      }
    }

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, limit).map(r => r.doc);
  }

  public listDocuments(filter: { language?: string; category?: string } = {}): KnowledgeDocument[] {
    let docs = Array.from(this.documents.values());
    if (filter.language) {
      docs = docs.filter(d => d.language === filter.language);
    }
    if (filter.category) {
      docs = docs.filter(d => d.category === filter.category);
    }
    return docs;
  }

  public addDocument(doc: KnowledgeDocument): void {
    this.documents.set(doc.id, doc);
  }

  public getStats() {
    return {
      totalDocuments: this.documents.size,
      languages: this.getLanguages(),
      categories: this.getCategories(),
    };
  }

  private getLanguages(): string[] {
    const langs = new Set<string>();
    for (const doc of this.documents.values()) {
      langs.add(doc.language);
    }
    return Array.from(langs);
  }

  private getCategories(): string[] {
    const cats = new Set<string>();
    for (const doc of this.documents.values()) {
      cats.add(doc.category);
    }
    return Array.from(cats);
  }

  private loadFromEvaLine(): void {
    const evalinePath = path.join(this.knowledgeBasePath, 'evaline-com-ua');
    if (!fs.existsSync(evalinePath)) {
      logger.warn(LogCategory.KB, 'KnowledgeBase', 'EvaLine path not found', { path: evalinePath });
      return;
    }

    const sitePath = path.join(evalinePath, 'site');
    if (fs.existsSync(sitePath)) {
      this.loadDirectory(sitePath);
    }

    for (const lang of ['en', 'ru', 'uk'] as const) {
      const readmePath = path.join(evalinePath, `README.${lang}.md`);
      if (fs.existsSync(readmePath)) {
        this.addDocument({
          id: `evaline-readme-${lang}`,
          title: `EvaLine README (${lang.toUpperCase()})`,
          content: fs.readFileSync(readmePath, 'utf8'),
          category: 'company-overview',
          language: lang,
          tags: ['readme', 'evaline'],
          source: `evaline-com-ua/README.${lang}.md`,
        });
      }
    }
  }

  private loadDirectory(dirPath: string): void {
    const items = fs.readdirSync(dirPath);
    for (const item of items) {
      const itemPath = path.join(dirPath, item);
      const stat = fs.statSync(itemPath);

      if (stat.isFile() && item.endsWith('.md')) {
        const lang: KnowledgeDocument['language'] = this.detectLanguage(itemPath);
        const content = fs.readFileSync(itemPath, 'utf8');
        const titleMatch = content.match(/^#\s+(.+)$/m);
        const title = titleMatch ? titleMatch[1] : item.replace('.md', '');

        this.addDocument({
          id: `${lang}-${item.replace('.md', '').toLowerCase()}`,
          title,
          content,
          category: this.inferCategory(itemPath),
          language: lang,
          tags: [lang, 'evaline', 'product'],
          source: path.relative(this.knowledgeBasePath, itemPath),
        });
      } else if (stat.isDirectory()) {
        this.loadDirectory(itemPath);
      }
    }
  }

  private detectLanguage(filePath: string): 'en' | 'uk' | 'ru' | 'pl' | 'ro' | 'de' {
    if (filePath.includes('/site/en/')) return 'en';
    if (filePath.includes('/site/uk/')) return 'uk';
    if (filePath.includes('/site/ru/')) return 'ru';
    if (filePath.includes('/site/pl/')) return 'pl';
    if (filePath.includes('/site/ro/')) return 'ro';
    if (filePath.includes('/site/de/')) return 'de';
    return 'en';
  }

  private inferCategory(filePath: string): string {
    const lower = filePath.toLowerCase();
    if (lower.includes('b2b')) return 'b2b';
    if (lower.includes('b2c')) return 'b2c';
    if (lower.includes('certif')) return 'certificates';
    if (lower.includes('contact') || lower.includes('kontakt')) return 'contact';
    if (lower.includes('about') || lower.includes('pro-nas') || lower.includes('uber')) return 'about';
    if (lower.includes('wholesale') || lower.includes('poshuk-partneriv')) return 'wholesale';
    if (lower.includes('donate') || lower.includes('dopomoga')) return 'donate';
    if (lower.includes('news') || lower.includes('novini')) return 'news';
    if (lower.includes('index')) return 'home';
    return 'general';
  }

  public async handleCommand(args: string): Promise<string> {
    const parts = args.trim().split(/\s+/);
    const action = parts[0]?.toLowerCase();

    if (!action || action === 'help') {
      return '\n╔══ KB COMMANDS ══╗\n  /kb status\n  /kb search <query>\n  /kb list [lang|category]\n╚═════════════════╝';
    }

    if (action === 'status') {
      const stats = this.getStats();
      return `\n  KB Status: ${stats.totalDocuments} docs, ${stats.languages.length} languages, ${stats.categories.length} categories`;
    }

    if (action === 'search') {
      const query = parts.slice(1).join(' ');
      if (!query) return '[ERROR] Usage: /kb search <query>';
      const results = this.search(query, { limit: 5 });
      let output = `\n  Search "${query}": ${results.length} results\n`;
      for (const r of results) {
        output += `    - [${r.language.toUpperCase()}] ${r.title} (${r.category})\n`;
      }
      return output;
    }

    if (action === 'list') {
      const filter = parts[1];
      const docs = this.listDocuments({ language: filter });
      let output = `\n  KB Documents: ${docs.length}\n`;
      for (const d of docs.slice(0, 10)) {
        output += `    - [${d.language.toUpperCase()}] ${d.title} (${d.category})\n`;
      }
      if (docs.length > 10) output += `    ... and ${docs.length - 10} more\n`;
      return output;
    }

    return `[ERROR] Unknown: /kb ${action}. Try /kb help`;
  }
}

export const knowledgeBasePlugin = new KnowledgeBasePlugin();

import { Plugin, PluginContext, PluginManifest } from '../../core/plugin-system/types.js';
import { UniversalLlmClient } from '../../core/UniversalLlmClient.js';
import { logger, LogCategory } from '../../core/Logger.js';

export type ConsiliumMode = 'solo' | 'broadcast' | 'dialogue' | 'consilium';

export interface ConsiliumParticipant {
  id: string;
  name: string;
  model: string;
  systemPrompt?: string;
  temperature?: number;
}

export interface ConsiliumTurn {
  participantId: string;
  participantName: string;
  model: string;
  content: string;
  durationMs: number;
  tokens?: number;
}

export interface ConsiliumRunOptions {
  mode: ConsiliumMode;
  prompt: string;
  models: string[];
  rounds?: number;
  synthesizerModel?: string;
  systemInstruction?: string;
  useKnowledgeBase?: boolean;
  knowledgeBaseContext?: string;
  onProgress?: (event: { type: string; message?: string }) => void;
}

export interface ConsiliumResult {
  mode: ConsiliumMode;
  turns: ConsiliumTurn[];
  synthesis?: string;
  synthesizerModel?: string;
  durationMs: number;
  totalTokens?: number;
}

const MANIFEST: PluginManifest = {
  id: 'consilium',
  name: 'Consilium Multi-Agent Engine',
  version: '1.0.0',
  description: 'Multi-agent deliberation with 4 modes: solo, broadcast, dialogue, consilium',
  author: 'EvaBot Engineering',
  enabled: true,
  category: 'ai',
};

export class ConsiliumPlugin implements Plugin {
  public readonly manifest = MANIFEST;
  public readonly routes: Array<{ method: string; path: string; handler: (body: any, query: any) => Promise<any> }> = [];
  public readonly commands: Array<{ cmd: string; handler: (args: string) => Promise<string>; help?: string }> = [];

  private context?: PluginContext;
  private client: UniversalLlmClient;

  constructor(apiKey?: string) {
    this.client = new UniversalLlmClient(apiKey);
  }

  public async initialize(context: PluginContext): Promise<void> {
    this.context = context;

    this.routes.push({
      method: 'POST',
      path: '/api/consilium',
      handler: async (body: any) => {
        const result = await this.run({
          mode: body.mode || 'consilium',
          prompt: body.prompt,
          models: body.models || [],
          rounds: body.rounds,
          synthesizerModel: body.synthesizerModel,
          systemInstruction: body.systemInstruction,
          useKnowledgeBase: body.useKnowledgeBase,
          knowledgeBaseContext: body.knowledgeBaseContext,
        });
        return { success: true, result };
      },
    });

    this.commands.push({
      cmd: '/consilium',
      handler: async (args: string) => this.handleCommand(args),
      help: 'Multi-agent deliberation. Usage: /consilium <mode> <prompt>',
    });

    this.commands.push({
      cmd: '/dialogue',
      handler: async (args: string) => this.handleCommand('dialogue ' + args),
      help: 'Two-model debate. Usage: /dialogue <prompt>',
    });

    this.commands.push({
      cmd: '/broadcast',
      handler: async (args: string) => this.handleCommand('broadcast ' + args),
      help: 'Broadcast to multiple models. Usage: /broadcast <prompt>',
    });

    logger.info(LogCategory.LLM, 'Consilium', 'Plugin initialized');
  }

  public async shutdown(): Promise<void> {
    logger.info(LogCategory.LLM, 'Consilium', 'Plugin shut down');
  }

  public async healthCheck() {
    return { status: 'healthy' as const, message: 'Consilium ready' };
  }

  public async run(options: ConsiliumRunOptions): Promise<ConsiliumResult> {
    const start = Date.now();
    const emit = (type: string, message?: string) => {
      options.onProgress?.({ type, message });
    };

    emit('start', `Mode: ${options.mode}, models: ${options.models.length}`);

    let result: ConsiliumResult;
    switch (options.mode) {
      case 'solo':
        result = await this.runSolo(options, start, emit);
        break;
      case 'broadcast':
        result = await this.runBroadcast(options, start, emit);
        break;
      case 'dialogue':
        result = await this.runDialogue(options, start, emit);
        break;
      case 'consilium':
        result = await this.runConsilium(options, start, emit);
        break;
      default:
        throw new Error(`Unknown mode: ${options.mode}`);
    }

    result.durationMs = Date.now() - start;
    emit('complete', `Duration: ${result.durationMs}ms`);
    return result;
  }

  private async runSolo(options: ConsiliumRunOptions, start: number, emit: (t: string, m?: string) => void): Promise<ConsiliumResult> {
    const model = options.models[0] || 'gemini-2.5-flash';
    const turnStart = Date.now();
    const response = await this.client.generateContent(model, options.prompt, {
      systemInstruction: options.systemInstruction,
    });
    const turn: ConsiliumTurn = {
      participantId: 'solo',
      participantName: 'Solo',
      model,
      content: response,
      durationMs: Date.now() - turnStart,
    };
    return {
      mode: 'solo',
      turns: [turn],
      synthesis: response,
      synthesizerModel: model,
      durationMs: 0,
    };
  }

  private async runBroadcast(options: ConsiliumRunOptions, start: number, emit: (t: string, m?: string) => void): Promise<ConsiliumResult> {
    const turns: ConsiliumTurn[] = [];
    const results = await Promise.all(
      options.models.map(async (model) => {
        const turnStart = Date.now();
        try {
          const content = await this.client.generateContent(model, options.prompt, {
            systemInstruction: options.systemInstruction,
          });
          return {
            participantId: model,
            participantName: model,
            model,
            content,
            durationMs: Date.now() - turnStart,
          };
        } catch (err: any) {
          return {
            participantId: model,
            participantName: model,
            model,
            content: `[ERROR] ${err.message}`,
            durationMs: Date.now() - turnStart,
          };
        }
      })
    );
    turns.push(...results);
    const synthesis = await this.synthesize(options, results.map(r => `${r.participantName}: ${r.content}`).join('\n\n'));
    return {
      mode: 'broadcast',
      turns,
      synthesis,
      synthesizerModel: options.synthesizerModel || options.models[0],
      durationMs: 0,
    };
  }

  private async runDialogue(options: ConsiliumRunOptions, start: number, emit: (t: string, m?: string) => void): Promise<ConsiliumResult> {
    const modelA = options.models[0] || 'gemini-2.5-flash';
    const modelB = options.models[1] || 'gemini-1.5-flash';
    const turns: ConsiliumTurn[] = [];
    const maxRounds = Math.min(options.rounds || 2, 5);

    let currentPrompt = options.prompt;
    for (let round = 0; round < maxRounds; round++) {
      emit('dialogue-round', `Round ${round + 1}/${maxRounds}: ${modelA}`);
      const turnAStart = Date.now();
      const responseA = await this.client.generateContent(modelA, currentPrompt, {
        systemInstruction: options.systemInstruction,
      });
      turns.push({
        participantId: `${modelA}-r${round}`,
        participantName: `${modelA} (R${round + 1})`,
        model: modelA,
        content: responseA,
        durationMs: Date.now() - turnAStart,
      });

      emit('dialogue-round', `Round ${round + 1}/${maxRounds}: ${modelB}`);
      const turnBStart = Date.now();
      const responseB = await this.client.generateContent(modelB, responseA, {
        systemInstruction: `You are responding to this message. Be concise and direct.`,
      });
      turns.push({
        participantId: `${modelB}-r${round}`,
        participantName: `${modelB} (R${round + 1})`,
        model: modelB,
        content: responseB,
        durationMs: Date.now() - turnBStart,
      });

      currentPrompt = responseB;
    }

    const synthesis = await this.synthesize(
      options,
      turns.map(t => `${t.participantName}: ${t.content}`).join('\n\n')
    );
    return {
      mode: 'dialogue',
      turns,
      synthesis,
      synthesizerModel: options.synthesizerModel || modelA,
      durationMs: 0,
    };
  }

  private async runConsilium(options: ConsiliumRunOptions, start: number, emit: (t: string, m?: string) => void): Promise<ConsiliumResult> {
    const turns: ConsiliumTurn[] = [];

    emit('round1', `Collecting opinions from ${options.models.length} models`);
    const initialResults = await Promise.all(
      options.models.map(async (model) => {
        const turnStart = Date.now();
        try {
          const content = await this.client.generateContent(model, options.prompt, {
            systemInstruction: options.systemInstruction,
          });
          return {
            participantId: model,
            participantName: model,
            model,
            content,
            durationMs: Date.now() - turnStart,
          };
        } catch (err: any) {
          return {
            participantId: model,
            participantName: model,
            model,
            content: `[ERROR] ${err.message}`,
            durationMs: Date.now() - turnStart,
          };
        }
      })
    );
    turns.push(...initialResults);

    const validResults = initialResults.filter(r => !r.content.startsWith('[ERROR]'));
    if (validResults.length < 2) {
      const synthesis = await this.synthesize(options, validResults.map(r => r.content).join('\n\n'));
      return {
        mode: 'consilium',
        turns,
        synthesis,
        synthesizerModel: options.synthesizerModel || options.models[0],
        durationMs: 0,
      };
    }

    emit('round2', 'Cross-evaluation');
    const crossResults: ConsiliumTurn[] = [];
    for (const reviewer of validResults) {
      const others = validResults.filter(r => r.participantId !== reviewer.participantId);
      const reviewPrompt = `Original question: ${options.prompt}\n\nOther responses:\n${others.map(r => `[${r.participantName}]: ${r.content}`).join('\n\n')}\n\nProvide a brief critical evaluation (1-2 sentences).`;
      const turnStart = Date.now();
      try {
        const review = await this.client.generateContent(reviewer.model, reviewPrompt, {
          systemInstruction: 'You are a critical reviewer. Be concise and direct.',
        });
        crossResults.push({
          participantId: `${reviewer.model}-review`,
          participantName: `${reviewer.model} (Review)`,
          model: reviewer.model,
          content: review,
          durationMs: Date.now() - turnStart,
        });
      } catch (err: any) {
        crossResults.push({
          participantId: `${reviewer.model}-review`,
          participantName: `${reviewer.model} (Review)`,
          model: reviewer.model,
          content: `[ERROR] ${err.message}`,
          durationMs: Date.now() - turnStart,
        });
      }
    }
    turns.push(...crossResults);

    emit('synthesis', 'Generating final consensus');
    const allContent = turns.map(t => `${t.participantName}: ${t.content}`).join('\n\n');
    const synthesis = await this.synthesize(options, allContent);

    return {
      mode: 'consilium',
      turns,
      synthesis,
      synthesizerModel: options.synthesizerModel || options.models[0],
      durationMs: 0,
    };
  }

  private async synthesize(options: ConsiliumRunOptions, content: string): Promise<string> {
    const synthModel = options.synthesizerModel || options.models[0] || 'gemini-2.5-flash';
    const synthPrompt = `You are the consensus arbiter. Synthesize the following deliberation into a concise, actionable final answer (2-3 paragraphs max). Be specific and decisive.\n\nDeliberation:\n${content}\n\nFinal consensus:`;
    return await this.client.generateContent(synthModel, synthPrompt, {
      systemInstruction: 'You synthesize deliberations into clear, actionable conclusions.',
    });
  }

  public async handleCommand(args: string): Promise<string> {
    const parts = args.trim().split(/\s+/);
    const mode = parts[0] as ConsiliumMode;
    const prompt = parts.slice(1).join(' ');

    if (!['solo', 'broadcast', 'dialogue', 'consilium'].includes(mode)) {
      return 'Usage: /consilium <solo|broadcast|dialogue|consilium> <prompt>';
    }
    if (!prompt) {
      return 'Usage: /consilium <mode> <prompt>';
    }

    const result = await this.run({
      mode,
      prompt,
      models: ['gemini-2.5-flash', 'gemini-2.0-flash', 'gemini-1.5-flash'],
    });

    let output = `\n=== Consilium [${mode.toUpperCase()}] ===\n`;
    for (const turn of result.turns) {
      output += `\n[${turn.participantName}]\n${turn.content}\n`;
    }
    if (result.synthesis) {
      output += `\n=== SYNTHESIS ===\n${result.synthesis}\n`;
    }
    return output;
  }
}

