    lines.push(`  STT usage        : ${sttUsed.toLocaleString('en-US')} / ${STT_MONTHLY_CAP_SECONDS.toLocaleString('en-US')} сек/міс (${sttUsage.month})`);
    lines.push(`  Translate usage  : ${trUsage.chars.toLocaleString('en-US')} / ${TRANSLATE_FREE_TIER_CHARS.toLocaleString('en-US')} симв/міс (${trUsage.month})`);
    lines.push(`  Autocorrect      : клієнтський перемикач (/autocorrect on|off у веб-UI)`);
    lines.push(`  Emoji mode       : клієнтський перемикач (/emoji on|off; за замовчуванням OFF — емодзі вирізаються)`);
    lines.push(`  Developer mode   : ${devStatus}`);
    lines.push(`  Session id       : ${session}`);
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }

  /**
   * /agents (aliases: /агенти, /рота, /роли-агентів) — two-section agent
   * roster: 18 corporate roles (CORPORATE_ROLES) + 10 Sephirot Tree-of-Life
   * nodes (SEPHIROT_ROLES). Adam/Eva personas are marked explicitly.
   */
  private static handleAgents(): string {
    const corporate = Object.values(CORPORATE_ROLES);
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push('  РОСТЕР АГЕНТІВ (/agents) — КОРПОРАЦІЯ + СЕФІРОТ');
    lines.push('═'.repeat(78));

    lines.push(`  [CORPORATE] ШІ-корпорація — ${corporate.length} ролей:`);
    let i = 1;
    for (const role of corporate) {
      const persona = /Adam/i.test(role.name) ? ' [ADAM]' : /Eva/i.test(role.name) ? ' [EVA]' : '';
      lines.push(`   ${String(i).padStart(2)}. ${role.id.padEnd(18)} ${role.name} | модель: ${role.preferredModel}${persona}`);
      i++;
    }

    lines.push('');
    lines.push(`  [SEPHIROT] Дерево Життя — ${SEPHIROT_ROLES.length} вузлів (консиліум):`);
    let j = 1;
    for (const node of SEPHIROT_ROLES) {
      const persona = node.voicePersona === 'neutral' ? '' : ` [${node.voicePersona.toUpperCase()}]`;
      lines.push(`   ${String(j).padStart(2)}. ${node.sephira} | ${node.nameEn} — ${node.title} | модель: ${node.model}${persona}`);
      j++;
    }

    lines.push('─'.repeat(78));
    lines.push(`  Всього: ${corporate.length} корпоративних ролей + ${SEPHIROT_ROLES.length} вузлів Сефірот = ${corporate.length + SEPHIROT_ROLES.length} агентів.`);
    lines.push('  Персони озвучки: [EVA] — голос Єви, [ADAM] — голос Адама, решта neutral.');
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }

  private static handleInfo(args: string[]): string {
    const query = args[0]?.toLowerCase();
    if (!query) {
      return `Использование: /info <model_id> (напр. /info gemini-3.8-flash или /info claude-3-7-sonnet)`;
    }

    const model = ModelRegistry.getAllModels().find(
      (m) => m.id.toLowerCase() === query || m.name.toLowerCase().includes(query) || m.id.toLowerCase().includes(query)
    );

    if (!model) {
      return `[ERROR] Модель "${query}" не найдена в каталоге 78 моделей. Используйте /models для поиска.`;
    }

    const rating = ModelRatings.computeRating(model);
    const isFree = model.pricing.freeTierStatus === '100% Free Quota Available';
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push(`  ТЕХНИЧЕСКИЙ ПАСПОРТ МОДЕЛИ: ${model.name.toUpperCase()}`);
    lines.push('═'.repeat(78));
    lines.push(`  ID модели        : ${model.id}`);
    lines.push(`  Провайдер        : ${model.provider} [Категория: ${model.category}]`);
    lines.push(`  Протокол вызова  : ${model.protocol} │ Рекомендовано: ${model.recommended ? 'ДА' : 'НЕТ'}`);
    lines.push(`  Тарифный статус  : ${isFree ? '100% FREE QUOTA' : 'PAID / COMMERCIAL'}`);
    lines.push('─'.repeat(78));
    lines.push(`  Контекстное окно : ${model.contextWindow.toLocaleString()} токенов (~${(model.contextWindow / 1000).toFixed(0)}k)`);
    lines.push(`  Макс. ответ      : ${model.maxOutputTokens.toLocaleString()} токенов`);
    lines.push('─'.repeat(78));
    lines.push(`  СТОИМОСТЬ ТОКЕНОВ:`);
    lines.push(`    • Входящие     : ${model.pricing.inputPer1MTokensUSD} (${model.pricing.inputPer1MTokensEUR})`);
    lines.push(`    • Исходящие    : ${model.pricing.outputPer1MTokensUSD} (${model.pricing.outputPer1MTokensEUR})`);
    lines.push(`    • Квоты / Лимит: ${model.pricing.freeTierDetails}`);
    lines.push('─'.repeat(78));
    lines.push(`  РЕЙТИНГ И БЕНЧМАРКИ (Оценка системы: ${rating.composite}/100):`);
    lines.push(`    • Интеллект / Кодинг : ${rating.quality}/100`);
    lines.push(`    • Новизна (2026 fleet): ${rating.recency}/100`);
    lines.push(`    • Скорость генерации : ${rating.speed}/100`);
    lines.push(`    • Емкость контекста  : ${rating.context}/100`);
    lines.push(`    • Экономичность      : ${rating.cost}/100`);
    lines.push('─'.repeat(78));
    lines.push(`  ОПИСАНИЕ:`);
    lines.push(`    ${model.description}`);
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }
}

import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { logger, LogCategory } from './Logger.js';

export interface ChatHistoryRecord {
  id: number;
  sessionId: string;
  ts: number;
  role: string;
  content: string;
  model: string;
  lang: string;
}

export interface ChatHistoryCounts {
  totalMessages: number;
  sessions: number;
}

export interface ChatSearchHit extends ChatHistoryRecord {
  rank: number;
}

export const DEFAULT_CHAT_HISTORY_DB_PATH = '/var/www/evabot-backend/data/chat-history.db';
export const CONSILIUM_SESSION_ID = 'consilium';

export class ChatHistoryStore {
  private static instances: Map<string, ChatHistoryStore> = new Map();
  private db: DatabaseSync;
  private dbPath: string;
  private ready: boolean = false;

  private constructor(dbPath: string) {
    this.dbPath = dbPath;
    try {
      fs.mkdirSync(path.dirname(dbPath), { recursive: true });
      this.db = new DatabaseSync(dbPath);
      this.migrate();
      this.ready = true;
      logger.info(LogCategory.STORAGE, 'CHAT_DB', `Chat history SQLite store ready at ${dbPath}`);
    } catch (err: any) {
      this.db = null as any;
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `Chat history store unavailable: ${err.message}`);
    }
  }

  public static getInstance(dbPath?: string): ChatHistoryStore {
    const resolved = dbPath || process.env.EVABOT_CHAT_DB || DEFAULT_CHAT_HISTORY_DB_PATH;
    if (!ChatHistoryStore.instances.has(resolved)) {
      ChatHistoryStore.instances.set(resolved, new ChatHistoryStore(resolved));
    }
    return ChatHistoryStore.instances.get(resolved)!;
  }

  public isReady(): boolean {
    return this.ready;
  }

  public getPath(): string {
    return this.dbPath;
  }

  private ensureSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id TEXT,
        ts INTEGER,
        role TEXT,
        content TEXT,
        model TEXT,
        lang TEXT
      );
      CREATE INDEX IF NOT EXISTS idx_messages_session_id ON messages(session_id);
      CREATE INDEX IF NOT EXISTS idx_messages_ts ON messages(ts);
      CREATE VIRTUAL TABLE IF NOT EXISTS messages_fts USING fts5(content, content='messages', content_rowid='id');
      CREATE TRIGGER IF NOT EXISTS messages_fts_insert AFTER INSERT ON messages BEGIN
        INSERT INTO messages_fts(rowid, content) VALUES (new.id, new.content);
      END;
      CREATE TRIGGER IF NOT EXISTS messages_fts_delete AFTER DELETE ON messages BEGIN
        INSERT INTO messages_fts(messages_fts, rowid, content) VALUES ('delete', old.id, old.content);
      END;
      CREATE TRIGGER IF NOT EXISTS messages_fts_update AFTER UPDATE ON messages BEGIN
        INSERT INTO messages_fts(messages_fts, rowid, content) VALUES ('delete', old.id, old.content);
        INSERT INTO messages_fts(rowid, content) VALUES (new.id, new.content);
      END;
      CREATE TABLE IF NOT EXISTS session_state (
        session_id TEXT PRIMARY KEY,
        auto_enabled INTEGER NOT NULL DEFAULT 0,
        last_model TEXT,
        updated_ts INTEGER
      );
    `);
  }

  private migrate(): void {
    this.ensureSchema();
  }

  /**
   * Persists one chat message. Fire-and-forget safe: never throws to callers.
   */
  public appendMessage(msg: { sessionId: string; role: string; content: string; model?: string; lang?: string; ts?: number }): number | null {
    if (!this.ready || !this.db) return null;
    try {
      const stmt = this.db.prepare(
        'INSERT INTO messages (session_id, ts, role, content, model, lang) VALUES (?, ?, ?, ?, ?, ?)'
      );
      const result = stmt.run(
        msg.sessionId || 'default',
        msg.ts ?? Date.now(),
        msg.role,
        msg.content || '',
        msg.model || '',
        msg.lang || ''
      );
      return Number(result.lastInsertRowid);
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `appendMessage failed: ${err.message}`);
      return null;
    }
  }

  public getSessionHistory(sessionId: string, limit: number = 50): ChatHistoryRecord[] {
    if (!this.ready || !this.db) return [];
    try {
      const rows = this.db
        .prepare(
          `SELECT id, session_id, ts, role, content, model, lang
           FROM messages WHERE session_id = ?
           ORDER BY id DESC LIMIT ?`
        )
        .all(sessionId, limit) as any[];
      return rows
        .reverse()
        .map(this.mapRow);
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `getSessionHistory failed: ${err.message}`);
      return [];
    }
  }

  /**
   * Last N messages across ALL sessions (newest first for listing convenience is reversed to chronological).
   */
  public getRecentMessages(limit: number = 20): ChatHistoryRecord[] {
    if (!this.ready || !this.db) return [];
    try {
      const rows = this.db
        .prepare(
          `SELECT id, session_id, ts, role, content, model, lang
           FROM messages ORDER BY id DESC LIMIT ?`
        )
        .all(limit) as any[];
      return rows.reverse().map(this.mapRow);
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `getRecentMessages failed: ${err.message}`);
      return [];
    }
  }

  /**
   * Full-text search across message content using the FTS5 index.
   */
  public searchMessages(query: string, limit: number = 10): ChatSearchHit[] {
    if (!this.ready || !this.db || !query) return [];
    try {
      const cleanTokens = query
        .replace(/[^\p{L}\p{N}\s]/gu, ' ')
        .split(/\s+/)
        .filter((t) => t.length > 2);
      if (cleanTokens.length === 0) return [];
      const ftsQuery = cleanTokens.map((t) => `"${t}"*`).join(' OR ');
      const rows = this.db
        .prepare(
          `SELECT m.id, m.session_id, m.ts, m.role, m.content, m.model, m.lang, rank
           FROM messages_fts f
           JOIN messages m ON m.id = f.rowid
           WHERE messages_fts MATCH ?
           ORDER BY rank
           LIMIT ?`
        )
        .all(ftsQuery, limit) as any[];
      return rows.map((row) => ({
        ...this.mapRow(row),
        rank: Number(row.rank) || 0,
      }));
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `searchMessages failed: ${err.message}`);
      return [];
    }
  }

  public listSessions(limit: number = 20): Array<{ sessionId: string; messages: number; firstTs: number; lastTs: number }> {
    if (!this.ready || !this.db) return [];
    try {
      const rows = this.db
        .prepare(
          `SELECT session_id,
                  COUNT(*) as messages,
                  MIN(ts) as firstTs,
                  MAX(ts) as lastTs
           FROM messages
           GROUP BY session_id
           ORDER BY MAX(ts) DESC
           LIMIT ?`
        )
        .all(limit) as any[];
      return rows.map((r) => ({
        sessionId: String(r.session_id),
        messages: Number(r.messages),
        firstTs: Number(r.firstTs),
        lastTs: Number(r.lastTs),
      }));
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `listSessions failed: ${err.message}`);
      return [];
    }
  }

  public countAll(): { totalMessages: number; sessions: number } {
    if (!this.ready || !this.db) return { totalMessages: 0, sessions: 0 };
    try {
      const msgRow = this.db.prepare('SELECT COUNT(*) as count FROM messages').get() as any;
      const sessRow = this.db
        .prepare('SELECT COUNT(DISTINCT session_id) as count FROM messages')
        .get() as any;
      return {
        totalMessages: Number(msgRow?.count) || 0,
        sessions: Number(sessRow?.count) || 0,
      };
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `countAll failed: ${err.message}`);
      return { totalMessages: 0, sessions: 0 };
    }
  }

  /**
   * Per-session UI state (TASK-333): /auto flag + last used model.
   * Survives restarts. Never throws to callers.
   */
  public getSessionState(sessionId: string): { autoEnabled: boolean; lastModel: string | null } {
    const fallback = { autoEnabled: false, lastModel: null };
    if (!this.ready || !this.db) return fallback;
    try {
      const row = this.db
        .prepare('SELECT auto_enabled, last_model FROM session_state WHERE session_id = ?')
        .get(sessionId) as any;
      if (!row) return fallback;
      return {
        autoEnabled: Number(row.auto_enabled) === 1,
        lastModel: row.last_model != null ? String(row.last_model) : null,
      };
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `getSessionState failed: ${err.message}`);
      return fallback;
    }
  }

  public setSessionAuto(sessionId: string, enabled: boolean): void {
    if (!this.ready || !this.db) return;
    try {
      this.db
        .prepare(
          `INSERT INTO session_state (session_id, auto_enabled, last_model, updated_ts)
           VALUES (?, ?, NULL, ?)
           ON CONFLICT(session_id) DO UPDATE SET auto_enabled = excluded.auto_enabled, updated_ts = excluded.updated_ts`
        )
        .run(sessionId, enabled ? 1 : 0, Date.now());
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `setSessionAuto failed: ${err.message}`);
    }
  }

  public setSessionLastModel(sessionId: string, model: string): void {
    if (!this.ready || !this.db) return;
    try {
      this.db
        .prepare(
          `INSERT INTO session_state (session_id, auto_enabled, last_model, updated_ts)
           VALUES (?, 0, ?, ?)
           ON CONFLICT(session_id) DO UPDATE SET last_model = excluded.last_model, updated_ts = excluded.updated_ts`
        )
        .run(sessionId, model, Date.now());
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `setSessionLastModel failed: ${err.message}`);
    }
  }

  /** Test/maintenance helper: removes a session_state row. Never throws. */
  public deleteSessionState(sessionId: string): void {
    if (!this.ready || !this.db) return;
    try {
      this.db.prepare('DELETE FROM session_state WHERE session_id = ?').run(sessionId);
    } catch (err: any) {
      logger.warn(LogCategory.STORAGE, 'CHAT_DB', `deleteSessionState failed: ${err.message}`);
    }
  }

  private mapRow(row: any): ChatHistoryRecord {
    return {
      id: Number(row.id),
      sessionId: String(row.session_id ?? ''),
      ts: Number(row.ts ?? 0),
      role: String(row.role ?? ''),
      content: String(row.content ?? ''),
      model: String(row.model ?? ''),
      lang: String(row.lang ?? ''),
    };
  }

  public close(): void {
    if (this.db) {
      try {
        this.db.close();
      } catch (err: any) {
        logger.warn(LogCategory.STORAGE, 'CHAT_DB', `close failed: ${err.message}`);
      }
      this.ready = false;
    }
  }
}

/**
 * ProductCatalog — EvaLine company product database (pure core module).
 *
 * Loads data/products.json (extracted from knowledge-base/evaline-com-ua/site/**)
 * and provides read-only access + localized text-table formatting.
 *
 * Module independence: imports NOTHING from server code — only node built-ins.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export type CatalogLang = 'en' | 'uk' | 'ru';

export interface Product {
  id: string;
  sku?: string | null;
  name: { en: string; uk: string; ru: string };
  category: string;
  sizes: string[];
  thickness?: string;
  colors: string[];
  materials?: string;
  certifications: string[];
  markets: string[];
  notes: string;
}

export interface CatalogData {
  updatedAt: string;
  source: string;
  languages: string[];
  products: Product[];
}

export interface CatalogStats {
  total: number;
  updatedAt: string;
  byCategory: Record<string, number>;
}

const LABELS: Record<CatalogLang, Record<string, string>> = {
  en: {
    title: 'EVALINE PRODUCT CATALOG',
    products: 'Products',
    updated: 'DB updated',
    byCategory: 'By category',
    filter: 'Filter',
    matches: 'matches',
    noMatch: 'No products match the query.',
    usage: 'Usage: /products [category|query]',
    categories: 'Categories',
    details: 'Product details',
    sizes: 'Sizes',
    thickness: 'Thickness',
    colors: 'Colors',
    materials: 'Materials',
    certs: 'Certificates',
    markets: 'Markets',
    notes: 'Notes',
    na: 'N/A',
  },
  uk: {
    title: 'КАТАЛОГ ПРОДУКЦІЇ EVALINE',
    products: 'Товарів',
    updated: 'БД оновлено',
    byCategory: 'За категоріями',
    filter: 'Фільтр',
    matches: 'збігів',
    noMatch: 'За запитом товарів не знайдено.',
    usage: 'Використання: /products [категорія|запит]',
    categories: 'Категорії',
    details: 'Деталі товару',
    sizes: 'Розміри',
    thickness: 'Товщина',
    colors: 'Кольори',
    materials: 'Матеріали',
    certs: 'Сертифікати',
    markets: 'Ринки',
    notes: 'Примітки',
    na: 'N/A',
  },
  ru: {
    title: 'КАТАЛОГ ПРОДУКЦИИ EVALINE',
    products: 'Товаров',
    updated: 'БД обновлена',
    byCategory: 'По категориям',
    filter: 'Фильтр',
    matches: 'совпадений',
    noMatch: 'По запросу товары не найдены.',
    usage: 'Использование: /products [категория|запрос]',
    categories: 'Категории',
    details: 'Детали товара',
    sizes: 'Размеры',
    thickness: 'Толщина',
    colors: 'Цвета',
    materials: 'Материалы',
    certs: 'Сертификаты',
    markets: 'Рынки',
    notes: 'Примечания',
    na: 'N/A',
  },
};

function resolveDataPath(): string {
  // Candidate locations, in priority order (covers src/, dist/ and cwd layouts).
  const here = path.dirname(fileURLToPath(import.meta.url));
  return (
    [
      path.resolve(here, '../../data/products.json'),
      path.resolve(here, '../../../data/products.json'),
      path.resolve(process.cwd(), 'data/products.json'),
    ].find((p) => fs.existsSync(p)) || path.resolve(here, '../../data/products.json')
  );
}

let cache: CatalogData | null = null;

function load(): CatalogData {
  if (cache) return cache;
  try {
    cache = JSON.parse(fs.readFileSync(resolveDataPath(), 'utf8')) as CatalogData;
  } catch (err: any) {
    cache = { updatedAt: 'N/A', source: 'unavailable', languages: [], products: [] };
  }
  return cache!;
}

function normName(p: Product, lang: CatalogLang): string {
  return p.name[lang] || p.name.en;
}

function listOrNa(values: string[] | undefined, na: string): string {
  return values && values.length ? values.join(', ') : na;
}

export class ProductCatalog {
  /** Full product list. */
  public static getProducts(): Product[] {
    return load().products;
  }

  /** Products of one category (case-insensitive, prefix match allowed). */
  public static byCategory(category: string): Product[] {
    const want = (category || '').toLowerCase().trim();
    return load().products.filter(
      (p) => p.category.toLowerCase() === want || p.category.toLowerCase().startsWith(want)
    );
  }

  /** Free-text search over names (en/uk/ru), category, sizes, colors, materials, certificates, markets, notes. */
  public static search(query: string): Product[] {
    const q = (query || '').toLowerCase().trim();
    if (!q) return this.getProducts();
    return load().products.filter((p) => {
      const haystack = [
        p.name.en, p.name.uk, p.name.ru, p.category,
        p.sizes.join(' '), p.thickness || '', p.colors.join(' '),
        p.materials || '', p.certifications.join(' '), p.markets.join(' '), p.notes,
      ].join(' ').toLowerCase();
      return haystack.includes(q);
    });
  }

  /** Count statistics per category. */
  public static stats(): CatalogStats {
    const data = load();
    const byCategory: Record<string, number> = {};
    for (const p of data.products) {
      byCategory[p.category] = (byCategory[p.category] || 0) + 1;
    }
    return { total: data.products.length, updatedAt: data.updatedAt, byCategory };
  }

  /** Sorted list of category slugs. */
  public static getCategories(): string[] {
    return Object.keys(this.stats().byCategory).sort();
  }

  /** Default output: stats + category list (used by /products with no args). */
  public static formatStats(lang: CatalogLang = 'en'): string {
    const s = LABELS[lang] || LABELS.en;
    const st = this.stats();
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push(`  [PROD] ${s.title}`);
    lines.push('═'.repeat(78));
    lines.push(`  ${s.products}: ${st.total}   |   ${s.updated}: ${st.updatedAt}`);
    lines.push('─'.repeat(78));
    lines.push(`  ${s.byCategory}:`);
    for (const cat of Object.keys(st.byCategory).sort()) {
      lines.push(`    • ${cat.padEnd(16)} : ${st.byCategory[cat]}`);
    }
    lines.push('─'.repeat(78));
    lines.push(`  ${s.usage}`);
    lines.push(`  ${s.categories}: ${this.getCategories().join(', ')}`);
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }

  /** Filtered output: category name or free-text query (used by /products <arg>). */
  public static formatFiltered(query: string, lang: CatalogLang = 'en'): string {
    const s = LABELS[lang] || LABELS.en;
    const byCat = this.byCategory(query);
    const products = byCat.length > 0 ? byCat : this.search(query);
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push(`  [PROD] ${s.title} — ${s.filter}: "${query}" (${products.length} ${s.matches})`);
    lines.push('═'.repeat(78));
    if (products.length === 0) {
      lines.push(`  ${s.noMatch}`);
      lines.push('─'.repeat(78));
      lines.push(`  ${s.usage}`);
      lines.push(`  ${s.categories}: ${this.getCategories().join(', ')}`);
      lines.push('═'.repeat(78));
      return lines.join('\n');
    }
    for (const p of products) {
      this.appendProduct(lines, p, lang, false);
    }
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }

  /** Full localized catalog table. */
  public static formatCatalog(lang: CatalogLang = 'en'): string {
    const s = LABELS[lang] || LABELS.en;
    const products = this.getProducts();
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push(`  [PROD] ${s.title} (${products.length} ${s.products.toLowerCase()})`);
    lines.push('═'.repeat(78));
    for (const p of products) {
      this.appendProduct(lines, p, lang, true);
    }
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }

  private static appendProduct(lines: string[], p: Product, lang: CatalogLang, full: boolean): void {
    const s = LABELS[lang] || LABELS.en;
    const na = s.na;
    lines.push(`   [${p.category}] ${normName(p, lang)}`);
    if (full || p.sizes.length) lines.push(`      ${s.sizes.padEnd(12)}: ${listOrNa(p.sizes, na)}`);
    if (full || p.thickness) lines.push(`      ${s.thickness.padEnd(12)}: ${p.thickness || na}`);
    if (full || p.colors.length) lines.push(`      ${s.colors.padEnd(12)}: ${listOrNa(p.colors, na)}`);
    if (full) {
      lines.push(`      ${s.materials.padEnd(12)}: ${p.materials || na}`);
      lines.push(`      ${s.certs.padEnd(12)}: ${listOrNa(p.certifications, na)}`);
      lines.push(`      ${s.markets.padEnd(12)}: ${listOrNa(p.markets, na)}`);
    }
    lines.push(`      ${s.notes.padEnd(12)}: ${p.notes}`);
    lines.push('');
  }
}

/**
 * CompanyKnowledge — EvaLine corporate knowledge matrix (who knows what).
 *
 * Maps every corporate role (src/core/CorporateRoles.ts, real roleIds) to the
 * knowledge domains it must master, the on-disk data sources backing those
 * domains, and an info-exchange map (who exchanges what with whom).
 */
