import { transcribeVoiceWithFallback, type SttLanguage, type SttResult } from '../core/CloudSTT.js';
import { DeveloperMode } from '../core/DeveloperMode.js';
import { ChatEngine } from './ChatEngine.js';

export const TELEGRAM_MESSAGE_LIMIT = 4096;
const TELEGRAM_API_BASE = 'https://api.telegram.org';
const RATE_LIMIT_INTERVAL_MS = 1000;
const VOICE_PLACEHOLDER = '[WRN] Не вдалося завантажити голосове повідомлення. Спробуйте ще раз.';
const VOICE_PREFIX = ' Розпізнано:';

/** Async transcriber injected for tests; production default = Google CloudSTT with FLAC fallback. */
export type VoiceTranscriber = (audio: Buffer, lang: SttLanguage) => Promise<SttResult>;
const HISTORY_SESSION_PREFIX = 'tg-';

export interface TelegramCommandExecutor {
  (command: string): string;
}

/**
 * Splits an arbitrary text into chunks that each fit the Telegram sendMessage
 * hard limit (4096 UTF-16 code units per message). Prefers splitting on blank
 * lines, then newlines, then hard-cutting long unbroken lines.
 */
export function splitTelegramMessage(text: string, limit: number = TELEGRAM_MESSAGE_LIMIT): string[] {
  const clean = (text || '').trim();
  if (!clean) return [];
  if (clean.length <= limit) return [clean];

  const chunks: string[] = [];
  let remaining = clean;

  while (remaining.length > limit) {
    const window = remaining.slice(0, limit);

    let cut = window.lastIndexOf('\n\n');
    if (cut < Math.floor(limit * 0.25)) cut = window.lastIndexOf('\n');
    if (cut < Math.floor(limit * 0.25)) cut = window.lastIndexOf(' ');
    if (cut < Math.floor(limit * 0.25)) cut = limit;

    chunks.push(remaining.slice(0, cut).trimEnd());
    remaining = remaining.slice(cut).trimStart();
  }

  if (remaining) chunks.push(remaining);
  return chunks;
}

interface TelegramUser {
  id: number;
  is_bot?: boolean;
  first_name?: string;
  last_name?: string;
  username?: string;
  language_code?: string;
}

interface TelegramVoice {
  file_id: string;
  duration?: number;
  mime_type?: string;
  file_size?: number;
}

interface TelegramMessage {
  message_id: number;
  from?: TelegramUser;
  date: number;
  chat: { id: number; type: string; title?: string; username?: string };
  text?: string;
  voice?: TelegramVoice;
}

interface TelegramUpdate {
  update_id: number;
  message?: TelegramMessage;
}

interface TelegramApiResponse<T> {
  ok: boolean;
  result?: T;
  description?: string;
}

export class TelegramBot {
  private token: string;
  private apiBase: string;
  private chatEngine: ChatEngine;
  private execute: TelegramCommandExecutor;
  private transcriber: VoiceTranscriber;
  private chatLocales: Map<number, SupportedLocale> = new Map();
  private chatQueues: Map<number, Promise<void>> = new Map();
  private chatLastRun: Map<number, number> = new Map();
  private offset: number = 0;
  private running: boolean = false;

  constructor(options: { token?: string; apiBase?: string; execute?: TelegramCommandExecutor; transcriber?: VoiceTranscriber } = {}) {
    this.token = options.token || Config.telegramBotToken;
    this.apiBase = options.apiBase || TELEGRAM_API_BASE;
    this.execute = options.execute || ((command) => ModelCommand.execute(command));
    this.transcriber = options.transcriber || ((audio, lang) => transcribeVoiceWithFallback(audio, { lang }));
    this.chatEngine = new ChatEngine();
  }

  public static isEnabled(): boolean {
    return Boolean(Config.telegramBotToken);
  }

  public async start(): Promise<void> {
    if (!this.token) {
      logger.warn(LogCategory.SYSTEM, 'TelegramBot', 'Telegram bot disabled (no token)');
      return;
    }
    if (this.running) return;

    this.running = true;
    logger.info(LogCategory.SYSTEM, 'TelegramBot', 'Starting Telegram long-polling loop...');
    void this.pollLoop();
  }

  public stop(): void {
    this.running = false;
  }

  private async api<T>(method: string, payload?: Record<string, unknown>): Promise<T | undefined> {
    const res = await fetch(`${this.apiBase}/bot${this.token}/${method}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload || {}),
    });
    const data = (await res.json()) as TelegramApiResponse<T>;
    if (!data.ok) {
      throw new Error(`Telegram ${method} failed: ${data.description || 'unknown error'}`);
    }
    return data.result;
  }

  private async pollLoop(): Promise<void> {
    while (this.running) {
      try {
        const updates = await this.api<TelegramUpdate[]>('getUpdates', {
          offset: this.offset,
          timeout: 25,
          allowed_updates: ['message'],
        });
        for (const update of updates || []) {
          this.offset = update.update_id + 1;
          if (update.message) {
            void this.handleMessage(update.message);
          }
        }
      } catch (err: any) {
        if (!this.running) break;
        logger.warn(LogCategory.SYSTEM, 'TelegramBot', `Long-poll error: ${err.message}. Retrying in 5s...`);
        await this.sleep(5000);
      }
    }
  }

  private handleMessage(message: TelegramMessage): Promise<void> {
    return this.enqueueForChat(message.chat.id, () => this.processMessage(message));
  }

  /**
   * Rate limit: 1 message per second per chat. All work for a chat is chained
   * on a per-chat promise queue; each task starts at least RATE_LIMIT_INTERVAL_MS
   * after the previous task in the same chat started.
   */
  private async enqueueForChat(chatId: number, task: () => Promise<void>): Promise<void> {
    const previous = this.chatQueues.get(chatId) || Promise.resolve();
    const run = previous
      .then(async () => {
        const last = this.chatLastRun.get(chatId) || 0;
        const waitMs = Math.max(0, RATE_LIMIT_INTERVAL_MS - (Date.now() - last));
        if (waitMs > 0) await this.sleep(waitMs);
        this.chatLastRun.set(chatId, Date.now());
        await task();
      })
      .catch((err: any) => {
        logger.error(LogCategory.SYSTEM, 'TelegramBot', `Chat ${chatId} handler error: ${err.message}`);
      });

    this.chatQueues.set(chatId, run);
    try {
      await run;
    } finally {
      if (this.chatQueues.get(chatId) === run) this.chatQueues.delete(chatId);
    }
  }

  private async processMessage(message: TelegramMessage): Promise<void> {
    const chatId = message.chat.id;
    const from = message.from;

    if (message.voice) {
      await this.handleVoiceMessage(message);
      return;
    }

    const text = (message.text || '').trim();
    if (!text) return;

    if (!from || (!from.username && !from.first_name)) {
      await this.sendMessage(chatId, '[WRN] Please register a Telegram account (set a username or name) to chat with EvaBot.');
      return;
    }

    if (text.startsWith('/')) {
      await this.handleCommand(chatId, text);
      return;
    }

    await this.handleChatMessage(chatId, text);
  }

  private async handleCommand(chatId: number, raw: string): Promise<void> {
    const locale = this.getChatLocale(chatId);

    if (raw.startsWith('/start')) {
      const strings = I18nEngine.getStrings(locale);
      await this.sendMessage(chatId, `[BOT] ${strings.greeting}\n\n${I18nEngine.formatHelp(locale)}`);
      return;
    }

    const [head] = raw.split(/\s+/);
    const canonicalHead = normalizeCommand(head).split(/\s+/)[0];

    if (canonicalHead === '/lang') {
      const arg = raw.split(/\s+/)[1]?.toLowerCase() || '';
      const resolved: SupportedLocale = arg === 'uk' || arg === 'ua' ? 'uk' : arg === 'ru' ? 'ru' : 'en';
      this.chatLocales.set(chatId, resolved);
      const strings = I18nEngine.getStrings(resolved);
      await this.sendMessage(chatId, strings.langSwitched);
      return;
    }

    if (canonicalHead === '/models') {
      await this.sendMessage(chatId, this.execute('/models'));
      await this.sendModelsKeyboard(chatId);
      return;
    }

    // /subagent needs the async executor (parallel LLM batch, up to ~2 min).
    if (canonicalHead === '/subagent') {
      const output = await ModelCommand.executeAsync(normalizeCommand(raw));
      await this.sendMessage(chatId, output);
      return;
    }

    // /developer keeps the RAW command: normalizeCommand lowercases the whole
    // line, which would corrupt mixed-case passwords (DeveloperMode.parseCommand
    // does its own head-alias resolution).
    if (canonicalHead === '/developer') {
      const sessionId = `${HISTORY_SESSION_PREFIX}${chatId}`;
      DeveloperMode.setActiveSession(sessionId);
      const output = this.execute(raw);
      await this.sendMessage(chatId, output);
      return;
    }

    const commandText = normalizeCommand(raw);
    const output = this.execute(commandText);
    await this.sendMessage(chatId, output);
  }

  private async handleChatMessage(chatId: number, text: string): Promise<void> {
    const sessionId = `${HISTORY_SESSION_PREFIX}${chatId}`;
    const locale = this.getChatLocale(chatId);
    try {
      const response = await this.chatEngine.respond({ message: text, sessionId, locale });
      await this.sendMessage(chatId, response.text);
    } catch (err: any) {
      logger.error(LogCategory.SYSTEM, 'TelegramBot', `Chat error for ${sessionId}: ${err.message}`);
      await this.sendMessage(chatId, `[WRN] Chat engine error: ${err.message}`);
    }
  }

  /**
   * Voice messages (.ogg/opus, 48 kHz): download → Google CloudSTT (OGG_OPUS,
   * FLAC 16 kHz fallback inside transcribeVoiceWithFallback) → send transcript
   * as reply, then treat the transcript like typed text: '/…' runs as a
   * command, otherwise it flows into the normal chat engine.
   */
  private async handleVoiceMessage(message: TelegramMessage): Promise<void> {
    const chatId = message.chat.id;
    const from = message.from;
    const voice = message.voice;
    if (!voice) return;
    if (!from || (!from.username && !from.first_name)) {
      await this.sendMessage(chatId, '[WRN] Please register a Telegram account to send voice messages.');
      return;
    }

    let audio: Buffer | null = null;
    try {
      audio = await this.downloadVoiceFile(voice.file_id);
    } catch (err: any) {
      logger.warn(LogCategory.SYSTEM, 'TelegramBot', `Voice download failed: ${err.message}`);
    }
    if (!audio) {
      await this.sendMessage(chatId, VOICE_PLACEHOLDER);
      return;
    }

    const lang = localeToSttLang(this.getChatLocale(chatId));
    const result = await this.transcriber(audio, lang);
    if (!result.ok || !result.transcript) {
      logger.warn(LogCategory.SYSTEM, 'TelegramBot', `Voice transcription failed: ${result.error}`);
      await this.sendMessage(chatId, `[WRN] Не вдалося розпізнати голосове повідомлення${result.error ? ` (${result.error})` : ''}.`);
      return;
    }

    await this.sendMessage(chatId, `${VOICE_PREFIX} ${result.transcript}`);
    if (result.transcript.startsWith('/')) {
      await this.handleCommand(chatId, result.transcript);
    } else {
      await this.handleChatMessage(chatId, result.transcript);
    }
  }

  private async downloadVoiceFile(fileId: string): Promise<Buffer | null> {
    const file = await this.api<{ file_path?: string }>('getFile', { file_id: fileId });
    const filePath = file?.file_path;
    if (!filePath) return null;
    const res = await fetch(`${this.apiBase}/file/bot${this.token}/${filePath}`);
    const buf = Buffer.from(await res.arrayBuffer());
    logger.info(LogCategory.SYSTEM, 'TelegramBot', `Downloaded voice file ${filePath} (${buf.length} bytes)`);
    return buf.length > 0 ? buf : null;
  }

  public async sendModelsKeyboard(chatId: number): Promise<void> {
    const top8 = ModelRatings.getTopFree(8);
    const rows: string[][] = [];
    for (let i = 0; i < top8.length; i += 2) {
      rows.push(top8.slice(i, i + 2).map((e) => e.model.name));
    }
    await this.api('sendMessage', {
      chat_id: chatId,
      text: ' Top-8 free models — tap to inspect:',
      reply_markup: { keyboard: rows, resize_keyboard: true, one_time_keyboard: true },
    });
  }

  public getChatLocale(chatId: number): SupportedLocale {
    return this.chatLocales.get(chatId) || I18nEngine.getLocale();
  }

  public async sendMessage(chatId: number, text: string): Promise<void> {
    const chunks = splitTelegramMessage(text, TELEGRAM_MESSAGE_LIMIT);
    if (chunks.length === 0) return;
    for (const chunk of chunks) {
      await this.api('sendMessage', { chat_id: chatId, text: chunk, disable_web_page_preview: true });
    }
  }

  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

let singleton: TelegramBot | null = null;

/** Maps a chat locale to a Google STT language code. */
export function localeToSttLang(locale: SupportedLocale): SttLanguage {
  return locale === 'uk' ? 'uk-UA' : locale === 'ru' ? 'ru-RU' : 'en-US';
}

export function startTelegramBot(): void {
  if (!TelegramBot.isEnabled()) {
    logger.warn(LogCategory.SYSTEM, 'TelegramBot', 'Telegram bot disabled (no token)');
    return;
  }
  try {
    if (!singleton) singleton = new TelegramBot();
    void singleton.start();
    logger.info(LogCategory.SYSTEM, 'TelegramBot', 'Telegram bot started (long-polling)');
  } catch (err: any) {
    logger.error(LogCategory.SYSTEM, 'TelegramBot', `Failed to start Telegram bot: ${err.message}`);
  }
}

/**
 * Resilience.ts — Hang protection and provider fallback infrastructure.
 *
 * Provides:
 *  - withTimeout(): race a promise against a hard deadline so a hung provider
 *    call never blocks the brain forever.
 *  - CircuitBreaker: per-provider breaker (closed / open / half-open).
 *    Opens after `openThreshold` consecutive failures, stays open for
 *    `cooldownMs`, then allows a single half-open probe.
 *  - BREAKERS: static registry keyed by provider name (google, omniroute,
 *    openrouter, hf, zai, groq, cerebras, cloudflare, mistral, opencode).
 *  - ProviderFallbackChain: helpers to filter a candidate model chain by
 *    breaker health and render a text health report for the /health command.
 *
 * Design note: all state is in-process memory. After a process restart every
 * breaker resets to closed — acceptable for a single-node brain.
 */

import { logger } from './Logger.js';
import { OpLog } from './OpLog.js';

/** Default hard deadline for a single LLM provider call (45 s). */
export const LLM_CALL_TIMEOUT_MS = 45_000;

/**
 * Rejects if the wrapped promise does not settle within `ms` milliseconds.
 * The underlying promise is NOT cancelled (JS cannot cancel fetches without
 * an AbortSignal), but the caller stops waiting on it.
 */
export function withTimeout<T>(promise: Promise<T>, ms: number, label: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error(`[TIMEOUT] ${label} did not complete within ${ms}ms`));
    }, ms);

    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (err) => {
        clearTimeout(timer);
        reject(err);
      }
    );
  });
}

export type BreakerState = 'closed' | 'open' | 'half-open';

export interface BreakerSnapshot {
  provider: string;
  state: BreakerState;
  consecutiveFailures: number;
  lastError?: string;
  lastErrorTs?: number;
  lastOkTs?: number;
  openedAtTs?: number;
}

/** Global ring buffer of the last provider errors (for /health "last 5 errors"). */
const recentProviderErrors: ChainAttemptEvent[] = [];

export class CircuitBreaker {
  public readonly provider: string;
  public openThreshold: number = 3;
  public cooldownMs: number = 60_000;

  private state: BreakerState = 'closed';
  private consecutiveFailures = 0;
  private lastError?: string;
  private lastErrorTs?: number;
  private lastOkTs?: number;
  private openedAtTs?: number;

  constructor(provider: string) {
    this.provider = provider;
  }

  public getState(): BreakerState {
    // An open breaker whose cooldown has elapsed transitions to half-open so
    // the next canAttempt() call admits a single probe request.
    if (this.state === 'open' && Date.now() - (this.openedAtTs || 0) >= this.cooldownMs) {
      this.state = 'half-open';
      OpLog.getInstance().log('warn', 'breaker', `${this.provider} → half-open (cooldown elapsed, admitting probe)`);
    }
    return this.state;
  }

  /**
   * Whether a request may be attempted right now.
   *  - closed  → always yes
   *  - open    → no (until cooldown elapses, then half-open allows one probe)
   *  - half-open → yes, but only one probe in flight (state is flipped to
   *    'open' semantics by recordSuccess/recordFailure outcomes)
   */
  public canAttempt(): boolean {
    const st = this.getState();
    if (st === 'closed') return true;
    if (st === 'open') return false;
    // half-open: admit exactly one probe, then block until it resolves
    this.state = 'open';
    this.openedAtTs = Date.now() - this.cooldownMs; // will re-enter half-open check on next getState
    return true;
  }

  public recordSuccess(): void {
    const wasOpen = this.state !== 'closed';
    this.consecutiveFailures = 0;
    this.lastOkTs = Date.now();
    this.state = 'closed';
    this.openedAtTs = undefined;
    if (wasOpen) {
      OpLog.getInstance().log('warn', 'breaker', `${this.provider} → closed (probe succeeded)`);
    }
  }

  public recordFailure(err: Error | string): void {
    const msg = typeof err === 'string' ? err : err.message;
    this.consecutiveFailures += 1;
    this.lastError = msg;
    this.lastErrorTs = Date.now();

    if (this.state === 'half-open' || this.consecutiveFailures >= this.openThreshold) {
      this.state = 'open';
      this.openedAtTs = Date.now();
      OpLog.getInstance().log('warn', 'breaker', `${this.provider} → open (${this.consecutiveFailures} consecutive failures, cooldown ${this.cooldownMs / 1000}s)`);
      logger.warn('CircuitBreaker', `Provider "${this.provider}" breaker OPENED after ${this.consecutiveFailures} consecutive failures. Cooldown ${this.cooldownMs / 1000}s. Last error: ${msg}`);
    }
    recentProviderErrors.push({ model: '-', provider: this.provider, outcome: 'failed', error: msg, ts: Date.now() });
    if (recentProviderErrors.length > 20) recentProviderErrors.shift();
  }

  public snapshot(): BreakerSnapshot {
    const st = this.getState();
    const snap: BreakerSnapshot = {
      provider: this.provider,
      state: st,
      consecutiveFailures: this.consecutiveFailures,
    };
    if (this.lastError) snap.lastError = this.lastError;
    if (this.lastErrorTs) snap.lastErrorTs = this.lastErrorTs;
    if (this.lastOkTs) snap.lastOkTs = this.lastOkTs;
    if (this.openedAtTs) snap.openedAtTs = this.openedAtTs;
    return snap;
  }
}

/** Known provider fleet of the EvaBot cluster. */
export const BREAKER_PROVIDER_NAMES = [
  'google',
  'omniroute',
  'openrouter',
  'hf',
  'zai',
  'groq',
  'cerebras',
  'cloudflare',
  'mistral',
  'opencode',
] as const;

const breakers = new Map<string, CircuitBreaker>();

export function getBreaker(provider: string): CircuitBreaker {
  let b = breakers.get(provider);
  if (!b) {
    b = new CircuitBreaker(provider);
    breakers.set(provider, b);
  }
  return b;
}

/** Static registry keyed by provider name (lazily populated for all known names). */
export const BREAKERS: Record<string, CircuitBreaker> = Object.fromEntries(
  BREAKER_PROVIDER_NAMES.map((p) => [p, getBreaker(p)])
);

/** Maps a model id to its logical provider/breaker key. */
export function providerOfModel(model: string): string {
  const m = model.toLowerCase();
  if (m.startsWith('omniroute/') || m.startsWith('omni/')) return 'omniroute';
  if (m.startsWith('opencode/')) return 'opencode';
  if (m.startsWith('hf/')) return 'hf';
  if (m.startsWith('zai/')) return 'zai';
  if (m.startsWith('groq/')) return 'groq';
  if (m.startsWith('cerebras/')) return 'cerebras';
  if (m.startsWith('cloudflare/')) return 'cloudflare';
  if (m.startsWith('mistralai/') || m.startsWith('mistral/')) return 'mistral';
  if (m.startsWith('openrouter/') || m.endsWith(':free')) return 'openrouter';
  return 'google';
}

export interface ChainAttemptEvent {
  model: string;
  provider: string;
  outcome: 'skipped-open-breaker' | 'ok' | 'failed' | 'timeout';
  error?: string;
  ts: number;
}

/**
 * Wraps the execution of an ordered provider/model fallback chain.
 * `attempt(model)` should throw on failure; the chain skips candidates whose
 * breaker is open, records breaker outcomes and keeps the last N events.
 */
export class ProviderFallbackChain {
  private events: ChainAttemptEvent[] = [];
  private readonly maxEvents = 100;

  public getEvents(): ChainAttemptEvent[] {
    return [...this.events];
  }

  /** Candidates that are allowed to be attempted right now. */
  public filterHealthy(models: string[]): string[] {
    return models.filter((model) => {
      const breaker = getBreaker(providerOfModel(model));
      const allowed = breaker.getState() !== 'open' || breaker.canAttempt();
      if (!allowed) {
        this.push({ model, provider: breaker.provider, outcome: 'skipped-open-breaker', ts: Date.now() });
      }
      return allowed;
    });
  }

  public recordOk(model: string): void {
    const provider = providerOfModel(model);
    getBreaker(provider).recordSuccess();
    this.push({ model, provider, outcome: 'ok', ts: Date.now() });
  }

  public recordFailure(model: string, err: Error, isTimeout: boolean): void {
    const provider = providerOfModel(model);
    getBreaker(provider).recordFailure(err);
    this.push({ model, provider, outcome: isTimeout ? 'timeout' : 'failed', error: err.message, ts: Date.now() });
  }

  private push(ev: ChainAttemptEvent): void {
    this.events.push(ev);
    if (this.events.length > this.maxEvents) this.events.shift();
  }

  /** Text table: provider, breaker state, last error, last ok ts. */
  public static getHealthReport(): string {
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push('   HEALTH ОТЧЁТ LLM-ПРОВАЙДЕРОВ (CircuitBreakers)');
    lines.push('═'.repeat(78));
    lines.push('  ПРОВАЙДЕР    СТАТУС      СБОЕВ  ПОСЛЕДНЯЯ ОШИБКА');
    lines.push('─'.repeat(78));

    for (const name of BREAKER_PROVIDER_NAMES) {
      const snap = getBreaker(name).snapshot();
      const icon = snap.state === 'closed' ? '[OK]' : snap.state === 'half-open' ? '[HALF]' : '[OPEN]';
      const lastErr = snap.lastError ? snap.lastError.substring(0, 36) : '—';
      lines.push(
        `  ${name.padEnd(12)} ${icon} ${snap.state.padEnd(8)} ${String(snap.consecutiveFailures).padEnd(6)} ${lastErr}`
      );
      if (snap.lastOkTs) {
        lines.push(`               last ok: ${new Date(snap.lastOkTs).toISOString().replace('T', ' ').substring(0, 19)} UTC`);
      }
    }

    lines.push('─'.repeat(78));
    lines.push('  ПОСЛЕДНИЕ 5 ОШИБОК (за время жизни процесса):');
    const globalErrs = recentProviderErrors.slice(-5);
    if (globalErrs.length === 0) {
      lines.push('    • Ошибок не зафиксировано.');
    }
    for (const ev of globalErrs) {
      const when = new Date(ev.ts).toISOString().replace('T', ' ').substring(0, 19);
      lines.push(`    • ${when} [${ev.provider}] ${ev.model}: ${ev.error || ev.outcome}`);
    }
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }
}

