const RSS_TIMEOUT_MS = 8_000;
const CACHE_TTL_MS = 15 * 60 * 1000;
const MAX_QUERIES_PER_RUN = 5;
const MAX_ITEMS_SHOWN = 15;

interface CacheEntry {
  items: NewsItem[];
  fetchedAt: number;
  partialErrors: string[];
}

let cache: CacheEntry | null = null;

/** Normalizes a title for near-duplicate detection. */
function normalizeTitle(title: string): string {
  return title
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Token-set Jaccard similarity between two normalized titles. */
function titleSimilarity(a: string, b: string): number {
  const ta = new Set(normalizeTitle(a).split(' ').filter((t) => t.length > 2));
  const tb = new Set(normalizeTitle(b).split(' ').filter((t) => t.length > 2));
  if (ta.size === 0 || tb.size === 0) return 0;
  let inter = 0;
  for (const t of ta) if (tb.has(t)) inter++;
  return inter / (ta.size + tb.size - inter);
}

/** Extracts the "source -" prefix Google News prepends to RSS titles. */
function splitGoogleNewsTitle(raw: string): { source: string; title: string } {
  const idx = raw.lastIndexOf(' - ');
  if (idx > 0 && idx > raw.length - 40) {
    return { source: raw.slice(idx + 3).trim(), title: raw.slice(0, idx).trim() };
  }
  return { source: '', title: raw.trim() };
}

/** Parses Google News RSS XML with regex (no XML parser dependency). */
function parseGoogleNewsRss(xml: string, category: NewsTagId): NewsItem[] {
  const items: NewsItem[] = [];
  const itemBlocks = xml.match(/<item>[\s\S]*?<\/item>/g) || [];
  for (const block of itemBlocks.slice(0, 12)) {
    const titleMatch = block.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/);
    const linkMatch = block.match(/<link>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/link>/);
    const dateMatch = block.match(/<pubDate>([\s\S]*?)<\/pubDate>/);
    const sourceMatch = block.match(/<source[^>]*>([\s\S]*?)<\/source>/);
    if (!titleMatch || !linkMatch) continue;
    const { source, title } = splitGoogleNewsTitle(titleMatch[1].trim());
    items.push({
      title,
      url: (linkMatch[1] || '').trim(),
      source: (sourceMatch ? sourceMatch[1].trim() : '') || source || 'news.google.com',
      date: dateMatch ? dateMatch[1].trim() : '',
      category,
    });
  }
  return items;
}

async function fetchGoogleNewsRss(query: string, category: NewsTagId): Promise<NewsItem[]> {
  const url = `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=uk&gl=UA&ceid=UA:uk`;
  const res = await withTimeout(
    fetch(url, { headers: { 'User-Agent': 'EvaBot-NewsEngine/1.0 (+https://evabot.online)' } }),
    RSS_TIMEOUT_MS,
    `google-news-rss:${query}`
  );
  if (!res.ok) throw new Error(`Google News RSS HTTP ${res.status} for "${query}"`);
  const xml = await res.text();
  return parseGoogleNewsRss(xml, category);
}

async function fetchNewsApi(query: string, category: NewsTagId): Promise<NewsItem[]> {
  const key = process.env.NEWS_API_KEY;
  if (!key) return [];
  const url = `https://newsapi.org/v2/everything?q=${encodeURIComponent(query)}&language=uk&sortBy=publishedAt&pageSize=10&apiKey=${key}`;
  const res = await withTimeout(
    fetch(url, { headers: { 'User-Agent': 'EvaBot-NewsEngine/1.0' } }),
    RSS_TIMEOUT_MS,
    `newsapi:${query}`
  );
  if (!res.ok) throw new Error(`newsapi.org HTTP ${res.status} for "${query}"`);
  const json: any = await res.json();
  const articles = json?.articles || [];
  return articles.map((a: any) => ({
    title: String(a.title || '').trim(),
    url: String(a.url || ''),
    source: a.source?.name || 'newsapi.org',
    date: a.publishedAt || '',
    category,
  }));
}

export class NewsEngine {
  /** Resolves a free-text category name/alias to a NewsTagId, if any. */
  public static resolveTag(input: string): NewsTagId | null {
    const q = input.toLowerCase().trim();
    for (const tag of Object.values(NEWS_TAGS)) {
      if (tag.id === q || tag.aliases.includes(q)) return tag.id;
    }
    return null;
  }

  public static getAllTagIds(): NewsTagId[] {
    return Object.keys(NEWS_TAGS) as NewsTagId[];
  }

  /**
   * Multi-source fetch for the requested tags (default: all tags).
   * Runs at most MAX_QUERIES_PER_RUN Google News queries (round-robin over
   * tags) plus an optional newsapi.org call; each request has an 8s timeout
   * and is executed under Promise.allSettled. Results are cached 15 minutes.
   */
  public static async fetchNews(
    tags?: NewsTagId[],
    opts: { forceRefresh?: boolean } = {}
  ): Promise<{ items: NewsItem[]; partialErrors: string[]; cached: boolean }> {
    const now = Date.now();
    if (!opts.forceRefresh && cache && now - cache.fetchedAt < CACHE_TTL_MS) {
      return { items: cache.items, partialErrors: cache.partialErrors, cached: true };
    }

    const wanted = tags && tags.length > 0 ? tags : this.getAllTagIds();
    const tasks: Array<Promise<NewsItem[]>> = [];
    const sources: string[] = [];

    let queryBudget = MAX_QUERIES_PER_RUN;
    for (const tag of wanted) {
      const cat = NEWS_TAGS[tag];
      if (!cat) continue;
      for (const q of cat.queries) {
        if (queryBudget <= 0) break;
        queryBudget--;
        sources.push(`rss:${tag}:${q}`);
        tasks.push(fetchGoogleNewsRss(q, tag));
      }
      tasks.push(fetchNewsApi(cat.queries[0], tag).then((items) => (items.length > 0 ? items : [])));
    }

    const settled = await Promise.allSettled(tasks);
    const all: NewsItem[] = [];
    const partialErrors: string[] = [];

    settled.forEach((r, i) => {
      if (r.status === 'fulfilled') {
        all.push(...r.value);
      } else {
        const msg = `${sources[i] || `task#${i}`}: ${r.reason?.message || String(r.reason)}`;
        partialErrors.push(msg);
        logger.warn('NewsEngine', `Source failed: ${msg}`);
      }
    });

    const items = this.dedupeByTitle(all);
    cache = { items, fetchedAt: now, partialErrors };
    return { items, partialErrors, cached: false };
  }

  /** Dedupes items by title similarity (Jaccard > 0.6 keeps the first). */
  public static dedupeByTitle(items: NewsItem[]): NewsItem[] {
    const kept: NewsItem[] = [];
    for (const item of items) {
      const dup = kept.some((k) => k.category === item.category && titleSimilarity(k.title, item.title) > 0.6);
      if (!dup) kept.push(item);
    }
    return kept;
  }

  /**
   * Formats the news digest: dedupe, group by category, top ~15 items with
   * source + date + link. Locale-aware category headers (en/uk/ru).
   */
  public static formatNews(
    lang: 'en' | 'uk' | 'ru' = 'en',
    items?: NewsItem[],
    partialErrors: string[] = []
  ): string {
    const lines: string[] = [];
    const data = items || (cache ? cache.items : []);
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push(`  NEWS НОВИНИ EVALINE — ${data.length} Material Feed (${new Date().toISOString().replace('T', ' ').substring(0, 16)} UTC)`);
    lines.push('═'.repeat(78));

    if (data.length === 0) {
      lines.push('  Лента пуста. Запустите /news — движок подтянет свежие заголовки.');
      lines.push('═'.repeat(78));
      return lines.join('\n');
    }

    let shown = 0;
    for (const tag of Object.keys(NEWS_TAGS) as NewsTagId[]) {
      const cat = NEWS_TAGS[tag];
      const catItems = data.filter((i) => i.category === tag);
      if (catItems.length === 0) continue;
      lines.push('');
      lines.push(`   ${cat.labels[lang] || cat.labels.en} (${catItems.length}):`);
      for (const item of catItems) {
        if (shown >= MAX_ITEMS_SHOWN) break;
        const date = item.date ? new Date(item.date).toISOString().replace('T', ' ').substring(0, 16) : '—';
        const title = item.title.length > 96 ? item.title.substring(0, 93) + '...' : item.title;
        lines.push(`    • [${date}] ${title}`);
        lines.push(`      ${item.source} | ${item.url}`);
        shown++;
      }
      if (shown >= MAX_ITEMS_SHOWN) break;
    }

    if (partialErrors.length > 0) {
      lines.push('');
      lines.push(`  [WRN] Недоступні джерела (${partialErrors.length}): ${partialErrors[0]}`);
    }
    lines.push('');
    lines.push('  Використання: /news [тег] — war | odessa | economy | eva | trends | evaline');
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }

  /**
   * Synchronous cache-first text used by ModelCommand.execute (which is sync).
   * If the cache is empty it kicks off a fire-and-forget refresh and reports.
   */
  public static getCachedText(lang: 'en' | 'uk' | 'ru' = 'en', tags?: NewsTagId[]): string | null {
    if (cache && Date.now() - cache.fetchedAt < CACHE_TTL_MS) {
      const items = tags && tags.length > 0 ? cache.items.filter((i) => tags.includes(i.category)) : cache.items;
      return this.formatNews(lang, items, cache.partialErrors);
    }
    // warm up in background; next /news call (or executeAsync) gets real data
    NewsEngine.fetchNews().catch(() => undefined);
    return null;
  }
}

/**
 * OpLog.ts — unified operation log for the EvaBot brain.
 *
 * Provides:
 *  - In-memory ring buffer (last 1000 entries) for fast /log queries.
 *  - Append-only JSONL persistence at data/operations.jsonl with size-based
 *    rotation (at 5 MB the file is renamed to operations.jsonl.1).
 *  - Entry schema: { ts, level: info|warn|error|debug, kind: command|llm|breaker|system|chat, text, meta? }
 *  - query({limit, level?, kind?, textLike?, since?}) and stats() aggregations.
 *  - DebugContext: a module-level debug flag + latency spans used by the
 *    /debug command and the ChatRouter debug footer.
 *
 * Design guarantees:
 *  - log() NEVER throws — persistence failures are silently swallowed so the
 *    operation log can never take down the chat or LLM path.
 *  - 'debug' level entries are recorded only while the debug flag is ON
 *    (see isDebugOn / setDebugOn); other levels are always recorded.
 */

import fs from 'node:fs';
import path from 'node:path';

export type OpLogLevel = 'info' | 'warn' | 'error' | 'debug';
export type OpLogKind = 'command' | 'llm' | 'breaker' | 'system' | 'chat' | 'auto';

export interface OpLogEntry {
  ts: number;
  level: OpLogLevel;
  kind: OpLogKind;
  text: string;
  meta?: Record<string, unknown>;
}

export interface OpLogQuery {
  limit?: number;
  level?: OpLogLevel;
  kind?: OpLogKind;
  textLike?: string;
  since?: number;
}

export interface OpLogStats {
  bufferSize: number;
  byLevel: Record<OpLogLevel, number>;
  byKind: Record<OpLogKind, number>;
  lastError?: OpLogEntry;
  filePath: string;
  fileBytes?: number;
}

/** Rotation threshold for the JSONL file (5 MB). */
export const OPLOG_ROTATE_BYTES = 5 * 1024 * 1024;

/** Ring buffer capacity (last N entries kept in memory). */
export const OPLOG_RING_CAPACITY = 1000;

/* ────────────────────────────  DebugContext  ──────────────────────────── */

const debugState = { enabled: false };

/** Whether debug mode is currently ON (server-side flag, /debug command). */
export function isDebugOn(): boolean {
  return debugState.enabled;
}

/** Toggles the server-side debug flag. */
export function setDebugOn(value: boolean): void {
  debugState.enabled = value;
}

/** A latency span for one LLM round-trip (used for the * debug footer). */
export interface DebugSpan {
  model: string;
  provider: string;
  startTs: number;
  latencyMs?: number;
  fallback?: string;
  ended: boolean;
  end(fallback?: string): void;
}

/** Starts a debug span for a model/provider call. */
export function startSpan(model: string, provider: string): DebugSpan {
  const span: DebugSpan = {
    model,
    provider,
    startTs: Date.now(),
    latencyMs: undefined,
    fallback: undefined,
    ended: false,
    end(fallback?: string) {
      if (span.ended) return;
      span.ended = true;
      span.latencyMs = Date.now() - span.startTs;
      span.fallback = fallback;
      OpLog.getInstance().log('debug', 'llm', `span model=${model} provider=${provider} latencyMs=${span.latencyMs}`);
    },
  };
  return span;
}

/** Renders the `* debug:` footer line shown in chat replies while debug is ON. */
export function renderDebugFooter(span: DebugSpan): string {
  const latency = span.latencyMs ?? Date.now() - span.startTs;
  return `* debug: model=${span.model} provider=${span.provider} latency=${latency}ms fallback=${span.fallback ?? '—'}`;
}

/* ────────────────────────────────  OpLog  ──────────────────────────────── */

export class OpLog {
  private ring: OpLogEntry[] = [];
  private filePath: string;
  private rotateBytes: number;
  private static instance: OpLog | null = null;

  constructor(options?: { filePath?: string; rotateBytes?: number }) {
    this.filePath = options?.filePath || path.resolve(process.cwd(), 'data', 'operations.jsonl');
    this.rotateBytes = options?.rotateBytes || OPLOG_ROTATE_BYTES;
  }

  /** Process-wide singleton (default data/operations.jsonl path). */
  public static getInstance(): OpLog {
    if (!OpLog.instance) {
      OpLog.instance = new OpLog();
    }
    return OpLog.instance;
  }

  /** Absolute path of the JSONL file (used by /debug full). */
  public getPath(): string {
    return this.filePath;
  }

  /**
   * Records one entry. Never throws: ring-buffer append and JSONL persistence
   * are both wrapped so a logging failure can never break the caller.
   */
  public log(level: OpLogLevel, kind: OpLogKind, text: string, meta?: Record<string, unknown>): void {
    try {
      // Debug gating: skip 'debug' entries unless the /debug flag is ON.
      if (level === 'debug' && !isDebugOn()) return;

      const entry: OpLogEntry = { ts: Date.now(), level, kind, text };
      if (meta !== undefined) entry.meta = meta;

      this.ring.push(entry);
      if (this.ring.length > OPLOG_RING_CAPACITY) this.ring.shift();

      this.appendJsonl(entry);
    } catch {
      /* never throw from log() */
    }
  }

  /** Queries the ring buffer. Returns newest-first entries, limited. */
  public query(q: OpLogQuery = {}): OpLogEntry[] {
    const limit = Math.max(1, Math.min(OPLOG_RING_CAPACITY, q.limit || 20));
    let hits = this.ring.slice();
    if (q.level) hits = hits.filter((e) => e.level === q.level);
    if (q.kind) hits = hits.filter((e) => e.kind === q.kind);
    if (q.textLike) {
      const needle = q.textLike.toLowerCase();
      hits = hits.filter((e) => e.text.toLowerCase().includes(needle));
    }
    if (typeof q.since === 'number') hits = hits.filter((e) => e.ts >= q.since!);
    return hits.slice(-limit).reverse();
  }

  /** Aggregates: counts by kind/level, last error entry, buffer size, file size. */
  public stats(): OpLogStats {
    const byLevel: Record<OpLogLevel, number> = { info: 0, warn: 0, error: 0, debug: 0 };
    const byKind: Record<OpLogKind, number> = { command: 0, llm: 0, breaker: 0, system: 0, chat: 0, auto: 0 };
    let lastError: OpLogEntry | undefined;
    for (const e of this.ring) {
      byLevel[e.level] += 1;
      byKind[e.kind] += 1;
      if (e.level === 'error') lastError = e;
    }
    const stats: OpLogStats = { bufferSize: this.ring.length, byLevel, byKind, filePath: this.filePath };
    if (lastError) stats.lastError = lastError;
    try {
      stats.fileBytes = fs.statSync(this.filePath).size;
    } catch {
      /* file may not exist yet */
    }
    return stats;
  }

  /** Append-only JSONL write with size-based rotation (file → file.1). */
  private appendJsonl(entry: OpLogEntry): void {
    try {
      let size = 0;
      try {
        size = fs.statSync(this.filePath).size;
      } catch {
        size = 0; // file does not exist yet
      }
      if (size >= this.rotateBytes) {
        try {
          fs.renameSync(this.filePath, this.filePath + '.1');
        } catch {
          /* rotation best-effort; keep appending */
        }
      }
      fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
      fs.appendFileSync(this.filePath, JSON.stringify(entry) + '\n', 'utf8');
    } catch {
      /* persistence is best-effort — never throw */
    }
  }
}

/** Shared singleton accessor (short alias for call sites). */
export const opLog = OpLog.getInstance();

/**
 * Translator.ts — Google Cloud Translation Basic (v3) client for EvaBot.
 *
 * Endpoint: POST https://translation.googleapis.com/v3/projects/{project}/locations/global:translateText
 * Auth:     Bearer token from GoogleAuthProvider + REQUIRED header X-Goog-User-Project.
 * Free tier: first 500,000 characters/month are free (applied as a $10 credit every
 *            month) — https://cloud.google.com/translate/pricing (verified 2026-09).
 *
 * ONLY-FREE policy: a persistent monthly counter (data/translate-usage.json,
 * { month: 'YYYY-MM', chars }) refuses any request once the soft cap of 480,000
 * characters is reached, so the account can never be billed.
 *
 * Design guarantees:
 *  - translate() NEVER throws into the command path — all failures are returned
 *    as { ok: false, error } results.
 *  - 10 s hard deadline via Resilience.withTimeout (+ AbortSignal on the fetch).
 *  - Contents are batched: max 128 fragments per HTTP request (v3 limit).
 */

import fs from 'node:fs';
import path from 'node:path';
import { GoogleAuthProvider } from './GoogleAuthProvider.js';
import { withTimeout } from './Resilience.js';
import { logger } from './Logger.js';
import { OpLog } from './OpLog.js';

/** Soft monthly character cap (below the 500,000 free-tier ceiling). */
export const TRANSLATE_MONTHLY_CAP = 480_000;

/** Google free tier: first 500k characters/month (source: translate/pricing). */
export const TRANSLATE_FREE_TIER_CHARS = 500_000;

/** Max fragments (contents[]) per single v3 translateText request. */
export const TRANSLATE_MAX_FRAGMENTS_PER_REQUEST = 128;

/** Hard deadline for one HTTP translation round-trip. */
export const TRANSLATE_TIMEOUT_MS = 10_000;

/** Target language codes the /translate command accepts. */
export const TRANSLATE_LANG_RE = /^[a-z]{2,3}(-[A-Za-z0-9]{2,8})?$/;

export const TRANSLATE_PROJECT = 'evabot-agent-server';

export interface TranslatorOptions {
  fetchFn?: typeof fetch;
  getCredentials?: typeof GoogleAuthProvider.getCredentials;
  usageFilePath?: string;
  timeoutMs?: number;
}

export interface TranslateResult {
  ok: boolean;
  /** Translated fragments (same order as the input). Empty when !ok. */
  translations: string[];
  /** Detected source language, when the API reports it. */
  detectedLanguageCode?: string;
  /** Characters counted against the monthly usage for THIS call. */
  charsUsed: number;
  /** { month, chars } snapshot after this call. */
  usage: { month: string; chars: number };
  /** Human-readable failure reason (empty when ok). */
  error?: string;
}

export interface UsageRecord {
  month: string;
  chars: number;
}

export function currentMonthKey(now: Date = new Date()): string {
  return `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`;
}

/** Builds the v3 translateText JSON body (exported for tests). */
export function buildTranslateBody(
  contents: string[],
  targetLanguageCode: string,
  sourceLanguageCode?: string
): Record<string, unknown> {
  const body: Record<string, unknown> = {
    targetLanguageCode,
    contents,
    mimeType: 'text/plain',
  };
  if (sourceLanguageCode) body.sourceLanguageCode = sourceLanguageCode;
  return body;
}

/** Splits fragments into batches of at most TRANSLATE_MAX_FRAGMENTS_PER_REQUEST. */
export function splitIntoBatches<T>(items: T[], max = TRANSLATE_MAX_FRAGMENTS_PER_REQUEST): T[][] {
  const batches: T[][] = [];
  for (let i = 0; i < items.length; i += max) {
    batches.push(items.slice(i, i + max));
  }
  return batches;
}

export class Translator {
  private readonly fetchFn: typeof fetch;
  private readonly getCredentials: typeof GoogleAuthProvider.getCredentials;
  private readonly usageFilePath: string;
  private readonly timeoutMs: number;

  constructor(opts: TranslatorOptions = {}) {
    this.fetchFn = opts.fetchFn || fetch.bind(globalThis);
    this.getCredentials = (opts.getCredentials ||
      GoogleAuthProvider.getCredentials.bind(GoogleAuthProvider)) as typeof GoogleAuthProvider.getCredentials;
    this.usageFilePath =
      opts.usageFilePath || path.join(process.cwd(), 'data', 'translate-usage.json');
    this.timeoutMs = opts.timeoutMs || TRANSLATE_TIMEOUT_MS;
  }

  /**
   * Translates one fragment or a batch of fragments into `to`.
   * Never throws: failures come back as { ok: false, error }.
   */
  public async translate(
    text: string | string[],
    to: string,
    from?: string
  ): Promise<TranslateResult> {
    const contents = (Array.isArray(text) ? text : [text]).map((t) => String(t ?? ''));
    const target = (to || '').trim().toLowerCase();

    if (!contents.length || contents.every((c) => c.trim() === '')) {
      return { ok: false, translations: [], charsUsed: 0, usage: this.getUsage(), error: 'Порожній текст для перекладу.' };
    }
    if (!TRANSLATE_LANG_RE.test(target)) {
      return { ok: false, translations: [], charsUsed: 0, usage: this.getUsage(), error: `Неправильний код мови цілі: "${to}". Приклад: uk, en, ru, pl, de.` };
    }

    // ONLY-FREE guard: refuse BEFORE spending if this call would cross the cap.
    const pendingChars = contents.reduce((sum, c) => sum + c.length, 0);
    const usage = this.getUsage();
    if (usage.chars + pendingChars > TRANSLATE_MONTHLY_CAP) {
      const msg = `[TRANSLATE] Місячний ліміт free tier вичерпано: ${usage.chars}/${TRANSLATE_MONTHLY_CAP} символів використано цього місяця (${usage.month}). Ліміт відновиться 1-го числа наступного місяця.`;
      logger.warn('Translator', msg);
      OpLog.getInstance().log('warn', 'system', msg);
      return { ok: false, translations: [], charsUsed: 0, usage, error: msg };
    }

    try {
      const credentials = await this.getCredentials();
      if (!credentials) {
        return { ok: false, translations: [], charsUsed: 0, usage: this.getUsage(), error: 'Немає Google-автентифікації (GoogleAuthProvider повернув null).' };
      }

      const allTranslations: string[] = [];
      let detected: string | undefined;
      const batches = splitIntoBatches(contents);
      let charsThisCall = 0;

      for (const batch of batches) {
        const url = `https://translation.googleapis.com/v3/projects/${TRANSLATE_PROJECT}/locations/global:translateText`;
        const res = await withTimeout(
          this.fetchFn(url, {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${credentials.token}`,
              'X-Goog-User-Project': TRANSLATE_PROJECT,
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(buildTranslateBody(batch, target, from)),
            signal: AbortSignal.timeout(this.timeoutMs),
          }),
          this.timeoutMs,
          'Google Cloud Translation v3'
        );

        if (!res.ok) {
          const errText = await res.text().catch(() => '');
          throw new Error(`HTTP ${res.status}: ${errText.substring(0, 300)}`);
        }
        const data: any = await res.json();
        const list = (data.translations || []) as Array<{ translatedText: string; detectedLanguageCode?: string }>;
        if (list.length !== batch.length) {
          throw new Error(`Очікувано ${batch.length} перекладів, отримано ${list.length}.`);
        }
        for (const t of list) {
          allTranslations.push(t.translatedText);
          if (t.detectedLanguageCode && !detected) detected = t.detectedLanguageCode;
        }
        charsThisCall += batch.reduce((sum, c) => sum + c.length, 0);
      }

      const newUsage = this.addUsage(charsThisCall);
      return {
        ok: true,
        translations: allTranslations,
        detectedLanguageCode: detected,
        charsUsed: charsThisCall,
        usage: newUsage,
      };
    } catch (err: any) {
      const msg = `[TRANSLATE] Помилка перекладу: ${err?.message || err}`;
      logger.warn('Translator', msg);
      return { ok: false, translations: [], charsUsed: 0, usage: this.getUsage(), error: msg };
    }
  }

  /** Reads (and month-rolls) the persistent usage counter. Never throws. */
  public getUsage(): { month: string; chars: number } {
    try {
      const raw = fs.readFileSync(this.usageFilePath, 'utf8');
      const rec = JSON.parse(raw) as UsageRecord;
      const month = currentMonthKey();
      if (rec.month === month) return { month: rec.month, chars: rec.chars || 0 };
      return { month, chars: 0 };
    } catch {
      return { month: currentMonthKey(), chars: 0 };
    }
  }

  /** Adds `chars` to the monthly counter and persists it. Never throws. */
  public addUsage(chars: number): { month: string; chars: number } {
    const cur = this.getUsage();
    const next: UsageRecord = { month: cur.month, chars: cur.chars + Math.max(0, chars) };
    try {
      fs.mkdirSync(path.dirname(this.usageFilePath), { recursive: true });
      fs.writeFileSync(this.usageFilePath, JSON.stringify(next, null, 2), 'utf8');
    } catch (err: any) {
      logger.warn('Translator', `Не вдалося зберегти лічильник перекладів: ${err?.message}`);
    }
    return next;
  }

  /** Usage footer for command replies: chars used / cap + free-tier note. */
  public formatUsageFooter(usage: { month: string; chars: number }): string {
    return `[NET] Переклад-лічильник: ${usage.chars}/${TRANSLATE_MONTHLY_CAP} символів цього місяця (free tier: 500 000/міс — cloud.google.com/translate/pricing).`;
  }
}

/** Shared singleton used by the /translate command (real credentials). */
export const translator = new Translator();

/**
 * CloudTTS.ts — Google Cloud Text-to-Speech for EvaBot (ONLY-FREE compliant).
 *
 * Reuses GoogleAuthProvider token/credentials logic (user-ADC refresh token
 * exchange). Every request sends:
 *   Authorization: Bearer <token>
 *   X-Goog-User-Project: evabot-agent-server   (REQUIRED for user-ADC auth)
 *
 * Endpoint: POST https://texttospeech.googleapis.com/v1/text:synthesize
 *
 * ONLY-FREE rule (verified 2026-09 against the official pricing page
 * https://cloud.google.com/text-to-speech/pricing):
 *   - WaveNet voices: first 1M chars/month free, then pay-per-char.
 *   - Chirp 3: HD voices: free allowance exists too (1M chars/mo), but after
 *     the cap it is the most expensive family ($30/1M chars).
 *   - Standard voices: first 4M chars/month free.
 * The module enforces a hard monthly character cap (MAX_CHARS_FREE_PER_MONTH,
 * default 900_000 = safety margin under the 1M Wavenet free allowance) and
 * REFUSES to synthesize beyond it. It never silently spends money: requests
 * over the cap are rejected with an overCap result so callers can fall back
 * to browser TTS.
 *
 * Persona voice mapping (verified from live GET /v1/voices, 2066 voices):
 *   Ева (female) → uk-UA-Chirp3-HD-Aoede  (FEMALE, Chirp3-HD 1M chars/mo free)
 *   Адам (male)  → ru-RU-Chirp3-HD-Fenrir (MALE,   Chirp3-HD 1M chars/mo free)
 * Chirp3-HD voices sound far more natural than Wavenet AND have the same
 * 1M chars/month free allowance (verified 2026-09, official pricing page).
 * Runtime overrides: data/voice-prefs.json (written by /voices set) wins over
 * these defaults; explicit constructor opts (tests) win over everything.
 *
 * Extras:
 *   - Monthly usage counter persisted at data/tts-usage.json {month, chars}.
 *   - Audio cache: identical (text+voice) results stored at
 *     data/tts-cache/<sha1>.mp3 — cache hits never hit the API or the counter.
 *   - 10 s hard deadline via Resilience.withTimeout.
 *   - synthesize() NEVER throws into the chat flow: all failures resolve to
 *     { ok: false, error } so callers can fall back gracefully.
 */

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { logger } from './Logger.js';
import { GoogleAuthProvider } from './GoogleAuthProvider.js';
import { withTimeout } from './Resilience.js';

export type TtsPersona = 'eva' | 'adam';

export interface TtsSynthesisOptions {
  lang?: string;
  persona?: TtsPersona;
  voiceName?: string;
}

export interface TtsSynthesisResult {
  ok: boolean;
  base64Audio?: string;
  voice: string;
  charCount: number;
  cached?: boolean;
  overCap?: boolean;
  charsLeftThisMonth?: number;
  payPerCharAfterCap?: boolean;
  error?: string;
}

export interface TtsUsageState {
  month: string;
  chars: number;
}

export interface CloudTTSOptions {
  dataDir?: string;
  fetchFn?: typeof fetch;
  getCredentials?: () => Promise<{ token: string } | null>;
  cap?: number;
  evaVoice?: string;
  adamVoice?: string;
  timeoutMs?: number;
}

const TTS_ENDPOINT = 'https://texttospeech.googleapis.com/v1/text:synthesize';
const TTS_VOICES_ENDPOINT = 'https://texttospeech.googleapis.com/v1/voices';
const USER_PROJECT = 'evabot-agent-server';

/** Voice family derived from the voice name (drives pricing metadata). */
export function voiceFamily(voiceName: string): 'chirp3-hd' | 'wavenet' | 'neural2' | 'studio' | 'standard' {
  if (voiceName.includes('Chirp3')) return 'chirp3-hd';
  if (voiceName.includes('Wavenet')) return 'wavenet';
  if (voiceName.includes('Neural2')) return 'neural2';
  if (voiceName.includes('Studio')) return 'studio';
  return 'standard';
}

/** Free-tier allowance per family, chars/month (verified 2026-09, see doc). */
export function familyFreeAllowance(family: string): number {
  switch (family) {
    case 'standard': return 4_000_000;
    case 'wavenet':
    case 'neural2':
    case 'chirp3-hd': return 1_000_000;
    default: return 100_000; // studio
  }
}

/** Pay-per-char label used when the module reports a cap-exhausted family. */
export function familyPayPerCharNote(family: string): string {
  switch (family) {
    case 'chirp3-hd': return 'PAY-PER-CHAR after cap: US$30 per 1M chars';
    case 'studio': return 'PAY-PER-CHAR after cap: US$160 per 1M chars';
    case 'neural2': return 'PAY-PER-CHAR after cap: US$16 per 1M chars';
    default: return 'PAY-PER-CHAR after cap: US$16 per 1M chars';
  }
}

/** Extracts languageCode ("uk-UA") from a full voice name. */
export function languageCodeOf(voiceName: string): string {
  const parts = voiceName.split('-');
  return parts.length >= 2 ? `${parts[0]}-${parts[1]}` : 'en-US';
}

// ============================================================================
// Voice catalog + ONLY-FREE family validation (drives the /voices command).
// Free families: chirp3-hd, wavenet, neural2, standard (1M–4M chars/mo free).
// Paid-only families (e.g. studio) are rejected by /voices set.
// ============================================================================

export type CatalogVoiceFamily = 'chirp3-hd' | 'wavenet' | 'neural2' | 'standard';

export interface CatalogVoice {
  name: string;
  family: CatalogVoiceFamily;
  gender: 'FEMALE' | 'MALE';
  free: boolean;
}

/** Families allowed by /voices set (all free-tier). Studio/others rejected. */
export const FREE_VOICE_FAMILIES: ReadonlySet<string> = new Set<CatalogVoiceFamily>([
  'chirp3-hd', 'wavenet', 'neural2', 'standard',
]);

/** Family → sort rank for /voices listing (Chirp3-HD first, most natural). */
export function familyRank(family: string): number {
  switch (family) {
    case 'chirp3-hd': return 0;
    case 'wavenet': return 1;
    case 'neural2': return 2;
    case 'standard': return 3;
    default: return 9;
  }
}

const CHIRP3_FEMALE = ['Aoede', 'Autonoe', 'Callirrhoe', 'Despina', 'Erinome', 'Gacrux', 'Kore', 'Laomedeia', 'Leda', 'Pulcherrima', 'Sadr', 'Vindemiatrix', 'Zephyr'];
const CHIRP3_MALE = ['Achernar', 'Achird', 'Algenib', 'Algol', 'Alnilam', 'Charon', 'Enceladus', 'Fenrir', 'Iapetus', 'Orus', 'Puck', 'Umbriel', 'Zubenelgenubi'];

function catalogVoicesFor(locales: string[]): CatalogVoice[] {
  const out: CatalogVoice[] = [];
  for (const loc of locales) {
    for (const n of CHIRP3_FEMALE) out.push({ name: `${loc}-Chirp3-HD-${n}`, family: 'chirp3-hd', gender: 'FEMALE', free: true });
    for (const n of CHIRP3_MALE) out.push({ name: `${loc}-Chirp3-HD-${n}`, family: 'chirp3-hd', gender: 'MALE', free: true });
  }
  return out;
}

const UK_WAVENET: Array<[string, CatalogVoiceFamily, 'FEMALE' | 'MALE']> = [
  ['uk-UA-Wavenet-B', 'wavenet', 'FEMALE'],
  ['uk-UA-Standard-B', 'standard', 'FEMALE'],
];

const RU_WAVENET: Array<[string, CatalogVoiceFamily, 'FEMALE' | 'MALE']> = [
  ['ru-RU-Wavenet-A', 'wavenet', 'FEMALE'],
  ['ru-RU-Wavenet-D', 'wavenet', 'MALE'],
  ['ru-RU-Standard-A', 'standard', 'FEMALE'],
  ['ru-RU-Standard-B', 'standard', 'FEMALE'],
  ['ru-RU-Standard-D', 'standard', 'MALE'],
  ['ru-RU-Standard-E', 'standard', 'MALE'],
];

const EN_WAVENET: Array<[string, CatalogVoiceFamily, 'FEMALE' | 'MALE']> = [
  ['en-US-Wavenet-A', 'wavenet', 'FEMALE'],
  ['en-US-Wavenet-B', 'wavenet', 'MALE'],
  ['en-US-Wavenet-C', 'wavenet', 'FEMALE'],
  ['en-US-Wavenet-D', 'wavenet', 'MALE'],
  ['en-US-Wavenet-E', 'wavenet', 'FEMALE'],
  ['en-US-Wavenet-F', 'wavenet', 'MALE'],
  ['en-US-Standard-A', 'standard', 'FEMALE'],
  ['en-US-Standard-B', 'standard', 'MALE'],
  ['en-US-Standard-C', 'standard', 'FEMALE'],
  ['en-US-Standard-D', 'standard', 'MALE'],
  ['en-US-Standard-E', 'standard', 'FEMALE'],
  ['en-US-Standard-F', 'standard', 'MALE'],
];

/** Static ONLY-FREE voice catalog per language (Chirp3-HD + Wavenet tiers). */
export const VOICE_CATALOG: CatalogVoice[] = [
  ...catalogVoicesFor(['uk-UA', 'ru-RU', 'en-US']),
  ...UK_WAVENET.map(([name, family, gender]) => ({ name, family, gender, free: true })),
  ...RU_WAVENET.map(([name, family, gender]) => ({ name, family, gender, free: true })),
  ...EN_WAVENET.map(([name, family, gender]) => ({ name, family, gender, free: true })),
];

export interface VoiceValidationResult {
  ok: boolean;
  family?: CatalogVoiceFamily;
  gender?: string;
  error?: string;
}

/** Validates a voice name against the ONLY-FREE catalog + family whitelist. */
export function validateVoiceName(voiceName: string): VoiceValidationResult {
  const entry = VOICE_CATALOG.find((v) => v.name === voiceName);
  if (!entry) {
    return {
      ok: false,
      error: `unknown voice "${voiceName}" (not in the free catalog — use /voices to list available voices)`,
    };
  }
  if (!FREE_VOICE_FAMILIES.has(entry.family)) {
    return {
      ok: false,
      family: entry.family,
      error: `voice family "${entry.family}" is NOT in the free-family list (allowed: ${[...FREE_VOICE_FAMILIES].join(', ')})`,
    };
  }
  return { ok: true, family: entry.family, gender: entry.gender };
}

// ============================================================================
// Voice preferences persistence (data/voice-prefs.json, written by /voices set)
// ============================================================================

export interface VoicePrefs {
  evaVoice?: string;
  adamVoice?: string;
}

/** Default location of the persisted voice preferences file. */
export function voicePrefsPath(dataDir: string = path.resolve(process.cwd(), 'data')): string {
  return path.join(dataDir, 'voice-prefs.json');
}

/** Loads data/voice-prefs.json (if present and valid). Never throws. */
export function loadVoicePrefs(dataDir: string = path.resolve(process.cwd(), 'data')): VoicePrefs {
  try {
    const p = voicePrefsPath(dataDir);
    if (fs.existsSync(p)) {
      const raw = JSON.parse(fs.readFileSync(p, 'utf8'));
      const prefs: VoicePrefs = {};
      if (typeof raw.evaVoice === 'string' && raw.evaVoice) prefs.evaVoice = raw.evaVoice;
      if (typeof raw.adamVoice === 'string' && raw.adamVoice) prefs.adamVoice = raw.adamVoice;
      return prefs;
    }
  } catch {
    // Corrupt file → fall back to defaults.
  }
  return {};
}

/** Persists data/voice-prefs.json {evaVoice, adamVoice}. */
export function saveVoicePrefs(prefs: VoicePrefs, dataDir: string = path.resolve(process.cwd(), 'data')): void {
  fs.mkdirSync(dataDir, { recursive: true });
  const merged = { ...loadVoicePrefs(dataDir), ...prefs };
  fs.writeFileSync(voicePrefsPath(dataDir), JSON.stringify(merged, null, 2), 'utf8');
}

/** Builds the exact JSON body for POST /v1/text:synthesize. */
export function buildSynthesizeRequest(text: string, voiceName: string): Record<string, unknown> {
  return {
    input: { text },
    voice: {
      languageCode: languageCodeOf(voiceName),
      name: voiceName,
    },
    audioConfig: {
      audioEncoding: 'MP3',
    },
  };
}

export class CloudTTS {
  private readonly dataDir: string;
  private readonly cacheDir: string;
  private readonly fetchFn: typeof fetch;
  private readonly getCredentials: () => Promise<{ token: string } | null>;
  private readonly cap: number;
  private evaVoice: string;
  private adamVoice: string;
  private readonly timeoutMs: number;
  private usage: TtsUsageState | null = null;
  private voicesReady: boolean = false;

  constructor(opts: CloudTTSOptions = {}) {
    this.dataDir = opts.dataDir || path.resolve(process.cwd(), 'data');
    this.cacheDir = path.join(this.dataDir, 'tts-cache');
    this.fetchFn = opts.fetchFn || fetch;
    this.getCredentials = opts.getCredentials || (async () => {
      const creds = await GoogleAuthProvider.getCredentials();
      return creds ? { token: creds.token } : null;
    });
    this.cap = opts.cap ?? 900_000;
    // Voice precedence: explicit opts (tests) > data/voice-prefs.json
    // (/voices set) > Chirp3-HD defaults (most natural free-tier voices).
    const prefs = loadVoicePrefs(this.dataDir);
    this.evaVoice = opts.evaVoice || prefs.evaVoice || 'uk-UA-Chirp3-HD-Aoede';
    this.adamVoice = opts.adamVoice || prefs.adamVoice || 'ru-RU-Chirp3-HD-Fenrir';
    this.timeoutMs = opts.timeoutMs ?? 10_000;
  }

  /** Re-reads data/voice-prefs.json into the live instance (after /voices set). */
  public reloadVoicePrefs(): void {
    const prefs = loadVoicePrefs(this.dataDir);
    if (prefs.evaVoice) this.evaVoice = prefs.evaVoice;
    if (prefs.adamVoice) this.adamVoice = prefs.adamVoice;
  }

  /** Explicit voice name (env override) wins, then persona, then lang guess. */
  public resolveVoice(opts: TtsSynthesisOptions = {}): string {
    if (opts.voiceName) return opts.voiceName;
    if (opts.persona === 'adam') return this.adamVoice;
    if (opts.persona === 'eva') return this.evaVoice;
    const lang = (opts.lang || '').toLowerCase();
    if (lang.startsWith('ru')) return this.adamVoice;
    if (lang.startsWith('uk') || lang.startsWith('ua')) return this.evaVoice;
    return this.evaVoice;
  }

  public getCap(): number {
    return this.cap;
  }

  public getEvaVoice(): string {
    return this.evaVoice;
  }

  public getAdamVoice(): string {
    return this.adamVoice;
  }

  public isVoicesReady(): boolean {
    return this.voicesReady;
  }

  /** Current month key, e.g. "2026-09". */
  public static currentMonth(d: Date = new Date()): string {
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}`;
  }

  /** Loads (and month-rolls) the persisted usage counter. */
  public getUsage(): TtsUsageState {
    const now = CloudTTS.currentMonth();
    if (this.usage && this.usage.month === now) return this.usage;
    try {
      const p = path.join(this.dataDir, 'tts-usage.json');
      if (fs.existsSync(p)) {
        const raw = JSON.parse(fs.readFileSync(p, 'utf8'));
        if (raw.month === now) {
          this.usage = { month: raw.month, chars: Number(raw.chars) || 0 };
          return this.usage;
        }
      }
    } catch {
      // Corrupt file → start fresh for this month.
    }
    this.usage = { month: now, chars: 0 };
    return this.usage;
  }

  public getMonthChars(): number {
    return this.getUsage().chars;
  }

  public getCharsLeft(): number {
    return Math.max(0, this.cap - this.getMonthChars());
  }

  private persistUsage(): void {
    try {
      fs.mkdirSync(this.dataDir, { recursive: true });
      fs.writeFileSync(
        path.join(this.dataDir, 'tts-usage.json'),
        JSON.stringify(this.getUsage(), null, 2),
        'utf8',
      );
    } catch (err: any) {
      logger.warn('CloudTTS', `Failed to persist usage counter: ${err.message}`);
    }
  }

  private cachePath(text: string, voice: string): string {
    const sha1 = crypto.createHash('sha1').update(`${voice}::${text}`).digest('hex');
    return path.join(this.cacheDir, `${sha1}.mp3`);
  }

  /** Cache hit check — cache hits never hit the API nor the usage counter. */
  public readCache(text: string, voice: string): string | null {
    try {
      const p = this.cachePath(text, voice);
      if (fs.existsSync(p) && fs.statSync(p).size > 0) {
        return fs.readFileSync(p).toString('base64');
      }
    } catch {
      // Cache read failure is non-fatal.
    }
    return null;
  }

  public writeCache(text: string, voice: string, base64Audio: string): void {
    try {
      fs.mkdirSync(this.cacheDir, { recursive: true });
      fs.writeFileSync(this.cachePath(text, voice), new Uint8Array(Buffer.from(base64Audio, 'base64')));
    } catch (err: any) {
      logger.warn('CloudTTS', `Failed to write TTS cache: ${err.message}`);
    }
  }

  /**
   * Synthesizes text to base64 MP3. Never throws — failures resolve to
   * { ok: false, error } so the chat flow can fall back to browser TTS.
   */
  public async synthesize(text: string, opts: TtsSynthesisOptions = {}): Promise<TtsSynthesisResult> {
    const clean = String(text || '').trim();
    const voice = this.resolveVoice(opts);
    const charCount = clean.length;
    const family = voiceFamily(voice);
    const payPerCharNote = familyPayPerCharNote(family);

    if (!clean) {
      return { ok: false, voice, charCount: 0, error: 'empty text' };
    }

    // 1. Cache hit path (no API call, no counter increment).
    const cached = this.readCache(clean, voice);
    if (cached) {
      return {
        ok: true,
        base64Audio: cached,
        voice,
        charCount,
        cached: true,
        charsLeftThisMonth: this.getCharsLeft(),
      };
    }

    // 2. ONLY-FREE hard cap enforcement. Refuse before spending anything.
    if (this.getMonthChars() + charCount > this.cap) {
      logger.warn('CloudTTS', `Monthly cap ${this.cap} reached (${this.getMonthChars()} used). Refusing synthesis of ${charCount} chars — falling back to browser TTS. ${payPerCharNote}`);
      return {
        ok: false,
        voice,
        charCount,
        overCap: true,
        charsLeftThisMonth: 0,
        payPerCharAfterCap: true,
        error: `Monthly free cap (${this.cap} chars) reached. ${payPerCharNote}. Falling back to browser TTS.`,
      };
    }

    // 3. Credentials.
    let token: string;
    try {
      const creds = await this.getCredentials();
      if (!creds || !creds.token) {
        return { ok: false, voice, charCount, error: 'No Google credentials available' };
      }
      token = creds.token;
    } catch (err: any) {
      return { ok: false, voice, charCount, error: `Credentials failed: ${err.message}` };
    }

    // 4. HTTP call with 10 s deadline; errors never throw into chat flow.
    try {
      const res = await withTimeout(
        this.fetchFn(TTS_ENDPOINT, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`,
            'X-Goog-User-Project': USER_PROJECT,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(buildSynthesizeRequest(clean, voice)),
        }),
        this.timeoutMs,
        'CloudTTS text:synthesize',
      );

      if (!res.ok) {
        const errBody = await res.text().catch(() => '');
        return {
          ok: false,
          voice,
          charCount,
          payPerCharAfterCap: family === 'chirp3-hd' && !this.voicesReady,
          error: `TTS API ${res.status}: ${errBody.slice(0, 200)}`,
        };
      }

      const data: any = await res.json();
      const base64Audio = data.audioContent || '';
      if (!base64Audio) {
        return { ok: false, voice, charCount, error: 'Empty audioContent from TTS API' };
      }

      this.voicesReady = true;

      // 5. Persist counter AFTER a successful synthesis (charge once).
      const usage = this.getUsage();
      usage.chars += charCount;
      this.persistUsage();

      // 6. Cache identical (text+voice) results.
      this.writeCache(clean, voice, base64Audio);

      return {
        ok: true,
        base64Audio,
        voice,
        charCount,
        cached: false,
        charsLeftThisMonth: this.getCharsLeft(),
      };
    } catch (err: any) {
      return { ok: false, voice, charCount, error: `TTS request failed: ${err.message}` };
    }
  }

  /**
   * Lists voices for a language (e.g. ru-RU, uk-UA) via GET /v1/voices.
   * Used for /api/tts/status "voicesReady" and for diagnostics.
   */
  public async listVoices(lang?: string): Promise<Array<{ name: string; gender: string }>> {
    try {
      const creds = await this.getCredentials();
      if (!creds || !creds.token) return [];
      const url = lang
        ? `${TTS_VOICES_ENDPOINT}?languageCode=${encodeURIComponent(lang)}`
        : TTS_VOICES_ENDPOINT;
      const res = await withTimeout(
        this.fetchFn(url, {
          headers: {
            'Authorization': `Bearer ${creds.token}`,
            'X-Goog-User-Project': USER_PROJECT,
          },
        }),
        this.timeoutMs,
        'CloudTTS /v1/voices',
      );
      if (!res.ok) return [];
      const data: any = await res.json();
      const voices = (data.voices || []).map((v: any) => ({
        name: v.name,
        gender: v.ssmlGender || 'UNSPECIFIED',
      }));
      this.voicesReady = voices.length > 0;
      return voices;
    } catch {
      return [];
    }
  }
}

/** Process-wide singleton used by the voice router and chat integrations. */
export const cloudTts = new CloudTTS();

/**
 * CloudSTT.ts — Google Cloud Speech-to-Text (v1 recognize) with ONLY-FREE guard.
 *
 * Design constraints:
 *  - Uses the v1 `speech:recognize` endpoint with the standard model
 *    `latest_long`, which falls under the recurring free allowance of
 *    60 minutes/month per account (chirp models are Speech-to-Text V2 only
 *    and have no published free allowance — see docs/ops/CLOUD_STT.md).
 *  - Enforces a module-level monthly cap (3000 s = 50 min free + safety
 *    margin) persisted in data/stt-usage.json {month, secondsUsed}.
 *    Requests are REFUSED once the cap is reached — never silently spend money.
 *  - Auth: Bearer token from GoogleAuthProvider + required
 *    `X-Goog-User-Project: evabot-agent-server` header.
 *  - 15 s hard deadline via Resilience.withTimeout; never throws into the
 *    request path (errors are returned on the SttResult).
 *  - ffmpeg fallback chain: OGG_OPUS attempt → FLAC 16 kHz mono retry.
 */

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { logger, LogCategory } from './Logger.js';
import { GoogleAuthProvider } from './GoogleAuthProvider.js';
import { withTimeout } from './Resilience.js';

export const STT_ENDPOINT = 'https://speech.googleapis.com/v1/speech:recognize';
export const STT_PROJECT_HEADER = 'evabot-agent-server';
/** v1 standard model → included in the 60 min/month free tier (chirp is V2-only, paid from min 1). */
export const STT_MODEL = 'latest_long';
/** 3600 s free tier  600 s safety margin = 3000 s. */
export const STT_MONTHLY_CAP_SECONDS = 3000;
export const STT_TIMEOUT_MS = 15_000;

export const STT_USAGE_PATH = path.resolve(process.cwd(), 'data', 'stt-usage.json');

export type SttLanguage = 'uk-UA' | 'ru-RU' | 'en-US';
export type SttEncoding = 'OGG_OPUS' | 'FLAC' | 'WEBM_OPUS' | 'LINEAR16';

export interface SttOptions {
  lang?: SttLanguage;
  encoding?: SttEncoding;
  sampleRate?: number;
  /** Override billed/estimated duration (e.g. Telegram voice.duration). */
  durationSeconds?: number;
}

export interface SttResult {
  transcript: string;
  confidence: number;
  secondsBilled: number;
  ok: boolean;
  error?: string;
  usedFallbackFlac?: boolean;
}

export interface SttUsage {
  month: string;
  secondsUsed: number;
}

/** Current billing month key, UTC (e.g. '2026-09'). */
export function monthKey(date: Date = new Date()): string {
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`;
}

export function readUsage(): SttUsage {
  try {
    const raw = fs.readFileSync(STT_USAGE_PATH, 'utf8');
    const parsed = JSON.parse(raw) as SttUsage;
    if (parsed && parsed.month === monthKey() && typeof parsed.secondsUsed === 'number') {
      return parsed;
    }
  } catch {
    // missing / corrupted / previous month → fresh counter
  }
  return { month: monthKey(), secondsUsed: 0 };
}

export function writeUsage(usage: SttUsage): void {
  const dir = path.dirname(STT_USAGE_PATH);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(STT_USAGE_PATH, JSON.stringify(usage, null, 2), 'utf8');
}

/** Whether `seconds` more could be billed this month without breaching the cap. */
export function isWithinCap(seconds: number, usage: SttUsage = readUsage()): boolean {
  if (usage.month !== monthKey()) return true;
  return usage.secondsUsed + seconds <= STT_MONTHLY_CAP_SECONDS;
}

export function recordUsage(seconds: number, usage: SttUsage = readUsage()): SttUsage {
  const fresh = usage.month === monthKey()
    ? usage
    : { month: monthKey(), secondsUsed: 0 };
  fresh.secondsUsed += seconds;
  writeUsage(fresh);
  return fresh;
}

/** Test helper: reset the monthly counter to zero (fresh month). */
export function resetUsageForTest(): void {
  writeUsage({ month: monthKey(), secondsUsed: 0 });
}

/**
 * Size-based duration estimate used when no explicit duration is provided:
 *  - FLAC / LINEAR16 16 kHz mono 16-bit  32 000 bytes/s
 *  - Opus (OGG/WEBM)  48 kbps  6 000 bytes/s (typical Telegram voice)
 * Always rounds up to the next whole second (Google rounds up too).
 */
export function estimateAudioSeconds(sizeBytes: number, encoding: SttEncoding = 'OGG_OPUS', sampleRate: number = 16000): number {
  const bytesPerSecond = encoding === 'FLAC' || encoding === 'LINEAR16'
    ? Math.max(4000, sampleRate * 2)
    : 6000;
  return Math.max(1, Math.ceil(sizeBytes / bytesPerSecond));
}

/** ffprobe-based duration (best effort); returns null when ffprobe is unavailable. */
export function probeAudioSeconds(audio: Buffer): number | null {
  const tmpIn = path.join(os.tmpdir(), `evabot-stt-probe-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  try {
    fs.writeFileSync(tmpIn, audio);
    const out = execFileSync('ffprobe', [
      '-v', 'error',
      '-show_entries', 'format=duration',
      '-of', 'default=noprint_wrappers=1:nokey=1',
      tmpIn,
    ], { encoding: 'utf8', timeout: 4000 });
    const seconds = parseFloat(out.trim());
    if (Number.isFinite(seconds) && seconds > 0) {
      return Math.ceil(seconds);
    }
  } catch {
    // ffprobe missing or unreadable container → caller falls back to estimate
  } finally {
    try { fs.unlinkSync(tmpIn); } catch { /* ignore */ }
  }
  return null;
}

/** ffmpeg argument vector for the 16 kHz mono FLAC fallback conversion. */
export function buildFfmpegFlacArgs(input: string, output: string): string[] {
  return ['-y', '-i', input, '-ar', '16000', '-ac', '1', '-f', 'flac', output];
}

/** Converts arbitrary input audio to FLAC 16 kHz mono via ffmpeg. Returns null on failure. */
export function convertToFlac16k(audio: Buffer): Buffer | null {
  const tmpIn = path.join(os.tmpdir(), `evabot-stt-in-${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const tmpOut = `${tmpIn}.flac`;
  try {
    fs.writeFileSync(tmpIn, audio);
    execFileSync('ffmpeg', buildFfmpegFlacArgs(tmpIn, tmpOut), { encoding: 'utf8', timeout: 30_000 });
    const flac = fs.readFileSync(tmpOut);
    return flac.length > 0 ? flac : null;
  } catch (err: any) {
    logger.warn(LogCategory.SYSTEM, 'CloudSTT', `ffmpeg FLAC conversion failed: ${err.message}`);
    return null;
  } finally {
    try { fs.unlinkSync(tmpIn); } catch { /* ignore */ }
    try { fs.unlinkSync(tmpOut); } catch { /* ignore */ }
  }
}

/**
 * Pure request builder for speech:recognize.
 *  - FLAC: sample rate is auto-detected from the header (omitted).
 *  - OGG_OPUS / WEBM_OPUS: defaults to 48000 (Telegram voice is 48 kHz).
 *  - LINEAR16: sampleRate is required.
 */
export function buildRecognizeRequest(
  audioBase64: string,
  opts: SttOptions = {}
): { config: Record<string, unknown>; audio: { content: string } } {
  const encoding: SttEncoding = opts.encoding || 'OGG_OPUS';
  const config: Record<string, unknown> = {
    languageCode: opts.lang || 'uk-UA',
    model: STT_MODEL,
    enableAutomaticPunctuation: true,
  };
  if (encoding === 'LINEAR16') {
    config.encoding = encoding;
    config.sampleRateHertz = opts.sampleRate || 16000;
  } else if (encoding === 'FLAC') {
    config.encoding = encoding; // sampleRateHertz auto-detected from FLAC header
  } else {
    config.encoding = encoding;
    config.sampleRateHertz = opts.sampleRate || 48000;
  }
  return { config, audio: { content: audioBase64 } };
}

async function callRecognizeApi(
  audioBase64: string,
  opts: SttOptions
): Promise<{ transcript: string; confidence: number; error?: string }> {
  const creds = await GoogleAuthProvider.getCredentials();
  if (!creds || creds.type !== 'bearer') {
    return { transcript: '', confidence: 0, error: 'NO_GOOGLE_CREDENTIALS' };
  }

  const body = JSON.stringify(buildRecognizeRequest(audioBase64, opts));
  const res = await withTimeout(
    fetch(STT_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${creds.token}`,
        'X-Goog-User-Project': STT_PROJECT_HEADER,
      },
      body,
    }),
    STT_TIMEOUT_MS,
    'CloudSTT speech:recognize'
  );

  const data: any = await res.json().catch(() => null);
  if (!res.ok) {
    const msg = data?.error?.message || `HTTP ${res.status}`;
    return { transcript: '', confidence: 0, error: `STT_API_ERROR: ${msg}` };
  }

  const result = data?.results?.[0]?.alternatives?.[0];
  return {
    transcript: (result?.transcript || '').trim(),
    confidence: typeof result?.confidence === 'number' ? result.confidence : 0,
  };
}

/**
 * Transcribes audio via Google Cloud STT v1 (model latest_long) under the
 * monthly ONLY-FREE cap. Never throws — failures come back on the result.
 */
export async function transcribeAudio(
  audio: Buffer | string,
  opts: SttOptions = {}
): Promise<SttResult> {
  try {
    const buf = typeof audio === 'string' ? Buffer.from(audio, 'base64') : audio;
    if (!buf || buf.length === 0) {
      return { transcript: '', confidence: 0, secondsBilled: 0, ok: false, error: 'EMPTY_AUDIO' };
    }

    // ONLY-FREE guard: refuse BEFORE spending when this request would breach the cap.
    const encoding: SttEncoding = opts.encoding || 'OGG_OPUS';
    const estSeconds = opts.durationSeconds
      ?? probeAudioSeconds(buf)
      ?? estimateAudioSeconds(buf.length, encoding, opts.sampleRate || (encoding === 'FLAC' ? 16000 : 48000));
    if (!isWithinCap(estSeconds)) {
      const usage = readUsage();
      logger.warn(LogCategory.SYSTEM, 'CloudSTT', `Monthly STT cap reached (${usage.secondsUsed}/${STT_MONTHLY_CAP_SECONDS}s) — request refused`);
      return {
        transcript: '',
        confidence: 0,
        secondsBilled: 0,
        ok: false,
        error: `MONTHLY_CAP_REACHED (used ${usage.secondsUsed}s / cap ${STT_MONTHLY_CAP_SECONDS}s; resets ${monthKey()}→next month)`,
      };
    }

    const audioBase64 = buf.toString('base64');
    const res = await callRecognizeApi(audioBase64, opts);
    if (res.error) {
      return { transcript: '', confidence: 0, secondsBilled: 0, ok: false, error: res.error };
    }

    // Bill actual (rounded-up) duration; ffprobe on real audio beats the estimate.
    const billed = opts.durationSeconds ?? probeAudioSeconds(buf) ?? estSeconds;
    recordUsage(billed);
    logger.info(LogCategory.SYSTEM, 'CloudSTT', `Transcribed ${billed}s audio, confidence ${res.confidence.toFixed(2)}`);

    return { transcript: res.transcript, confidence: res.confidence, secondsBilled: billed, ok: true };
  } catch (err: any) {
    logger.warn(LogCategory.SYSTEM, 'CloudSTT', `transcribeAudio failed: ${err.message}`);
    return { transcript: '', confidence: 0, secondsBilled: 0, ok: false, error: err.message };
  }
}

/**
 * Preferred chain for Telegram voice (.ogg/opus) and CLI /listen:
 * 1. OGG_OPUS @ 48 kHz direct attempt.
 * 2. On API failure (not cap refusal): ffmpeg → FLAC 16 kHz mono, retry FLAC.
 */
export async function transcribeVoiceWithFallback(
  audio: Buffer,
  opts: SttOptions = {}
): Promise<SttResult> {
  const first = await transcribeAudio(audio, { ...opts, encoding: opts.encoding || 'OGG_OPUS', sampleRate: opts.sampleRate || 48000 });
  if (first.ok || (first.error || '').includes('MONTHLY_CAP_REACHED')) return first;

  const flac = convertToFlac16k(audio);
  if (!flac) return first;

  const second = await transcribeAudio(flac, { ...opts, encoding: 'FLAC' });
  if (second.ok) return { ...second, usedFallbackFlac: true };
  return { ...first, error: `${first.error} | FLAC fallback: ${second.error}` };
}

import { Router, withErrorHandling } from './Router.js';
import { cloudTts } from '../../core/CloudTTS.js';
import {
  transcribeAudio,
  transcribeVoiceWithFallback,
  type SttEncoding,
  type SttLanguage,
  type SttResult,
} from '../../core/CloudSTT.js';
import { logger, LogCategory } from '../../core/Logger.js';

const MAX_UPLOAD_BYTES = 25 * 1024 * 1024;

function readRawBody(req: import('node:http').IncomingMessage): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_UPLOAD_BYTES) {
        reject(new Error('Audio body too large'));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

/**
 * Minimal multipart/form-data extractor: returns the first part that carries
 * a filename (or the name "audio"/"file"), decoded between the CRLF headers
 * and the trailing boundary delimiter.
 */
export function extractMultipartFile(body: Buffer, contentType: string): Buffer | null {
  const boundaryMatch = /boundary=(?:"([^"]+)"|([^;]+))/i.exec(contentType);
  if (!boundaryMatch) return null;
  const boundary = `--${(boundaryMatch[1] || boundaryMatch[2]).trim()}`;
  const marker = Buffer.from(boundary);
  let start = body.indexOf(marker);
  while (start !== -1) {
    const headerEnd = body.indexOf('\r\n\r\n', start);
    if (headerEnd === -1) break;
    const headers = body.slice(start, headerEnd).toString('utf8');
    const nextBoundary = body.indexOf(marker, headerEnd);
    if (nextBoundary === -1) break;
    const isFile = /filename="/.test(headers) || /name="(audio|file)"/i.test(headers);
    if (isFile) {
      let end = nextBoundary;
      if (body[end - 2] === 13 && body[end - 1] === 10) end -= 2;
      return body.slice(headerEnd + 4, end);
    }
    start = nextBoundary;
  }
  return null;
}

function normalizeLang(raw: string | null): SttLanguage {
  if (raw === 'ru-RU' || raw === 'ru') return 'ru-RU';
  if (raw === 'en-US' || raw === 'en') return 'en-US';
  return 'uk-UA';
}

function normalizeEncoding(raw: string | null): SttEncoding | undefined {
  const v = (raw || '').toUpperCase();
  if (v === 'OGG_OPUS' || v === 'FLAC' || v === 'WEBM_OPUS' || v === 'LINEAR16') return v;
  return undefined;
}

function sendSttResult(ctx: { sendJson: (s: number, d: any) => void }, result: SttResult): void {
  if (result.ok) {
    ctx.sendJson(200, { transcript: result.transcript, confidence: result.confidence, secondsBilled: result.secondsBilled });
    return;
  }
  if ((result.error || '').includes('MONTHLY_CAP_REACHED')) {
    ctx.sendJson(429, { error: result.error });
    return;
  }
  ctx.sendJson(502, { error: result.error || 'STT_FAILED' });
}

export function createVoiceRouter(): Router {
  const router = new Router();

  // POST /api/tts  {text, persona: 'eva'|'adam', lang?} → {ok, audioBase64, voice, cached}
  router.post('/api/tts', withErrorHandling(async (ctx) => {
    const body = await ctx.parseJsonBody();
    const text = typeof body?.text === 'string' ? body.text : '';
    if (!text.trim()) {
      ctx.sendJson(400, { ok: false, error: 'Missing "text".' });
      return;
    }
    const persona = body?.persona === 'adam' ? 'adam' : body?.persona === 'eva' ? 'eva' : undefined;
    const lang = typeof body?.lang === 'string' ? body.lang : undefined;
    const result = await cloudTts.synthesize(text, { persona, lang });
    if (result.ok && result.base64Audio) {
      ctx.sendJson(200, { ok: true, audioBase64: result.base64Audio, mimeType: 'audio/mp3', voice: result.voice, cached: result.cached, overCap: false });
    } else {
      ctx.sendJson(200, { ok: false, fallback: 'browser-tts', error: result.error || 'synthesis failed', overCap: result.overCap === true });
    }
  }));

  // GET /api/tts/status → voices, usage vs free cap
  router.get('/api/tts/status', withErrorHandling(async (ctx) => {
    const usage = cloudTts.getUsage();
    ctx.sendJson(200, {
      voicesReady: true,
      evaVoice: cloudTts.getEvaVoice(),
      adamVoice: cloudTts.getAdamVoice(),
      monthChars: usage.chars,
      cap: cloudTts.getCap(),
      remainingChars: cloudTts.getCharsLeft(),
      freeTier: 'wavenet-1M/mo',
    });
  }));

  // POST /api/stt?lang=uk-UA&encoding=OGG_OPUS
  // Accepts: raw audio body (audio/* or application/octet-stream),
  // multipart/form-data (first file part), or JSON {audio: <base64>}.
  router.post('/api/stt', withErrorHandling(async (ctx) => {
    const lang = normalizeLang(ctx.query.get('lang'));
    const encoding = normalizeEncoding(ctx.query.get('encoding'));
    const sampleRateRaw = parseInt(ctx.query.get('sampleRate') || '', 10);
    const sampleRate = Number.isFinite(sampleRateRaw) ? sampleRateRaw : undefined;
    const useFallback = ctx.query.get('fallback') !== 'false';

    const contentType = (ctx.req.headers['content-type'] || '').toLowerCase();
    let audio: Buffer | null = null;

    if (contentType.includes('multipart/form-data')) {
      const body = await readRawBody(ctx.req);
      audio = extractMultipartFile(body, ctx.req.headers['content-type'] || '');
    } else if (contentType.includes('application/json')) {
      const body = await ctx.parseJsonBody();
      if (body && typeof body.audio === 'string' && body.audio) {
        audio = Buffer.from(body.audio, 'base64');
      }
    } else if (contentType.startsWith('audio/') || contentType.includes('octet-stream') || contentType === '') {
      audio = await readRawBody(ctx.req);
    }

    if (!audio || audio.length === 0) {
      ctx.sendJson(400, { error: 'No audio payload. Send raw body, multipart file part, or JSON {audio: base64}.' });
      return;
    }

    logger.info(LogCategory.HTTP, 'STT', `${ctx.pathname} lang=${lang} encoding=${encoding || 'auto'} bytes=${audio.length} ip=${ctx.clientIp}`);
    const result = useFallback
      ? await transcribeVoiceWithFallback(audio, { lang, encoding, sampleRate })
      : await transcribeAudio(audio, { lang, encoding, sampleRate });
    sendSttResult(ctx, result);
  }));

  return router;
}

import crypto from 'node:crypto';
import { Config } from './Config.js';

/**
 * DeveloperMode — password-protected "developer mode" per chat session.
 *
 * Sessions unlock via `/developer unlock <password>` and stay unlocked for
 * UNLOCK_TTL_MS (2h). The password comes from env EVADEV_PASSWORD (exposed as
 * Config.developerPassword). Verification is constant-time (sha256 +
 * crypto.timingSafeEqual) and the raw password is NEVER echoed back nor
 * persisted — ChatRouter/ChatEngine mask it through maskPasswordIn() before
 * writing to ChatHistoryStore.
 */
export interface DeveloperCommand {
  sub: 'unlock' | 'status' | 'lock' | 'help';
  password?: string;
}

interface UnlockEntry {
  expiresAt: number;
}

const UNLOCK_TTL_MS = 2 * 60 * 60 * 1000; // 2h
const unlocks = new Map<string, UnlockEntry>();

/** Injectable clock so tests can simulate TTL expiry without real timers. */
let nowFn: () => number = () => Date.now();

/**
 * Session context of the command currently being executed. Set by the
 * transports (TelegramBot → `tg-<chatId>`, ModelsRouter /api/models/command →
 * body.sessionId) before ModelCommand.execute; plain CLI leaves it unset and
 * falls back to DEFAULT_SESSION ('cli').
 */
let activeSession: string | null = null;

export class DeveloperMode {
  public static readonly UNLOCK_TTL_MS = UNLOCK_TTL_MS;
  public static readonly DEFAULT_SESSION = 'cli';

  /** Sets the session context for the command about to execute. */
  public static setActiveSession(sessionId?: string): void {
    activeSession = sessionId && sessionId.trim() ? sessionId.trim() : null;
  }

  /** Clears the session context (returns to the CLI default). */
  public static clearActiveSession(): void {
    activeSession = null;
  }

  /** Test hook: override the clock (pass Date.now to restore). */
  public static setClock(fn: () => number): void {
    nowFn = fn;
  }

  /** Live password: env wins so tests / runtime re-exports take effect immediately. */
  public static getPassword(): string {
    return (process.env.EVADEV_PASSWORD || Config.developerPassword || '').trim();
  }

  /** Constant-time password verification (sha256 + timingSafeEqual). */
  public static verify(password: string): boolean {
    const expected = this.getPassword();
    if (!expected || !password) return false;
    const a = crypto.createHash('sha256').update(password, 'utf8').digest();
    const b = crypto.createHash('sha256').update(expected, 'utf8').digest();
    return crypto.timingSafeEqual(a, b);
  }

  /** Resolves the effective session id: explicit → active → CLI default. */
  public static resolveSession(sessionId?: string): string {
    return (sessionId && sessionId.trim()) || activeSession || this.DEFAULT_SESSION;
  }

  /** Unlock a session; returns false on wrong password or missing env config. */
  public static unlock(sessionId: string, password: string): boolean {
    if (!this.verify(password)) return false;
    unlocks.set(this.resolveSession(sessionId), { expiresAt: nowFn() + UNLOCK_TTL_MS });
    return true;
  }

  /** Whether the session is currently unlocked (lazily prunes expired entries). */
  public static isUnlocked(sessionId: string): boolean {
    const entry = unlocks.get(this.resolveSession(sessionId));
    if (!entry) return false;
    if (nowFn() >= entry.expiresAt) {
      unlocks.delete(this.resolveSession(sessionId));
      return false;
    }
    return true;
  }

  /** Remaining TTL (ms) or 0 when locked. */
  public static ttlRemainingMs(sessionId: string): number {
    if (!this.isUnlocked(sessionId)) return 0;
    const entry = unlocks.get(this.resolveSession(sessionId))!;
    return Math.max(0, entry.expiresAt - nowFn());
  }

  /** Explicit lock; returns true when the session WAS unlocked. */
  public static lock(sessionId: string): boolean {
    const was = this.isUnlocked(sessionId);
    unlocks.delete(this.resolveSession(sessionId));
    return was;
  }

  /** Human status line: locked/unlocked + TTL. */
  public static statusLine(sessionId: string): string {
    if (this.isUnlocked(sessionId)) {
      const mins = Math.round(this.ttlRemainingMs(sessionId) / 60000);
      return `[DEV-ON] Режим розробника АКТИВНИЙ (сесія ${this.resolveSession(sessionId)}) — автозакриття через ~${mins} хв.`;
    }
    return `[DEV-OFF] Режим розробника ЗАЧИНЕНО (сесія ${this.resolveSession(sessionId)}).`;
  }

  /** Full wipe (tests). */
  public static resetAll(): void {
    unlocks.clear();
  }

  /**
   * Masks the password argument in persisted chat history:
   * "/developer unlock MyS3cret" → "/developer unlock ****".
   * Handles EN + UK command spellings and any leading whitespace.
   */
  public static maskPasswordIn(text: string): string {
    if (!text) return text;
    return text.replace(
      /^(\s*\/(?:developer|девелопер|розробник)\s+unlock\s+)([^\s]+)(.*)$/i,
      (_m, head: string, _pwd: string, tail: string) => `${head}****${tail}`
    );
  }

  /**
   * Parses a raw /developer command while PRESERVING the password casing
   * (normalizeCommand lowercases everything, so the raw string is parsed here).
   * Returns null when the input is not a /developer command.
   */
  public static parseCommand(raw: string): DeveloperCommand | null {
    const trimmed = (raw || '').trim();
    if (!trimmed) return null;
    const spaceIdx = trimmed.indexOf(' ');
    const head = (spaceIdx === -1 ? trimmed : trimmed.slice(0, spaceIdx))
      .toLowerCase()
      .replace(/['`´ʼ’]/g, "'");
    // Command head spellings (kept in sync with COMMAND_ALIASES in ModelRatings).
    if (!['/developer', '/девелопер', '/розробник'].includes(head)) return null;
    const rest = spaceIdx === -1 ? '' : trimmed.slice(spaceIdx + 1).trim();
    if (!rest) return { sub: 'help' };
    const subSpace = rest.indexOf(' ');
    const sub = (subSpace === -1 ? rest : rest.slice(0, subSpace)).toLowerCase();
    if (sub === 'unlock') {
      const password = subSpace === -1 ? '' : rest.slice(subSpace + 1).trim();
      return { sub: 'unlock', password };
    }
    if (sub === 'status') return { sub: 'status' };
    if (sub === 'lock') return { sub: 'lock' };
    return { sub: 'help' };
  }
}

import os from 'node:os';
import { Config } from './Config.js';
import { BREAKER_PROVIDER_NAMES, getBreaker, providerOfModel } from './Resilience.js';
import { ProductCatalog } from './ProductCatalog.js';
import { knowledgeBase } from './KnowledgeBase.js';

export interface LastUsedModelInfo {
  model: string;
  provider: string;
  ts: number;
}

/**
 * Module-level "last model actually used by a chat request" registry.
 * ChatRouter / ChatEngine update it on every request so SystemContext can
 * answer "какая сейчас подключена модель?" with the REAL model, not a guess.
 */
let lastUsedModel: LastUsedModelInfo | null = null;

export function recordLastUsedModel(model: string, provider: string): void {
  const changed = !lastUsedModel || lastUsedModel.model !== model || lastUsedModel.provider !== provider;
  lastUsedModel = { model, provider, ts: Date.now() };
  // A different model just served a request → the 60s-cached block is stale.
  if (changed) SystemContext.invalidate();
}

export function getLastUsedModel(): LastUsedModelInfo | null {
  return lastUsedModel;
}

/**
 * SystemContext — compact self-awareness block (1200 chars) describing the
 * CURRENT EvaBot runtime: active/default model, proxy endpoint, breaker
 * health (state reads only, no network), cluster topology, key services,
 * company identity and catalog/KB stats. Cached for 60s.
 */
export class SystemContext {
  public static readonly CACHE_TTL_MS = 60_000;
  public static readonly MAX_CHARS = 1200;

  private static cache: { text: string; ts: number } | null = null;

  /** Drops the cached block (used by tests and by recordLastUsedModel consumers). */
  public static invalidate(): void {
    this.cache = null;
  }

  /**
   * Full developer-mode prompt addendum (FEATURE 2). Injected by ChatRouter /
   * ChatEngine only when the session is unlocked via /developer unlock.
   */
  public static readonly DEVELOPER_BLOCK: string =
    'Ти в режимі розробника. Відповідай максимально повно і технічно: повні шляхи файлів, команди, конфіги, моделі, витрати, ключі (крім самих секретів — показуй тільки префікси), архітектура, код. Не приховуй внутрішню інформацію системи EvaBot/EvaLine.';

  public static build(): string {
    if (this.cache && Date.now() - this.cache.ts < this.CACHE_TTL_MS) {
      return this.cache.text;
    }
    const text = this.render();
    this.cache = { text, ts: Date.now() };
    return text;
  }

  private static render(): string {
    const defaultModel = Config.defaultModel;
    const last = getLastUsedModel();
    const lastLine = last
      ? `Остання використана модель: ${last.model} (provider: ${last.provider})`
      : 'Остання використана модель: ще не використовувалась у цій сесії процесу';

    // Breaker health: state snapshot only (no network calls).
    let closed = 0;
    let halfOpen = 0;
    let open = 0;
    try {
      for (const name of BREAKER_PROVIDER_NAMES) {
        const st = getBreaker(name).snapshot().state;
        if (st === 'open') open += 1;
        else if (st === 'half-open') halfOpen += 1;
        else closed += 1;
      }
    } catch {
      /* breaker stats are best-effort */
    }
    const breakerLine = `Breakers: ${closed} closed / ${halfOpen} half-open / ${open} open (з ${BREAKER_PROVIDER_NAMES.length})`;

    // Product + KB stats (local reads only).
    let productCount = 0;
    try {
      productCount = ProductCatalog.stats().total;
    } catch {
      /* catalog is best-effort */
    }
    let kbLine = 'База знань: недоступна';
    try {
      const kbStats = knowledgeBase.getStats();
      kbLine = `База знань: ${kbStats.documentCount} документів (${kbStats.name})`;
    } catch {
      /* KB is best-effort */
    }

    const lines: string[] = [
      `[SYSTEM CONTEXT — власне середовище бота EvaBot, оновлено ${new Date().toISOString().substring(0, 16)}]`,
      `Модель за замовчуванням: ${defaultModel} (provider: ${providerOfModel(defaultModel)})`,
      lastLine,
      `OmniRoute edge-proxy: ${Config.omnirouteBaseUrl} (роутер моделей, health не перевіряється тут)`,
      breakerLine,
      'Кластер: [1] evabot-agent-vm — europe-west3-a, c3-standard-8 (ЦЕЙ сервер, brain/бекенд) · [2] evabot-micro — us-central1-a (frontend edge/face)',
      'Сервіси: evabot-brain :3000 (Node/TS) · omniroute :20128 · voice :8000 · n8n (docker)',
      'Компанія: ТОВ ЕВА-ЛАЙН, ЄДРПОУ 40484497, м. Чорноморськ Одеська обл. — виробник піни EVA (EVA-піна), 2 учасники, каптал 16 000 000 ₴',
      `Продукти: ${productCount} у data/products.json`,
      kbLine,
    ];
    let text = lines.join('\n');
    if (text.length > this.MAX_CHARS) text = `${text.substring(0, this.MAX_CHARS - 1)}…`;
    return text;
  }

  /** Used by the CLI dashboard/tests to confirm this VM identity. */
  public static isBrainVm(): boolean {
    return os.hostname().length > 0 && Config.serverPort > 0;
  }
}

