export interface SephirotRunOptions {
  rounds?: number;
  synthesizerModel?: string;
  useKnowledgeBase?: boolean;
}

export interface SephirotStatus {
  running: boolean;
  topic: string;
  startedAt?: number;
  finishedAt?: number;
  durationMs?: number;
  rounds?: number;
  error?: string;
  synthesis?: string;
}

const SEPHIROT_SESSION_ID = 'sephirot';
const DEFAULT_SYNTHESIZER_MODEL = 'gemini-3.1-pro';

export class SephirotEngine {
  private static status: SephirotStatus = { running: false, topic: '' };

  /**
   * Maps the 10 Sephirot nodes onto ConsiliumParticipant shapes accepted by
   * ConsiliumEngine (id/model/name/title/systemPrompt/temperature). Nodes are
   * emitted in BFS tree order so each consilium round walks the tree top-down:
   * crown level (vision/strategy/analysis) speaks first, the middle tree second,
   * foundation/execution last.
   */
  public static buildParticipants(topic: string): ConsiliumParticipant[] {
    return SEPHIROT_ROLES.map((node) => {
      const parents = node.parentIds.map((pid) => SEPHIROT_ROLES.find((n) => n.id === pid)?.sephira || pid);
      const upstream = parents.length
        ? ` You receive input from: ${parents.join(', ')}.`
        : ' You are the root of the tree.';
      return {
        id: `sephira-${node.id}`,
        model: node.model,
        name: node.nameEn,
        title: node.title,
        systemPrompt: `${node.systemPrompt}${upstream} Topic under deliberation: "${topic}".`,
        temperature: node.voicePersona === 'neutral' ? 0.4 : 0.6,
      };
    });
  }

  public static async runSephirotConsilium(
    topic: string,
    options: SephirotRunOptions = {}
  ): Promise<ConsiliumResult> {
    const cleanTopic = (topic || '').trim();
    if (!cleanTopic) throw new Error('Sephirot consilium requires a non-empty topic');

    const rounds = Math.max(1, Math.min(options.rounds ?? 3, 4));
    const synthesizerModel = options.synthesizerModel || DEFAULT_SYNTHESIZER_MODEL;
    const participants = this.buildParticipants(cleanTopic);

    this.status = { running: true, topic: cleanTopic, startedAt: Date.now(), rounds };

    const engine = new ConsiliumEngine(Config.geminiApiKey || undefined);
    try {
      const result = await engine.run({
        mode: 'consilium',
        prompt: this.buildPrompt(cleanTopic),
        participants,
        rounds,
        synthesizerModel,
        useKnowledgeBase: options.useKnowledgeBase ?? true,
      });

      this.status = {
        running: false,
        topic: cleanTopic,
        startedAt: this.status.startedAt,
        finishedAt: Date.now(),
        durationMs: result.durationMs,
        rounds,
        synthesis: result.synthesis,
      };

      this.persistResult(cleanTopic, result);
      return result;
    } catch (err: any) {
      this.status = {
        running: false,
        topic: cleanTopic,
        startedAt: this.status.startedAt,
        finishedAt: Date.now(),
        error: err.message,
      };
      throw err;
    }
  }

  /**
   * The 10-node consilium prompt: explains the decision hierarchy so every
   * agent knows where it sits in the Sephirot tree.
   */
  private static buildPrompt(topic: string): string {
    const tree = SEPHIROT_ROLES.map((n) => {
      const parents = n.parentIds.length ? n.parentIds.join(' + ') : '(root)';
      return `- ${n.id} [stage ${n.stage}] (${n.sephira}) ← parents: ${parents}`;
    }).join('\n');
    return (
      `Sephirot consilium on the topic: "${topic}".\n\n` +
      `Ten agents are arranged on the Tree of Life decision hierarchy:\n${tree}\n\n` +
      `Deliberate across the Tetraxis axes — Vision → Strategy → Execution → Feedback — ` +
      `respecting the parent-child flow: intention (Kether) splits into force (Chokmah) and form (Binah), ` +
      `growth (Chesed) is bounded by severity (Gevurah), balanced by beauty (Tiferet), sustained by endurance (Netzach), ` +
      `communicated by splendor (Hod), grounded in data (Yesod) and executed in the kingdom (Malkuth).`
    );
  }

  /**
   * Fire-and-forget persistence + status, mirroring how ChatRouter persists
   * consilium runs into the shared chat-history DB.
   */
  private static persistResult(topic: string, result: ConsiliumResult): void {
    try {
      const store = ChatHistoryStore.getInstance();
      const lang = I18nEngine.getLocale();
      store.appendMessage({ sessionId: SEPHIROT_SESSION_ID, role: 'user', content: topic, model: 'sephirot', lang });
      if (result.synthesis) {
        store.appendMessage({ sessionId: SEPHIROT_SESSION_ID, role: 'assistant', content: result.synthesis, model: 'sephirot', lang });
      }
    } catch (err: any) {
      logger.warn('SephirotEngine', `History persistence skipped: ${err.message}`);
    }
  }

  public static getStatus(): SephirotStatus {
    return { ...this.status };
  }

  /**
   * Synchronous entrypoint used by ModelCommand. Long runs (minutes) are
   * launched in the background and tracked via getStatus(), so /sephirot
   * returns immediately with an acknowledgement, like /consilium does in the
   * web/CLI async paths.
   */
  public static startAsyncRun(topic: string, options: SephirotRunOptions = {}): string {
    if (this.status.running) {
      return `[SEPHIROT] Уже запущено: "${this.status.topic}" (з ${new Date(this.status.startedAt || 0).toISOString()}). Статус: /sephirot status`;
    }
    const cleanTopic = (topic || '').trim();
    if (!cleanTopic) {
      return 'Використання: /sephirot <тема>. Статус: /sephirot status';
    }
    void this.runSephirotConsilium(cleanTopic, options).catch((err: any) => {
      logger.error('SephirotEngine', `Background sephirot run failed: ${err.message}`);
    });
    return (
      ` SEPHIROT CONSILIUM — запущено (10 сфер Дерева Життя, Tetraxis loops).\n` +
      `  Тема: "${cleanTopic}"\n` +
      `  Це може тривати кілька хвилин. Прогрес/результат: /sephirot status\n` +
      `  Синтез буде збережено в сесії "sephirot" чат-історії (/history, /search).`
    );
  }
}

import { logger } from './Logger.js';
import { GoogleAuthProvider, DEFAULT_GEMINI_API_KEY } from './GoogleAuthProvider.js';
import { Config } from './Config.js';

export interface ChatMessagePart {
  text: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  parts: ChatMessagePart[];
}

export interface GenerationOptions {
  temperature?: number;
  maxOutputTokens?: number;
  systemInstruction?: string;
  signal?: AbortSignal;
}

/**
 * Which backend a resolved credential is meant for.
 *  - 'generativelanguage' → Gemini API free tier ($0, per-key quota) via the
 *    AIza API key. DEFAULT path — NEVER sends paid traffic.
 *  - 'vertex' → Vertex AI (paid on-demand per-token, no free tier) via OAuth
 *    bearer. ONLY used on explicit opt-in (EVA_VERTEX_ENABLED=1 or the caller
 *    explicitly set a bearer token).
 */
export type GeminiEndpoint = 'generativelanguage' | 'vertex';

export interface ResolvedGeminiAuth {
  token: string;
  type: 'api_key' | 'bearer';
  endpoint: GeminiEndpoint;
  /** Where the credential came from (for diagnostics / live verification). */
  source: string;
  headers: Record<string, string>;
}

export class GeminiClient {
  private explicitToken?: string;
  private tokenType: 'api_key' | 'bearer' = 'api_key';
  private baseUrl: string = 'https://generativelanguage.googleapis.com/v1beta';
  private vertexBaseUrl: string = 'https://europe-west3-aiplatform.googleapis.com/v1/projects/evabot-agent-server/locations/europe-west3/publishers/google';

  constructor(apiKeyOrToken?: string) {
    if (apiKeyOrToken) {
      this.setApiKey(apiKeyOrToken);
    }
  }

  /**
   * Sets an explicit credential. An AIza-style value is treated as a Gemini
   * API key (free tier); a `ya29.` OAuth token is treated as an explicit
   * Vertex opt-in (bearer → paid traffic).
   */
  public setApiKey(apiKey: string): void {
    const trimmed = apiKey.trim();
    this.explicitToken = trimmed;
    if (trimmed.startsWith('ya29.')) {
      this.tokenType = 'bearer';
    } else {
      this.tokenType = 'api_key';
    }
  }

  /** Explicitly opts this client into paid Vertex traffic with a bearer token. */
  public setBearerToken(token: string): void {
    this.explicitToken = token.trim();
    this.tokenType = 'bearer';
  }

  public hasApiKey(): boolean {
    return Boolean(this.explicitToken && this.explicitToken.length > 5);
  }

  /**
   * ONLY-FREE credential resolution order:
   * 1. Explicit credential set via setApiKey()/setBearerToken():
   *    - api key  → generativelanguage free tier (?key= / x-goog-api-key)
   *    - bearer   → Vertex (explicit caller opt-in — request-level override)
   * 2. EVA_VERTEX_ENABLED=1 (Config.vertexEnabled) → Vertex bearer via
   *    GoogleAuthProvider (explicit environment opt-in to paid traffic).
   * 3. Otherwise → Gemini API key free tier: GEMINI_API_KEY env (already
   *    resolved into Config.geminiApiKey) → DEFAULT_GEMINI_API_KEY fallback.
   *
   * Bearer/ADC tokens are never used against generativelanguage (they fail
   * with ACCESS_TOKEN_SCOPE_INSUFFICIENT there), and the key path must never
   * send X-Goog-User-Project (the ?key= credential bills the free tier of the
   * key's own project — a user-project header would reroute it to paid
   * billing of the ADC project).
   */
  private async resolveAuth(): Promise<ResolvedGeminiAuth> {
    if (this.explicitToken && this.explicitToken.length > 5) {
      if (this.tokenType === 'bearer') {
        return {
          token: this.explicitToken,
          type: 'bearer',
          endpoint: 'vertex',
          source: 'explicit bearer token (caller opt-in)',
          headers: { 'Authorization': `Bearer ${this.explicitToken}` },
        };
      }
      return {
        token: this.explicitToken,
        type: 'api_key',
        endpoint: 'generativelanguage',
        source: 'explicit API key (setApiKey)',
        headers: { 'x-goog-api-key': this.explicitToken },
      };
    }

    // Vertex ONLY on explicit environment opt-in (EVA_VERTEX_ENABLED=1).
    if (Config.vertexEnabled) {
      const autoCreds = await GoogleAuthProvider.getCredentials();
      if (autoCreds && autoCreds.type === 'bearer') {
        logger.info('GeminiClient', `Vertex AI explicitly enabled (${Config.vertexEnabled ? 'EVA_VERTEX_ENABLED=1' : 'opt-in'}) — using paid bearer traffic from: ${autoCreds.source}`);
        return {
          token: autoCreds.token,
          type: 'bearer',
          endpoint: 'vertex',
          source: autoCreds.source,
          headers: { 'Authorization': `Bearer ${autoCreds.token}` },
        };
      }
      logger.warn('GeminiClient', 'EVA_VERTEX_ENABLED=1 but no bearer credentials available — falling back to Gemini API free-tier key.');
    }

    // Free tier: env key (via Config) → built-in default key. $0 cost.
    const key = Config.geminiApiKey || DEFAULT_GEMINI_API_KEY;
    return {
      token: key,
      type: 'api_key',
      endpoint: 'generativelanguage',
      source: key === DEFAULT_GEMINI_API_KEY ? 'default embedded key (free tier, TODO rotate)' : 'GEMINI_API_KEY env (free tier)',
      headers: { 'x-goog-api-key': key },
    };
  }

  private getVertexLocations(cleanModel: string): string[] {
    if (cleanModel.includes('pro')) {
      return ['us-central1', 'europe-west3'];
    }
    return ['europe-west3', 'us-central1'];
  }

  private getVertexUrl(location: string, cleanModel: string, streaming: boolean): string {
    const action = streaming ? 'streamGenerateContent?alt=sse' : 'generateContent';
    return `https://${location}-aiplatform.googleapis.com/v1/projects/evabot-agent-server/locations/${location}/publishers/google/models/${encodeURIComponent(cleanModel)}:${action}`;
  }

  /**
   * Generates content without streaming
   */
  public async generateContent(
    model: string,
    contents: ChatMessage[],
    options: GenerationOptions = {}
  ): Promise<string> {
    const auth = await this.resolveAuth();
    const cleanModel = model.replace(/^models\//, '');

    const payload: any = {
      contents,
      generationConfig: {
        temperature: options.temperature ?? 0.7,
        maxOutputTokens: options.maxOutputTokens ?? 4096,
      },
    };

    if (auth.type === 'bearer') {
      if (options.systemInstruction) {
        payload.systemInstruction = {
          parts: [{ text: options.systemInstruction }],
        };
      }

      const locations = this.getVertexLocations(cleanModel);
      for (let i = 0; i < locations.length; i++) {
        const loc = locations[i];
        const url = this.getVertexUrl(loc, cleanModel, false);

      logger.debug('GeminiClient', `Sending unary request to ${cleanModel} via Vertex AI (${loc})`, {
        messageCount: contents.length,
        endpoint: auth.endpoint,
        authSource: auth.source,
      });

        const response = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...auth.headers,
          },
          body: JSON.stringify(payload),
          signal: options.signal,
        });

        if (response.status === 404) {
          logger.warn('GeminiClient', `Model "${cleanModel}" returned 404 in ${loc}.`);
          if (i < locations.length - 1) {
            continue;
          }
          if (cleanModel !== 'gemini-2.5-flash') {
            logger.warn('GeminiClient', `Model "${cleanModel}" not found on Vertex AI across locations. Falling back to gemini-2.5-flash`);
            return this.generateContent('gemini-2.5-flash', contents, options);
          }
        }

        if (!response.ok) {
          const errText = await response.text();
          let parsedErr = errText;
          try {
            const jsonErr = JSON.parse(errText);
            if (jsonErr.error?.message) parsedErr = jsonErr.error.message;
          } catch {}
          throw new Error(`Vertex AI API Error (${response.status}): ${parsedErr}`);
        }

        const data: any = await response.json();
        const candidate = data.candidates?.[0];
        const parts = candidate?.content?.parts;
        if (Array.isArray(parts) && parts.length > 0) {
          const text = parts.map((p: any) => p.text || '').join('');
          if (text.length > 0) return text;
        }
        if (candidate?.finishReason) return `[Completed with reason: ${candidate.finishReason}]`;
        return '[No response text received from model]';
      }
      throw new Error(`Model ${cleanModel} failed on all Vertex AI endpoints.`);
    } else {
      const url = `${this.baseUrl}/models/${encodeURIComponent(cleanModel)}:generateContent?key=${auth.token}`;
      if (options.systemInstruction) {
        payload.system_instruction = {
          parts: [{ text: options.systemInstruction }],
        };
      }

      logger.debug('GeminiClient', `Sending unary request to ${cleanModel}`, {
        messageCount: contents.length,
        authType: auth.type,
        endpoint: auth.endpoint,
        authSource: auth.source,
      });

      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...auth.headers,
        },
        body: JSON.stringify(payload),
        signal: options.signal,
      });

      if (!response.ok) {
        const errText = await response.text();
        let parsedErr = errText;
        try {
          const jsonErr = JSON.parse(errText);
          if (jsonErr.error?.message) parsedErr = jsonErr.error.message;
        } catch {}
        throw new Error(`Google AI API Error (${response.status}): ${parsedErr}`);
      }

      const data: any = await response.json();
      const candidate = data.candidates?.[0];
      const parts = candidate?.content?.parts;
      if (Array.isArray(parts) && parts.length > 0) {
        const text = parts.map((p: any) => p.text || '').join('');
        if (text.length > 0) return text;
      }
      if (candidate?.finishReason) return `[Completed with reason: ${candidate.finishReason}]`;
      return '[No response text received from model]';
    }
  }

  /**
   * Streams content chunk-by-chunk via Server-Sent Events (SSE)
   */
  public async streamContent(
    model: string,
    contents: ChatMessage[],
    onChunk: (chunk: string) => void,
    options: GenerationOptions = {}
  ): Promise<string> {
    const auth = await this.resolveAuth();
    const cleanModel = model.replace(/^models\//, '');

    const payload: any = {
      contents,
      generationConfig: {
        temperature: options.temperature ?? 0.7,
        maxOutputTokens: options.maxOutputTokens ?? 4096,
      },
    };

    if (auth.type === 'bearer') {
      if (options.systemInstruction) {
        payload.systemInstruction = {
          parts: [{ text: options.systemInstruction }],
        };
      }

      const locations = this.getVertexLocations(cleanModel);
      let activeResponse: Response | null = null;

      for (let i = 0; i < locations.length; i++) {
        const loc = locations[i];
        const url = this.getVertexUrl(loc, cleanModel, true);

        logger.debug('GeminiClient', `Starting stream request to ${cleanModel} via Vertex AI (${loc})`, {
          messageCount: contents.length,
          endpoint: auth.endpoint,
          authSource: auth.source,
        });

        const response = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...auth.headers,
          },
          body: JSON.stringify(payload),
          signal: options.signal,
        });

        if (response.status === 404) {
          logger.warn('GeminiClient', `Model "${cleanModel}" stream returned 404 in ${loc}.`);
          if (i < locations.length - 1) {
            continue;
          }
          if (cleanModel !== 'gemini-2.5-flash') {
            logger.warn('GeminiClient', `Model "${cleanModel}" not found on Vertex AI across locations. Falling back to gemini-2.5-flash`);
            return this.streamContent('gemini-2.5-flash', contents, onChunk, options);
          }
        }

        if (!response.ok) {
          const errText = await response.text();
          let parsedErr = errText;
          try {
            const jsonErr = JSON.parse(errText);
            if (jsonErr.error?.message) parsedErr = jsonErr.error.message;
          } catch {}
          throw new Error(`Vertex AI API Stream Error (${response.status}): ${parsedErr}`);
        }

        activeResponse = response;
        break;
      }

      if (!activeResponse || !activeResponse.body) {
        throw new Error("Response body is empty.");
      }

      return this.readStreamBody(activeResponse, onChunk);
    } else {
      const url = `${this.baseUrl}/models/${encodeURIComponent(cleanModel)}:streamGenerateContent?alt=sse&key=${auth.token}`;
      if (options.systemInstruction) {
        payload.system_instruction = {
          parts: [{ text: options.systemInstruction }],
        };
      }

      logger.debug('GeminiClient', `Starting stream request to ${cleanModel}`, {
        messageCount: contents.length,
        authType: auth.type,
        endpoint: auth.endpoint,
        authSource: auth.source,
      });

      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...auth.headers,
        },
        body: JSON.stringify(payload),
        signal: options.signal,
      });

      if (!response.ok) {
        const errText = await response.text();
        let parsedErr = errText;
        try {
          const jsonErr = JSON.parse(errText);
          if (jsonErr.error?.message) parsedErr = jsonErr.error.message;
        } catch {}
        throw new Error(`Google AI API Error (${response.status}): ${parsedErr}`);
      }

      if (!response.body) {
        throw new Error("Response body is empty.");
      }

      return this.readStreamBody(response, onChunk);
    }
  }

  private async readStreamBody(response: Response, onChunk: (chunk: string) => void): Promise<string> {
    const reader = response.body!.getReader();
    const decoder = new TextDecoder('utf-8');
    let buffer = '';
    let fullText = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed.startsWith('data: ')) {
          const jsonStr = trimmed.slice(6).trim();
          if (jsonStr === '[DONE]') continue;

          try {
            const parsed = JSON.parse(jsonStr);
            const candidate = parsed.candidates?.[0];
            const parts = candidate?.content?.parts;
            if (Array.isArray(parts)) {
              for (const part of parts) {
                if (part.text) {
                  fullText += part.text;
                  onChunk(part.text);
                }
              }
            }
          } catch {
            // Buffer fragment or invalid JSON
          }
        }
      }
    }

    // Process leftover buffer
    if (buffer.trim().startsWith('data: ')) {
      try {
        const jsonStr = buffer.trim().slice(6).trim();
        const parsed = JSON.parse(jsonStr);
        const parts = parsed.candidates?.[0]?.content?.parts;
        if (Array.isArray(parts)) {
          for (const part of parts) {
            if (part.text) {
              fullText += part.text;
              onChunk(part.text);
            }
          }
        }
      } catch {
        // ignore
      }
    }

    return fullText;
  }
}

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync, execSync } from 'node:child_process';
import { logger } from './Logger.js';

export interface AuthCredentials {
  token: string;
  type: 'bearer' | 'api_key';
  source: string;
  account: string;
}

/**
 * Gemini free-tier key resolution (TASK-331).
 * ONLY-FREE rule: keys on the Gemini API free tier cost $0.
 * The legacy hard-coded literal was REVOKED (verified 2026-09-07:
 * API_KEY_INVALID) and has been REMOVED from source control.
 *
 * Resolution order for the live free-tier key:
 * 1. `GEMINI_API_KEY` env (loaded from backend .env by Config).
 * 2. GCP Secret Manager secret `evabot-gemini-api-key`
 *    (project evabot-agent-server, Gemini API free tier, $0), read lazily
 *    on first use via `gcloud secrets versions access` (ADC is available on
 *    the VM), cached in memory for the process lifetime, 10s timeout.
 *
 * On failure the resolver returns '' so callers degrade gracefully; the key
 * value is NEVER logged — only the resolution source.
 */
const GEMINI_SECRET_NAME = 'evabot-gemini-api-key';
let cachedSecretManagerKey: string | null = null;

/** Reads the Gemini free-tier key from Secret Manager (cached in memory, '' on failure). */
export function getGeminiApiKeyFromSecretManager(): string {
  if (cachedSecretManagerKey !== null) {
    return cachedSecretManagerKey;
  }
  try {
    const out = execFileSync(
      'gcloud',
      ['secrets', 'versions', 'access', 'latest', `--secret=${GEMINI_SECRET_NAME}`],
      { encoding: 'utf8', timeout: 10_000 },
    );
    cachedSecretManagerKey = out.trim();
    logger.info('GoogleAuthProvider', `Resolved Gemini free-tier key from Secret Manager secret '${GEMINI_SECRET_NAME}'`);
  } catch {
    cachedSecretManagerKey = '';
    logger.warn('GoogleAuthProvider', `Secret Manager secret '${GEMINI_SECRET_NAME}' unavailable — Gemini key fallback degraded (key value not logged)`);
  }
  return cachedSecretManagerKey;
}

/** Env-first resolution: GEMINI_API_KEY env → Secret Manager fallback → ''. */
export function resolveGeminiApiKey(): string {
  return process.env.GEMINI_API_KEY?.trim() || getGeminiApiKeyFromSecretManager();
}

/**
 * @deprecated TASK-331 compatibility shim — keeps existing importers working
 * without the hard-coded literal. String-coerces lazily to
 * resolveGeminiApiKey() (env → Secret Manager, '' on failure). New code must
 * use resolveGeminiApiKey() or Config.geminiApiKey instead.
 */
class LazyDefaultGeminiKey {
  valueOf(): string { return resolveGeminiApiKey(); }
  toString(): string { return resolveGeminiApiKey(); }
  trim(): string { return resolveGeminiApiKey(); }
  toJSON(): string { return resolveGeminiApiKey(); }
  [Symbol.toPrimitive](): string { return resolveGeminiApiKey(); }
}

export const DEFAULT_GEMINI_API_KEY = new LazyDefaultGeminiKey() as unknown as string;

export class GoogleAuthProvider {
  private static cachedCredentials: AuthCredentials | null = null;
  private static expiresAt: number = 0;

  /**
   * Resolves the active Google Cloud / Google AI credentials automatically.
   * NOTE: bearer-first resolution is intended for Google Cloud APIs
   * (Translator, CloudTTS, CloudSTT) which require OAuth tokens.
   * Gemini (generativelanguage.googleapis.com) must NOT use these bearer
   * tokens (scope-insufficient on that endpoint) — GeminiClient resolves its
    * free-tier API key separately (GEMINI_API_KEY env → Secret Manager fallback).
   *
   * IMPORTANT: this method must NEVER return the Gemini API key (GEMINI_API_KEY
   * env is an AIza/AQ **API key**, not a bearer token — cloud consumers send it
   * as `Authorization: Bearer` and would get 401). The env branch was removed:
   * cloud consumers always get an OAuth bearer here.
   *
   * Order of precedence:
   * 1. In-memory unexpired cache
   * 2. Google Compute Engine VM Metadata Token (100% native on GCP instances)
   * 3. Google ADC (Application Default Credentials) refresh_token exchange for evabot.online@gmail.com
   * 4. Local gcloud CLI access token
   */
  public static async getCredentials(): Promise<AuthCredentials | null> {
    const now = Date.now();
    if (this.cachedCredentials && now < this.expiresAt) {
      return this.cachedCredentials;
    }

    // 1. Google ADC refresh token exchange (full cloud-platform scope for evabot.online@gmail.com)
    const adcToken = await this.exchangeAdcRefreshToken();
    if (adcToken) {
      this.cachedCredentials = {
        token: adcToken,
        type: 'bearer',
        source: 'Google ADC (evabot.online@gmail.com)',
        account: 'evabot.online@gmail.com',
      };
      this.expiresAt = now + 50 * 60 * 1000;
      logger.info('GoogleAuthProvider', 'Authenticated automatically via Google ADC refresh token');
      return this.cachedCredentials;
    }

    // 3. Google Compute Engine VM Metadata Server fallback
    const gceToken = await this.fetchGceMetadataToken();
    if (gceToken) {
      this.cachedCredentials = {
        token: gceToken,
        type: 'bearer',
        source: 'Google Compute Engine Service Account',
        account: 'evabot.online@gmail.com',
      };
      this.expiresAt = now + 50 * 60 * 1000; // 50 minutes
      logger.info('GoogleAuthProvider', 'Authenticated automatically via Google Compute Engine Metadata Service');
      return this.cachedCredentials;
    }

    // 4. Local gcloud CLI
    const gcloudToken = this.fetchGcloudCliToken();
    if (gcloudToken) {
      this.cachedCredentials = {
        token: gcloudToken,
        type: 'bearer',
        source: 'Google Cloud SDK (gcloud)',
        account: 'evabot.online@gmail.com',
      };
      this.expiresAt = now + 30 * 60 * 1000;
      logger.info('GoogleAuthProvider', 'Authenticated automatically via gcloud CLI');
      return this.cachedCredentials;
    }

    return null;
  }

  private static fetchGceMetadataToken(): Promise<string | null> {
    return new Promise((resolve) => {
      const options = {
        hostname: 'metadata.google.internal',
        port: 80,
        path: '/computeMetadata/v1/instance/service-accounts/default/token',
        method: 'GET',
        headers: {
          'Metadata-Flavor': 'Google',
        },
        timeout: 1000,
      };

      const req = http.request(options, (res) => {
        if (res.statusCode !== 200) {
          resolve(null);
          return;
        }

        let body = '';
        res.on('data', (chunk) => { body += chunk; });
        res.on('end', () => {
          try {
            const data = JSON.parse(body);
            resolve(data.access_token || null);
          } catch {
            resolve(null);
          }
        });
      });

      req.on('error', () => resolve(null));
      req.on('timeout', () => {
        req.destroy();
        resolve(null);
      });
      req.end();
    });
  }

  private static async exchangeAdcRefreshToken(): Promise<string | null> {
    try {
      const possiblePaths = [
        '/home/fedor/.config/gcloud/legacy_credentials/evabot.online@gmail.com/adc.json',
        path.join(process.env.HOME || '', '.config/gcloud/legacy_credentials/evabot.online@gmail.com/adc.json'),
        path.join(process.env.HOME || '', '.config/gcloud/application_default_credentials.json'),
      ];

      for (const p of possiblePaths) {
        if (fs.existsSync(p)) {
          const raw = fs.readFileSync(p, 'utf8');
          const json = JSON.parse(raw);
          if (json.refresh_token && json.client_id && json.client_secret) {
            const params = new URLSearchParams({
              client_id: json.client_id,
              client_secret: json.client_secret,
              refresh_token: json.refresh_token,
              grant_type: 'refresh_token',
            });

            const res = await fetch('https://oauth2.googleapis.com/token', {
              method: 'POST',
              headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
              body: params.toString(),
            });

            if (res.ok) {
              const data: any = await res.json();
              return data.access_token || null;
            }
          }
        }
      }
    } catch {
      // Ignore
    }
    return null;
  }

  private static fetchGcloudCliToken(): string | null {
    try {
      const output = execSync('gcloud auth print-access-token 2>/dev/null', {
        encoding: 'utf8',
        timeout: 3000,
      }).trim();
      if (output.startsWith('ya29.')) {
        return output;
      }
    } catch {
      // Ignore
    }
    return null;
  }
}

