<script>
  // Clean old SW cache & CacheStorage
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.getRegistrations().then(r => r.forEach(reg => reg.unregister()));
  }
  if ('caches' in window) {
    caches.keys().then(keys => keys.forEach(k => caches.delete(k)));
  }

  // Theme Management
  const urlTheme = new URLSearchParams(window.location.search).get('theme');
  let currentTheme = urlTheme || localStorage.getItem('eva_tui_theme') || 'dark';
  function applyTheme(theme) {
    currentTheme = theme;
    localStorage.setItem('eva_tui_theme', theme);
    if (theme === 'light') {
      document.documentElement.classList.add('theme-light');
      document.body.classList.add('theme-light');
      const btn = document.getElementById('theme-btn');
      if (btn) btn.textContent = '[ ТЕМА: LIGHT]';
    } else {
      document.documentElement.classList.remove('theme-light');
      document.body.classList.remove('theme-light');
      const btn = document.getElementById('theme-btn');
      if (btn) btn.textContent = '[ ТЕМА: DARK]';
    }
  }
  applyTheme(currentTheme);
  function toggleTheme() {
    applyTheme(currentTheme === 'dark' ? 'light' : 'dark');
  }
  window.addEventListener('keydown', (e) => {
    if ((e.key === 't' || e.key === 'T') && !['INPUT','TEXTAREA'].includes(document.activeElement.tagName)) {
      toggleTheme();
    }
  });
  applyTheme(currentTheme);

  // Spinner
  const spinChars = ['', '', '', '', '', '', '', '', '', ''];
  let spinIdx = 0;
  setInterval(() => {
    spinIdx = (spinIdx + 1) % spinChars.length;
    const el = document.getElementById('spin');
    if (el) el.textContent = spinChars[spinIdx];
  }, 100);

  // UTC clock
  function updateClock() {
    const d = new Date().toISOString().replace('T', ' ').substring(11, 19) + ' UTC';
    const el = document.getElementById('clock-utc');
    if (el) el.textContent = d;
  }
  setInterval(updateClock, 1000);

  function makeBar(pct, total = 10) {
    pct = Math.max(0, Math.min(100, pct));
    const filled = Math.round((pct / 100) * total);
    return '[' + '■'.repeat(filled) + '□'.repeat(total - filled) + ']';
  }

  function formatSecs(sec) {
    const d = Math.floor(sec / 86400);
    const h = String(Math.floor((sec % 86400) / 3600)).padStart(2, '0');
    const m = String(Math.floor((sec % 3600) / 60)).padStart(2, '0');
    const s = String(sec % 60).padStart(2, '0');
    return (d > 0 ? d + 'd ' : '') + h + ':' + m + ':' + s;
  }

  // Logs & Filters
  let activeFilter = 'all';
  let cachedDomainLogs = [];
  let cachedSystemLogs = [];

  function setLogFilter(f) {
    activeFilter = f;
    ['all', 'domains', 'system'].forEach(id => {
      const btn = document.getElementById('filter-' + id);
      if (btn) {
        if (id === f) btn.classList.add('active');
        else btn.classList.remove('active');
      }
    });
    renderLogs();
  }

  function renderLogs() {
    const container = document.getElementById('log-stream');
    if (!container) return;

    let items = [];
    if (activeFilter === 'all' || activeFilter === 'domains') {
      cachedDomainLogs.forEach(l => items.push({ type: 'domain', ...l }));
    }
    if (activeFilter === 'all' || activeFilter === 'system') {
      cachedSystemLogs.forEach(l => items.push({ type: 'system', ...l }));
    }

    const countEl = document.getElementById('log-count');
    if (countEl && items.length > 0) countEl.textContent = items.length;

    if (items.length === 0) return;

    container.innerHTML = items.map(item => {
      if (item.type === 'domain') {
        let badgeClass = 'badge-ok';
        let icon = '[OK]';
        if (item.statusLevel === 'warn') {
          badgeClass = 'badge-warn';
          icon = '[WRN]';
        } else if (item.statusLevel === 'err') {
          badgeClass = 'badge-err';
          icon = '[ERR]';
        }

        return '<div class="log-row">' +
          '<span class="c-dim">[' + item.timeStr + ']</span> ' +
          '<span class="badge ' + badgeClass + '">' + icon + ' ' + item.status + '</span> ' +
          '<span class="bold c-fg">' + item.method + '</span> ' +
          '<strong class="c-fg">' + item.host + '</strong> ' +
          '<span class="c-dim">' + escapeHtml(item.uri) + '</span> ' +
          '<span class="c-dim">(' + item.proto + ' ' + item.durationMs + 'ms)</span> ' +
          '<span class="c-faint">ip:' + item.ip + '</span>' +
        '</div>';
      } else {
        let badgeClass = 'badge-ok';
        let icon = '[OK]';
        if (item.levelClass === 'warn') {
          badgeClass = 'badge-warn';
          icon = '[WRN]';
        } else if (item.levelClass === 'err') {
          badgeClass = 'badge-err';
          icon = '[ERR]';
        }

        return '<div class="log-row">' +
          '<span class="c-dim">[' + item.timeStr + ']</span> ' +
          '<span class="badge ' + badgeClass + '">' + icon + ' ' + item.level + '</span> ' +
          '<span class="bold c-fg">[' + item.subsystem + ']</span> ' +
          '<span class="c-fg">' + escapeHtml(item.message) + '</span>' +
        '</div>';
      }
    }).join('');
  }

  function escapeHtml(str) {
    if (!str) return '';
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function renderProcesses(procs) {
    const tbody = document.getElementById('proc-tbody');
    if (!tbody || !Array.isArray(procs) || procs.length === 0) return;

    tbody.innerHTML = procs.map(p => {
      let badgeClass = 'badge-ok';
      if (p.statusClass === 'warn') {
        badgeClass = 'badge-warn';
      } else if (p.statusClass === 'err') {
        badgeClass = 'badge-err';
      }

      const nodeClean = p.node ? p.node.split(' ')[0] : 'node';
      const nameClean = p.role ? (p.name + ' (' + p.role.split(' ')[0] + ')') : p.name;

      return '<tr>' +
        '<td>' + p.pid + '</td>' +
        '<td>' + nodeClean + '</td>' +
        '<td class="bold c-fg">' + nameClean + '</td>' +
        '<td class="c-ok">' + p.cpu + '</td>' +
        '<td>' + p.mem + '</td>' +
        '<td><span class="badge ' + badgeClass + '">[' + p.status + ']</span></td>' +
      '</tr>';
    }).join('');
  }

  async function pollCluster() {
    const t0 = performance.now();
    try {
      const res = await fetch('/api/logs?_t=' + Date.now(), { cache: 'no-store' });
      const clientLatency = Math.round(performance.now() - t0);
      if (res.ok) {
        const d = await res.json();
        if (d.domainLogs) cachedDomainLogs = d.domainLogs;
        if (d.systemLogs) cachedSystemLogs = d.systemLogs;
        if (d.processes) renderProcesses(d.processes);
        renderLogs();

        // RTT
        const rtt = d.meshLatencyMs || clientLatency || 122;
        const mr = document.getElementById('m-rtt');
        if (mr) mr.textContent = rtt + ' ms RTT';

        // Micro metrics
        if (d.microMetrics) {
          const m = d.microMetrics;
          const fl = document.getElementById('f-load');
          if (fl) fl.textContent = (m.loadAvg.indexOf(',') !== -1 ? m.loadAvg.split(',')[0] : m.loadAvg) + ' (' + m.cpuPct + '%)';
          const flb = document.getElementById('f-load-bar');
          if (flb) flb.textContent = makeBar(m.cpuPct);
          const fr = document.getElementById('f-ram');
          if (fr) fr.textContent = m.memUsedMb + '/' + m.memTotalMb + ' MB (' + Math.round((m.memUsedMb/m.memTotalMb)*100) + '%)';
          const fu = document.getElementById('f-uptime');
          if (fu) fu.textContent = m.uptimeStr;
        }
      }
    } catch (e) {}

    // Fetch Health for brain core
    try {
      const res = await fetch('/api/health?_t=' + Date.now(), { cache: 'no-store' });
      if (res.ok) {
        const d = await res.json();
        const loadVal = parseFloat(d.systemLoad || '0.9');
        const cpuPct = Math.min(100, Math.round((loadVal / (d.cpuCores || 8)) * 100));
        const bc = document.getElementById('b-cpu');
        if (bc) bc.textContent = loadVal.toFixed(2) + ' (' + cpuPct + '%)';
        const bcb = document.getElementById('b-cpu-bar');
        if (bcb) bcb.textContent = makeBar(cpuPct);

        const totMem = d.totalMemoryMb || 32099;
        const freeMem = d.freeMemoryMb || 25000;
        const usedMem = totMem - freeMem;
        const ramPct = Math.round((usedMem / totMem) * 100);
        const br = document.getElementById('b-ram');
        if (br) br.textContent = (usedMem / 1024).toFixed(1) + '/' + Math.round(totMem / 1024) + ' GB (' + ramPct + '%)';

        const bu = document.getElementById('b-uptime');
        if (bu) bu.textContent = formatSecs(d.uptimeSeconds || 0);

        const bm = document.getElementById('b-models');
        if (bm && d.availableModels) bm.textContent = d.availableModels + ' моделей онлайн';
      }
    } catch (e) {}
  }

  function manualRefresh() {
    pollCluster();
  }

  setInterval(pollCluster, 3000);
</script>
</body>
</html>
`;
  }
}

import { UniversalLlmClient, LlmProvider, UniversalMessage } from '../core/UniversalLlmClient.js';
import { Config } from '../core/Config.js';
import { KnowledgeBaseConnector } from '../core/CorporateRoles.js';
import { rulesEngine } from '../core/RulesEngine.js';
import { applyLocalePolicy } from '../core/LocalePolicy.js';
import { ChatHistoryStore } from '../core/ChatHistoryStore.js';
import { I18nEngine, SupportedLocale } from '../core/I18nEngine.js';
import { logger } from '../core/Logger.js';
import { SystemContext, recordLastUsedModel } from '../core/SystemContext.js';
import { DeveloperMode } from '../core/DeveloperMode.js';
import { AutoModelRouter } from '../core/AutoModelRouter.js';

/**
 * Thin chat-engine facade shared by the Telegram transport.
 *
 * ChatRouter is tightly coupled to the HTTP request/response cycle (SSE writes,
 * status codes, rate-limit headers), so instead of reusing it directly we expose
 * the same underlying units it composes — UniversalLlmClient, KnowledgeBaseConnector,
 * RulesEngine and ChatHistoryStore — as a plain async `respond()` call that any
 * non-HTTP transport can drive. Keep this in sync with ChatRouter.resolveSystemInstruction.
 */
export interface ChatEngineRequest {
  message: string;
  sessionId: string;
  locale?: SupportedLocale;
  model?: string;
  provider?: LlmProvider;
  useHistory?: boolean;
  useKnowledgeBase?: boolean;
}

export interface ChatEngineResponse {
  text: string;
  model: string;
  sessionId: string;
}

export class ChatEngine {
  private kbConnector: KnowledgeBaseConnector;
  private client: UniversalLlmClient;
  private historyLimit: number;

  constructor(options: { apiKey?: string; model?: string; historyLimit?: number } = {}) {
    this.client = new UniversalLlmClient(options.apiKey || (Config.vertexEnabled ? undefined : Config.geminiApiKey) || undefined);
    this.kbConnector = new KnowledgeBaseConnector();
    this.historyLimit = options.historyLimit ?? 12;
  }

  public resolveSystemInstruction(): string {
    const base = Config.defaultSystemInstruction;
    const withLocale = applyLocalePolicy(base);
    const withRules = `${withLocale}\n${rulesEngine.compileRulesInstruction()}`;
    return withRules;
  }

  public async respond(request: ChatEngineRequest): Promise<ChatEngineResponse> {
    const { message, sessionId, locale } = request;

    const store = ChatHistoryStore.getInstance();
    let history: Array<{ role: string; content: string }> = [];
    if (request.useHistory !== false) {
      try {
        history = store
          .getSessionHistory(sessionId, this.historyLimit)
          .map((rec) => ({ role: rec.role === 'assistant' ? 'assistant' : 'user', content: rec.content }));
      } catch (err: any) {
        logger.warn('ChatEngine', `History load skipped for ${sessionId}: ${err.message}`);
      }
    }

    // TASK-320: /auto mode — when the session opted in and no explicit model
    // was requested, pick the best FREE model for this message + history.
    let targetModel = request.model || Config.defaultModel;
    if (!request.model && AutoModelRouter.isActive(sessionId)) {
      targetModel = AutoModelRouter.pick({ message, history, historyLimit: this.historyLimit }, sessionId).modelId;
    }
    const useKnowledgeBase = request.useKnowledgeBase !== false;
    const useHistory = request.useHistory !== false;

    // Track the actually-used model for SystemContext (FEATURE 1).
    recordLastUsedModel(targetModel, this.client.resolveProvider(targetModel, request.provider));

    let effectiveInstruction = this.resolveSystemInstruction();

    if (useKnowledgeBase) {
      try {
        const docs = await this.kbConnector.search(message, { limit: 3 });
        if (docs.length > 0) {
          effectiveInstruction += `\n${this.kbConnector.formatContextForPrompt(docs)}`;
        }
      } catch (err: any) {
        logger.warn('ChatEngine', `KB retrieval skipped for ${sessionId}: ${err.message}`);
      }
    }

    // System-awareness (FEATURE 1) + developer block (FEATURE 2), appended
    // after the existing system prompt building (LocalePolicy/rules/KB).
    effectiveInstruction += `\n${SystemContext.build()}`;
    if (DeveloperMode.isUnlocked(sessionId)) {
      effectiveInstruction += `\n${SystemContext.DEVELOPER_BLOCK}`;
    }

    const messages: UniversalMessage[] = [
      ...history.map((m) => ({
        role: (m.role === 'assistant' ? 'assistant' : 'user') as UniversalMessage['role'],
        content: m.content,
      })),
      { role: 'user', content: message.trim() },
    ];
    const responseText = await this.client.generateContent(targetModel, messages, {
      systemInstruction: effectiveInstruction,
      provider: request.provider,
    });

    this.persist(sessionId, 'user', message.trim(), targetModel, locale);
    this.persist(sessionId, 'assistant', responseText, targetModel, locale);

    return { text: responseText, model: targetModel, sessionId };
  }

  private persist(sessionId: string, role: string, content: string, model: string, locale?: SupportedLocale): void {
    try {
      ChatHistoryStore.getInstance().appendMessage({
        sessionId,
        role,
        content: DeveloperMode.maskPasswordIn(content),
        model,
        lang: locale || I18nEngine.getLocale(),
      });
    } catch (err: any) {
      logger.warn('ChatEngine', `Chat history persistence skipped: ${err.message}`);
    }
  }
}

