export type AlertSeverity = 'low' | 'medium' | 'high' | 'critical';
export type AlertChannel = 'console' | 'file' | 'webhook' | 'email' | 'syslog' | 'desktop';

export interface AlertEvent {
  id: string;
  timestamp: string;
  severity: AlertSeverity;
  title: string;
  message: string;
  source: string;
  metadata?: Record<string, any>;
  channels: AlertChannel[];
}

export interface AlertChannelConfig {
  type: AlertChannel;
  enabled: boolean;
  config: Record<string, any>;
}

export interface AlertConfig {
  channels: AlertChannelConfig[];
  thresholds: {
    errorRate: number;
    suspiciousActivity: number;
    responseTimeMs: number;
  };
  rateLimit: {
    maxPerHour: number;
    cooldownMs: number;
  };
}

const DEFAULT_ALERT_CONFIG: AlertConfig = {
  channels: [
    { type: 'console', enabled: true, config: { colors: true } },
    { type: 'file', enabled: true, config: { path: 'logs/alerts.log' } },
    { type: 'syslog', enabled: false, config: { facility: 'local0', tag: 'evabot' } },
    { type: 'webhook', enabled: false, config: { url: '', method: 'POST' } },
    { type: 'email', enabled: false, config: { smtp: {}, to: [], from: '' } },
    { type: 'desktop', enabled: false, config: { sound: true } },
  ],
  thresholds: {
    errorRate: 5,
    suspiciousActivity: 3,
    responseTimeMs: 5000,
  },
  rateLimit: {
    maxPerHour: 100,
    cooldownMs: 60_000,
  },
};

const SEVERITY_COLORS: Record<AlertSeverity, string> = {
  low: '\x1b[36m',
  medium: '\x1b[33m',
  high: '\x1b[31m',
  critical: '\x1b[1m\x1b[41m\x1b[37m',
};

const SEVERITY_EMOJI: Record<AlertSeverity, string> = {
  low: '[LOW]',
  medium: '[MED]',
  high: '[HIGH]',
  critical: '[CRIT]',
};

export class AlertManager {
  private static instance: AlertManager;
  private config: AlertConfig = DEFAULT_ALERT_CONFIG;
  private recentAlerts: Map<string, number> = new Map();
  private alerts: AlertEvent[] = [];
  private maxAlerts: number = 1000;

  private constructor() {
    this.loadConfig();
  }

  public static getInstance(): AlertManager {
    if (!AlertManager.instance) AlertManager.instance = new AlertManager();
    return AlertManager.instance;
  }

  private loadConfig(): void {
    try {
      const env = process.env;
      if (env.ALERT_WEBHOOK_URL) {
        const ch = this.config.channels.find((c) => c.type === 'webhook');
        if (ch) {
          ch.enabled = true;
          ch.config.url = env.ALERT_WEBHOOK_URL;
        }
      }
      if (env.ALERT_EMAIL_TO) {
        const ch = this.config.channels.find((c) => c.type === 'email');
        if (ch) {
          ch.enabled = true;
          ch.config.to = env.ALERT_EMAIL_TO.split(',');
        }
      }
      if (env.SYSLOG_HOST) {
        const ch = this.config.channels.find((c) => c.type === 'syslog');
        if (ch) {
          ch.enabled = true;
          ch.config.host = env.SYSLOG_HOST;
          ch.config.port = parseInt(env.SYSLOG_PORT || '514', 10);
        }
      }
    } catch (e) {
      // Use defaults
    }
  }

  public async alert(
    severity: AlertSeverity,
    title: string,
    message: string,
    source: string = 'system',
    metadata?: Record<string, any>,
  ): Promise<AlertEvent> {
    if (this.isRateLimited(title)) {
      logger.debug(LogCategory.SYSTEM, 'ALERT', `Rate limited: ${title}`);
      return {
        id: 'rate-limited', timestamp: new Date().toISOString(),
        severity, title, message, source, metadata, channels: [],
      };
    }

    const event: AlertEvent = {
      id: this.generateId(),
      timestamp: new Date().toISOString(),
      severity, title, message, source, metadata,
      channels: this.config.channels.filter((c) => c.enabled).map((c) => c.type),
    };

    this.alerts.push(event);
    if (this.alerts.length > this.maxAlerts) this.alerts.shift();

    await this.deliver(event);

    logger.warn(LogCategory.SYSTEM, 'ALERT', `${severity.toUpperCase()}: ${title} - ${message}`, metadata);
    return event;
  }

  public async low(title: string, message: string, source?: string, metadata?: any) {
    return this.alert('low', title, message, source, metadata);
  }
  public async medium(title: string, message: string, source?: string, metadata?: any) {
    return this.alert('medium', title, message, source, metadata);
  }
  public async high(title: string, message: string, source?: string, metadata?: any) {
    return this.alert('high', title, message, source, metadata);
  }
  public async critical(title: string, message: string, source?: string, metadata?: any) {
    return this.alert('critical', title, message, source, metadata);
  }

  private async deliver(event: AlertEvent): Promise<void> {
    for (const channel of this.config.channels.filter((c) => c.enabled)) {
      try {
        switch (channel.type) {
          case 'console': this.deliverConsole(event, channel.config); break;
          case 'file': this.deliverFile(event, channel.config); break;
          case 'webhook': await this.deliverWebhook(event, channel.config); break;
          case 'email': await this.deliverEmail(event, channel.config); break;
          case 'syslog': await this.deliverSyslog(event, channel.config); break;
          case 'desktop': this.deliverDesktop(event, channel.config); break;
        }
      } catch (err: any) {
        logger.error(LogCategory.SYSTEM, 'ALERT_DELIVERY', `Failed to deliver to ${channel.type}: ${err.message}`);
      }
    }
  }

  private deliverConsole(event: AlertEvent, config: any): void {
    const color = SEVERITY_COLORS[event.severity];
    const emoji = SEVERITY_EMOJI[event.severity];
    const line = `${emoji} ${color}[${event.severity.toUpperCase()}]${'\x1b[0m'} ${event.title}\n   ${event.message}`;
    console.log(`\n${line}\n   Source: ${event.source} | ${event.timestamp}\n`);
    if (config.colors && event.severity === 'critical') {
      try { process.stdout.write('\x07'); } catch {}
    }
  }

  private deliverFile(event: AlertEvent, config: any): void {
    try {
      const logPath = path.resolve(process.cwd(), config.path);
      const dir = path.dirname(logPath);
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      const line = JSON.stringify(event) + '\n';
      fs.appendFileSync(logPath, line);
    } catch {}
  }

  private async deliverWebhook(event: AlertEvent, config: any): Promise<void> {
    if (!config.url) return;
    const payload = {
      event_type: 'evabot_alert',
      severity: event.severity,
      title: event.title,
      message: event.message,
      source: event.source,
      timestamp: event.timestamp,
      host: os.hostname(),
      metadata: event.metadata,
    };
    const response = await fetch(config.url, {
      method: config.method || 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(5000),
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
  }

  private async deliverEmail(event: AlertEvent, config: any): Promise<void> {
    // Реализация через SMTP (nodemailer в production)
    logger.info(LogCategory.SYSTEM, 'ALERT_EMAIL', `Email would be sent to ${config.to}: ${event.title}`);
  }

  private async deliverSyslog(event: AlertEvent, config: any): Promise<void> {
    const net = await import('node:dgram');
    const client = net.createSocket('udp4');
    const severity = { low: 6, medium: 4, high: 3, critical: 2 }[event.severity];
    const priority = (config.facility || 16) * 8 + severity;
    const msg = `<${priority}>${event.title}: ${event.message}`;
    client.send(msg, config.port || 514, config.host || 'localhost');
    client.close();
  }

  private deliverDesktop(event: AlertEvent, config: any): void {
    if (config.sound) {
      try { process.stdout.write('\x07\x07\x07'); } catch {}
    }
  }

  private isRateLimited(title: string): boolean {
    const key = `${title}`;
    const now = Date.now();
    const lastSent = this.recentAlerts.get(key);
    if (lastSent && (now - lastSent) < this.config.rateLimit.cooldownMs) {
      return true;
    }
    this.recentAlerts.set(key, now);
    return false;
  }

  private generateId(): string {
    return `alert-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
  }

  public getRecentAlerts(limit: number = 50, severity?: AlertSeverity): AlertEvent[] {
    let filtered = [...this.alerts];
    if (severity) filtered = filtered.filter((a) => a.severity === severity);
    return filtered.slice(-limit).reverse();
  }

  public getConfig(): AlertConfig {
    return this.config;
  }

  public setChannelEnabled(type: AlertChannel, enabled: boolean): void {
    const ch = this.config.channels.find((c) => c.type === type);
    if (ch) ch.enabled = enabled;
  }

  public getStats(): {
    totalAlerts: number;
    bySeverity: Record<AlertSeverity, number>;
    activeChannels: AlertChannel[];
  } {
    const bySeverity: Record<AlertSeverity, number> = { low: 0, medium: 0, high: 0, critical: 0 };
    for (const a of this.alerts) bySeverity[a.severity]++;
    return {
      totalAlerts: this.alerts.length,
      bySeverity,
      activeChannels: this.config.channels.filter((c) => c.enabled).map((c) => c.type),
    };
  }
}

export const alertManager = AlertManager.getInstance();

/**
 * SubagentEngine.ts — /subagent command (TASK-325).
 *
 * Spawns N parallel LLM sub-agents, each with a distinct role persona and its
 * own FREE model (never Gemini — reserved for development), then synthesizes
 * all answers into a single verdict.
 *
 * Design:
 *  - Role personas (Analyst / Builder / Critic / Researcher) shape the system
 *    instruction so parallel answers are genuinely diverse, not 4x the same.
 *  - Every sub-agent runs through UniversalLlmClient (breaker + 45s timeout +
 *    ranked fallback chain come for free).
 *  - Parallelism via Promise.allSettled: one failed agent never kills the
 *    batch; failures are reported inline.
 *  - Synthesis is a separate free-model call that receives all successful
 *    answers and produces a final verdict.
 *
 * Limits (ONLY-FREE + abuse guard): max 4 sub-agents per run, 60s wall
 * budget per agent, fleet restricted to $0 models.
 */

import { UniversalLlmClient } from './UniversalLlmClient.js';
import { ModelRegistry } from '../models/ModelRegistry.js';
import { Config } from './Config.js';
import { logger } from './Logger.js';
import { OpLog } from './OpLog.js';

export interface SubagentRole {
  id: string;
  title: string;
  systemSuffix: string;
}

export interface SubagentResult {
  role: SubagentRole;
  modelId: string;
  ok: boolean;
  answer: string;
  error?: string;
  durationMs: number;
}

export interface SubagentRun {
  task: string;
  agentCount: number;
  results: SubagentResult[];
  synthesis: string;
  totalDurationMs: number;
}

export const SUBAGENT_ROLES: SubagentRole[] = [
  {
    id: 'analyst',
    title: 'Analyst',
    systemSuffix: 'You are the ANALYST sub-agent. Decompose the task, identify constraints, risks and unknowns. Be structured and concise (max 200 words).',
  },
  {
    id: 'builder',
    title: 'Builder',
    systemSuffix: 'You are the BUILDER sub-agent. Produce a concrete, actionable solution: steps, code or artifacts where relevant. Be pragmatic (max 200 words).',
  },
  {
    id: 'critic',
    title: 'Critic',
    systemSuffix: 'You are the CRITIC sub-agent. Attack the obvious solution: edge cases, failure modes, security, cost. Suggest mitigations (max 200 words).',
  },
  {
    id: 'researcher',
    title: 'Researcher',
    systemSuffix: 'You are the RESEARCHER sub-agent. Surface alternatives, prior art and trade-offs the others may miss (max 200 words).',
  },
];

/** Free $0 fleet for sub-agents — LIVE-VERIFIED 2026-09-08 (chat matrix):
 *  inkling* removed (403 'agentic harnesses only'), nemotron-ultra removed
 *  (45s+ latency). `openrouter/free` is the reliable meta-router. */
const SUBAGENT_FLEET = [
  'nvidia/nemotron-3-super-120b-a12b:free',
  'cohere/north-mini-code:free',
  'inclusionai/ling-3.0-flash-sante:free',
  'poolside/laguna-s-2.1:free',
  'dots-studio/dots-3-note-preview:free',
  'google/gemma-4-31b-it:free',
  'openrouter/free',
  // OmniRoute edge (free self-hosted margin) — for fleet diversity
  'omni/cf-gpt-oss-120b',
  'omni/cf-llama-3.3-70b',
  'omni/groq-gpt-oss-120b',
];

/** Picks a diverse model per slot: distinct ids across slots (wrap-around if fleet < agents). */
export function assignModels(agentCount: number): string[] {
  const pool = SUBAGENT_FLEET.filter((id) => ModelRegistry.isValidModel(id));
  const out: string[] = [];
  for (let i = 0; i < agentCount; i++) {
    const preferred = pool[i % pool.length];
    // Avoid two agents on the same model while the pool allows diversity.
    const candidate = out.includes(preferred) && pool.length > agentCount ? pool[(i + 1) % pool.length] : preferred;
    out.push(candidate);
  }
  return out;
}

export class SubagentEngine {
  private client: UniversalLlmClient;

  constructor(apiKey?: string) {
    this.client = new UniversalLlmClient(apiKey || (Config.vertexEnabled ? undefined : Config.geminiApiKey) || undefined);
  }

  /**
   * Parses '/subagent [N] <task>' — N optional (default 3, max 4).
   */
  public static parseArgs(args: string): { agentCount: number; task: string } {
    const m = args.match(/^([1-4])\s+(.*)$/s);
    if (m) return { agentCount: parseInt(m[1], 10), task: m[2].trim() };
    return { agentCount: 3, task: args.trim() };
  }

  /**
   * Runs the parallel sub-agent batch + synthesis. NEVER touches paid models.
   */
  public async run(task: string, agentCount = 3, apiKey?: string): Promise<SubagentRun> {
    const t0 = Date.now();
    const n = Math.max(1, Math.min(4, agentCount));
    const roles = SUBAGENT_ROLES.slice(0, n);
    const models = assignModels(n);

    OpLog.getInstance().log('info', 'system', `/subagent run: ${n} agents, task="${task.substring(0, 80)}"`);
    logger.info('SubagentEngine', `Spawning ${n} sub-agents: ${roles.map((r, i) => `${r.title}(${models[i]})`).join(', ')}`);

    const settled = await Promise.allSettled(
      roles.map((role, i) => this.runAgent(role, models[i], task, apiKey))
    );

    const results: SubagentResult[] = settled.map((s, i) => {
      if (s.status === 'fulfilled') return s.value;
      return {
        role: roles[i],
        modelId: models[i],
        ok: false,
        answer: '',
        error: s.reason?.message || 'unknown error',
        durationMs: 0,
      };
    });

    const okResults = results.filter((r) => r.ok);
    let synthesis = '';
    if (okResults.length > 0) {
      try {
        synthesis = await this.synthesize(task, okResults, apiKey);
      } catch (err: any) {
        synthesis = `[SYNTHESIS FAILED: ${err.message}] — raw answers below.`;
      }
    } else {
      synthesis = '[X] All sub-agents failed. See per-agent errors below.';
    }

    const totalDurationMs = Date.now() - t0;
    OpLog.getInstance().log('info', 'system', `/subagent done: ${okResults.length}/${n} ok in ${totalDurationMs}ms`);
    return { task, agentCount: n, results, synthesis, totalDurationMs };
  }

  private async runAgent(role: SubagentRole, modelId: string, task: string, apiKey?: string): Promise<SubagentResult> {
    const t0 = Date.now();
    const instruction = `${Config.defaultSystemInstruction}\n${role.systemSuffix}`;
    const answer = await this.client.generateContent(
      modelId,
      [{ role: 'user', content: task }],
      { systemInstruction: instruction, maxOutputTokens: 1024, apiKey },
      true // ranked fallback chain stays enabled
    );
    return { role, modelId, ok: true, answer: answer.trim(), durationMs: Date.now() - t0 };
  }

  private async synthesize(task: string, results: SubagentResult[], apiKey?: string): Promise<string> {
    const block = results
      .map((r, i) => `[${i + 1}] ${r.role.title} (${r.modelId}):\n${r.answer}`)
      .join('\n\n');
    const instruction = `${Config.defaultSystemInstruction}\nYou are the SYNTHESIZER of a multi-agent consilium. Merge the sub-agent answers below into one verdict: agree on the best plan, resolve contradictions explicitly, output a short action list. Max 250 words.`;
    return this.client.generateContent(
      'openrouter/free',
      [{ role: 'user', content: `TASK: ${task}\n\nSUB-AGENT ANSWERS:\n${block}` }],
      { systemInstruction: instruction, maxOutputTokens: 1024, apiKey }
    );
  }

  /** Renders the full run as chat-ready text. */
  public static format(run: SubagentRun): string {
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push(`   SUB-AGENTS — параллельный запуск (${run.results.length} агентов, ${Math.round(run.totalDurationMs / 100) / 10}s)`);
    lines.push('═'.repeat(78));
    lines.push(`  ЗАДАЧА: ${run.task.substring(0, 120)}${run.task.length > 120 ? '…' : ''}`);
    lines.push('');
    for (const r of run.results) {
      const status = r.ok ? '[OK]' : '[FAIL]';
      const dur = `${Math.round(r.durationMs / 100) / 10}s`;
      lines.push(`  ${status} ${r.role.title.padEnd(10)} ${r.modelId} (${dur})`);
      if (r.ok) {
        for (const l of r.answer.split('\n').slice(0, 12)) lines.push(`       ${l}`);
        if (r.answer.split('\n').length > 12) lines.push('       …');
      } else {
        lines.push(`       error: ${r.error}`);
      }
      lines.push('');
    }
    lines.push('─'.repeat(78));
    lines.push('  СИНТЕЗ:');
    for (const l of run.synthesis.split('\n').slice(0, 20)) lines.push(`  ${l}`);
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }
}

/**
 * AutoModelRouter — /auto smart dynamic free-model selection (TASK-320).
 *
 * ONLY-FREE policy: the router picks exclusively from models with
 * pricing.freeTierStatus === '100% Free Quota Available'. It never selects a
 * paid model, so /auto can never generate billing.
 *
 * Selection inputs (per request):
 *  1. Context volume — estimated tokens of message + chat history; a model
 *     whose context window cannot hold the payload is disqualified.
 *  2. Task complexity — heuristic tiers: light chat / code / deep reasoning /
 *     longform. Complexity shifts quality weight up and speed weight down.
 *  3. Provider limits — RPM hints parsed from freeTierDetails + per-provider
 *     CircuitBreaker state (an open breaker disqualifies the whole provider).
 *
 * State: per-session auto flag + last decision cache. The auto flag and the
 * last used model are persisted per session in ChatHistoryStore (session_state
 * table, TASK-333) and survive restarts; the in-memory Set is a write-through
 * cache seeded lazily from the store on first access per session. lastDecision
 * stays in-process only.
 */

import { ModelRegistry, GeminiModelInfo } from '../models/ModelRegistry.js';
import { ModelRatings, ModelRating } from '../models/ModelRatings.js';
import { getBreaker, providerOfModel } from './Resilience.js';
import { OpLog } from './OpLog.js';
import { ChatHistoryStore } from './ChatHistoryStore.js';

export type TaskComplexity = 'light' | 'code' | 'reasoning' | 'longform';

export interface TaskAnalysis {
  estimatedTokens: number;
  complexity: TaskComplexity;
  isCode: boolean;
  needsLargeContext: boolean;
  signals: string[];
}

export interface AutoDecision {
  modelId: string;
  modelName: string;
  provider: string;
  complexity: TaskComplexity;
  estimatedTokens: number;
  contextWindow: number;
  score: number;
  reason: string;
  runnerUp?: string;
}

export interface AutoPickInput {
  message: string;
  history?: Array<{ role: string; content: string }>;
  /** History messages beyond this count are ignored for estimation. */
  historyLimit?: number;
}

/** Rough token estimate: ~4 chars per token plus per-message overhead. */
export function estimateTokens(text: string): number {
  if (!text) return 0;
  return Math.ceil(text.length / 4) + 8;
}

const CODE_SIGNALS: Array<[RegExp, string]> = [
  [/```/, 'fenced code block'],
  [/\b(function|class|const|let|var|import|export|def|async|await|return)\b/, 'source-code keywords'],
  [/\b(SELECT|INSERT|UPDATE|DELETE|JOIN)\b.*\b(FROM|INTO|SET)\b/i, 'SQL'],
  [/\b(debug|bug|error|exception|stack ?trace|refactor|compile|typescript|python|javascript|json|api)\b/i, 'debug/dev vocabulary'],
  [/\b(баг|ошибк\w+|исключени\w+|рефактор\w*|компиляц\w+|отлад\w+|класс|функци\w+|скрипт\w*|запрос\w*)\b/i, 'debug/dev vocabulary (RU)'],
  [/\b(баг|помилк\w+|виняток\w+|рефакторин\w+|налагоджен\w+|клас|функц\w+|скрипт\w*)\b/i, 'debug/dev vocabulary (UK)'],
  [/^[ \t]*[{<\[#]|;\s*$/m, 'code-like punctuation'],
];

const REASONING_SIGNALS: Array<[RegExp, string]> = [
  [/\b(prove|proof|theorem|logic|strategy|architect|design|compare|trade-?off|analyz|аналіз|дослідж|доказ|стратег)\w*/i, 'analytical vocabulary'],
  [/\?{2,}|\bwhy\b|\bчому\b|\bпочему\b/i, 'deep-why question'],
  [/^(порівняй|сравни|compare|проанализ|проаналіз)/i, 'explicit analysis request'],
];

const LONGFORM_SIGNALS: Array<[RegExp, string]> = [
  [/\b(essay|статья|стаття|report|доклад|документ|перепиши|rewrite|summarize|summary|резюмируй|конспект)\w*/i, 'longform request'],
  [/\b(переведи|translate)\b/i, 'translation task'],
];

/**
 * Heuristic task analysis: volume + complexity tier.
 */
export function analyzeTask(input: AutoPickInput): TaskAnalysis {
  const historyLimit = input.historyLimit ?? 12;
  const history = (input.history || []).slice(-historyLimit);
  const historyText = history.map((m) => m.content || '').join('\n');
  const fullText = `${historyText}\n${input.message || ''}`;

  const estimatedTokens = estimateTokens(fullText);
  const signals: string[] = [];

  let isCode = false;
  for (const [re, label] of CODE_SIGNALS) {
    if (re.test(input.message)) {
      isCode = true;
      signals.push(label);
      break;
    }
  }

  let isReasoning = false;
  for (const [re, label] of REASONING_SIGNALS) {
    if (re.test(input.message)) {
      isReasoning = true;
      signals.push(label);
      break;
    }
  }

  let isLongform = false;
  for (const [re, label] of LONGFORM_SIGNALS) {
    if (re.test(input.message)) {
      isLongform = true;
      signals.push(label);
      break;
    }
  }

  const needsLargeContext = estimatedTokens > 60_000;
  if (needsLargeContext) signals.push(`large payload ~${(estimatedTokens / 1000).toFixed(0)}k tok`);

  let complexity: TaskComplexity;
  if (isCode) complexity = 'code';
  else if (isReasoning) complexity = 'reasoning';
  else if (isLongform || estimatedTokens > 12_000) complexity = 'longform';
  else complexity = 'light';

  return { estimatedTokens, complexity, isCode, needsLargeContext, signals };
}

/** Parses the RPM hint embedded in freeTierDetails ('15 RPM', '30 RPM', ...). */
function rpmOf(model: GeminiModelInfo): number {
  const m = model.pricing.freeTierDetails.match(/(\d+)\s*RPM/i);
  return m ? parseInt(m[1], 10) : 0;
}

/**
 * Per-complexity weight profile. Quality dominates hard tasks; speed
 * dominates light chat; context always matters for big payloads.
 */
function weightsFor(complexity: TaskAnalysis['complexity']): { quality: number; context: number; speed: number; limit: number } {
  switch (complexity) {
    case 'code':
      return { quality: 0.55, context: 0.25, speed: 0.05, limit: 0.15 };
    case 'reasoning':
      return { quality: 0.55, context: 0.20, speed: 0.05, limit: 0.20 };
    case 'longform':
      return { quality: 0.30, context: 0.45, speed: 0.05, limit: 0.20 };
    case 'light':
    default:
      return { quality: 0.30, context: 0.10, speed: 0.40, limit: 0.20 };
  }
}

/** Context fit 0..100: plenty of headroom over the estimated payload. */
function contextFit(contextWindow: number, estimatedTokens: number): number {
  if (estimatedTokens === 0) return 60;
  const ratio = contextWindow / (estimatedTokens * 1.5);
  if (ratio >= 8) return 100;
  if (ratio >= 4) return 90;
  if (ratio >= 2) return 75;
  if (ratio >= 1) return 50;
  return 0; // payload would not fit — disqualified upstream anyway
}

/** Provider-limit health 0..100 from RPM hints + breaker state. */
function limitHealth(model: GeminiModelInfo): { score: number; open: boolean } {
  const provider = providerOfModel(model.id);
  const breaker = getBreaker(provider);
  if (breaker.getState() === 'open') return { score: 0, open: true };
  const rpm = rpmOf(model);
  let score = 50;
  if (rpm >= 30) score = 100;
  else if (rpm >= 20) score = 85;
  else if (rpm >= 15) score = 70;
  else if (rpm >= 5) score = 45;
  else if (rpm > 0) score = 25;
  return { score, open: false };
}

/** Curated free fleet — real registry ids only, LIVE-VERIFIED on OpenRouter
 *  2026-09-08 (queried /api/v1/models with $0 pricing + live chat matrix).
 *  POLICY: Gemini on our Google account is RESERVED FOR DEVELOPMENT.
 *  Removed after live testing: thinkingmachines/inkling{,-small}:free (403
 *  'agentic harnesses only'), nvidia/nemotron-3-ultra (55B MoE exceeds the
 *  45s interactive deadline). `openrouter/free` is the always-working
 *  terminal fallback. */
const AUTO_FLEET_IDS = [
  'openrouter/free',
  'nvidia/nemotron-3-super-120b-a12b:free',
  'dots-studio/dots-3-note-preview:free',
  'cohere/north-mini-code:free',
  'inclusionai/ling-3.0-flash-sante:free',
  'poolside/laguna-s-2.1:free',
  'google/gemma-4-31b-it:free',
  'omni/cf-gpt-oss-120b',
  'omni/cf-llama-3.3-70b',
  'omni/groq-gpt-oss-120b',
  'omni/zai-glm-5.3-flash',
];

/**
 * AutoModelRouter — session registry + scoring engine.
 */
export class AutoModelRouter {
  private static autoSessions = new Set<string>();
  private static seededSessions = new Set<string>();
  private static lastDecision = new Map<string, AutoDecision>();

  /** Lazily seeds the in-memory auto-flag cache from the persisted store (once per session). */
  private static ensureSeeded(sessionId: string): void {
    if (AutoModelRouter.seededSessions.has(sessionId)) return;
    AutoModelRouter.seededSessions.add(sessionId);
    try {
      const state = ChatHistoryStore.getInstance().getSessionState(sessionId);
      if (state.autoEnabled) AutoModelRouter.autoSessions.add(sessionId);
    } catch {
      // persistence is best-effort — never break routing on store errors
    }
  }

  public static isActive(sessionId: string): boolean {
    AutoModelRouter.ensureSeeded(sessionId);
    return AutoModelRouter.autoSessions.has(sessionId);
  }

  public static setActive(sessionId: string, on: boolean): void {
    AutoModelRouter.seededSessions.add(sessionId);
    if (on) AutoModelRouter.autoSessions.add(sessionId);
    else {
      AutoModelRouter.autoSessions.delete(sessionId);
      AutoModelRouter.lastDecision.delete(sessionId);
    }
    try {
      ChatHistoryStore.getInstance().setSessionAuto(sessionId, on);
    } catch {
      // persistence is best-effort
    }
  }

  public static activeSessions(): string[] {
    return [...AutoModelRouter.autoSessions];
  }

  public static getLastDecision(sessionId: string): AutoDecision | null {
    return AutoModelRouter.lastDecision.get(sessionId) || null;
  }

  /**
   * Picks the best free model for the request. Deterministic, synchronous,
   * offline (no network) — only registry data + breaker state.
   */
  public static pick(input: AutoPickInput, sessionId: string = 'cli'): AutoDecision {
    const analysis = analyzeTask(input);
    const weights = weightsFor(analysis.complexity);

    let best: { model: GeminiModelInfo; score: number } | null = null;
    let runnerUp: string | undefined;
    const considered: string[] = [];

    for (const id of AUTO_FLEET_IDS) {
      const model = ModelRegistry.getModelById(id);
      if (!model) continue;
      if (model.pricing.freeTierStatus !== '100% Free Quota Available') continue;
      // Hard disqualify: context cannot hold the payload with headroom.
      if (model.contextWindow < analysis.estimatedTokens * 1.2) continue;
      const { open } = limitHealth(model);
      if (open) continue;

      const rating: ModelRating = ModelRatings.computeRating(model);
      const fit = contextFit(model.contextWindow, analysis.estimatedTokens);
      const health = limitHealth(model).score;
      const score =
        rating.quality * weights.quality +
        fit * weights.context +
        rating.speed * weights.speed +
        health * weights.limit;
      considered.push(`${id}:${Math.round(score)}`);

      if (!best || score > best.score) {
        runnerUp = best?.model.id;
        best = { model, score };
      }
    }

    // Guaranteed terminal fallback: openrouter/free meta-router (never dies
    // from a single model removal). Gemini is reserved for development.
    const chosen = best?.model
      || ModelRegistry.getModelById('openrouter/free')
      || ModelRegistry.getModelById('nvidia/nemotron-3-super-120b-a12b:free')
      || ModelRegistry.getFreeModels()[0];
    const decision: AutoDecision = {
      modelId: chosen.id,
      modelName: chosen.name,
      provider: providerOfModel(chosen.id),
      complexity: analysis.complexity,
      estimatedTokens: analysis.estimatedTokens,
      contextWindow: chosen.contextWindow,
      score: Math.round(best?.score ?? 0),
      reason: AutoModelRouter.explain(chosen, analysis, weights),
      runnerUp,
    };
    AutoModelRouter.lastDecision.set(sessionId, decision);
    try {
      ChatHistoryStore.getInstance().setSessionLastModel(sessionId, decision.modelId);
    } catch {
      // persistence is best-effort
    }
    OpLog.getInstance().log('info', 'auto', `/auto ${sessionId} → ${decision.modelId} (complexity=${analysis.complexity}, tokens≈${analysis.estimatedTokens}, score=${decision.score})`);
    return decision;
  }

  private static explain(model: GeminiModelInfo, analysis: TaskAnalysis, weights: { quality: number; context: number; speed: number; limit: number }): string {
    const tier: Record<TaskAnalysis['complexity'], string> = {
      light: 'простой диалог → приоритет скорости',
      code: 'код/отладка → приоритет качества',
      reasoning: 'глубокий анализ → приоритет качества',
      longform: 'длинный контекст → приоритет объёма окна',
    };
    const signals = analysis.signals.length > 0 ? `; сигналы: ${analysis.signals.slice(0, 3).join(', ')}` : '';
    return `${tier[analysis.complexity]} (Q×${weights.quality} C×${weights.context} S×${weights.speed} L×${weights.limit}); окно ${model.contextWindow.toLocaleString()} tok против ~${analysis.estimatedTokens.toLocaleString()} tok${signals}`;
  }

  /** Human-readable status block for the /auto command. */
  public static formatStatus(sessionId: string): string {
    const active = AutoModelRouter.isActive(sessionId);
    const decision = AutoModelRouter.getLastDecision(sessionId);
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push('  AUTO — ДИНАМИЧЕСКИЙ ВЫБОР БЕСПЛАТНЫХ МОДЕЛЕЙ');
    lines.push('═'.repeat(78));
    lines.push(`  Статус для сессии "${sessionId}": ${active ? '[ON] включён' : '[OFF] выключен'}`);
    lines.push('');
    lines.push('  Как работает:');
    lines.push('    • Оценивает объём контекста (сообщение + история) и сложность задачи');
    lines.push('    • Сложность: light (болтовня) / code / reasoning / longform');
    lines.push('    • Выбирает ЛУЧШУЮ БЕСПЛАТНУЮ модель под задачу (только free-квоты, $0)');
    lines.push('    • Учитывает лимиты провайдера (RPM/RPD) и CircuitBreaker-статус');
    lines.push('    • Модели с открытым breaker или тесным контекстным окном — исключаются');
    lines.push('');
    lines.push('  Команды:');
    lines.push('    /auto on          — включить авто-выбор для этой сессии');
    lines.push('    /auto off         — выключить (вернуться к дефолтной модели)');
    lines.push('    /auto test <текст> — показать, какую модель выберет движок и почему');
    lines.push('    /auto fleet       — пул моделей, из которых выбирает /auto');
    if (decision) {
      lines.push('');
      lines.push('  ПОСЛЕДНЕЕ РЕШЕНИЕ:');
      lines.push(`    • Модель    : ${decision.modelName} (${decision.modelId})`);
      lines.push(`    • Провайдер : ${decision.provider} | Score: ${decision.score}/100`);
      lines.push(`    • Сложность : ${decision.complexity} | Объём: ~${decision.estimatedTokens.toLocaleString()} tok / окно ${decision.contextWindow.toLocaleString()} tok`);
      lines.push(`    • Причина   : ${decision.reason}`);
    }
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }

  /** Renders the candidate fleet table for /auto fleet. */
  public static formatFleet(): string {
    const lines: string[] = [];
    lines.push('');
    lines.push('═'.repeat(78));
    lines.push(`  AUTO-FLEET — ПУЛ БЕСПЛАТНЫХ МОДЕЛЕЙ (${AUTO_FLEET_IDS.length})`);
    lines.push('═'.repeat(78));
    for (const id of AUTO_FLEET_IDS) {
      const m = ModelRegistry.getModelById(id);
      if (!m) {
        lines.push(`  [MISSING] ${id} — нет в реестре!`);
        continue;
      }
      const r = ModelRatings.computeRating(m);
      lines.push(`  ${m.id.padEnd(44)} ctx:${String(m.contextWindow).padStart(8)}  Q${r.quality} S${r.speed} → ${m.pricing.freeTierDetails.substring(0, 40)}`);
    }
    lines.push('═'.repeat(78));
    return lines.join('\n');
  }
}

import { logger } from './Logger.js';

export interface Room {
  id: string;
  createdAt: number;
  members: Map<string, { sessionId: string; joinedAt: number; name: string }>;
  metadata: Record<string, unknown>;
}

export class RoomManager {
  private static instance: RoomManager;
  private rooms = new Map<string, Room>();
  private sessionToRoom = new Map<string, string>();

  private constructor() {}

  static getInstance(): RoomManager {
    if (!RoomManager.instance) {
      RoomManager.instance = new RoomManager();
    }
    return RoomManager.instance;
  }

  createOrJoin(roomId: string, sessionId: string, memberName?: string): Room {
    let room = this.rooms.get(roomId);
    const now = Date.now();

    if (!room) {
      room = {
        id: roomId,
        createdAt: now,
        members: new Map(),
        metadata: {},
      };
      this.rooms.set(roomId, room);
      logger.info('RoomManager', `Created room: ${roomId}`);
    }

    // Remove from previous room if any
    this.leaveRoom(sessionId);

    room.members.set(sessionId, {
      sessionId,
      joinedAt: Date.now(),
      name: memberName || `User-${sessionId.slice(0, 8)}`,
    });
    this.sessionToRoom.set(sessionId, roomId);

    logger.info('RoomManager', `Session ${sessionId} joined room: ${roomId}`);
    return room;
  }

  leaveRoom(sessionId: string): boolean {
    const roomId = this.sessionToRoom.get(sessionId);
    if (!roomId) return false;

    const room = this.rooms.get(roomId);
    if (room) {
      room.members.delete(sessionId);
      if (room.members.size === 0) {
        this.rooms.delete(roomId);
        logger.info('RoomManager', `Room ${roomId} deleted (empty)`);
      }
    }
    this.sessionToRoom.delete(sessionId);
    return true;
  }

  getRoomForSession(sessionId: string): string | undefined {
    return this.sessionToRoom.get(sessionId);
  }

  getRoom(roomId: string): Room | undefined {
    return this.rooms.get(roomId);
  }

  listRooms(): Array<{ id: string; members: number; createdAt: number }> {
    return Array.from(this.rooms.values()).map(r => ({
      id: r.id,
      members: r.members.size,
      createdAt: r.createdAt,
    }));
  }

  getRoomMembers(roomId: string): Array<{ sessionId: string; name: string; joinedAt: number }> {
    const room = this.rooms.get(roomId);
    if (!room) return [];
    return Array.from(room.members.entries()).map(([sid, m]) => ({
      sessionId: sid,
      name: m.name,
      joinedAt: m.joinedAt,
    }));
  }
}

